import { useRouter } from 'expo-router';
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { ScopeSwitch } from '@/components/scope-switch';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { useCurrency } from '@/contexts/currency-context';
import { useScope } from '@/contexts/scope-context';
import { formatMoney } from '@/lib/currency';
import { projectedResidencyCountryByYearEnd, summarizeCountries } from '@/lib/days';
import { isCitizenshipTaxed } from '@/lib/residencyRules';
import { fetchAllRows } from '@/lib/fetchAll';
import {
  computeForeignAssetPeak,
  FOREIGN_REPORTING_JURISDICTIONS,
  hasReportingCitizenship,
  type ForeignReportingJurisdictionId,
} from '@/lib/foreignAssetReporting';
import { formatDateDisplay } from '@/lib/format';
import { writeNoticeSnapshot } from '@/lib/noticeSnapshot';
import { daysUntilRenewal } from '@/lib/renewal';
import { compareSpendByCategory, significantSpendTrends, summarizeSpendByCategory, summarizeSpendByCountry } from '@/lib/spend';
import { supabase } from '@/lib/supabase';
import type {
  AccountRow,
  BalanceSnapshotRow,
  CategoryRow,
  CountryVisitedRow,
  TransactionRow,
  UserCitizenshipRow,
  UserVisaRow,
} from '@/types/database';

const ACCENT = ModuleAccents.countries;

// How close to a country's residency day-count trigger (or a visa's expiry) counts as worth
// surfacing here — same window size as the card-renewal notice, reused for
// consistency rather than inventing a new number.
const NEAR_THRESHOLD_BUFFER_DAYS = 30;
const VISA_NOTICE_WINDOW_DAYS = 60;

export default function InsightsScreen() {
  const router = useRouter();
  const { session } = useAuth();
  const { homeCountry, convert, convertToCurrency, isLoading: isCurrencyLoading } = useCurrency();

  const [visits, setVisits] = useState<CountryVisitedRow[]>([]);
  const [citizenships, setCitizenships] = useState<UserCitizenshipRow[]>([]);
  const [visas, setVisas] = useState<UserVisaRow[]>([]);
  const [categories, setCategories] = useState<CategoryRow[]>([]);
  const { filterAccounts, filterTransactions, filterSnapshots } = useScope();
  const [allAccounts, setAccounts] = useState<AccountRow[]>([]);
  const [allTransactions, setTransactions] = useState<TransactionRow[]>([]);
  const [allSnapshots, setSnapshots] = useState<BalanceSnapshotRow[]>([]);
  const accounts = filterAccounts(allAccounts);
  const transactions = filterTransactions(allTransactions);
  const snapshots = filterSnapshots(allSnapshots);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    if (!session) return;
    setError(null);
    setIsLoading(true);
    const [visitsResult, citizenshipsResult, visasResult, accountsResult, txResult, snapshotsResult, categoriesResult] =
      await Promise.all([
        supabase.from('countries_visited').select('*'),
        supabase.from('user_citizenships').select('*'),
        supabase.from('user_visas').select('*'),
        supabase.from('accounts').select('*'),
        fetchAllRows<TransactionRow>((from, to) => supabase.from('transactions').select('*').order('date').order('id').range(from, to)),
        fetchAllRows<BalanceSnapshotRow>((from, to) =>
          supabase.from('balance_snapshots').select('*').order('date').order('id').range(from, to)
        ),
        supabase.from('categories').select('*'),
      ]);
    if (visitsResult.error) {
      setError(visitsResult.error.message);
      setIsLoading(false);
      return;
    }
    setVisits(visitsResult.data ?? []);
    setCitizenships(citizenshipsResult.data ?? []);
    setVisas(visasResult.data ?? []);
    setAccounts(accountsResult.data ?? []);
    setTransactions(txResult.data);
    setSnapshots(snapshotsResult.data);
    setCategories(categoriesResult.data ?? []);
    setIsLoading(false);

    // Same "mark everything currently active as seen" snapshot
    // app/summary/index.tsx's own load() writes — previously only
    // visiting Summary cleared the TopBar badge at all; Insights had none
    // of this, so a badge only went away if you happened to pass through
    // Summary too. Gated on isCurrencyLoading for the same reason Summary
    // is: homeCountry starts out null until CurrencyProvider settles, and
    // computing notices before then could wrongly snapshot the wrong set.
    if (!isCurrencyLoading) {
      writeNoticeSnapshot({ session, homeCountry, convertToCurrency });
    }
  }, [session, homeCountry, isCurrencyLoading, convertToCurrency]);

  useEffect(() => {
    load();
  }, [load]);

  const showLoading = isLoading || isCurrencyLoading;

  // Citizenship of a country with citizenship-based taxation (the US being
  // the only one modeled today) makes crossing its day-count threshold
  // moot — that citizen owes its taxes either way, day count or not. Not
  // the same as "citizen of any flagged country": most countries tax by
  // residence, so a UK citizen who genuinely drops under the UK's day
  // count really does stop being UK tax-resident, and should still see
  // that flag. See lib/residencyRules.ts's isCitizenshipTaxed.
  const citizenshipCountries = citizenships.map((c) => c.country);
  const countryRows = summarizeCountries(visits)
    .filter((c) => c.overLimit || c.daysRemaining <= NEAR_THRESHOLD_BUFFER_DAYS)
    .filter((c) => !isCitizenshipTaxed(c.country, citizenshipCountries));
  const residencyProjectionRaw = homeCountry ? projectedResidencyCountryByYearEnd(visits, homeCountry) : null;
  const residencyProjection =
    residencyProjectionRaw && !isCitizenshipTaxed(residencyProjectionRaw.country, citizenshipCountries)
      ? residencyProjectionRaw
      : null;

  const jurisdictionPeaks = (Object.keys(FOREIGN_REPORTING_JURISDICTIONS) as ForeignReportingJurisdictionId[])
    .filter((id) => hasReportingCitizenship(citizenships, id))
    .map((id) => ({
      id,
      peak: computeForeignAssetPeak(accounts, transactions, snapshots, id, convertToCurrency),
    }));

  const visaAlerts = visas
    .filter((v) => v.expiry_date && daysUntilRenewal(v.expiry_date) <= VISA_NOTICE_WINDOW_DAYS)
    .sort((a, b) => daysUntilRenewal(a.expiry_date!) - daysUntilRenewal(b.expiry_date!));

  const excludedAccountIds = new Set(accounts.filter((a) => a.excluded_from_country_tracking).map((a) => a.id));
  // Same exclusions lib/wealthSeries.ts's buildBalanceModel uses for
  // income/spend — without these, a loan drawdown (liability account) or a
  // property sale (real-estate account) shows up as "income" just because
  // it's a large positive amount, wildly inflating a country's total.
  const accountTypeById = new Map(accounts.map((a) => [a.id, a.account_type]));
  const realEstateAccountIds = new Set(accounts.filter((a) => a.asset_category === 'real_estate').map((a) => a.id));
  // Current year only, not all-time — an all-time sum across years of
  // imported history read as implausibly large and wasn't actually useful
  // for "where does my income currently land" (the whole point of this
  // section, for weighing an active residency decision).
  const currentYearPrefix = String(new Date().getFullYear());
  const incomeTransactions = transactions.filter((tx) => {
    if (tx.amount <= 0 || tx.is_internal_transfer) return false;
    if (!tx.date.startsWith(currentYearPrefix)) return false;
    if (tx.account_id && accountTypeById.get(tx.account_id) === 'liability') return false;
    if (tx.account_id && realEstateAccountIds.has(tx.account_id)) return false;
    return true;
  });
  const incomeByCountry = summarizeSpendByCountry(incomeTransactions, visits, homeCountry, convert, excludedAccountIds).slice(0, 6);

  // This calendar month vs last, by category — flags a category that's
  // moved sharply rather than requiring a trip to Spend Detail (which has
  // the same comparison, just not surfaced as a flag; see
  // lib/spend.ts's significantSpendTrends for the "worth mentioning"
  // thresholds).
  const now = new Date();
  const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  const priorMonthDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  const priorMonthPrefix = `${priorMonthDate.getFullYear()}-${String(priorMonthDate.getMonth() + 1).padStart(2, '0')}`;
  const categoryNameById = new Map(categories.map((c) => [c.id, c.name]));
  const monthSpendTx = transactions.filter((tx) => !tx.is_internal_transfer && tx.amount < 0);
  const currentMonthSpend = summarizeSpendByCategory(
    monthSpendTx.filter((tx) => tx.date.startsWith(currentMonthPrefix)),
    categoryNameById,
    convert
  );
  const priorMonthSpend = summarizeSpendByCategory(
    monthSpendTx.filter((tx) => tx.date.startsWith(priorMonthPrefix)),
    categoryNameById,
    convert
  );
  const spendTrends = significantSpendTrends(compareSpendByCategory(currentMonthSpend, priorMonthSpend));

  const hasAnyFlag = countryRows.length > 0 || residencyProjection !== null || visaAlerts.length > 0;

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ScopeSwitch accent={ACCENT} />
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Insights
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedText style={styles.muted}>
          What your citizenship, residency, and income streams add up to right now, pulled from what you&apos;ve
          already logged, not tax advice.
        </ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {showLoading ? (
          <ActivityIndicator style={styles.loading} color={ACCENT} />
        ) : (
          <>
            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
              Residency
            </ThemedText>
            {!hasAnyFlag ? (
              <Surface accentColor={ACCENT}>
                <ThemedText style={styles.muted}>
                  Nothing close to a residency threshold or visa deadline right now.
                </ThemedText>
              </Surface>
            ) : null}
            {countryRows.map((c) => (
              <Pressable
                key={c.country}
                onPress={() =>
                  router.push(`/countries/${encodeURIComponent(c.country)}/calendar?year=${new Date().getFullYear()}`)
                }>
                <Surface accentColor={c.overLimit ? Colors.light.negative : ACCENT}>
                  <ThemedText type="defaultSemiBold">{c.country}</ThemedText>
                  <ThemedText style={c.overLimit ? styles.flagged : styles.muted}>
                    {c.overLimit
                      ? `${c.daysUsed} days counted, at or past the ${c.thresholdDays}-day trigger (${c.windowLabel}).`
                      : `${c.daysRemaining} day${c.daysRemaining === 1 ? '' : 's'} left before reaching the ${c.thresholdDays}-day trigger (${c.windowLabel}).`}
                  </ThemedText>
                  <ThemedText type="link" style={styles.viewCalendarLink}>
                    View calendar ›
                  </ThemedText>
                </Surface>
              </Pressable>
            ))}
            {residencyProjection ? (
              <Pressable
                onPress={() =>
                  router.push(
                    `/countries/${encodeURIComponent(residencyProjection.country)}/calendar?year=${new Date().getFullYear()}`
                  )
                }>
                <Surface accentColor={Colors.light.negative}>
                  <ThemedText type="defaultSemiBold">{residencyProjection.country}</ThemedText>
                  <ThemedText style={styles.flagged}>
                    On track to spend {residencyProjection.daysIn} days here by year-end, reaching its{' '}
                    {residencyProjection.thresholdDays}-day residency trigger if the year plays out as currently
                    logged.
                  </ThemedText>
                  <ThemedText type="link" style={styles.viewCalendarLink}>
                    View calendar ›
                  </ThemedText>
                </Surface>
              </Pressable>
            ) : null}
            {visaAlerts.map((v) => (
              <Pressable key={v.id} onPress={() => router.push('/account/citizenship')}>
                <Surface accentColor={ACCENT}>
                  <ThemedText type="defaultSemiBold">
                    {v.country} {v.visa_type ?? 'visa'}
                  </ThemedText>
                  <ThemedText style={styles.muted}>Expires {formatDateDisplay(v.expiry_date)}.</ThemedText>
                </Surface>
              </Pressable>
            ))}

            {spendTrends.length > 0 ? (
              <>
                <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
                  Spending trends
                </ThemedText>
                <ThemedText style={styles.muted}>This month vs. last month, categories that moved the most.</ThemedText>
                {spendTrends.slice(0, 5).map((t) => {
                  const isUp = t.change > 0;
                  return (
                    <Pressable
                      key={t.categoryId ?? 'uncategorized'}
                      onPress={() => t.categoryId && router.push(`/spend/${t.categoryId}`)}>
                      <Surface accentColor={ACCENT}>
                        <ThemedText type="defaultSemiBold">{t.categoryName}</ThemedText>
                        <ThemedText style={isUp ? styles.flagged : styles.positive}>
                          {isUp ? '↑' : '↓'} {formatMoney(Math.abs(t.change), t.currency || 'USD')}
                          {t.previousAmount > 0 ? ` (${Math.round((Math.abs(t.change) / t.previousAmount) * 100)}%)` : ' (new)'}
                        </ThemedText>
                        <ThemedText style={styles.muted}>
                          {formatMoney(t.previousAmount, t.currency || 'USD')} → {formatMoney(t.currentAmount, t.currency || 'USD')}
                        </ThemedText>
                      </Surface>
                    </Pressable>
                  );
                })}
              </>
            ) : null}

            {jurisdictionPeaks.length > 0 ? (
              <>
                <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
                  Foreign asset reporting
                </ThemedText>
                {jurisdictionPeaks.map(({ id, peak }) => {
                  const config = FOREIGN_REPORTING_JURISDICTIONS[id];
                  const isOverThreshold = config.threshold != null && peak > config.threshold;
                  return (
                    <Pressable key={id} onPress={() => router.push({ pathname: '/summary/foreign-balance-history', params: { jurisdiction: id } })}>
                      <Surface accentColor={isOverThreshold ? Colors.light.negative : ACCENT}>
                        <ThemedText type="defaultSemiBold">{config.label}</ThemedText>
                        <ThemedText type="mono" style={styles.value}>
                          {formatMoney(peak, config.currency)}
                        </ThemedText>
                        <ThemedText style={isOverThreshold ? styles.flagged : styles.muted}>
                          {isOverThreshold
                            ? `Peak balance this year is over the ${formatMoney(config.threshold!, config.currency)} ${config.label} threshold.`
                            : 'Peak combined foreign-currency balance this year.'}
                        </ThemedText>
                      </Surface>
                    </Pressable>
                  );
                })}
              </>
            ) : null}

            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
              Income by country ({new Date().getFullYear()})
            </ThemedText>
            {incomeByCountry.length === 0 ? (
              <Surface accentColor={ACCENT}>
                <ThemedText style={styles.muted}>No income transactions logged this year yet.</ThemedText>
              </Surface>
            ) : (
              <Surface accentColor={ACCENT}>
                <ThemedText style={styles.muted}>
                  Where this year&apos;s income landed while you were day-counted in each country. Useful context for
                  weighing residency decisions, not a tax calculation.
                </ThemedText>
                {incomeByCountry.map((row) => (
                  <ThemedView key={row.country} style={styles.incomeRow}>
                    <ThemedText>{row.country}</ThemedText>
                    <ThemedText type="mono">
                      {row.totals.map((t) => formatMoney(t.amount, t.currency)).join(' + ')}
                    </ThemedText>
                  </ThemedView>
                ))}
              </Surface>
            )}
          </>
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 4,
  },
  muted: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  flagged: {
    fontSize: 13,
    color: Colors.light.negative,
  },
  positive: {
    fontSize: 13,
    color: Colors.light.positive,
  },
  viewCalendarLink: {
    marginTop: 6,
    fontSize: 12,
  },
  sectionSpacing: {
    marginTop: 20,
    marginBottom: 4,
  },
  loading: {
    marginTop: 32,
  },
  value: {
    fontSize: 20,
    marginVertical: 2,
  },
  incomeRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginTop: 6,
  },
  error: {
    color: Colors.light.negative,
  },
});
