import type { ConvertedAmount } from '@/contexts/currency-context';
import type { TransactionRow } from '@/types/database';

export type CardBalance = { currency: string; amount: number };

/**
 * Outstanding balance per card, derived from card_id transactions — no
 * separately tracked balance field, consistent with how net worth and spend
 * totals are derived elsewhere. Ledger sign convention (see wealthSeries.ts)
 * is negative-for-spend, positive-for-payment; that's inverted here so a
 * card with net spend shows as a positive amount owed. A card with net
 * payments exceeding spend shows negative (a credit), which is correct, not
 * clamped away.
 *
 * Grouped by currency per card, same technique as summarizeSpendByCategory —
 * a card used in multiple currencies gets multiple totals rather than an
 * incorrect cross-currency sum.
 */
export function summarizeCardBalances(
  transactions: Pick<TransactionRow, 'card_id' | 'amount' | 'currency'>[],
  convert: (amount: number, fromCurrency: string) => ConvertedAmount
): Map<string, CardBalance[]> {
  const byCard = new Map<string, Map<string, number>>();

  for (const tx of transactions) {
    if (!tx.card_id) continue;
    const { amount, currency } = convert(tx.amount, tx.currency);
    if (!byCard.has(tx.card_id)) byCard.set(tx.card_id, new Map());
    const totals = byCard.get(tx.card_id)!;
    totals.set(currency, (totals.get(currency) ?? 0) - amount);
  }

  const result = new Map<string, CardBalance[]>();
  for (const [cardId, totals] of byCard.entries()) {
    result.set(
      cardId,
      Array.from(totals.entries()).map(([currency, amount]) => ({ currency, amount }))
    );
  }
  return result;
}
