import { useLocalSearchParams, useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, Switch, TextInput } from 'react-native';

import { CategoryPicker } from '@/components/category-picker';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { showAlert } from '@/lib/alert';
import { supabase } from '@/lib/supabase';
import type { CategoryRow } from '@/types/database';

const ACCENT = ModuleAccents.spend;

export default function CategoryRuleFormScreen() {
  const { id, merchant: prefilledMerchant, categoryId: prefilledCategoryId } = useLocalSearchParams<{
    id: string;
    merchant?: string;
    categoryId?: string;
  }>();
  const isNew = id === 'new';
  const router = useRouter();

  const [isLoading, setIsLoading] = useState(!isNew);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [pattern, setPattern] = useState(prefilledMerchant ?? '');
  const [categoryId, setCategoryId] = useState<string | null>(prefilledCategoryId ?? null);
  const [applyToExisting, setApplyToExisting] = useState(isNew);
  const [categories, setCategories] = useState<CategoryRow[]>([]);
  const [showCategoryPicker, setShowCategoryPicker] = useState(false);

  useEffect(() => {
    supabase
      .from('categories')
      .select('*')
      .then(({ data }) => setCategories(data ?? []));
  }, []);

  useEffect(() => {
    if (isNew) return;
    let cancelled = false;
    supabase
      .from('category_rules')
      .select('*')
      .eq('id', id)
      .single()
      .then(({ data, error: fetchError }) => {
        if (cancelled) return;
        if (fetchError) {
          setError(fetchError.message);
        } else if (data) {
          setPattern(data.merchant_pattern);
          setCategoryId(data.category_id);
        }
        setIsLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [id, isNew]);

  const selectedCategory = categories.find((c) => c.id === categoryId);

  async function handleSave() {
    const trimmed = pattern.trim();
    if (!trimmed) {
      setError('Enter text to match against a merchant name.');
      return;
    }
    if (!categoryId) {
      setError('Choose a category.');
      return;
    }

    setError(null);
    setIsSaving(true);

    if (isNew) {
      const { data: session } = await supabase.auth.getUser();
      if (!session.user) {
        setIsSaving(false);
        setError('You must be signed in.');
        return;
      }
      const { error: insertError } = await supabase
        .from('category_rules')
        .insert({ user_id: session.user.id, merchant_pattern: trimmed, category_id: categoryId });
      if (insertError) {
        setIsSaving(false);
        setError(insertError.message);
        return;
      }
    } else {
      const { error: updateError } = await supabase
        .from('category_rules')
        .update({ merchant_pattern: trimmed, category_id: categoryId })
        .eq('id', id);
      if (updateError) {
        setIsSaving(false);
        setError(updateError.message);
        return;
      }
    }

    if (applyToExisting) {
      // Bounded to currently-uncategorized transactions only — a rule
      // never overwrites a category someone (or an earlier rule) already
      // set, matching the same "never overwrite a manual choice" guarantee
      // the merchant-blur auto-apply gives on new transactions.
      const { data: candidates, error: fetchError } = await supabase
        .from('transactions')
        .select('id, merchant')
        .is('category_id', null)
        .not('merchant', 'is', null);
      if (!fetchError && candidates) {
        const matchingIds = candidates
          .filter((tx) => tx.merchant && tx.merchant.toLowerCase().includes(trimmed.toLowerCase()))
          .map((tx) => tx.id);
        if (matchingIds.length > 0) {
          await supabase.from('transactions').update({ category_id: categoryId }).in('id', matchingIds);
        }
      }
    }

    setIsSaving(false);
    router.back();
  }

  function handleDelete() {
    showAlert('Delete rule', 'Transactions already categorized by this rule keep their category. This cannot be undone.', [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Delete',
        style: 'destructive',
        onPress: async () => {
          setIsSaving(true);
          const { error: deleteError } = await supabase.from('category_rules').delete().eq('id', id);
          setIsSaving(false);
          if (deleteError) {
            setError(deleteError.message);
            return;
          }
          router.back();
        },
      },
    ]);
  }

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            {isNew ? 'Add Rule' : 'Edit Rule'}
          </ThemedText>
          {!isNew ? (
            <Pressable onPress={handleDelete} hitSlop={12}>
              <IconSymbol name="trash" size={22} color={Colors.light.negative} />
            </Pressable>
          ) : null}
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedText type="defaultSemiBold">When a merchant contains</ThemedText>
        <TextInput
          value={pattern}
          onChangeText={setPattern}
          placeholder="e.g. uber"
          autoCapitalize="none"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
        />
        <ThemedText style={styles.hint}>Case-insensitive, matches anywhere in the merchant name.</ThemedText>

        <ThemedText type="defaultSemiBold">Categorize it as</ThemedText>
        <Pressable onPress={() => setShowCategoryPicker(true)} style={[styles.input, { borderColor: ACCENT }]}>
          <ThemedText>{selectedCategory ? selectedCategory.name : 'Choose a category'}</ThemedText>
        </Pressable>
        <CategoryPicker
          visible={showCategoryPicker}
          onClose={() => setShowCategoryPicker(false)}
          categories={categories}
          selectedCategoryId={categoryId}
          onSelect={setCategoryId}
          onCategoryCreated={(category) => setCategories((prev) => [...prev, category])}
          accentColor={ACCENT}
        />

        <ThemedView style={styles.row}>
          <ThemedText style={styles.checkboxLabel}>Also apply to existing uncategorized transactions</ThemedText>
          <Switch value={applyToExisting} onValueChange={setApplyToExisting} trackColor={{ true: ACCENT }} />
        </ThemedView>

        <Pressable onPress={handleSave} disabled={isSaving} style={[styles.button, { backgroundColor: ACCENT }]}>
          {isSaving ? (
            <ActivityIndicator color={ModuleAccentOnColor.spend} />
          ) : (
            <ThemedText style={{ color: ModuleAccentOnColor.spend, fontWeight: '600' }}>Save</ThemedText>
          )}
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  centered: { alignItems: 'center', justifyContent: 'center' },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 8,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 12,
    marginTop: 4,
    marginBottom: 8,
  },
  checkboxLabel: {
    flex: 1,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  error: {
    color: Colors.light.negative,
  },
});
