import { Pressable, StyleSheet, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { ThemedText } from '@/components/themed-text';
import { Colors } from '@/constants/theme';
import { useTour } from '@/contexts/tour-context';

const ACCENT = Colors.light.tint;

/**
 * Floating instruction card for the interactive walkthrough — sits on top
 * of whatever real screen the tour has navigated to. Fully opaque (not the
 * translucent Surface component, which reads as barely-there floated over
 * arbitrary busy screen content), and rendered after <Stack> in
 * app/_layout.tsx so it reliably paints above the current screen by plain
 * render order.
 *
 * Darkening the rest of the screen and highlighting the target both happen
 * elsewhere now, on the real element itself (step.highlightAnchor, checked
 * directly in the four call sites — home-wheel.tsx, app/accounts/index.tsx,
 * app/account/index.tsx, top-bar.tsx): the target renders a border/glow on
 * itself, and everything else on that screen gets wrapped in a plain
 * opacity dim. Two earlier versions of this tried to compute that from
 * here instead — first a spotlight cutout, then just the dim layer, both
 * needing the target's screen position measured via measureInWindow — and
 * both kept coming out misaligned on-device despite retries and elevation
 * fixes. Local opacity-on-a-wrapper needs no measurement at all, so
 * there's nothing left to be wrong. This card just gives instructions and
 * Back/Skip/Next controls; pointerEvents="box-none" on the wrapper means
 * everything else on the real screen underneath stays fully tappable.
 */
export function TourOverlay() {
  const { isActive, step, stepIndex, totalSteps, nextStep, prevStep, skipTour, finishTour } = useTour();
  const insets = useSafeAreaInsets();

  if (!isActive || !step) return null;

  const isLastStep = stepIndex === totalSteps - 1;
  const cardAtTop = step.cardPosition === 'top';

  return (
    <View
      style={[styles.cardWrapper, cardAtTop ? { top: insets.top + 70 } : { bottom: insets.bottom + 16 }]}
      pointerEvents="box-none">
      <View style={styles.card}>
        <ThemedText style={styles.stepCount}>
          Step {stepIndex + 1} of {totalSteps}
        </ThemedText>
        <ThemedText type="defaultSemiBold" style={{ color: ACCENT }}>
          {step.title}
        </ThemedText>
        <ThemedText style={styles.body}>{step.body}</ThemedText>

        <View style={styles.actionsRow}>
          <View style={styles.leftActions}>
            {stepIndex > 0 ? (
              <Pressable onPress={prevStep} hitSlop={8}>
                <ThemedText type="link">Back</ThemedText>
              </Pressable>
            ) : null}
            <Pressable onPress={skipTour} hitSlop={8}>
              <ThemedText style={styles.muted}>Skip Tour</ThemedText>
            </Pressable>
          </View>

          {step.waitForTapAnchor ? (
            <ThemedText style={[styles.muted, styles.waitingHint]}>Tap it to continue →</ThemedText>
          ) : (
            <Pressable onPress={isLastStep ? finishTour : nextStep} style={[styles.primaryButton, { backgroundColor: ACCENT }]}>
              <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>
                {isLastStep ? 'Finish' : 'Next'}
              </ThemedText>
            </Pressable>
          )}
        </View>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  cardWrapper: {
    position: 'absolute',
    left: 16,
    right: 16,
  },
  card: {
    backgroundColor: Colors.light.backgroundSolid,
    borderRadius: 18,
    borderWidth: 1,
    borderColor: Colors.light.cardBorder,
    padding: 16,
    gap: 8,
    shadowColor: '#000000',
    shadowOffset: { width: 0, height: 6 },
    shadowOpacity: 0.3,
    shadowRadius: 16,
    elevation: 31,
  },
  stepCount: {
    fontSize: 12,
    opacity: 0.6,
    color: Colors.light.textMuted,
  },
  body: {
    fontSize: 14,
    lineHeight: 20,
  },
  actionsRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginTop: 4,
  },
  leftActions: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 16,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  waitingHint: {
    fontStyle: 'italic',
  },
  primaryButton: {
    borderRadius: 8,
    paddingVertical: 8,
    paddingHorizontal: 16,
  },
});
