import { costOfLivingIndex } from '@/lib/costOfLiving';
import { attributedCountryForDate, isExcludedFromCountryTracking } from '@/lib/spend';
import type { AccountRow, CountryVisitedRow, TransactionRow } from '@/types/database';

const MS_PER_DAY = 24 * 60 * 60 * 1000;

type VisitForAttribution = Pick<CountryVisitedRow, 'country' | 'city' | 'entry_date' | 'exit_date'>;

/**
 * Sums (min(exit_date ?? today, today) - entry_date + 1) across every one of
 * the user's own visits to `country` — ongoing trips count through today,
 * matching how day-threshold tracking elsewhere in this app already treats
 * them (see the country day-threshold logic).
 */
export function daysSpentInCountry(visits: VisitForAttribution[], country: string, today: Date = new Date()): number {
  let days = 0;
  for (const visit of visits) {
    if (visit.country !== country) continue;
    const entry = new Date(visit.entry_date);
    const exit = visit.exit_date ? new Date(visit.exit_date) : today;
    const cappedExit = exit > today ? today : exit;
    const diff = Math.round((cappedExit.getTime() - entry.getTime()) / MS_PER_DAY) + 1;
    if (diff > 0) days += diff;
  }
  return days;
}

/** All-time spend (converted, positive magnitude) attributed to `country` — same attribution rules lib/spend.ts's summarizeSpendByCountry uses. */
function totalSpendInCountry(
  transactions: TransactionRow[],
  visits: VisitForAttribution[],
  homeCountry: string | null,
  excludedAccountIds: Set<string>,
  country: string,
  convertToCurrency: (amount: number, fromCurrency: string, toCurrency: string) => number,
  currency: string
): number {
  let total = 0;
  for (const tx of transactions) {
    if (tx.is_internal_transfer || tx.amount >= 0) continue;
    const attributedCountry = attributedCountryForDate(
      tx.date,
      visits,
      homeCountry,
      isExcludedFromCountryTracking(tx, excludedAccountIds)
    );
    if (attributedCountry !== country) continue;
    total += Math.abs(convertToCurrency(tx.amount, tx.currency, currency));
  }
  return total;
}

export type TripSpendConfidence = 'own-history' | 'personal-baseline' | 'home-baseline';

export type TripSpendEstimate = {
  dailyRate: number;
  /** null when tripLengthDays wasn't provided (an open-ended/ongoing trip) — only a daily rate makes sense then. */
  totalEstimate: number | null;
  confidence: TripSpendConfidence;
  currency: string;
};

/**
 * Estimates spend for a planned trip — a three-tier waterfall, each tier
 * strictly preferring the user's own real behavior over the cost-of-living
 * index (see lib/costOfLiving.ts for why that index is approximate).
 * Returns null (never a guess) when the target country has no index entry,
 * or none of the three tiers has enough data to work from.
 */
export function estimateTripSpend({
  targetCountry,
  tripLengthDays,
  transactions,
  visits,
  homeCountry,
  accounts,
  convertToCurrency,
  currency,
  today = new Date(),
}: {
  targetCountry: string;
  tripLengthDays: number | null;
  transactions: TransactionRow[];
  visits: VisitForAttribution[];
  homeCountry: string | null;
  accounts: Pick<AccountRow, 'id' | 'excluded_from_country_tracking'>[];
  convertToCurrency: (amount: number, fromCurrency: string, toCurrency: string) => number;
  /** The currency the estimate is returned in — pass the caller's display currency. */
  currency: string;
  today?: Date;
}): TripSpendEstimate | null {
  const targetIndex = costOfLivingIndex(targetCountry);
  if (targetIndex == null) return null;

  const excludedAccountIds = new Set(accounts.filter((a) => a.excluded_from_country_tracking).map((a) => a.id));

  function toEstimate(dailyRate: number, confidence: TripSpendConfidence): TripSpendEstimate {
    return {
      dailyRate,
      totalEstimate: tripLengthDays != null ? dailyRate * tripLengthDays : null,
      confidence,
      currency,
    };
  }

  // Tier 1: own history in the target country itself — no index involved,
  // their own recorded behavior there beats any reference number.
  const ownDays = daysSpentInCountry(visits, targetCountry, today);
  if (ownDays > 0) {
    const ownSpend = totalSpendInCountry(
      transactions,
      visits,
      homeCountry,
      excludedAccountIds,
      targetCountry,
      convertToCurrency,
      currency
    );
    if (ownSpend > 0) {
      return toEstimate(ownSpend / ownDays, 'own-history');
    }
  }

  // Tier 2: a day-weighted personal baseline built from every OTHER curated
  // country the user has trip history in — each normalized to a COLA=100
  // rate, averaged, then rescaled to the target country's own index.
  const visitedCountries = new Set(visits.map((v) => v.country));
  let weightedRateSum = 0;
  let totalWeightDays = 0;
  for (const country of visitedCountries) {
    if (country === targetCountry) continue;
    const index = costOfLivingIndex(country);
    if (index == null) continue;
    const days = daysSpentInCountry(visits, country, today);
    if (days <= 0) continue;
    const spend = totalSpendInCountry(transactions, visits, homeCountry, excludedAccountIds, country, convertToCurrency, currency);
    if (spend <= 0) continue;
    const normalizedRate = spend / days / (index / 100);
    weightedRateSum += normalizedRate * days;
    totalWeightDays += days;
  }
  if (totalWeightDays > 0) {
    const personalBaselineRate = weightedRateSum / totalWeightDays;
    return toEstimate(personalBaselineRate * (targetIndex / 100), 'personal-baseline');
  }

  // Tier 3: home-country spend, scaled by the target/home COLA ratio — the
  // last resort for someone with no curated-country trip history at all.
  if (homeCountry) {
    const homeIndex = costOfLivingIndex(homeCountry);
    if (homeIndex != null) {
      let homeSpend = 0;
      const homeSpendDates = new Set<string>();
      for (const tx of transactions) {
        if (tx.is_internal_transfer || tx.amount >= 0) continue;
        const attributedCountry = attributedCountryForDate(
          tx.date,
          visits,
          homeCountry,
          isExcludedFromCountryTracking(tx, excludedAccountIds)
        );
        if (attributedCountry !== homeCountry) continue;
        homeSpend += Math.abs(convertToCurrency(tx.amount, tx.currency, currency));
        homeSpendDates.add(tx.date);
      }
      if (homeSpend > 0 && homeSpendDates.size > 0) {
        const homeDailyRate = homeSpend / homeSpendDates.size;
        return toEstimate(homeDailyRate * (targetIndex / homeIndex), 'home-baseline');
      }
    }
  }

  return null;
}
