import { computeWealthSeries, generatePeriods } from '@/lib/wealthSeries';
import type { AccountRow, BalanceSnapshotRow, TransactionRow, UserCitizenshipRow } from '@/types/database';

export type ForeignReportingJurisdictionId = 'fbar' | 't1135' | 'uk-overseas';

export type ForeignReportingJurisdiction = {
  id: ForeignReportingJurisdictionId;
  /** Exact country name string as stored in user_citizenships.country (see lib/countries.ts COUNTRIES) — having this citizenship is what makes the jurisdiction relevant to a given user, independent of where they currently live. */
  citizenshipCountry: string;
  /** The reporting jurisdiction's own currency — "foreign" is relative to this, not to the user's home/residence country. A US citizen living in Canada still owes FBAR on their Canadian (CAD) accounts, so USD is always the FBAR reference currency regardless of home country. */
  currency: string;
  /** Reporting threshold in `currency`, or null when the jurisdiction has no single fixed aggregate-balance threshold (the UK card is informational only). */
  threshold: number | null;
  label: string;
  fullName: string;
};

export const FOREIGN_REPORTING_JURISDICTIONS: Record<ForeignReportingJurisdictionId, ForeignReportingJurisdiction> = {
  fbar: {
    id: 'fbar',
    citizenshipCountry: 'United States',
    currency: 'USD',
    threshold: 10000,
    label: 'FBAR',
    fullName: 'FBAR (Report of Foreign Bank and Financial Accounts)',
  },
  t1135: {
    id: 't1135',
    citizenshipCountry: 'Canada',
    currency: 'CAD',
    threshold: 100000,
    label: 'T1135',
    fullName: 'T1135 (Foreign Income Verification Statement)',
  },
  'uk-overseas': {
    id: 'uk-overseas',
    citizenshipCountry: 'United Kingdom',
    currency: 'GBP',
    threshold: null,
    label: 'Overseas assets',
    fullName: 'UK overseas assets',
  },
  // More jurisdictions can be added here later — each is just a config
  // entry plus a citizenship check; computeForeignAssetPeak,
  // computeForeignAssetWeeklySeries, and the drill-down screen
  // (app/summary/foreign-balance-history.tsx) are already generic.
};

/** True if any of the user's citizenships match the jurisdiction's reporting country. */
export function hasReportingCitizenship(
  citizenships: Pick<UserCitizenshipRow, 'country'>[],
  jurisdiction: ForeignReportingJurisdictionId
): boolean {
  const country = FOREIGN_REPORTING_JURISDICTIONS[jurisdiction].citizenshipCountry;
  return citizenships.some((c) => c.country === country);
}

type ForeignLedgerInput = {
  accounts: Pick<AccountRow, 'id' | 'tracking_method' | 'currency' | 'account_type' | 'asset_category'>[];
  transactions: Pick<TransactionRow, 'date' | 'amount' | 'currency' | 'account_id'>[];
  balanceSnapshots: Pick<BalanceSnapshotRow, 'account_id' | 'date' | 'balance'>[];
};

/**
 * "Foreign" here means "denominated in a currency other than the reporting
 * jurisdiction's own currency" — accounts has no per-account country field,
 * so this is the closest available signal, not a precise match. A
 * same-currency account genuinely held abroad won't be caught; a
 * foreign-currency account held domestically would be wrongly included.
 * Restricted to account_type 'asset' — these reports concern foreign
 * financial accounts you hold, not foreign liabilities like a mortgage.
 * Also excludes asset_category 'real_estate' — directly-held property
 * (e.g. a house) isn't a "financial account" for any of these reports,
 * even when it's denominated in a foreign currency.
 */
function scopeToForeignAccounts(
  accounts: Pick<AccountRow, 'id' | 'tracking_method' | 'currency' | 'account_type' | 'asset_category'>[],
  transactions: Pick<TransactionRow, 'date' | 'amount' | 'currency' | 'account_id'>[],
  balanceSnapshots: Pick<BalanceSnapshotRow, 'account_id' | 'date' | 'balance'>[],
  referenceCurrency: string
): ForeignLedgerInput {
  const foreignAccounts = accounts.filter(
    (a) => a.currency !== referenceCurrency && a.account_type === 'asset' && a.asset_category !== 'real_estate'
  );
  const foreignAccountIds = new Set(foreignAccounts.map((a) => a.id));

  return {
    accounts: foreignAccounts,
    transactions: transactions.filter((tx) => tx.account_id && foreignAccountIds.has(tx.account_id)),
    balanceSnapshots: balanceSnapshots.filter((s) => foreignAccountIds.has(s.account_id)),
  };
}

/**
 * Aggregate MAXIMUM balance across a jurisdiction's foreign financial
 * accounts at any point during the calendar year — not each account's own
 * max, the max of the SUM at any single point in time (this is how FBAR's
 * $10,000 test works; T1135's cost-amount test and the UK card reuse the
 * same peak-balance shape as a reasonable proxy, since this app tracks
 * running balances, not historical cost basis). Reuses computeWealthSeries's
 * existing running-balance/high-water-mark logic (same "high" computation
 * the wealth chart's candles use) by passing it a single period spanning
 * Jan 1 -> today, scoped to just that jurisdiction's foreign accounts.
 */
export function computeForeignAssetPeak(
  accounts: Pick<AccountRow, 'id' | 'tracking_method' | 'currency' | 'account_type' | 'asset_category'>[],
  transactions: Pick<TransactionRow, 'date' | 'amount' | 'currency' | 'account_id'>[],
  balanceSnapshots: Pick<BalanceSnapshotRow, 'account_id' | 'date' | 'balance'>[],
  jurisdiction: ForeignReportingJurisdictionId,
  convertToCurrency: (amount: number, fromCurrency: string, toCurrency: string) => number,
  today: Date = new Date()
): number {
  const { currency } = FOREIGN_REPORTING_JURISDICTIONS[jurisdiction];
  const foreign = scopeToForeignAccounts(accounts, transactions, balanceSnapshots, currency);
  if (foreign.accounts.length === 0) return 0;

  const yearStart = new Date(today.getFullYear(), 0, 1);
  const [candle] = computeWealthSeries({
    ...foreign,
    periods: [{ start: yearStart, end: today }],
    convert: (amount, from) => convertToCurrency(amount, from, currency),
  });

  return candle.high;
}

export type ForeignAssetWeeklyPoint = { periodEnd: string; balance: number };

/**
 * Week-by-week foreign balance from Jan 1 through today, for the Summary
 * notice to drill into as a line chart instead of just a single peak
 * number. Reuses the same generatePeriods('week', ...) helper the wealth
 * chart uses, then takes each period's closing balance (not its high) —
 * this is meant to show the actual shape of the balance over the year, not
 * a running peak-to-date line.
 */
export function computeForeignAssetWeeklySeries(
  accounts: Pick<AccountRow, 'id' | 'tracking_method' | 'currency' | 'account_type' | 'asset_category'>[],
  transactions: Pick<TransactionRow, 'date' | 'amount' | 'currency' | 'account_id'>[],
  balanceSnapshots: Pick<BalanceSnapshotRow, 'account_id' | 'date' | 'balance'>[],
  jurisdiction: ForeignReportingJurisdictionId,
  convertToCurrency: (amount: number, fromCurrency: string, toCurrency: string) => number,
  today: Date = new Date()
): ForeignAssetWeeklyPoint[] {
  const { currency } = FOREIGN_REPORTING_JURISDICTIONS[jurisdiction];
  const foreign = scopeToForeignAccounts(accounts, transactions, balanceSnapshots, currency);
  if (foreign.accounts.length === 0) return [];

  const startOfYear = new Date(today.getFullYear(), 0, 1);
  const weeksSoFar = Math.max(1, Math.ceil((today.getTime() - startOfYear.getTime()) / (7 * 24 * 60 * 60 * 1000)) + 1);
  const periods = generatePeriods('week', weeksSoFar, today).filter((p) => p.start <= today);

  const candles = computeWealthSeries({
    ...foreign,
    periods,
    convert: (amount, from) => convertToCurrency(amount, from, currency),
  });

  return candles.map((c) => ({ periodEnd: c.periodEnd, balance: c.close }));
}
