import type { DocumentType } from '@/types/database';

export const DOCUMENT_TYPE_OPTIONS: { value: DocumentType; label: string }[] = [
  { value: 'passport', label: 'Passport' },
  { value: 'visa', label: 'Visa' },
  { value: 'insurance', label: 'Insurance' },
  { value: 'health', label: 'Health & Medical' },
  { value: 'tax', label: 'Tax Document' },
  { value: 'housing', label: 'Lease/Housing' },
  { value: 'proof_of_travel', label: 'Proof of Travel' },
  { value: 'other', label: 'Other' },
];

export function documentTypeLabel(type: DocumentType): string {
  return DOCUMENT_TYPE_OPTIONS.find((o) => o.value === type)?.label ?? 'Other';
}

export const MAX_DOCUMENT_FILE_SIZE_BYTES = 10 * 1024 * 1024;

export const SUPPORTED_DOCUMENT_MIME_TYPES = [
  'application/pdf',
  'image/jpeg',
  'image/png',
  'image/heic',
  'image/heif',
];

export function isImageFile(mimeType: string | null | undefined, name: string): boolean {
  if (mimeType && mimeType.startsWith('image/')) return true;
  return /\.(jpe?g|png|heic|heif|gif|webp)$/i.test(name);
}

/** Best-effort mime type from a filename's extension — used when sharing a single downloaded document directly (no mime_type column on `documents` to read from). */
export function guessMimeTypeFromName(name: string): string {
  const ext = name.split('.').pop()?.toLowerCase();
  switch (ext) {
    case 'pdf':
      return 'application/pdf';
    case 'jpg':
    case 'jpeg':
      return 'image/jpeg';
    case 'png':
      return 'image/png';
    case 'heic':
      return 'image/heic';
    case 'heif':
      return 'image/heif';
    default:
      return 'application/octet-stream';
  }
}
