import { Fragment } from 'react';
import { Modal, Pressable, ScrollView, StyleSheet, View, type StyleProp, type ViewStyle } from 'react-native';
import { GestureHandlerRootView } from 'react-native-gesture-handler';

import { FlagIcon } from '@/components/flag-icon';
import { ThemedText } from '@/components/themed-text';
import { Colors } from '@/constants/theme';

export type SelectOption = {
  value: string;
  label: string;
  /** A text glyph prepended to the label (e.g. the neutral-flag globe marker) — ignored when flagCode is set. */
  icon?: string;
  /** A lib/flagSvgs.ts code — renders a real flag via FlagIcon before the label instead of the plain-text icon above. */
  flagCode?: string;
  /** Renders a thin divider line directly above this option — for grouping options into tiers. */
  dividerBefore?: boolean;
};

export function SelectModal({
  visible,
  onClose,
  options,
  selectedValue,
  onSelect,
  containerStyle,
}: {
  visible: boolean;
  onClose: () => void;
  options: SelectOption[];
  selectedValue: string | null;
  onSelect: (value: string) => void;
  containerStyle?: StyleProp<ViewStyle>;
}) {
  return (
    <Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}>
      {/* The real fix: react-native-gesture-handler's own documentation
          states this plainly — Modal renders its content into a separate
          native window, outside the view hierarchy the app's root-level
          GestureHandlerRootView (app/_layout.tsx) actually covers, so
          nothing inside a Modal gets a working gesture/touch system at
          all unless the Modal's own content is wrapped in its own
          GestureHandlerRootView too. This matches every piece of
          evidence gathered chasing this bug the hard way first: broken
          on both iOS and Android but not on web (web's Modal is a DOM
          portal in the same document, no separate-native-window concept
          to lose touch handling to), neither the backdrop's nor any
          option's Pressable ever receiving a tap, and — confirmed via
          git history — GestureHandlerRootView was added to the app's
          root layout well after this component was first written,
          matching a real report that this used to work and stopped.
          Two earlier fixes (the backdrop-as-sibling restructuring, and
          collapsable={false} below) are kept since they're correct,
          low-risk improvements in their own right, but neither was
          actually the cause — this is. */}
      <GestureHandlerRootView style={styles.backdrop}>
        <Pressable style={StyleSheet.absoluteFill} onPress={onClose} collapsable={false} />
        <View
          collapsable={false}
          style={[
            styles.dropdown,
            // Deliberately opaque, not the shared translucent Surface color —
            // dropdowns float over arbitrary busy content (lists, the wheel,
            // charts), and translucent text on top of that was hard to read.
            { borderColor: Colors.light.tint, backgroundColor: Colors.light.backgroundSolid },
            containerStyle,
          ]}>
          <ScrollView>
            {options.map((option) => (
              <Fragment key={option.value}>
                {option.dividerBefore ? <View style={styles.divider} /> : null}
                <Pressable
                  collapsable={false}
                  style={[styles.dropdownItem, option.flagCode ? styles.dropdownItemRow : undefined]}
                  onPress={() => {
                    onSelect(option.value);
                    onClose();
                  }}>
                  {option.flagCode ? <FlagIcon code={option.flagCode} size={18} /> : null}
                  <ThemedText style={selectedValue === option.value ? { color: Colors.light.tint } : undefined}>
                    {!option.flagCode && option.icon ? `${option.icon}  ` : ''}
                    {option.label}
                  </ThemedText>
                </Pressable>
              </Fragment>
            ))}
          </ScrollView>
        </View>
      </GestureHandlerRootView>
    </Modal>
  );
}

const styles = StyleSheet.create({
  backdrop: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
  },
  dropdown: {
    width: 260,
    maxHeight: '70%',
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 10,
    paddingVertical: 6,
    shadowColor: '#000',
    shadowOpacity: 0.15,
    shadowRadius: 8,
    shadowOffset: { width: 0, height: 4 },
    elevation: 6,
  },
  dropdownItem: {
    paddingHorizontal: 16,
    paddingVertical: 10,
  },
  dropdownItemRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  divider: {
    height: StyleSheet.hairlineWidth,
    backgroundColor: Colors.light.tint,
    opacity: 0.3,
    marginVertical: 6,
    marginHorizontal: 14,
  },
});
