import type { LoyaltyAccountRow } from '@/types/database';

/** Used when a program isn't in points_program_rates — keeps an unrecognized program name from breaking the page or silently showing $0. */
export const DEFAULT_VALUE_PER_POINT_CENTS = 1.0;

export type ProgramTotal = { program: string; balance: number };

/** Case-insensitive lookup since a user-entered program name won't always match a reference table's casing exactly. */
export function valuePerPointCents(program: string, rates: Map<string, number>): number {
  return rates.get(program.trim().toLowerCase()) ?? DEFAULT_VALUE_PER_POINT_CENTS;
}

export function buildRatesLookup(rows: { program: string; value_per_point_cents: number }[]): Map<string, number> {
  return new Map(rows.map((r) => [r.program.trim().toLowerCase(), r.value_per_point_cents]));
}

/** Total points per program across all cards, descending by balance — same aggregation already used on the Cards dashboard's Total Points tile. */
export function summarizePointsByProgram(pointsBalances: LoyaltyAccountRow[]): ProgramTotal[] {
  const byProgram = new Map<string, number>();
  for (const p of pointsBalances) {
    byProgram.set(p.program, (byProgram.get(p.program) ?? 0) + p.balance);
  }
  return Array.from(byProgram.entries())
    .map(([program, balance]) => ({ program, balance }))
    .sort((a, b) => b.balance - a.balance);
}

/** Estimated dollar value of a set of program totals, given a rates lookup. */
export function estimatedPointsValueDollars(totals: ProgramTotal[], rates: Map<string, number>): number {
  return totals.reduce((sum, t) => sum + (t.balance * valuePerPointCents(t.program, rates)) / 100, 0);
}
