import { supabase } from '@/lib/supabase';

/**
 * Resolves a city's real coordinates — routed through the geocode-city
 * Edge Function rather than calling OpenStreetMap's Nominatim directly,
 * since Nominatim sends no CORS header, which silently blocks every
 * browser-based call while still "succeeding" at the network level (no
 * error ever surfaced, the result just never reached the caller). Native
 * platforms aren't subject to CORS and could call it directly, but routing
 * everything through one path avoids a platform fork for a call this
 * infrequent (once per newly-saved visit, see
 * app/countries/visit/[id].tsx, with the result stored on the row so it's
 * never looked up twice).
 *
 * Never throws: a network failure, timeout, or no match all just resolve
 * to null, since a visit should always be savable whether or not its
 * coordinates could be resolved.
 */
export async function geocodeCity(city: string, country: string): Promise<{ lat: number; lon: number } | null> {
  try {
    const { data, error } = await supabase.functions.invoke<{ lat: number | null; lon: number | null; error?: string }>(
      'geocode-city',
      { body: { city, country } }
    );
    // Logged rather than silently swallowed — this is the one place that
    // would otherwise hide exactly why a city never got real coordinates
    // (a bad response, an upstream failure, whatever), same class of
    // silent-failure that made the CORS issue this replaced so hard to
    // spot in the first place.
    if (error) {
      console.error(`geocodeCity(${city}, ${country}): function error`, error);
      return null;
    }
    if (!data) {
      console.error(`geocodeCity(${city}, ${country}): empty response`);
      return null;
    }
    if (data.error) {
      console.error(`geocodeCity(${city}, ${country}): ${data.error}`);
      return null;
    }
    if (data.lat == null || data.lon == null) {
      console.warn(`geocodeCity(${city}, ${country}): no match found`);
      return null;
    }
    return { lat: data.lat, lon: data.lon };
  } catch (err) {
    console.error(`geocodeCity(${city}, ${country}): threw`, err);
    return null;
  }
}

/**
 * Best-effort coordinates for a bare place name with no known country —
 * used to backfill a trip_segment's from/to saved before
 * components/city-autocomplete-input.tsx existed (or where free text was
 * typed instead of a suggestion), which has nothing more specific than the
 * label itself to search on. Routed through the same search-places Edge
 * Function the autocomplete uses (also a CORS workaround, same reasoning
 * as geocode-city), taking its top-ranked result. Never throws — no match,
 * a network failure, or an upstream error all just resolve to null.
 */
export async function searchBestPlaceMatch(query: string): Promise<{ lat: number; lon: number } | null> {
  try {
    const { data, error } = await supabase.functions.invoke<{
      results: { lat: number; lon: number }[];
      error?: string;
    }>('search-places', { body: { query } });
    if (error) {
      console.error(`searchBestPlaceMatch(${query}): function error`, error);
      return null;
    }
    if (!data || data.error) {
      console.error(`searchBestPlaceMatch(${query}): ${data?.error ?? 'empty response'}`);
      return null;
    }
    const first = data.results[0];
    return first ? { lat: first.lat, lon: first.lon } : null;
  } catch (err) {
    console.error(`searchBestPlaceMatch(${query}): threw`, err);
    return null;
  }
}
