import { StyleSheet, View, useWindowDimensions } from 'react-native';
import Svg, { Circle } from 'react-native-svg';

import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import type { VennBuckets } from '@/lib/tripCalendar';

/** Area of the lens where two equal-radius circles (centers `d` apart) overlap. Monotonically decreasing from πr² (d=0, fully coincident) to 0 (d≥2r, not touching) — used both to render and, via solveDistanceForArea below, to size the overlap from a target fraction. */
function lensArea(radius: number, distance: number): number {
  if (distance <= 0) return Math.PI * radius * radius;
  if (distance >= 2 * radius) return 0;
  return (
    2 * radius * radius * Math.acos(distance / (2 * radius)) -
    (distance / 2) * Math.sqrt(4 * radius * radius - distance * distance)
  );
}

/** Bisection — lensArea is monotonic in distance, so this always converges. 40 iterations is far more precision than a pixel needs. */
function solveDistanceForAreaFraction(radius: number, targetFraction: number): number {
  const targetArea = targetFraction * Math.PI * radius * radius;
  let lo = 0;
  let hi = 2 * radius;
  for (let i = 0; i < 40; i++) {
    const mid = (lo + hi) / 2;
    if (lensArea(radius, mid) > targetArea) lo = mid;
    else hi = mid;
  }
  return (lo + hi) / 2;
}

export function TripVennDiagram({
  buckets,
  myColor,
  partnerColor,
  myLabel,
  partnerLabel,
}: {
  buckets: VennBuckets;
  myColor: string;
  partnerColor: string;
  myLabel: string;
  partnerLabel: string;
}) {
  const { width: windowWidth } = useWindowDimensions();
  const { totalDays, sameCityDays } = buckets;

  if (totalDays === 0) {
    return <ThemedText style={styles.muted}>No days in this period.</ThemedText>;
  }

  const overlapFraction = sameCityDays / totalDays;
  const radius = Math.min(windowWidth - 64, 280) / 4.6;
  // A tiny gap (not exactly touching) when there's no overlap at all — d=2r
  // alone reads ambiguously, like the circles might still be touching.
  const distance = sameCityDays === 0 ? radius * 2.15 : solveDistanceForAreaFraction(radius, overlapFraction);
  const canvasWidth = radius * 2 + distance + 24;
  const canvasHeight = radius * 2 + 16;
  const centerY = canvasHeight / 2;
  const myCenterX = canvasWidth / 2 - distance / 2;
  const partnerCenterX = canvasWidth / 2 + distance / 2;

  return (
    <ThemedView style={styles.container}>
      <View style={{ width: canvasWidth, height: canvasHeight }}>
        <Svg width={canvasWidth} height={canvasHeight}>
          <Circle cx={myCenterX} cy={centerY} r={radius} fill={myColor} opacity={0.55} />
          <Circle cx={partnerCenterX} cy={centerY} r={radius} fill={partnerColor} opacity={0.55} />
        </Svg>
      </View>

      <ThemedView style={styles.legend}>
        <ThemedView style={styles.legendRow}>
          <View style={[styles.swatch, { backgroundColor: myColor }]} />
          <ThemedText style={styles.legendLabel}>{myLabel}</ThemedText>
        </ThemedView>
        <ThemedView style={styles.legendRow}>
          <View style={[styles.swatch, { backgroundColor: partnerColor }]} />
          <ThemedText style={styles.legendLabel}>{partnerLabel}</ThemedText>
        </ThemedView>
        <ThemedText style={styles.overlapLabel}>
          Together in the same city: {sameCityDays} of {totalDays} days
        </ThemedText>
      </ThemedView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    gap: 16,
  },
  legend: {
    gap: 8,
    alignSelf: 'stretch',
  },
  legendRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  swatch: {
    width: 14,
    height: 14,
    borderRadius: 7,
  },
  legendLabel: {
    fontSize: 14,
  },
  overlapLabel: {
    fontSize: 13,
    opacity: 0.8,
    marginTop: 4,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
    textAlign: 'center',
  },
});
