import { useFocusEffect } from '@react-navigation/native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Modal, Pressable, ScrollView, StyleSheet, Switch, TextInput, useWindowDimensions } from 'react-native';

import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { CountryFlag } from '@/components/country-flag';
import { SelectModal, type SelectOption } from '@/components/select-modal';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { useCurrency } from '@/contexts/currency-context';
import { computeDisplayName } from '@/hooks/use-connection-display';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { showAlert } from '@/lib/alert';
import { formatDateDisplay, formatDateTimeDisplay, toDateOnlyString } from '@/lib/format';
import { centeredSidePadding } from '@/lib/responsive';
import { supabase } from '@/lib/supabase';
import type { CountryVisitedRow, WishlistCityRow, WishlistNoteRow } from '@/types/database';

const ACCENT = ModuleAccents.countries;

type EligibleConnection = { id: string; displayName: string };

export default function WishlistItemScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();
  const { session } = useAuth();
  const { hiddenFlagCountries } = useCurrency();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();
  const { width: windowWidth } = useWindowDimensions();

  const [item, setItem] = useState<WishlistCityRow | null>(null);
  const [linkedVisit, setLinkedVisit] = useState<CountryVisitedRow | null>(null);
  const [notes, setNotes] = useState<WishlistNoteRow[]>([]);
  const [authorNames, setAuthorNames] = useState<Map<string, string>>(new Map());
  const [draft, setDraft] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [showMergePicker, setShowMergePicker] = useState(false);
  const [mergeCandidates, setMergeCandidates] = useState<CountryVisitedRow[]>([]);

  // Who this specific city could be shared with — every one of my accepted
  // connections. Unlike every other shared module, wishlist sharing has no
  // module-level opt-in/accept step at all: flipping a switch below grants
  // that one connection visibility into this one city immediately, a
  // one-way decision made entirely by the owner. sharedConnectionIds is
  // which of them this item is actually shared with right now.
  const [eligibleConnections, setEligibleConnections] = useState<EligibleConnection[]>([]);
  const [sharedConnectionIds, setSharedConnectionIds] = useState<Set<string>>(new Set());
  const [togglingConnectionId, setTogglingConnectionId] = useState<string | null>(null);
  const [showSharePicker, setShowSharePicker] = useState(false);

  const load = useCallback(async () => {
    setError(null);
    const { data: itemRow, error: itemError } = await supabase.from('wishlist_cities').select('*').eq('id', id).maybeSingle();
    if (itemError) {
      setError(itemError.message);
      setIsLoading(false);
      return;
    }
    setItem(itemRow);

    if (itemRow?.fulfilled_visit_id) {
      const { data: visitRow } = await supabase
        .from('countries_visited')
        .select('*')
        .eq('id', itemRow.fulfilled_visit_id)
        .maybeSingle();
      setLinkedVisit(visitRow);
    } else {
      setLinkedVisit(null);
    }

    const { data: noteRows } = await supabase
      .from('wishlist_notes')
      .select('*')
      .eq('wishlist_id', id)
      .order('created_at', { ascending: true });
    const loadedNotes = noteRows ?? [];
    setNotes(loadedNotes);

    // Resolve a display name for every note author who isn't me — each one
    // is necessarily a connection I share wishlist with (RLS on
    // wishlist_notes wouldn't have let them post otherwise), so find the
    // connection whose other party is that author and read its profile.
    if (session) {
      const otherAuthorIds = Array.from(new Set(loadedNotes.map((n) => n.author_id).filter((a) => a !== session.user.id)));
      if (otherAuthorIds.length > 0) {
        const { data: myConnections } = await supabase
          .from('connections')
          .select('id, requester_id, recipient_id')
          .eq('status', 'accepted');
        const names = new Map<string, string>();
        for (const authorId of otherAuthorIds) {
          const connection = (myConnections ?? []).find(
            (c) => c.requester_id === authorId || c.recipient_id === authorId
          );
          if (!connection) continue;
          const [profileResult, overrideResult] = await Promise.all([
            supabase.rpc('connection_partner_profile', { p_connection_id: connection.id }).maybeSingle(),
            supabase
              .from('connection_display_overrides')
              .select('label')
              .eq('connection_id', connection.id)
              .eq('viewer_user_id', session.user.id)
              .maybeSingle(),
          ]);
          names.set(
            authorId,
            computeDisplayName(overrideResult.data?.label ?? null, profileResult.data?.full_name ?? null, profileResult.data?.email ?? null)
          );
        }
        setAuthorNames(names);
      } else {
        setAuthorNames(new Map());
      }
    }

    // Only meaningful for the owner — a connection viewing a shared item
    // has no reason to see or change who else it's shared with.
    if (session && itemRow?.user_id === session.user.id) {
      const [connectionsResult, cityShareResult] = await Promise.all([
        supabase
          .from('connections')
          .select('id, requester_id, recipient_id')
          .eq('status', 'accepted')
          .or(`requester_id.eq.${session.user.id},recipient_id.eq.${session.user.id}`),
        supabase.from('wishlist_city_shares').select('connection_id').eq('wishlist_id', id),
      ]);
      setSharedConnectionIds(new Set((cityShareResult.data ?? []).map((r) => r.connection_id)));
      const connectionIds = (connectionsResult.data ?? []).map((c) => c.id);
      const eligible = await Promise.all(
        connectionIds.map(async (connectionId) => {
          const [profileResult, overrideResult] = await Promise.all([
            supabase.rpc('connection_partner_profile', { p_connection_id: connectionId }).maybeSingle(),
            supabase
              .from('connection_display_overrides')
              .select('label')
              .eq('connection_id', connectionId)
              .eq('viewer_user_id', session.user.id)
              .maybeSingle(),
          ]);
          const displayName = computeDisplayName(
            overrideResult.data?.label ?? null,
            profileResult.data?.full_name ?? null,
            profileResult.data?.email ?? null
          );
          return { id: connectionId, displayName };
        })
      );
      setEligibleConnections(eligible);
    }
    setIsLoading(false);
  }, [id, session]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  const isMine = item && session && item.user_id === session.user.id;

  const sharedNames = eligibleConnections.filter((c) => sharedConnectionIds.has(c.id)).map((c) => c.displayName);
  const shareSummary =
    eligibleConnections.length === 0
      ? 'No connections yet'
      : sharedNames.length === 0
        ? 'Not shared'
        : sharedNames.length <= 2
          ? sharedNames.join(', ')
          : `${sharedNames.length} people`;

  async function handleToggleCityShare(connectionId: string, nextShared: boolean) {
    if (!item) return;
    setTogglingConnectionId(connectionId);
    if (nextShared) {
      const { error: insertError } = await supabase
        .from('wishlist_city_shares')
        .insert({ wishlist_id: item.id, connection_id: connectionId });
      if (insertError) {
        setError(insertError.message);
        setTogglingConnectionId(null);
        return;
      }
      setSharedConnectionIds((prev) => new Set(prev).add(connectionId));
    } else {
      const { error: deleteError } = await supabase
        .from('wishlist_city_shares')
        .delete()
        .eq('wishlist_id', item.id)
        .eq('connection_id', connectionId);
      if (deleteError) {
        setError(deleteError.message);
        setTogglingConnectionId(null);
        return;
      }
      setSharedConnectionIds((prev) => {
        const next = new Set(prev);
        next.delete(connectionId);
        return next;
      });
    }
    setTogglingConnectionId(null);
  }

  async function handlePostNote() {
    if (!session || !draft.trim() || !item) return;
    setIsSaving(true);
    const { error: insertError } = await supabase.from('wishlist_notes').insert({
      wishlist_id: item.id,
      author_id: session.user.id,
      note: draft.trim(),
    });
    setIsSaving(false);
    if (insertError) {
      setError(insertError.message);
      return;
    }
    setDraft('');
    await load();
  }

  async function handleDeleteNote(noteId: string) {
    const { error: deleteError } = await supabase.from('wishlist_notes').delete().eq('id', noteId);
    if (deleteError) {
      setError(deleteError.message);
      return;
    }
    setNotes((prev) => prev.filter((n) => n.id !== noteId));
  }

  async function handleOpenMergePicker() {
    if (!item || !session) return;
    setError(null);
    const today = toDateOnlyString(new Date());
    // "Can't merge with old trips" — only a stop that hasn't started yet is
    // offered, so a wishlist item can never be retroactively "fulfilled" by
    // something that already happened before it was wished for. Matched on
    // city (case-insensitive) within the same country; not already claimed
    // by another wishlist item.
    const { data } = await supabase
      .from('countries_visited')
      .select('*')
      .eq('user_id', session.user.id)
      .eq('country', item.country)
      .ilike('city', item.city)
      .gt('entry_date', today);
    // Explicit user_id filter, not just RLS — same reasoning as
    // app/countries/wishlist/index.tsx's own list query (084 added a
    // second select policy for shared items, so an unfiltered query here
    // would also pull in other people's claimed visit ids, which happen to
    // never collide with this user's own countries_visited ids anyway, but
    // there's no reason to fetch or reason about rows that aren't mine).
    const { data: claimed } = await supabase
      .from('wishlist_cities')
      .select('fulfilled_visit_id')
      .eq('user_id', session.user.id)
      .not('fulfilled_visit_id', 'is', null);
    const claimedIds = new Set((claimed ?? []).map((c) => c.fulfilled_visit_id));
    setMergeCandidates((data ?? []).filter((v) => !claimedIds.has(v.id)));
    setShowMergePicker(true);
  }

  async function handleMerge(visitId: string) {
    if (!item) return;
    const { error: updateError } = await supabase
      .from('wishlist_cities')
      .update({ fulfilled_visit_id: visitId })
      .eq('id', item.id);
    setShowMergePicker(false);
    if (updateError) {
      setError(updateError.message);
      return;
    }
    await load();
  }

  async function handleUnlink() {
    if (!item) return;
    const { error: updateError } = await supabase.from('wishlist_cities').update({ fulfilled_visit_id: null }).eq('id', item.id);
    if (updateError) {
      setError(updateError.message);
      return;
    }
    await load();
  }

  function handleDeleteItem() {
    if (!item) return;
    showAlert('Remove from wishlist?', undefined, [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Remove',
        style: 'destructive',
        onPress: async () => {
          const { error: deleteError } = await supabase.from('wishlist_cities').delete().eq('id', item.id);
          if (deleteError) {
            setError(deleteError.message);
            return;
          }
          router.back();
        },
      },
    ]);
  }

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  if (!item) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ThemedText>Not found.</ThemedText>
      </ThemedView>
    );
  }

  const mergeOptions: SelectOption[] = mergeCandidates.map((v) => ({
    value: v.id,
    label: `${formatDateDisplay(v.entry_date)} → ${v.exit_date ? formatDateDisplay(v.exit_date) : 'ongoing'}`,
  }));

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView contentContainerStyle={[styles.content, { paddingHorizontal: centeredSidePadding(windowWidth) }]}>
        <ThemedView style={styles.contentInner}>
        <ThemedView style={styles.titleRow}>
          <ThemedView style={styles.titleWithFlag}>
            <CountryFlag countryName={item.country} hiddenFlagCountries={hiddenFlagCountries} size={28} />
            <ThemedText type="title" style={[{ color: ACCENT }, styles.titleText]} numberOfLines={1} adjustsFontSizeToFit>
              {item.city}
            </ThemedText>
          </ThemedView>
          <ThemedView style={styles.titleLinks}>
            <Pressable onPress={() => router.back()} hitSlop={12}>
              <ThemedText type="link">Done</ThemedText>
            </Pressable>
          </ThemedView>
        </ThemedView>
        <ThemedText style={styles.hint}>{item.country}</ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {isMine ? (
          <Pressable onPress={() => eligibleConnections.length > 0 && setShowSharePicker(true)}>
            <Surface accentColor={ACCENT} style={styles.shareSummaryRow}>
              <ThemedText type="defaultSemiBold">Share with</ThemedText>
              <ThemedText numberOfLines={1} style={[styles.shareSummaryValue, { color: ACCENT }]}>
                {shareSummary}
              </ThemedText>
              {eligibleConnections.length > 0 ? (
                <IconSymbol name="chevron.right" size={14} color={Colors.light.textMuted} />
              ) : null}
            </Surface>
          </Pressable>
        ) : null}

        <Modal visible={showSharePicker} transparent animationType="fade" onRequestClose={() => setShowSharePicker(false)}>
          <Pressable style={styles.shareBackdrop} onPress={() => setShowSharePicker(false)}>
            <Pressable style={styles.shareCard} onPress={(e) => e.stopPropagation()}>
              <ThemedView style={styles.shareCardHeader}>
                <ThemedText type="defaultSemiBold">Share with</ThemedText>
                <Pressable onPress={() => setShowSharePicker(false)} hitSlop={8}>
                  <ThemedText type="link">Done</ThemedText>
                </Pressable>
              </ThemedView>
              <ThemedText style={styles.muted}>
                Turning one on shows them this city right away, no request or acceptance needed on their end.
              </ThemedText>
              {eligibleConnections.map((connection) => (
                <ThemedView key={connection.id} style={styles.shareRow}>
                  <ThemedText numberOfLines={1} style={styles.shareRowLabel}>
                    {connection.displayName}
                  </ThemedText>
                  <Switch
                    value={sharedConnectionIds.has(connection.id)}
                    onValueChange={(next) => handleToggleCityShare(connection.id, next)}
                    disabled={togglingConnectionId === connection.id}
                    trackColor={{ true: ACCENT }}
                  />
                </ThemedView>
              ))}
            </Pressable>
          </Pressable>
        </Modal>

        {linkedVisit ? (
          <Surface accentColor={ACCENT}>
            <ThemedText type="defaultSemiBold">Linked to a trip</ThemedText>
            <ThemedText style={styles.muted}>
              {formatDateDisplay(linkedVisit.entry_date)} &rarr; {linkedVisit.exit_date ? formatDateDisplay(linkedVisit.exit_date) : 'ongoing'}
            </ThemedText>
            <Pressable onPress={() => router.push(`/countries/visit/${linkedVisit.id}`)} hitSlop={4}>
              <ThemedText type="link">View trip &rsaquo;</ThemedText>
            </Pressable>
            {isMine ? (
              <Pressable onPress={handleUnlink} hitSlop={4} style={styles.unlinkButton}>
                <ThemedText style={styles.muted}>Unlink</ThemedText>
              </Pressable>
            ) : null}
          </Surface>
        ) : isMine ? (
          <ThemedView style={styles.actionRow}>
            <Pressable
              style={[styles.actionButton, { backgroundColor: ACCENT }]}
              onPress={() =>
                router.push(
                  `/countries/visit/new?country=${encodeURIComponent(item.country)}&city=${encodeURIComponent(item.city)}&wishlistId=${item.id}`
                )
              }>
              <ThemedText style={{ color: ModuleAccentOnColor.countries, fontWeight: '600' }}>Plan this trip</ThemedText>
            </Pressable>
            <Pressable style={[styles.actionButton, styles.actionButtonOutline, { borderColor: ACCENT }]} onPress={handleOpenMergePicker}>
              <ThemedText style={{ color: ACCENT, fontWeight: '600' }}>Link to existing trip</ThemedText>
            </Pressable>
          </ThemedView>
        ) : null}

        <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
          Notes &amp; ideas
        </ThemedText>
        {notes.length === 0 ? <ThemedText style={styles.muted}>No notes yet.</ThemedText> : null}
        {notes.map((n) => {
          const isMineNote = n.author_id === session?.user.id;
          return (
            <Surface key={n.id} accentColor={ACCENT} style={styles.noteCard}>
              <ThemedView style={styles.noteHeader}>
                <ThemedView style={styles.noteMeta}>
                  <ThemedText style={styles.noteAuthor}>{isMineNote ? 'You' : authorNames.get(n.author_id) ?? 'Someone'}</ThemedText>
                  <ThemedText style={styles.noteTimestamp}>
                    {n.updated_at !== n.created_at ? 'Edited ' : ''}
                    {formatDateTimeDisplay(n.updated_at)}
                  </ThemedText>
                </ThemedView>
                {isMineNote ? (
                  <Pressable onPress={() => handleDeleteNote(n.id)} hitSlop={12}>
                    <IconSymbol name="trash" size={14} color={Colors.light.negative} />
                  </Pressable>
                ) : null}
              </ThemedView>
              <ThemedText>{n.note}</ThemedText>
            </Surface>
          );
        })}

        <ThemedView style={styles.composerRow}>
          <TextInput
            value={draft}
            onChangeText={setDraft}
            placeholder="Add a note or idea..."
            placeholderTextColor={Colors.light.textMuted}
            style={[styles.input, styles.composerInput, { borderColor: ACCENT }]}
            multiline
          />
          <Pressable
            onPress={handlePostNote}
            disabled={isSaving || !draft.trim()}
            style={[styles.sendButton, { backgroundColor: ACCENT, opacity: isSaving || !draft.trim() ? 0.5 : 1 }]}>
            <IconSymbol name="paperplane.fill" size={18} color={Colors.light.backgroundSolid} />
          </Pressable>
        </ThemedView>

        {isMine ? (
          <Pressable onPress={handleDeleteItem} hitSlop={8} style={styles.deleteItemRow}>
            <ThemedText style={{ color: Colors.light.negative }}>Remove from wishlist</ThemedText>
          </Pressable>
        ) : null}
        </ThemedView>
      </ScrollView>
      </ConnectionsSwipePanel>

      <SelectModal
        visible={showMergePicker}
        onClose={() => setShowMergePicker(false)}
        options={mergeOptions}
        selectedValue={null}
        onSelect={handleMerge}
      />
    </ThemedView>
  );
}

