/**
 * Minimal ZIP writer — STORE method only (no compression), pure JS/typed
 * arrays, zero dependencies. Documents are already-compressed formats
 * (PDF/JPEG) so skipping DEFLATE costs little size, and after the
 * expo-print native-module crash this keeps the export path free of any
 * library whose Expo Go compatibility we'd have to trust.
 */

export type ZipEntry = { name: string; data: Uint8Array };

const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) {
      c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    }
    table[n] = c >>> 0;
  }
  return table;
})();

function crc32(data: Uint8Array): number {
  let crc = 0xffffffff;
  for (let i = 0; i < data.length; i++) {
    crc = CRC_TABLE[(crc ^ data[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function dosDateTime(date: Date): { time: number; date: number } {
  const time = ((date.getHours() & 0x1f) << 11) | ((date.getMinutes() & 0x3f) << 5) | ((Math.floor(date.getSeconds() / 2)) & 0x1f);
  const dateVal = (((date.getFullYear() - 1980) & 0x7f) << 9) | (((date.getMonth() + 1) & 0xf) << 5) | (date.getDate() & 0x1f);
  return { time, date: dateVal };
}

function u16(arr: number[], value: number) {
  arr.push(value & 0xff, (value >> 8) & 0xff);
}
function u32(arr: number[], value: number) {
  arr.push(value & 0xff, (value >> 8) & 0xff, (value >> 16) & 0xff, (value >>> 24) & 0xff);
}

/** Builds a standard (unencrypted, uncompressed) .zip file from the given entries. */
export function buildZip(entries: ZipEntry[]): Uint8Array {
  const encoder = new TextEncoder();
  const { time, date } = dosDateTime(new Date());

  const chunks: Uint8Array[] = [];
  const centralParts: Uint8Array[] = [];
  let offset = 0;
  let centralDirSize = 0;

  for (const entry of entries) {
    const nameBytes = encoder.encode(entry.name);
    const crc = crc32(entry.data);
    const size = entry.data.length;

    const local: number[] = [];
    u32(local, 0x04034b50);
    u16(local, 20); // version needed to extract
    u16(local, 0); // flags
    u16(local, 0); // method: stored
    u16(local, time);
    u16(local, date);
    u32(local, crc);
    u32(local, size); // compressed size
    u32(local, size); // uncompressed size
    u16(local, nameBytes.length);
    u16(local, 0); // extra field length
    const localHeader = new Uint8Array(local);

    chunks.push(localHeader, nameBytes, entry.data);

    const central: number[] = [];
    u32(central, 0x02014b50);
    u16(central, 20); // version made by
    u16(central, 20); // version needed
    u16(central, 0); // flags
    u16(central, 0); // method
    u16(central, time);
    u16(central, date);
    u32(central, crc);
    u32(central, size);
    u32(central, size);
    u16(central, nameBytes.length);
    u16(central, 0); // extra length
    u16(central, 0); // comment length
    u16(central, 0); // disk number start
    u16(central, 0); // internal attributes
    u32(central, 0); // external attributes
    u32(central, offset); // local header offset
    const centralHeader = new Uint8Array([...central, ...nameBytes]);
    centralParts.push(centralHeader);
    centralDirSize += centralHeader.length;

    offset += localHeader.length + nameBytes.length + size;
  }

  const centralDirStart = offset;
  chunks.push(...centralParts);

  const end: number[] = [];
  u32(end, 0x06054b50);
  u16(end, 0); // disk number
  u16(end, 0); // disk with central dir
  u16(end, entries.length); // entries on this disk
  u16(end, entries.length); // total entries
  u32(end, centralDirSize);
  u32(end, centralDirStart);
  u16(end, 0); // comment length
  chunks.push(new Uint8Array(end));

  const total = chunks.reduce((sum, c) => sum + c.length, 0);
  const result = new Uint8Array(total);
  let pos = 0;
  for (const chunk of chunks) {
    result.set(chunk, pos);
    pos += chunk.length;
  }
  return result;
}
