import { useFocusEffect } from '@react-navigation/native';
import { useCallback, useState } from 'react';

import { useAuth } from '@/contexts/auth-context';
import { computeDisplayName } from '@/hooks/use-connection-display';
import { supabase } from '@/lib/supabase';
import type { SwipeConnection } from '@/components/connections-swipe-panel';

/** Accepted connections with resolved display names, for the ConnectionsSwipePanel quick-switcher. Shared between the Countries dashboard and each connection's own sub-wheel screen rather than duplicated. */
export function useSwipeConnections(): { connections: SwipeConnection[]; isLoading: boolean } {
  const { session } = useAuth();
  const [connections, setConnections] = useState<SwipeConnection[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const load = useCallback(async () => {
    if (!session) return;
    const myId = session.user.id;

    const { data: rows, error: connectionsError } = await supabase
      .from('connections')
      .select('*')
      .or(`requester_id.eq.${myId},recipient_id.eq.${myId}`)
      .eq('status', 'accepted');

    if (connectionsError || !rows) {
      setIsLoading(false);
      return;
    }

    const withNames = await Promise.all(
      rows.map(async (row) => {
        const [profileResult, overrideResult] = await Promise.all([
          supabase.rpc('connection_partner_profile', { p_connection_id: row.id }).maybeSingle(),
          supabase
            .from('connection_display_overrides')
            .select('label')
            .eq('connection_id', row.id)
            .eq('viewer_user_id', myId)
            .maybeSingle(),
        ]);
        const displayName = computeDisplayName(
          overrideResult.data?.label ?? null,
          profileResult.data?.full_name ?? null,
          profileResult.data?.email ?? null
        );
        return { id: row.id, displayName };
      })
    );

    setConnections(withNames);
    setIsLoading(false);
  }, [session]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  return { connections, isLoading };
}
