import type { TransactionRow } from '@/types/database';

function csvEscape(value: string): string {
  if (/[",\n]/.test(value)) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}

/**
 * A clean data dump for handing to an accountant/tax preparer — every
 * transaction for the given year, one row each, no subtotals or
 * formatting. Internal transfers are included (not filtered like the
 * spend-only views elsewhere) since a tax preparer needs the full ledger,
 * not just spend.
 */
export function buildTransactionsCsv(
  transactions: Pick<
    TransactionRow,
    'date' | 'merchant' | 'category_id' | 'account_id' | 'card_id' | 'amount' | 'currency' | 'is_internal_transfer' | 'notes'
  >[],
  categoryNameById: Map<string, string>,
  accountNameById: Map<string, string>,
  cardNameById: Map<string, string>
): string {
  const headers = ['Date', 'Description', 'Category', 'Source', 'Type', 'Amount', 'Currency', 'Notes'];
  const lines = [headers.join(',')];

  const sorted = [...transactions].sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));

  for (const tx of sorted) {
    const source = tx.account_id
      ? (accountNameById.get(tx.account_id) ?? 'Unknown account')
      : tx.card_id
        ? (cardNameById.get(tx.card_id) ?? 'Unknown card')
        : '';
    const category = tx.category_id ? (categoryNameById.get(tx.category_id) ?? 'Uncategorized') : 'Uncategorized';
    const type = tx.is_internal_transfer ? 'Transfer' : tx.amount < 0 ? 'Spend' : 'Income';
    const row = [
      tx.date,
      csvEscape(tx.merchant ?? ''),
      csvEscape(category),
      csvEscape(source),
      type,
      tx.amount.toFixed(2),
      tx.currency,
      csvEscape(tx.notes ?? ''),
    ];
    lines.push(row.join(','));
  }

  return lines.join('\n');
}
