import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, Switch, View } from 'react-native';

import { MonthYearJump } from '@/components/month-year-jump';
import { MultiTripCalendarGrid } from '@/components/multi-trip-calendar-grid';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import {
  addDays,
  CALENDAR_COLOR_PRESETS,
  mergeTripLists,
  type CalendarViewMode,
  type MultiParty,
  type TripLike,
} from '@/lib/tripCalendar';
import { supabase } from '@/lib/supabase';

const ACCENT = ModuleAccents.countries;

type PartyOption = { id: string; label: string; color: string; trips: TripLike[] };

export default function SharedCalendarScreen() {
  const router = useRouter();
  const { session } = useAuth();
  const { connections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const [parties, setParties] = useState<PartyOption[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<CalendarViewMode>('month');
  const [currentDate, setCurrentDate] = useState(new Date());

  const load = useCallback(async () => {
    if (!session) return;
    setIsLoading(true);
    const myId = session.user.id;

    const [myVisitsResult, myColorResult, overridesResult, connectionData] = await Promise.all([
      supabase.from('countries_visited').select('*'),
      supabase.from('user_settings').select('calendar_color').eq('user_id', myId).maybeSingle(),
      supabase.from('connection_display_overrides').select('connection_id, color').eq('viewer_user_id', myId),
      Promise.all(
        connections.map(async (c) => {
          const [visitedResult, plannedResult, colorResult] = await Promise.all([
            supabase.rpc('shared_countries_visited', { p_connection_id: c.id }),
            supabase.rpc('shared_trips_planned', { p_connection_id: c.id }),
            supabase.rpc('connection_partner_calendar_color', { p_connection_id: c.id }),
          ]);
          const trips = mergeTripLists(visitedResult.data ?? [], plannedResult.data ?? []).filter((t) => t.country);
          return { id: c.id, label: c.displayName, realColor: colorResult.data as string | null, trips };
        })
      ),
    ]);

    const overrideByConnection = new Map((overridesResult.data ?? []).map((o) => [o.connection_id, o.color]));
    const myTrips: TripLike[] = myVisitsResult.data ?? [];

    // Resolve a color per party (me first, then connections in list order),
    // then de-duplicate: two people who happen to have picked the same
    // swatch would otherwise be indistinguishable once both are toggled on
    // — this is session-only (never written back), purely for this one
    // combined view's legibility.
    const claimed = new Set<string>();
    function resolveColor(preferred: string | null, fallbackIndex: number): string {
      let color = preferred ?? CALENDAR_COLOR_PRESETS[fallbackIndex % CALENDAR_COLOR_PRESETS.length];
      let presetCursor = fallbackIndex;
      while (claimed.has(color)) {
        presetCursor++;
        color = CALENDAR_COLOR_PRESETS[presetCursor % CALENDAR_COLOR_PRESETS.length];
      }
      claimed.add(color);
      return color;
    }

    const resolved: PartyOption[] = [
      {
        id: 'me',
        label: 'You',
        color: resolveColor(myColorResult.data?.calendar_color ?? null, 0),
        trips: myTrips,
      },
      ...connectionData.map((c, i) =>
        ({
          id: c.id,
          label: c.label,
          color: resolveColor(overrideByConnection.get(c.id) ?? c.realColor, i + 1),
          trips: c.trips,
        })
      ),
    ];

    setParties(resolved);
    setIsLoading(false);
  }, [session, connections]);

  useFocusEffect(
    useCallback(() => {
      if (!isConnectionsLoading) load();
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isConnectionsLoading, connections.length])
  );

  function toggleParty(id: string) {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  function goPrev() {
    setCurrentDate((d) => (viewMode === 'month' ? new Date(d.getFullYear(), d.getMonth() - 1, 1) : addDays(d, -7)));
  }
  function goNext() {
    setCurrentDate((d) => (viewMode === 'month' ? new Date(d.getFullYear(), d.getMonth() + 1, 1) : addDays(d, 7)));
  }
  function goToday() {
    setCurrentDate(new Date());
  }

  const rangeLabel =
    viewMode === 'month'
      ? currentDate.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })
      : `Week of ${currentDate.toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}`;

  const selectedParties: MultiParty[] = parties
    .filter((p) => selectedIds.has(p.id))
    .map((p) => ({ id: p.id, color: p.color, trips: p.trips }));

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Shared Calendar
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedText style={styles.hint}>Check who you want to see. Their trips overlay on one calendar, each in their own color.</ThemedText>

        {isLoading ? (
          <ActivityIndicator color={ACCENT} />
        ) : (
          <>
            {parties.map((party) => (
              <Pressable key={party.id} onPress={() => toggleParty(party.id)} style={styles.toggleRow}>
                <View style={styles.toggleRowLeft}>
                  <ThemedView style={[styles.swatch, { backgroundColor: party.color }]} />
                  <ThemedText>{party.label}</ThemedText>
                </View>
                <Switch
                  value={selectedIds.has(party.id)}
                  onValueChange={() => toggleParty(party.id)}
                  trackColor={{ true: ACCENT }}
                />
              </Pressable>
            ))}

            <ThemedView style={styles.chipRow}>
              <Pressable
                onPress={() => setViewMode('month')}
                style={[styles.chip, { borderColor: ACCENT }, viewMode === 'month' ? { backgroundColor: ACCENT } : null]}>
                <ThemedText style={viewMode === 'month' ? styles.chipTextActive : undefined}>Month</ThemedText>
              </Pressable>
              <Pressable
                onPress={() => setViewMode('week')}
                style={[styles.chip, { borderColor: ACCENT }, viewMode === 'week' ? { backgroundColor: ACCENT } : null]}>
                <ThemedText style={viewMode === 'week' ? styles.chipTextActive : undefined}>Week</ThemedText>
              </Pressable>
            </ThemedView>

            <ThemedView style={styles.navRow}>
              <Pressable onPress={goPrev} hitSlop={12}>
                <ThemedText type="link">←</ThemedText>
              </Pressable>
              <Pressable onPress={goToday}>
                <ThemedText type="defaultSemiBold">{rangeLabel}</ThemedText>
              </Pressable>
              {viewMode === 'month' ? (
                <MonthYearJump
                  value={currentDate}
                  onChange={setCurrentDate}
                  accentColor={ACCENT}
                  renderTrigger={(open) => (
                    <Pressable onPress={open} hitSlop={10}>
                      <IconSymbol name="calendar" size={16} color={ACCENT} />
                    </Pressable>
                  )}
                />
              ) : null}
              <Pressable onPress={goNext} hitSlop={12}>
                <ThemedText type="link">→</ThemedText>
              </Pressable>
            </ThemedView>

            {selectedParties.length === 0 ? (
              <ThemedText style={styles.muted}>Select who you want to see above.</ThemedText>
            ) : (
              <MultiTripCalendarGrid currentDate={currentDate} viewMode={viewMode} parties={selectedParties} />
            )}
          </>
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 8,
  },
  toggleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingVertical: 8,
  },
  toggleRowLeft: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
  },
  swatch: {
    width: 14,
    height: 14,
    borderRadius: 7,
  },
  chipRow: {
    flexDirection: 'row',
    gap: 8,
    marginTop: 12,
  },
  chip: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 16,
    paddingHorizontal: 16,
    paddingVertical: 8,
  },
  chipTextActive: {
    color: '#FFFFFF',
  },
  navRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginTop: 4,
    marginBottom: 8,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
    marginTop: 8,
  },
});
