import { useRouter } from 'expo-router';
import { Pressable, ScrollView, StyleSheet } from 'react-native';

import { CountryChecklist } from '@/components/country-checklist';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { MOVING_CHECKLIST_ITEMS } from '@/lib/countryChecklist';

const TINT = Colors.light.tint;

export default function AccountChecklistScreen() {
  const router = useRouter();
  const { homeCountry } = useCurrency();

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: TINT }}>
            Setup Checklist
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>

        {homeCountry ? (
          <>
            <ThemedText style={styles.hint}>For {homeCountry}, your home country.</ThemedText>
            <CountryChecklist country={homeCountry} accentColor={TINT} items={MOVING_CHECKLIST_ITEMS} />
          </>
        ) : (
          <ThemedText style={styles.hint}>Set a home country in Account to see its setup checklist.</ThemedText>
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 4,
  },
});
