import type { Session } from '@supabase/supabase-js';
import { createContext, useCallback, useContext, useEffect, useMemo, useState, type PropsWithChildren } from 'react';
import * as Linking from 'expo-linking';
import { Platform } from 'react-native';

import { supabase } from '@/lib/supabase';

/**
 * Linking.createURL(path) on web builds path off window.location.origin
 * alone (confirmed directly by reading expo-linking's web implementation),
 * with no idea this site is served under a /app base path
 * (experiments.baseUrl in app.config.js, for clusterfinancial.com/app) —
 * it produced clusterfinancial.com/reset-password, a URL that doesn't
 * exist, instead of clusterfinancial.com/app/reset-password, so Supabase
 * fell back to the Site URL and every reset/signup-confirmation link
 * landed on login instead of the intended screen. process.env.EXPO_BASE_URL
 * is expo-router's own already-built-in runtime constant for this exact
 * value (same one its internal path-handling functions use), so this reads
 * from the same source of truth rather than hardcoding "/app" a second
 * time. Native is unaffected — Linking.createURL's own scheme-URL handling
 * there was never wrong.
 */
function authRedirectUrl(path: string): string {
  if (Platform.OS === 'web' && typeof window !== 'undefined') {
    const base = process.env.EXPO_BASE_URL ?? '';
    return `${window.location.origin}${base}${path}`;
  }
  return Linking.createURL(path);
}

type AuthContextValue = {
  session: Session | null;
  isLoading: boolean;
  /**
   * True once signed in (a session exists) but the account has a verified
   * MFA factor requiring step-up to aal2 that this session hasn't completed
   * yet — app/_layout.tsx shows the MFA challenge screen instead of the
   * protected app while this is true. False for accounts with no MFA
   * factor enrolled at all, since currentLevel === nextLevel === 'aal1' for
   * them.
   */
  mfaRequired: boolean;
  /** Re-checks the current session's AAL — call after a successful MFA challenge verify to flip mfaRequired false and let the protected app appear. */
  refreshMfaStatus: () => Promise<void>;
  signIn: (email: string, password: string) => Promise<{ error: string | null }>;
  signUp: (email: string, password: string, inviteCode: string) => Promise<{ error: string | null }>;
  signOut: () => Promise<void>;
  /** Sends a password-reset email pointing back at /reset-password. Always resolves without error even for an unknown email — Supabase doesn't distinguish, so neither do we (avoids leaking which emails have accounts). */
  resetPasswordForEmail: (email: string) => Promise<{ error: string | null }>;
};

const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: PropsWithChildren) {
  const [session, setSession] = useState<Session | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [mfaRequired, setMfaRequired] = useState(false);

  const refreshMfaStatus = useCallback(async () => {
    const { data, error } = await supabase.auth.mfa.getAuthenticatorAssuranceLevel();
    setMfaRequired(!error && !!data && data.currentLevel === 'aal1' && data.nextLevel === 'aal2');
  }, []);

  useEffect(() => {
    supabase.auth.getSession().then(async ({ data }) => {
      setSession(data.session);
      if (data.session) await refreshMfaStatus();
      setIsLoading(false);
    });

    const { data: subscription } = supabase.auth.onAuthStateChange((_event, newSession) => {
      setSession(newSession);
      if (newSession) {
        refreshMfaStatus();
      } else {
        setMfaRequired(false);
      }
    });

    return () => subscription.subscription.unsubscribe();
  }, [refreshMfaStatus]);

  const value = useMemo<AuthContextValue>(
    () => ({
      session,
      isLoading,
      mfaRequired,
      refreshMfaStatus,
      signIn: async (email, password) => {
        const { error } = await supabase.auth.signInWithPassword({ email, password });
        return { error: error?.message ?? null };
      },
      signUp: async (email, password, inviteCode) => {
        // Gate signup behind an invite code (redeem_invite_code, migration
        // 083) before creating the auth user at all — the web export at
        // clusterfinancial.com/app is a public URL now, so this is the only
        // thing stopping an open signup form. Atomic check-and-increment on
        // the server side, so this either consumes one use or fails clean.
        const { data: redeemed, error: redeemError } = await supabase.rpc('redeem_invite_code', {
          p_code: inviteCode.trim(),
        });
        if (redeemError || !redeemed) {
          return { error: 'Invalid or already-used invite code.' };
        }

        // Without emailRedirectTo, a project with "Confirm email" enabled
        // sends a confirmation link that falls back to Supabase's generic
        // Site URL setting (a Supabase dashboard default, not this app).
        // Points at /reset-password — NOT / — deliberately: that screen is
        // the one unguarded route (sits outside both Stack.Protected groups
        // in app/_layout.tsx) capable of running the code-exchange effect
        // BEFORE a session exists. / is behind guard={!!session}, so a
        // fresh signup confirmation (no session yet) would never even
        // mount there to run the exchange. reset-password.tsx checks the
        // `type` param Supabase appends (`signup` vs `recovery`) and routes
        // a signup confirmation on into / itself once the exchange
        // succeeds. Same redirect-URL-allowlist requirement as
        // resetPasswordForEmail below.
        const { error } = await supabase.auth.signUp({
          email,
          password,
          options: { emailRedirectTo: authRedirectUrl('/reset-password') },
        });
        return { error: error?.message ?? null };
      },
      signOut: async () => {
        await supabase.auth.signOut();
      },
      resetPasswordForEmail: async (email) => {
        const { error } = await supabase.auth.resetPasswordForEmail(email, {
          redirectTo: authRedirectUrl('/reset-password'),
        });
        return { error: error?.message ?? null };
      },
    }),
    [session, isLoading, mfaRequired, refreshMfaStatus]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}
