import type { PropsWithChildren } from 'react';
import { useId, useState } from 'react';
import { StyleSheet, View, type StyleProp, type ViewStyle } from 'react-native';
import Svg, { Defs, RadialGradient, Rect, Stop } from 'react-native-svg';

import { Colors } from '@/constants/theme';

/**
 * The app's card/surface look: a pearl card with a soft shadow, a colored
 * glow blooming from the top-left corner, and a crisp neutral hairline
 * border (Colors.light.cardBorder) — the glow still carries each card's
 * module color, the border stays uniform for consistent, precise definition
 * across every card regardless of accent. Used everywhere a bordered
 * content box was previously ad-hoc-styled per screen.
 */
export function Surface({
  children,
  style,
  accentColor,
}: PropsWithChildren<{ style?: StyleProp<ViewStyle>; accentColor?: string }>) {
  // Each card needs its own SVG gradient id — a hardcoded id would collide
  // across the many Surface instances a single screen renders (url(#id)
  // resolves against the whole document on web, so duplicates would all
  // point at whichever definition rendered last).
  const gradientId = `surfaceGlow-${useId().replace(/[^a-zA-Z0-9]/g, '')}`;
  const [size, setSize] = useState({ width: 0, height: 0 });
  const glowColor = accentColor ?? Colors.light.tint;

  return (
    <View
      // Some callers (e.g. the wishlist screen's form card) apply their
      // own position/zIndex via `style` to keep an autocomplete dropdown
      // inside this Surface painting above other content below it.
      // Without collapsable={false}, Android can still flatten this View
      // into its parent for a cheaper native view hierarchy, which drops
      // that positioning/stacking (and can corrupt touch-target
      // boundaries for whatever's nested inside) regardless of what the
      // style prop asked for — same fix select-modal.tsx already needed.
      collapsable={false}
      style={[
        styles.container,
        { backgroundColor: Colors.light.surface, borderColor: Colors.light.cardBorder },
        style,
      ]}>
      {/* Clipped separately from the card itself — overflow:hidden on the same
          view as a shadow suppresses the shadow entirely on iOS/Android. */}
      <View
        style={styles.glowClip}
        pointerEvents="none"
        onLayout={(e) => setSize({ width: e.nativeEvent.layout.width, height: e.nativeEvent.layout.height })}>
        {size.width > 0 && size.height > 0 ? (
          <Svg width={size.width} height={size.height}>
            <Defs>
              {/* Peak lowered (0.4→0.22) and pulled tighter into the corner
                  (r 85%→65%) — this radial's cx/cy (10%, 8%) sits almost
                  exactly where row/detail-page text starts, so its old peak
                  opacity was washing out contrast right under the label
                  text on pages that stack many Surfaces (checklists,
                  detail rows), not just adding a corner accent. */}
              <RadialGradient id={gradientId} cx="10%" cy="8%" r="65%">
                <Stop offset="0%" stopColor={glowColor} stopOpacity={0.22} />
                <Stop offset="60%" stopColor={glowColor} stopOpacity={0.09} />
                <Stop offset="100%" stopColor={glowColor} stopOpacity={0} />
              </RadialGradient>
            </Defs>
            <Rect width={size.width} height={size.height} fill={`url(#${gradientId})`} />
          </Svg>
        ) : null}
      </View>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 18,
    borderWidth: 1,
    padding: 16,
    gap: 8,
    // Deliberately no shadow/elevation at all — a prior version had
    // shadowXxx props with no elevation, which render on iOS/web (shadowXxx
    // works without elevation there) but are inert on Android without it,
    // so cards read as flat/clean on Android and noticeably muted (a soft
    // dark shadow bleeding through the translucent Colors.light.surface
    // background) on iOS/web — the same card looked different per platform.
    // Adding elevation to match wasn't the fix: elevation needs an opaque
    // backing to render cleanly, and this card's background is
    // deliberately translucent, which produced a visible rectangular
    // artifact behind content on Android when the two were combined.
    // Dropping the shadow entirely instead makes every platform render the
    // same border-only card Android already had.
  },
  glowClip: {
    ...StyleSheet.absoluteFillObject,
    borderRadius: 18,
    overflow: 'hidden',
  },
});
