import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { DateInput } from '@/components/date-input';
import { ScopeSwitch } from '@/components/scope-switch';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { TransactionRow as TransactionRowItem } from '@/components/transaction-row';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { LOCAL_CURRENCY, useCurrency } from '@/contexts/currency-context';
import { useScope } from '@/contexts/scope-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { computeBudgetProgress } from '@/lib/budgets';
import { formatMoney } from '@/lib/currency';
import { fetchAllRows } from '@/lib/fetchAll';
import { formatDateDisplay, toDateOnlyString } from '@/lib/format';
import { detectRecurringMerchants, totalMonthlyRecurringCost } from '@/lib/recurringTransactions';
import { compareSpendByCategory, summarizeSpendByCategory, summarizeSpendByCountry, type CategorySpend } from '@/lib/spend';
import { supabase } from '@/lib/supabase';
import { generatePeriods, type Period } from '@/lib/wealthSeries';
import type {
  AccountRow,
  BudgetRow,
  CategoryRow,
  CategoryRuleRow,
  CountryVisitedRow,
  CreditCardRow,
  TransactionRow,
} from '@/types/database';

const ACCENT = ModuleAccents.spend;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

type Granularity = 'week' | 'month' | 'custom';

const GRANULARITY_OPTIONS: { value: Granularity; label: string }[] = [
  { value: 'week', label: 'Week' },
  { value: 'month', label: 'Month' },
  { value: 'custom', label: 'Custom' },
];

type DetailView = 'category' | 'transactions';

const DETAIL_VIEW_OPTIONS: { value: DetailView; label: string }[] = [
  { value: 'category', label: 'By category' },
  { value: 'transactions', label: 'Transactions' },
];

function previousPeriod(period: Period): Period {
  const end = new Date(period.start.getTime() - MS_PER_DAY);
  const start = new Date(end.getTime() - (period.end.getTime() - period.start.getTime()));
  return { start, end };
}

function inPeriod(dateStr: string, period: Period): boolean {
  return dateStr >= toDateOnlyString(period.start) && dateStr <= toDateOnlyString(period.end);
}

function formatTotals(totals: { currency: string; amount: number }[]): string {
  return totals.map((t) => formatMoney(Math.abs(t.amount), t.currency)).join(' · ');
}

export default function SpendScreen() {
  const router = useRouter();
  const { homeCountry, convert, convertToCurrency, displayCurrency } = useCurrency();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const [granularity, setGranularity] = useState<Granularity>('month');
  const [detailView, setDetailView] = useState<DetailView>('category');
  const [customStart, setCustomStart] = useState(() => {
    const d = new Date();
    d.setDate(d.getDate() - 30);
    return d;
  });
  const [customEnd, setCustomEnd] = useState(new Date());

  const { filterTransactions, filterAccounts, filterCards } = useScope();
  const [allTransactions, setTransactions] = useState<TransactionRow[]>([]);
  const [categories, setCategories] = useState<CategoryRow[]>([]);
  const [categoryRules, setCategoryRules] = useState<CategoryRuleRow[]>([]);
  const [visits, setVisits] = useState<CountryVisitedRow[]>([]);
  const [allAccounts, setAccounts] = useState<AccountRow[]>([]);
  const [allCards, setCards] = useState<CreditCardRow[]>([]);
  const transactions = filterTransactions(allTransactions);
  const accounts = filterAccounts(allAccounts);
  const cards = filterCards(allCards);
  const [budgets, setBudgets] = useState<BudgetRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const [txResult, categoriesResult, categoryRulesResult, visitsResult, accountsResult, cardsResult, budgetsResult] =
      await Promise.all([
        fetchAllRows<TransactionRow>((from, to) =>
          supabase.from('transactions').select('*').order('date', { ascending: false }).order('id').range(from, to)
        ),
        supabase.from('categories').select('*'),
        supabase.from('category_rules').select('*'),
        supabase.from('countries_visited').select('*'),
        supabase.from('accounts').select('*'),
        supabase.from('credit_cards').select('*'),
        supabase.from('budgets').select('*'),
      ]);

    if (txResult.error) {
      setError(txResult.error.message);
      setIsLoading(false);
      return;
    }

    setTransactions(txResult.data);
    setCategories(categoriesResult.data ?? []);
    setCategoryRules(categoryRulesResult.data ?? []);
    setVisits(visitsResult.data ?? []);
    setAccounts(accountsResult.data ?? []);
    setCards(cardsResult.data ?? []);
    setBudgets(budgetsResult.data ?? []);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  const currentPeriod: Period = granularity === 'custom' ? { start: customStart, end: customEnd } : generatePeriods(granularity, 2)[1];
  const priorPeriod: Period =
    granularity === 'custom' ? previousPeriod(currentPeriod) : generatePeriods(granularity, 2)[0];

  const categoryNameById = new Map(categories.map((c) => [c.id, c.name]));

  // Spend only: excludes internal transfers and positive (income/refund) amounts — this dashboard is about money going out.
  const spendTransactions = transactions.filter((tx) => !tx.is_internal_transfer && tx.amount < 0);
  const currentTx = spendTransactions.filter((tx) => inPeriod(tx.date, currentPeriod));
  const priorTx = spendTransactions.filter((tx) => inPeriod(tx.date, priorPeriod));

  const currentSpend: CategorySpend[] = summarizeSpendByCategory(currentTx, categoryNameById, convert);
  const priorSpend: CategorySpend[] = summarizeSpendByCategory(priorTx, categoryNameById, convert);
  const trends = compareSpendByCategory(currentSpend, priorSpend);
  const excludedAccountIds = new Set(accounts.filter((a) => a.excluded_from_country_tracking).map((a) => a.id));
  const countrySpend = summarizeSpendByCountry(currentTx, visits, homeCountry, convert, excludedAccountIds);

  const totalsByCurrency = new Map<string, number>();
  for (const cat of currentSpend) {
    for (const t of cat.totals) {
      totalsByCurrency.set(t.currency, (totalsByCurrency.get(t.currency) ?? 0) + t.amount);
    }
  }
  const totalSpend = Array.from(totalsByCurrency.entries()).map(([currency, amount]) => ({ currency, amount }));

  // Both computed off the FULL transaction history, not the period-filtered
  // slice above — recurring detection needs the whole timeline to find a
  // pattern, and computeBudgetProgress determines its own current-month
  // window internally regardless of the period selector's own granularity.
  const recurringMerchants = detectRecurringMerchants(transactions, convert);
  const monthlyRecurringCost = totalMonthlyRecurringCost(recurringMerchants);
  // When "Local" is selected, convert() is a no-op and merchants can end up
  // in different currencies — same caveat lib/spend.ts's own totals accept
  // in that mode. Falls back to the first merchant's own currency rather
  // than a hardcoded default, so the figure at least matches SOMETHING on
  // screen instead of silently mislabeling a EUR total as USD.
  const recurringCostCurrency = displayCurrency !== LOCAL_CURRENCY ? displayCurrency : (recurringMerchants[0]?.currency ?? 'USD');
  const budgetProgress = computeBudgetProgress(budgets, transactions, visits, homeCountry, accounts, convertToCurrency);
  const overBudgetCount = budgetProgress.filter((p) => p.percentUsed >= 100).length;

  const accountNameById = new Map(accounts.map((a) => [a.id, a.name]));
  const cardNameById = new Map(cards.map((c) => [c.id, `${c.issuer} · ${c.name}`]));
  function sourceLabel(tx: TransactionRow): string {
    if (tx.account_id) return accountNameById.get(tx.account_id) ?? 'Account';
    if (tx.card_id) return cardNameById.get(tx.card_id) ?? 'Card';
    return 'Unknown source';
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView contentContainerStyle={styles.content}>
        <ScopeSwitch accent={ACCENT} onColor={ModuleAccentOnColor.spend} />
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Spend Detail
          </ThemedText>
          <Pressable onPress={() => router.push('/spend/rules')} hitSlop={12}>
            <ThemedText type="link">Rules</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedView style={styles.chipRow}>
          {GRANULARITY_OPTIONS.map((option) => {
            const isSelected = option.value === granularity;
            return (
              <Pressable
                key={option.value}
                onPress={() => setGranularity(option.value)}
                style={[
                  styles.chip,
                  { borderColor: ACCENT, backgroundColor: isSelected ? ACCENT : 'transparent' },
                ]}>
                <ThemedText style={isSelected ? { color: ModuleAccentOnColor.spend } : undefined}>
                  {option.label}
                </ThemedText>
              </Pressable>
            );
          })}
        </ThemedView>

        {granularity === 'custom' ? (
          <ThemedView style={styles.customRow}>
            <DateInput
              value={customStart}
              onChange={(date) => {
                setCustomStart(date);
                if (customEnd < date) setCustomEnd(date);
              }}
              accentColor={ACCENT}
            />
            <ThemedText>&rarr;</ThemedText>
            <DateInput value={customEnd} onChange={setCustomEnd} accentColor={ACCENT} minimumDate={customStart} />
          </ThemedView>
        ) : null}

        {isLoading ? (
          <ActivityIndicator style={styles.loading} color={ACCENT} />
        ) : (
          <>
            <Surface accentColor={ACCENT}>
              <ThemedText style={styles.muted}>
                {formatDateDisplay(toDateOnlyString(currentPeriod.start))} &rarr;{' '}
                {formatDateDisplay(toDateOnlyString(currentPeriod.end))}
              </ThemedText>
              <ThemedText type="mono" style={styles.totalValue}>
                {totalSpend.length > 0 ? formatTotals(totalSpend) : formatMoney(0, 'USD')}
              </ThemedText>
              <ThemedText style={styles.muted}>Total spend</ThemedText>
            </Surface>

            <ThemedView style={styles.summaryCardRow}>
              <Pressable style={styles.summaryCardFlex} onPress={() => router.push('/spend/subscriptions')}>
                <Surface accentColor={ACCENT}>
                  <ThemedText style={styles.muted}>Subscriptions</ThemedText>
                  <ThemedText type="mono" style={styles.summaryValue} numberOfLines={1} adjustsFontSizeToFit>
                    {recurringMerchants.length}
                  </ThemedText>
                  <ThemedText style={styles.muted} numberOfLines={1}>
                    {recurringMerchants.length > 0 ? `~${formatMoney(monthlyRecurringCost, recurringCostCurrency)}/mo` : 'None found'}
                  </ThemedText>
                </Surface>
              </Pressable>
              <Pressable style={styles.summaryCardFlex} onPress={() => router.push('/spend/budgets')}>
                <Surface accentColor={ACCENT}>
                  <ThemedText style={styles.muted}>Budgets</ThemedText>
                  <ThemedText type="mono" style={styles.summaryValue} numberOfLines={1} adjustsFontSizeToFit>
                    {budgetProgress.length}
                  </ThemedText>
                  <ThemedText
                    style={[styles.muted, overBudgetCount > 0 ? { color: Colors.light.negative } : null]}
                    numberOfLines={1}>
                    {budgetProgress.length === 0
                      ? 'None set'
                      : overBudgetCount > 0
                        ? `${overBudgetCount} over limit`
                        : 'On track'}
                  </ThemedText>
                </Surface>
              </Pressable>
            </ThemedView>

            <ThemedView style={[styles.chipRow, styles.sectionSpacing]}>
              {DETAIL_VIEW_OPTIONS.map((option) => {
                const isSelected = option.value === detailView;
                return (
                  <Pressable
                    key={option.value}
                    onPress={() => setDetailView(option.value)}
                    style={[styles.chip, { borderColor: ACCENT, backgroundColor: isSelected ? ACCENT : 'transparent' }]}>
                    <ThemedText style={isSelected ? { color: ModuleAccentOnColor.spend } : undefined}>
                      {option.label}
                    </ThemedText>
                  </Pressable>
                );
              })}
            </ThemedView>

            {detailView === 'category' ? (
              <>
                {currentSpend.length === 0 ? (
                  <ThemedText style={styles.muted}>No spend logged this period.</ThemedText>
                ) : null}
                <ThemedView style={styles.grid}>
                  {currentSpend.map((entry) => (
                    <Pressable
                      key={entry.categoryId ?? 'uncategorized'}
                      style={styles.gridTile}
                      onPress={() =>
                        router.push(
                          `/spend/${entry.categoryId ?? 'uncategorized'}?start=${toDateOnlyString(currentPeriod.start)}&end=${toDateOnlyString(currentPeriod.end)}`
                        )
                      }>
                      <Surface accentColor={ACCENT}>
                        <ThemedText type="defaultSemiBold" numberOfLines={1}>
                          {entry.categoryName}
                        </ThemedText>
                        <ThemedText type="mono" style={styles.muted} numberOfLines={1}>
                          {formatTotals(entry.totals)}
                        </ThemedText>
                      </Surface>
                    </Pressable>
                  ))}
                </ThemedView>
              </>
            ) : (
              <>
                {currentTx.length === 0 ? <ThemedText style={styles.muted}>No transactions this period.</ThemedText> : null}
                {currentTx.map((tx) => (
                  <TransactionRowItem
                    key={tx.id}
                    transaction={tx}
                    accentColor={ACCENT}
                    convert={convert}
                    categories={categories}
                    categoryRules={categoryRules}
                    visits={visits}
                    homeCountry={homeCountry}
                    excludedAccountIds={excludedAccountIds}
                    subtitle={sourceLabel(tx)}
                    onChange={(updated) => setTransactions((prev) => prev.map((t) => (t.id === updated.id ? updated : t)))}
                    onCategoryCreated={(category) => setCategories((prev) => [...prev, category])}
                  />
                ))}
              </>
            )}

            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
              Trends vs previous period
            </ThemedText>
            {trends.length === 0 ? <ThemedText style={styles.muted}>Not enough data to compare yet.</ThemedText> : null}
            {trends.map((trend) => (
              <Surface key={trend.categoryId ?? 'uncategorized'} accentColor={ACCENT}>
                <ThemedView style={styles.rowBetween}>
                  <ThemedText type="defaultSemiBold">{trend.categoryName}</ThemedText>
                  <ThemedText
                    type="mono"
                    style={trend.change > 0 ? styles.negative : trend.change < 0 ? styles.positive : styles.muted}>
                    {trend.change > 0 ? '↑' : trend.change < 0 ? '↓' : '–'} {formatMoney(Math.abs(trend.change), trend.currency || 'USD')}
                  </ThemedText>
                </ThemedView>
                <ThemedText style={styles.muted}>
                  {formatMoney(Math.abs(trend.previousAmount), trend.currency || 'USD')} &rarr;{' '}
                  {formatMoney(Math.abs(trend.currentAmount), trend.currency || 'USD')}
                </ThemedText>
              </Surface>
            ))}

            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
              By country
            </ThemedText>
            {countrySpend.length === 0 ? (
              <ThemedText style={styles.muted}>No spend logged this period.</ThemedText>
            ) : null}
            {countrySpend.map((entry) => (
              <Surface key={entry.country} accentColor={ACCENT}>
                <ThemedView style={styles.rowBetween}>
                  <ThemedText type="defaultSemiBold">{entry.country}</ThemedText>
                  <ThemedText type="mono">{formatTotals(entry.totals)}</ThemedText>
                </ThemedView>
              </Surface>
            ))}
          </>
        )}
      </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 4,
  },
  chipRow: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
  },
  chip: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 16,
    paddingHorizontal: 16,
    paddingVertical: 8,
  },
  grid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    justifyContent: 'space-between',
    rowGap: 12,
  },
  gridTile: {
    width: '48%',
  },
  customRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
  },
  dateInput: {
    flex: 1,
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
  },
  sectionSpacing: {
    marginTop: 16,
  },
  rowBetween: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  totalValue: {
    fontSize: 26,
  },
  summaryCardRow: {
    flexDirection: 'row',
    gap: 8,
    backgroundColor: 'transparent',
  },
  summaryCardFlex: {
    flex: 1,
  },
  summaryValue: {
    fontSize: 20,
  },
  positive: {
    color: Colors.light.positive,
  },
  negative: {
    color: Colors.light.negative,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  loading: {
    marginTop: 32,
  },
  error: {
    color: Colors.light.negative,
  },
});
