import { useEffect, useRef, useState, type ReactNode } from 'react';
import { Modal, Pressable, ScrollView, StyleSheet, View } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { Colors } from '@/constants/theme';

const MONTH_LABELS = Array.from({ length: 12 }, (_, i) => new Date(2000, i, 1).toLocaleDateString(undefined, { month: 'short' }));
// Same generous fixed window as components/date-input.tsx's own year list —
// a browsing calendar can legitimately be paged to a trip from decades ago
// or one still years out, so this just needs to comfortably cover both.
const YEAR_RANGE = { past: 80, future: 20 };
const YEAR_ROW_HEIGHT = 49;
const YEAR_COLUMNS = 4;

/**
 * Wraps a month/year header label (e.g. "March 2026") so tapping it opens a
 * month-grid, then year-list, jump picker — the same drill-down pattern as
 * DateInput's own popover, factored out for the several read-only browsing
 * calendars in the app (country calendar, connections travel calendar) that
 * render their own header + ‹ › month-step arrows already but had no way to
 * jump more than one month at a time. Only month and year are meaningful
 * here — day is always normalized to the 1st, since every caller only reads
 * getMonth()/getFullYear() off the result.
 */
export function MonthYearJump({
  value,
  onChange,
  accentColor,
  renderTrigger,
}: {
  value: Date;
  onChange: (date: Date) => void;
  accentColor: string;
  /** Overrides the default "March 2026" text trigger — e.g. a small icon button placed beside a differently-behaved label (see app/connections/[connectionId]/travel.tsx, whose own label is already a tap-to-jump-to-today shortcut). Called with the same `open` handler the default trigger uses. */
  renderTrigger?: (open: () => void) => ReactNode;
}) {
  const [visible, setVisible] = useState(false);
  const [viewMode, setViewMode] = useState<'months' | 'years'>('months');
  const [pendingYear, setPendingYear] = useState(value.getFullYear());
  const yearScrollRef = useRef<ScrollView>(null);

  const currentYear = new Date().getFullYear();
  const years = Array.from(
    { length: YEAR_RANGE.past + YEAR_RANGE.future + 1 },
    (_, i) => currentYear - YEAR_RANGE.past + i
  );

  useEffect(() => {
    if (!visible || viewMode !== 'years') return;
    const index = years.indexOf(pendingYear);
    if (index < 0) return;
    const row = Math.floor(index / YEAR_COLUMNS);
    const targetY = Math.max(0, row * YEAR_ROW_HEIGHT - YEAR_ROW_HEIGHT * 2);
    const timer = setTimeout(() => yearScrollRef.current?.scrollTo({ y: targetY, animated: false }), 0);
    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [visible, viewMode]);

  function open() {
    setPendingYear(value.getFullYear());
    setViewMode('months');
    setVisible(true);
  }

  function selectMonth(monthIndex: number) {
    onChange(new Date(pendingYear, monthIndex, 1));
    setVisible(false);
  }

  function selectYear(year: number) {
    setPendingYear(year);
    setViewMode('months');
  }

  return (
    <>
      {renderTrigger ? (
        renderTrigger(open)
      ) : (
        <Pressable onPress={open} hitSlop={6}>
          <ThemedText type="defaultSemiBold">
            {value.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}
          </ThemedText>
        </Pressable>
      )}

      <Modal visible={visible} transparent animationType="fade" onRequestClose={() => setVisible(false)}>
        <Pressable style={styles.backdrop} onPress={() => setVisible(false)}>
          <Pressable style={[styles.card, { borderColor: accentColor }]} onPress={(e) => e.stopPropagation()}>
            <View style={styles.header}>
              {viewMode === 'months' ? (
                <>
                  <Pressable onPress={() => setPendingYear((y) => y - 1)} hitSlop={10}>
                    <ThemedText style={[styles.nav, { color: accentColor }]}>‹</ThemedText>
                  </Pressable>
                  <Pressable onPress={() => setViewMode('years')} hitSlop={6}>
                    <ThemedText type="defaultSemiBold">{pendingYear}</ThemedText>
                  </Pressable>
                  <Pressable onPress={() => setPendingYear((y) => y + 1)} hitSlop={10}>
                    <ThemedText style={[styles.nav, { color: accentColor }]}>›</ThemedText>
                  </Pressable>
                </>
              ) : (
                <ThemedText type="defaultSemiBold">Select a year</ThemedText>
              )}
            </View>

            {viewMode === 'months' ? (
              <View style={styles.grid}>
                {MONTH_LABELS.map((label, index) => {
                  const isSelected = index === value.getMonth() && pendingYear === value.getFullYear();
                  return (
                    <Pressable
                      key={label}
                      onPress={() => selectMonth(index)}
                      style={[styles.gridCell, isSelected ? { backgroundColor: accentColor } : null]}>
                      <ThemedText style={isSelected ? styles.cellTextSelected : styles.cellText}>{label}</ThemedText>
                    </Pressable>
                  );
                })}
              </View>
            ) : (
              <ScrollView ref={yearScrollRef} style={styles.yearScroll}>
                <View style={styles.grid}>
                  {years.map((year) => {
                    const isSelected = year === pendingYear;
                    return (
                      <Pressable
                        key={year}
                        onPress={() => selectYear(year)}
                        style={[styles.gridCell, isSelected ? { backgroundColor: accentColor } : null]}>
                        <ThemedText style={isSelected ? styles.cellTextSelected : styles.cellText}>{year}</ThemedText>
                      </Pressable>
                    );
                  })}
                </View>
              </ScrollView>
            )}
          </Pressable>
        </Pressable>
      </Modal>
    </>
  );
}

const styles = StyleSheet.create({
  backdrop: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: 'rgba(0,0,0,0.25)',
  },
  card: {
    width: 300,
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 14,
    padding: 14,
    backgroundColor: Colors.light.backgroundSolid,
    shadowColor: '#000',
    shadowOpacity: 0.15,
    shadowRadius: 8,
    shadowOffset: { width: 0, height: 4 },
    elevation: 6,
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 10,
  },
  nav: {
    fontSize: 20,
    fontWeight: '700',
    paddingHorizontal: 10,
  },
  grid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
  },
  gridCell: {
    width: '25%',
    aspectRatio: 1.4,
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: 10,
  },
  cellText: {
    fontSize: 14,
    color: Colors.light.text,
  },
  cellTextSelected: {
    color: Colors.light.backgroundSolid,
    fontWeight: '700',
  },
  yearScroll: {
    maxHeight: 280,
  },
});
