import { useRouter } from 'expo-router';
import { useState } from 'react';
import { Pressable, StyleSheet, Switch } from 'react-native';

import { CategoryPicker } from '@/components/category-picker';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import type { ConvertedAmount } from '@/contexts/currency-context';
import { matchCategoryRule } from '@/lib/csvImport';
import { formatMoney } from '@/lib/currency';
import { formatDateDisplay } from '@/lib/format';
import { attributedLocationForDate } from '@/lib/spend';
import { supabase } from '@/lib/supabase';
import type { CategoryRow, CategoryRuleRow, CountryVisitedRow, TransactionRow as TransactionRowType } from '@/types/database';

/**
 * One row for one transaction — the single place every "levels of a
 * transaction" detail (absolute value + credit/debit, category, country/city
 * attribution + the "not related to this trip" override) lives, so every
 * screen that lists transactions (Card Spend Detail, Card detail, Account
 * detail, Spend category detail, City spend detail) shows the exact same
 * thing instead of five screens slowly drifting apart. Tapping the main
 * content navigates to the full edit screen (app/transactions/[id].tsx);
 * the category badge and travel toggle are their own inner Pressables so
 * they don't trigger that navigation too.
 */
export function TransactionRow({
  transaction,
  accentColor,
  convert,
  categories,
  categoryRules,
  visits,
  homeCountry,
  excludedAccountIds,
  subtitle,
  onChange,
  onCategoryCreated,
}: {
  transaction: TransactionRowType;
  accentColor: string;
  convert: (amount: number, fromCurrency: string) => ConvertedAmount;
  categories: CategoryRow[];
  categoryRules: CategoryRuleRow[];
  visits: Pick<CountryVisitedRow, 'country' | 'city' | 'entry_date' | 'exit_date'>[];
  homeCountry: string | null;
  /** account_ids with accounts.excluded_from_country_tracking set — forces home-country attribution for this row and hides the per-transaction toggle, since it would have no effect. */
  excludedAccountIds: Set<string>;
  /** Secondary label shown next to the date — e.g. the card or account name. */
  subtitle?: string;
  /** Called with the updated row right after a category change or travel-toggle flip, so the caller's own list state stays in sync. */
  onChange: (updated: TransactionRowType) => void;
  /** Called when a brand-new category is created from this row's picker, so the caller's own `categories` list stays in sync too. */
  onCategoryCreated: (category: CategoryRow) => void;
}) {
  const router = useRouter();
  const [showCategoryPicker, setShowCategoryPicker] = useState(false);

  const categoryNameById = new Map(categories.map((c) => [c.id, c.name]));

  const converted = convert(transaction.amount, transaction.currency);
  const isCredit = transaction.amount >= 0;
  const catId = transaction.category_id ?? matchCategoryRule(transaction.merchant ?? '', categoryRules);
  const categoryLabel = catId ? (categoryNameById.get(catId) ?? 'Unknown') : 'Uncategorized';
  const isAccountExcluded = !!transaction.account_id && excludedAccountIds.has(transaction.account_id);
  const rawLocation = attributedLocationForDate(transaction.date, visits, homeCountry, false);
  const location = attributedLocationForDate(
    transaction.date,
    visits,
    homeCountry,
    transaction.excluded_from_travel_spend || isAccountExcluded
  );
  const locationLabel = location.city ? `${location.city}, ${location.country}` : location.country;
  // Only worth offering the override when a real trip actually covers this
  // date — nothing to opt out of on a home-country day, and nothing to
  // toggle when the account already forces home-country attribution.
  const showTravelToggle = rawLocation.country !== (homeCountry ?? 'Unknown') && !isAccountExcluded;

  async function handleCategorySelect(categoryId: string) {
    setShowCategoryPicker(false);
    onChange({ ...transaction, category_id: categoryId });
    await supabase.from('transactions').update({ category_id: categoryId }).eq('id', transaction.id);
  }

  async function handleToggleTravel() {
    const next = !transaction.excluded_from_travel_spend;
    onChange({ ...transaction, excluded_from_travel_spend: next });
    await supabase.from('transactions').update({ excluded_from_travel_spend: next }).eq('id', transaction.id);
  }

  return (
    <Surface accentColor={accentColor} style={styles.card}>
      <Pressable onPress={() => router.push(`/transactions/${transaction.id}`)}>
        <ThemedView style={styles.rowBetween}>
          <ThemedText type="defaultSemiBold" style={styles.flexShrink} numberOfLines={1}>
            {transaction.merchant || 'Transaction'}
          </ThemedText>
          <ThemedView style={styles.amountGroup}>
            <ThemedText type="mono">{formatMoney(Math.abs(converted.amount), converted.currency)}</ThemedText>
            <ThemedText
              style={[styles.creditDebitTag, { color: isCredit ? Colors.light.positive : Colors.light.negative }]}>
              {isCredit ? 'Credit' : 'Debit'}
            </ThemedText>
          </ThemedView>
        </ThemedView>
        <ThemedView style={styles.rowBetween}>
          <ThemedText type="mono" style={styles.muted}>
            {formatDateDisplay(transaction.date)}
          </ThemedText>
          {subtitle ? (
            <ThemedText style={styles.muted} numberOfLines={1}>
              {subtitle}
            </ThemedText>
          ) : null}
        </ThemedView>
      </Pressable>
      <ThemedView style={styles.rowBetween}>
        <Pressable onPress={() => setShowCategoryPicker(true)} hitSlop={6}>
          <ThemedView style={[styles.categoryBadge, { borderColor: accentColor }]}>
            <ThemedText style={[styles.categoryBadgeText, { color: accentColor }]}>{categoryLabel}</ThemedText>
          </ThemedView>
        </Pressable>
        <ThemedText style={styles.muted} numberOfLines={1}>
          {locationLabel}
        </ThemedText>
      </ThemedView>
      {showTravelToggle ? (
        <ThemedView style={styles.travelToggleRow}>
          <ThemedText style={styles.muted}>Not related to this trip</ThemedText>
          <Switch value={transaction.excluded_from_travel_spend} onValueChange={handleToggleTravel} trackColor={{ true: accentColor }} />
        </ThemedView>
      ) : null}
      <CategoryPicker
        visible={showCategoryPicker}
        onClose={() => setShowCategoryPicker(false)}
        categories={categories}
        selectedCategoryId={catId}
        onSelect={handleCategorySelect}
        onCategoryCreated={onCategoryCreated}
        accentColor={accentColor}
      />
    </Surface>
  );
}

const styles = StyleSheet.create({
  card: {
    gap: 6,
  },
  rowBetween: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 8,
  },
  flexShrink: {
    flexShrink: 1,
  },
  amountGroup: {
    alignItems: 'flex-end',
    gap: 2,
  },
  creditDebitTag: {
    fontSize: 11,
    fontWeight: '600',
    textTransform: 'uppercase',
  },
  categoryBadge: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 12,
    paddingHorizontal: 10,
    paddingVertical: 3,
  },
  categoryBadgeText: {
    fontSize: 12,
    fontWeight: '600',
  },
  travelToggleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingTop: 4,
    borderTopWidth: StyleSheet.hairlineWidth,
    borderTopColor: Colors.light.icon,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
});
