import { useEffect } from 'react';
import { ActivityIndicator } from 'react-native';

import { ThemedView } from '@/components/themed-view';
import { useTour } from '@/contexts/tour-context';

/**
 * A trigger, not a screen — the actual walkthrough is TourOverlay, a
 * floating guidance card that follows real navigation across the app's
 * real screens (see contexts/tour-context.tsx) rather than a dedicated
 * static slideshow route. Reached two ways, both still just navigating
 * here: the first-run redirect in app/index.tsx (needsOnboarding), and
 * "Replay Walkthrough" in Account. startTour() immediately replaces this
 * route with its own first step's real destination, so this spinner is
 * never really seen.
 */
export default function OnboardingTriggerScreen() {
  const { startTour } = useTour();

  useEffect(() => {
    startTour();
  }, [startTour]);

  return (
    <ThemedView variant="screen" style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>
      <ActivityIndicator />
    </ThemedView>
  );
}
