import { createContext, useContext, useEffect, useMemo, useState, type PropsWithChildren } from 'react';

import { useAuth } from '@/contexts/auth-context';
import { avatarPublicUrl } from '@/lib/avatar';
import { refreshExchangeRatesIfStale } from '@/lib/exchangeRates';
import { supabase } from '@/lib/supabase';

/** Sentinel for "show native currency, no conversion" — distinct from any real currency code. */
export const LOCAL_CURRENCY = 'LOCAL';

export type ConvertedAmount = { amount: number; currency: string };

type CurrencyContextValue = {
  displayCurrency: string;
  homeCountry: string | null;
  availableCurrencies: string[];
  /** Full display name per currency code (e.g. "CAD" -> "Canadian Dollar"), from exchange_rates.name. Missing for any code not yet refreshed since that column was added. */
  currencyNames: Record<string, string>;
  isLoading: boolean;
  setDisplayCurrency: (currency: string) => Promise<void>;
  setHomeCountry: (country: string | null) => Promise<void>;
  /** Respects "Local" — no-ops and returns the native amount/currency unchanged. */
  convert: (amount: number, fromCurrency: string) => ConvertedAmount;
  /** Pure rate conversion between two explicit currencies — no "Local" concept. */
  convertToCurrency: (amount: number, fromCurrency: string, toCurrency: string) => number;
  /** Country names the user has opted to show a neutral marker for instead of their flag. */
  hiddenFlagCountries: string[];
  setFlagHidden: (country: string, hidden: boolean) => Promise<void>;
  /** Set when the last settings save (home country, display currency, or flag visibility) failed to persist — the in-app state still reflects the attempted change, but a reload will lose it until this is resolved. */
  settingsError: string | null;
  /** True only for a genuinely new user — no user_settings row exists yet at all (that row is only ever created lazily, on first upsert, not at signup). Existing accounts already have a row from things they've set, so this never re-triggers for them. Stays false while isLoading. */
  needsOnboarding: boolean;
  /** Marks onboarding done — flips needsOnboarding false immediately (optimistic) and persists a user_settings row so it stays false on reload, even if the walkthrough was skipped without setting anything else. */
  completeOnboarding: () => Promise<void>;
  /** From user_settings.full_name — null until set in Account > Account details. */
  fullName: string | null;
  setFullName: (name: string | null) => Promise<void>;
  /** Public URL for the user's profile photo, derived from user_settings.avatar_path — null if none uploaded. */
  avatarUrl: string | null;
  /** The raw storage path backing avatarUrl — exposed so the Account screen can remove the previous file after uploading a new one. */
  avatarPath: string | null;
  /** Pass the storage path just uploaded to the "avatars" bucket, or null to clear it. */
  setAvatarPath: (path: string | null) => Promise<void>;
};

const CurrencyContext = createContext<CurrencyContextValue | null>(null);

export function CurrencyProvider({ children }: PropsWithChildren) {
  const { session } = useAuth();
  const userId = session?.user.id;
  const [displayCurrency, setDisplayCurrencyState] = useState('USD');
  const [homeCountry, setHomeCountryState] = useState<string | null>(null);
  const [hiddenFlagCountries, setHiddenFlagCountriesState] = useState<string[]>([]);
  const [rates, setRates] = useState<Map<string, number>>(new Map());
  const [currencyNames, setCurrencyNames] = useState<Record<string, string>>({});
  const [isLoading, setIsLoading] = useState(true);
  const [settingsError, setSettingsError] = useState<string | null>(null);
  const [needsOnboarding, setNeedsOnboarding] = useState(false);
  const [fullName, setFullNameState] = useState<string | null>(null);
  const [avatarPath, setAvatarPathState] = useState<string | null>(null);

  useEffect(() => {
    if (!userId) {
      setIsLoading(false);
      return;
    }

    let cancelled = false;

    async function load() {
      await refreshExchangeRatesIfStale();

      const [ratesResult, settingsResult] = await Promise.all([
        supabase.from('exchange_rates').select('*'),
        supabase
          .from('user_settings')
          .select('display_currency, home_country, hidden_flag_countries, full_name, avatar_path')
          .eq('user_id', userId!)
          .maybeSingle(),
      ]);

      if (cancelled) return;

      if (ratesResult.data) {
        setRates(new Map(ratesResult.data.map((r) => [r.currency, r.rate_to_base])));
        const names: Record<string, string> = {};
        for (const r of ratesResult.data) {
          if (r.name) names[r.currency] = r.name;
        }
        setCurrencyNames(names);
      }
      if (settingsResult.error) {
        // A failure here (e.g. a column the client expects but the DB doesn't
        // have yet) previously meant home country / display currency just
        // silently stayed at their defaults with no indication why.
        console.error('Failed to load user settings:', settingsResult.error.message);
        setSettingsError(`Couldn't load your settings: ${settingsResult.error.message}`);
      } else if (settingsResult.data) {
        setDisplayCurrencyState(settingsResult.data.display_currency);
        setHomeCountryState(settingsResult.data.home_country);
        setHiddenFlagCountriesState(settingsResult.data.hidden_flag_countries ?? []);
        setFullNameState(settingsResult.data.full_name ?? null);
        setAvatarPathState(settingsResult.data.avatar_path ?? null);
        setNeedsOnboarding(false);
      } else {
        // No row at all — genuinely new user, never set anything yet.
        setNeedsOnboarding(true);
      }
      setIsLoading(false);
    }

    load();
    return () => {
      cancelled = true;
    };
    // Keyed on the stable user id, not the session object — Supabase hands
    // back a new session reference on every token refresh, which would
    // otherwise re-run this and clobber a display currency picked in the
    // meantime with whatever this fetch happened to read.
  }, [userId]);

  const value = useMemo<CurrencyContextValue>(() => {
    function convertToCurrency(amount: number, fromCurrency: string, toCurrency: string): number {
      if (fromCurrency === toCurrency) return amount;
      const fromRate = rates.get(fromCurrency);
      const toRate = rates.get(toCurrency);
      if (!fromRate || !toRate) return amount;
      return (amount * fromRate) / toRate;
    }

    async function setDisplayCurrency(currency: string) {
      const previous = displayCurrency;
      setDisplayCurrencyState(currency);
      if (!session) return;
      setSettingsError(null);
      const { error } = await supabase
        .from('user_settings')
        .upsert({ user_id: session.user.id, display_currency: currency }, { onConflict: 'user_id' });
      if (error) {
        console.error('Failed to save display currency:', error.message);
        setDisplayCurrencyState(previous);
        setSettingsError(`Couldn't save currency: ${error.message}`);
      }
    }

    async function setHomeCountry(country: string | null) {
      const previous = homeCountry;
      setHomeCountryState(country);
      if (!session) return;
      setSettingsError(null);
      const { error } = await supabase
        .from('user_settings')
        .upsert({ user_id: session.user.id, home_country: country }, { onConflict: 'user_id' });
      if (error) {
        console.error('Failed to save home country:', error.message);
        setHomeCountryState(previous);
        setSettingsError(`Couldn't save home country: ${error.message}`);
      }
    }

    async function setFullName(name: string | null) {
      const previous = fullName;
      setFullNameState(name);
      if (!session) return;
      setSettingsError(null);
      const { error } = await supabase
        .from('user_settings')
        .upsert({ user_id: session.user.id, full_name: name }, { onConflict: 'user_id' });
      if (error) {
        console.error('Failed to save name:', error.message);
        setFullNameState(previous);
        setSettingsError(`Couldn't save name: ${error.message}`);
      }
    }

    async function setAvatarPath(path: string | null) {
      const previous = avatarPath;
      setAvatarPathState(path);
      if (!session) return;
      setSettingsError(null);
      const { error } = await supabase
        .from('user_settings')
        .upsert({ user_id: session.user.id, avatar_path: path }, { onConflict: 'user_id' });
      if (error) {
        console.error('Failed to save avatar:', error.message);
        setAvatarPathState(previous);
        setSettingsError(`Couldn't save profile photo: ${error.message}`);
      }
    }

    async function setFlagHidden(country: string, hidden: boolean) {
      const previous = hiddenFlagCountries;
      const next = hidden
        ? Array.from(new Set([...hiddenFlagCountries, country]))
        : hiddenFlagCountries.filter((c) => c !== country);
      setHiddenFlagCountriesState(next);
      if (!session) return;
      setSettingsError(null);
      const { error } = await supabase
        .from('user_settings')
        .upsert({ user_id: session.user.id, hidden_flag_countries: next }, { onConflict: 'user_id' });
      if (error) {
        console.error('Failed to save flag preference:', error.message);
        setHiddenFlagCountriesState(previous);
        setSettingsError(`Couldn't save flag preference: ${error.message}`);
      }
    }

    function convert(amount: number, fromCurrency: string): ConvertedAmount {
      if (displayCurrency === LOCAL_CURRENCY) {
        return { amount, currency: fromCurrency };
      }
      return { amount: convertToCurrency(amount, fromCurrency, displayCurrency), currency: displayCurrency };
    }

    async function completeOnboarding() {
      setNeedsOnboarding(false);
      if (!session) return;
      const { error } = await supabase
        .from('user_settings')
        .upsert({ user_id: session.user.id, onboarding_completed_at: new Date().toISOString() }, { onConflict: 'user_id' });
      if (error) {
        // This write was previously unchecked, so a failure here (e.g. a
        // missing column from a migration that was never applied) left no
        // trace: needsOnboarding flipped false in memory for this session,
        // but with no user_settings row ever actually created, the very
        // next app open found no row again and sent the user right back
        // into onboarding — forever, with nothing in the logs to explain
        // why. See settingsError above for the same pattern already used
        // by every other setter in this file.
        console.error('Failed to save onboarding completion:', error.message);
        setSettingsError(`Couldn't save onboarding progress: ${error.message}`);
      }
    }

    return {
      displayCurrency,
      homeCountry,
      availableCurrencies: Array.from(rates.keys()).sort(),
      currencyNames,
      isLoading,
      setDisplayCurrency,
      setHomeCountry,
      convert,
      convertToCurrency,
      hiddenFlagCountries,
      setFlagHidden,
      settingsError,
      needsOnboarding,
      completeOnboarding,
      fullName,
      setFullName,
      avatarUrl: avatarPublicUrl(avatarPath),
      avatarPath,
      setAvatarPath,
    };
  }, [
    displayCurrency,
    homeCountry,
    hiddenFlagCountries,
    rates,
    currencyNames,
    isLoading,
    session,
    settingsError,
    needsOnboarding,
    fullName,
    avatarPath,
  ]);

  return <CurrencyContext.Provider value={value}>{children}</CurrencyContext.Provider>;
}

export function useCurrency() {
  const context = useContext(CurrencyContext);
  if (!context) {
    throw new Error('useCurrency must be used within a CurrencyProvider');
  }
  return context;
}
