import { LinearGradient } from 'expo-linear-gradient';
import { useState } from 'react';
import { Pressable, StyleSheet, View, useWindowDimensions } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import type { CityTripLike } from '@/lib/cityOverlap';
import { showAlert } from '@/lib/alert';
import { formatDateDisplay, toDateOnlyString } from '@/lib/format';
import { computeDayCells, computeRowBands, computeWeekRows, type CalendarViewMode, type HomeLocation } from '@/lib/tripCalendar';

const WEEKDAY_LABELS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

const MONTH_ROW_HEIGHT = 40;
const MONTH_BAND_HEIGHT = 9;
const WEEK_ROW_HEIGHT = 100;
const WEEK_BAND_HEIGHT = 36;

export function TripCalendarGrid({
  currentDate,
  viewMode,
  myTrips,
  partnerTrips,
  myColor,
  partnerColor,
  myHome,
  partnerHome,
}: {
  currentDate: Date;
  viewMode: CalendarViewMode;
  myTrips: CityTripLike[];
  partnerTrips: CityTripLike[];
  myColor: string;
  partnerColor: string;
  /** One-directional per-day fallback to home when the OTHER side is actually traveling there — see computeDayCells. */
  myHome?: HomeLocation | null;
  partnerHome?: HomeLocation | null;
}) {
  const { width: windowWidth } = useWindowDimensions();
  const [rowWidth, setRowWidth] = useState(windowWidth - 32);

  const dayWidth = rowWidth / 7;
  const rowHeight = viewMode === 'month' ? MONTH_ROW_HEIGHT : WEEK_ROW_HEIGHT;
  const bandHeight = viewMode === 'month' ? MONTH_BAND_HEIGHT : WEEK_BAND_HEIGHT;
  const showText = viewMode === 'week';

  const weekRows = computeWeekRows(currentDate, viewMode);
  const todayStr = toDateOnlyString(new Date());

  return (
    <ThemedView onLayout={(e) => setRowWidth(e.nativeEvent.layout.width)}>
      <ThemedView style={styles.weekdayRow}>
        {WEEKDAY_LABELS.map((label) => (
          <ThemedText key={label} style={[styles.weekdayLabel, { width: dayWidth }]}>
            {label}
          </ThemedText>
        ))}
      </ThemedView>

      {weekRows.map((rowDays, rowIndex) => {
        const cells = computeDayCells(rowDays, myTrips, partnerTrips, currentDate, viewMode, myHome, partnerHome);
        const bands = computeRowBands(cells, myColor, partnerColor);

        return (
          <View key={rowIndex} style={[styles.row, { height: rowHeight }]}>
            <View style={styles.dayNumberRow}>
              {rowDays.map((day, i) => {
                const dateStr = cells[i].date;
                const isToday = dateStr === todayStr;
                return (
                  <View key={dateStr} style={{ width: dayWidth, alignItems: 'center' }}>
                    <ThemedText
                      type={isToday ? 'defaultSemiBold' : 'default'}
                      style={[
                        styles.dayNumber,
                        !cells[i].inRange ? styles.dayNumberMuted : null,
                        isToday ? { color: Colors.light.tint } : null,
                      ]}>
                      {day.getDate()}
                    </ThemedText>
                  </View>
                );
              })}
            </View>

            <View style={styles.bandArea}>
              {bands.map((band) => {
                const left = band.startIndex * dayWidth + 1;
                const width = (band.endIndex - band.startIndex + 1) * dayWidth - 2;
                const top = band.track * (bandHeight + 3);
                const startDate = formatDateDisplay(cells[band.startIndex].date);
                const endDate = formatDateDisplay(cells[band.endIndex].date);

                const content = showText ? (
                  <ThemedText
                    numberOfLines={1}
                    ellipsizeMode="tail"
                    style={[styles.bandText, band.isBlend ? styles.bandTextOnBlend : null]}>
                    {band.label}
                  </ThemedText>
                ) : null;

                const handlePress = () =>
                  showAlert(band.label, startDate === endDate ? startDate : `${startDate} → ${endDate}`);

                if (band.isBlend) {
                  return (
                    <Pressable key={band.key} onPress={handlePress} style={[styles.band, { left, width, top, height: bandHeight }]}>
                      <LinearGradient
                        colors={[band.colors[0], band.colors[1]]}
                        start={{ x: 0, y: 0 }}
                        end={{ x: 1, y: 0 }}
                        style={[styles.bandFill, { borderRadius: 4 }]}>
                        {content}
                      </LinearGradient>
                    </Pressable>
                  );
                }

                return (
                  <Pressable
                    key={band.key}
                    onPress={handlePress}
                    style={[
                      styles.band,
                      styles.bandFill,
                      { left, width, top, height: bandHeight, backgroundColor: band.colors[0], borderRadius: 4 },
                    ]}>
                    {content}
                  </Pressable>
                );
              })}
            </View>
          </View>
        );
      })}
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  weekdayRow: {
    flexDirection: 'row',
  },
  weekdayLabel: {
    textAlign: 'center',
    fontSize: 11,
    opacity: 0.6,
  },
  row: {
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: Colors.light.icon,
  },
  dayNumberRow: {
    flexDirection: 'row',
  },
  dayNumber: {
    fontSize: 12,
  },
  dayNumberMuted: {
    opacity: 0.35,
  },
  bandArea: {
    flex: 1,
    position: 'relative',
  },
  band: {
    position: 'absolute',
  },
  bandFill: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 3,
  },
  bandText: {
    fontSize: 11,
    color: '#FFFFFF',
  },
  bandTextOnBlend: {
    fontWeight: '600',
  },
});
