import { useState } from 'react';
import { Modal, Pressable, StyleSheet, TextInput } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { supabase } from '@/lib/supabase';
import type { CategoryRow } from '@/types/database';

/**
 * The one place category selection lives — grouped chips (parent, then its
 * children) exactly like the transaction form's picker already did, plus an
 * "Add category" row at the bottom so a category the app doesn't already
 * have doesn't require a trip to the database. New categories are always
 * created top-level (nesting a fresh category under an existing one is a
 * refinement someone can do later; forcing that choice here just to add
 * "Pet Care" is unnecessary friction). Used by components/transaction-row.tsx
 * and app/transactions/new.tsx & [id].tsx so every category picker in the
 * app is this exact same one.
 */
export function CategoryPicker({
  visible,
  onClose,
  categories,
  selectedCategoryId,
  onSelect,
  onCategoryCreated,
  accentColor,
}: {
  visible: boolean;
  onClose: () => void;
  categories: CategoryRow[];
  selectedCategoryId: string | null;
  onSelect: (categoryId: string) => void;
  /** Called right after a new category is saved, so the caller can append it to whatever local `categories` list it's holding. */
  onCategoryCreated: (category: CategoryRow) => void;
  accentColor: string;
}) {
  const insets = useSafeAreaInsets();
  const { session } = useAuth();
  const [newName, setNewName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const topLevel = categories.filter((c) => c.parent_id === null);
  const childrenByParent = new Map<string, CategoryRow[]>();
  for (const c of categories) {
    if (c.parent_id) childrenByParent.set(c.parent_id, [...(childrenByParent.get(c.parent_id) ?? []), c]);
  }

  async function handleAddCategory() {
    const name = newName.trim();
    if (!name || !session) return;
    setIsSaving(true);
    setError(null);
    const { data, error: insertError } = await supabase
      .from('categories')
      .insert({ user_id: session.user.id, name, parent_id: null })
      .select()
      .single();
    setIsSaving(false);
    if (insertError) {
      setError(insertError.message);
      return;
    }
    setNewName('');
    onCategoryCreated(data);
    onSelect(data.id);
    onClose();
  }

  return (
    <Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}>
      <Pressable style={styles.backdrop} onPress={onClose}>
        <Pressable style={[styles.sheet, { paddingBottom: insets.bottom + 16 }]} onPress={(e) => e.stopPropagation()}>
          <ThemedText type="defaultSemiBold" style={styles.title}>
            Category
          </ThemedText>
          {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

          {topLevel.map((parent) => {
            const children = childrenByParent.get(parent.id) ?? [];
            const options = children.length > 0 ? children : [parent];
            return (
              <ThemedView key={parent.id} style={styles.section}>
                {children.length > 0 ? <ThemedText style={styles.sectionLabel}>{parent.name}</ThemedText> : null}
                <ThemedView style={styles.chipRow}>
                  {options.map((option) => {
                    const isSelected = option.id === selectedCategoryId;
                    return (
                      <Pressable
                        key={option.id}
                        onPress={() => {
                          onSelect(option.id);
                          onClose();
                        }}
                        style={[
                          styles.chip,
                          { borderColor: accentColor, backgroundColor: isSelected ? accentColor : 'transparent' },
                        ]}>
                        <ThemedText style={isSelected ? { color: Colors.light.backgroundSolid } : undefined}>
                          {option.name}
                        </ThemedText>
                      </Pressable>
                    );
                  })}
                </ThemedView>
              </ThemedView>
            );
          })}

          <ThemedView style={styles.addRow}>
            <TextInput
              value={newName}
              onChangeText={setNewName}
              placeholder="New category name"
              placeholderTextColor={Colors.light.textMuted}
              style={[styles.input, { color: Colors.light.text, borderColor: accentColor }]}
              onSubmitEditing={handleAddCategory}
            />
            <Pressable
              onPress={handleAddCategory}
              disabled={!newName.trim() || isSaving}
              style={[styles.addButton, { backgroundColor: accentColor, opacity: !newName.trim() || isSaving ? 0.5 : 1 }]}>
              <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>
                {isSaving ? '...' : 'Add'}
              </ThemedText>
            </Pressable>
          </ThemedView>

          <Pressable onPress={onClose} style={styles.doneButton} hitSlop={8}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </Pressable>
      </Pressable>
    </Modal>
  );
}

const styles = StyleSheet.create({
  backdrop: {
    flex: 1,
    backgroundColor: 'rgba(0,0,0,0.35)',
    justifyContent: 'flex-end',
  },
  sheet: {
    backgroundColor: Colors.light.backgroundSolid,
    borderTopLeftRadius: 18,
    borderTopRightRadius: 18,
    padding: 16,
    gap: 10,
    maxHeight: '80%',
  },
  title: {
    fontSize: 16,
  },
  section: {
    gap: 6,
  },
  sectionLabel: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  chipRow: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
  },
  chip: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 16,
    paddingHorizontal: 12,
    paddingVertical: 6,
  },
  addRow: {
    flexDirection: 'row',
    gap: 8,
    marginTop: 4,
  },
  input: {
    flex: 1,
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 12,
    paddingVertical: 10,
    fontSize: 15,
  },
  addButton: {
    borderRadius: 8,
    paddingHorizontal: 16,
    justifyContent: 'center',
  },
  doneButton: {
    alignSelf: 'center',
    marginTop: 4,
  },
  error: {
    color: Colors.light.negative,
    fontSize: 13,
  },
});
