import { useState } from 'react';
import { Pressable, StyleSheet, View, useWindowDimensions } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { showAlert } from '@/lib/alert';
import { formatDateDisplay, toDateOnlyString } from '@/lib/format';
import {
  computeMultiDayCells,
  computeMultiRowBands,
  computeWeekRows,
  type CalendarViewMode,
  type MultiParty,
} from '@/lib/tripCalendar';

const WEEKDAY_LABELS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

const BAND_GAP = 3;

/**
 * N-party sibling of components/trip-calendar-grid.tsx — same week/month
 * grid shell, but the day-number area and band tracks are sized to however
 * many parties are passed in (that component is fixed at exactly 2), and
 * every band is solid-color (no gradient blend — see computeMultiRowBands'
 * own doc comment for why that doesn't generalize past 2 parties).
 */
export function MultiTripCalendarGrid({
  currentDate,
  viewMode,
  parties,
}: {
  currentDate: Date;
  viewMode: CalendarViewMode;
  parties: MultiParty[];
}) {
  const { width: windowWidth } = useWindowDimensions();
  const [rowWidth, setRowWidth] = useState(windowWidth - 32);

  const dayWidth = rowWidth / 7;
  const dayNumberHeight = viewMode === 'week' ? 24 : 18;
  const bandHeight = viewMode === 'week' ? 30 : 9;
  const trackCount = Math.max(parties.length, 1);
  const bandAreaHeight = trackCount * (bandHeight + BAND_GAP);
  const rowHeight = dayNumberHeight + bandAreaHeight + 4;
  const showText = viewMode === 'week';

  const weekRows = computeWeekRows(currentDate, viewMode);
  const todayStr = toDateOnlyString(new Date());

  return (
    <ThemedView onLayout={(e) => setRowWidth(e.nativeEvent.layout.width)}>
      <ThemedView style={styles.weekdayRow}>
        {WEEKDAY_LABELS.map((label) => (
          <ThemedText key={label} style={[styles.weekdayLabel, { width: dayWidth }]}>
            {label}
          </ThemedText>
        ))}
      </ThemedView>

      {weekRows.map((rowDays, rowIndex) => {
        const cells = computeMultiDayCells(rowDays, parties, currentDate, viewMode);
        const bands = computeMultiRowBands(cells, parties);

        return (
          <View key={rowIndex} style={[styles.row, { height: rowHeight }]}>
            <View style={[styles.dayNumberRow, { height: dayNumberHeight }]}>
              {rowDays.map((day, i) => {
                const dateStr = cells[i].date;
                const isToday = dateStr === todayStr;
                return (
                  <View key={dateStr} style={{ width: dayWidth, alignItems: 'center' }}>
                    <ThemedText
                      type={isToday ? 'defaultSemiBold' : 'default'}
                      style={[
                        styles.dayNumber,
                        !cells[i].inRange ? styles.dayNumberMuted : null,
                        isToday ? { color: Colors.light.tint } : null,
                      ]}>
                      {day.getDate()}
                    </ThemedText>
                  </View>
                );
              })}
            </View>

            <View style={[styles.bandArea, { height: bandAreaHeight }]}>
              {bands.map((band) => {
                const left = band.startIndex * dayWidth + 1;
                const width = (band.endIndex - band.startIndex + 1) * dayWidth - 2;
                const top = band.track * (bandHeight + BAND_GAP);
                const startDate = formatDateDisplay(cells[band.startIndex].date);
                const endDate = formatDateDisplay(cells[band.endIndex].date);

                const content = showText ? (
                  <ThemedText numberOfLines={1} ellipsizeMode="tail" style={styles.bandText}>
                    {band.country}
                  </ThemedText>
                ) : null;

                return (
                  <Pressable
                    key={band.key}
                    onPress={() => showAlert(band.country, startDate === endDate ? startDate : `${startDate} → ${endDate}`)}
                    style={[
                      styles.band,
                      styles.bandFill,
                      { left, width, top, height: bandHeight, backgroundColor: band.color, borderRadius: 4 },
                    ]}>
                    {content}
                  </Pressable>
                );
              })}
            </View>
          </View>
        );
      })}
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  weekdayRow: {
    flexDirection: 'row',
  },
  weekdayLabel: {
    textAlign: 'center',
    fontSize: 11,
    opacity: 0.6,
  },
  row: {
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: Colors.light.icon,
  },
  dayNumberRow: {
    flexDirection: 'row',
  },
  dayNumber: {
    fontSize: 12,
  },
  dayNumberMuted: {
    opacity: 0.35,
  },
  bandArea: {
    position: 'relative',
  },
  band: {
    position: 'absolute',
  },
  bandFill: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 3,
  },
  bandText: {
    fontSize: 11,
    color: '#FFFFFF',
    fontWeight: '600',
  },
});
