import AsyncStorage from '@react-native-async-storage/async-storage';
import { createClient } from '@supabase/supabase-js';
import 'react-native-url-polyfill/auto';

import type { Database } from '@/types/database';

const supabaseUrl = process.env.EXPO_PUBLIC_SUPABASE_URL;
const supabaseAnonKey = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY;

if (!supabaseUrl || !supabaseAnonKey) {
  throw new Error(
    'Missing EXPO_PUBLIC_SUPABASE_URL or EXPO_PUBLIC_SUPABASE_ANON_KEY. Add them to a .env file at the project root (see .env.example) and restart the dev server.'
  );
}

// AsyncStorage's web implementation touches `window.localStorage` unconditionally,
// which throws during Expo Router's static web SSR pass (no `window` in Node).
// No-op there; the client rehydrates the real session once it mounts in the browser.
const ssrSafeStorage = {
  getItem: (key: string) => (typeof window === 'undefined' ? Promise.resolve(null) : AsyncStorage.getItem(key)),
  setItem: (key: string, value: string) =>
    typeof window === 'undefined' ? Promise.resolve() : AsyncStorage.setItem(key, value),
  removeItem: (key: string) =>
    typeof window === 'undefined' ? Promise.resolve() : AsyncStorage.removeItem(key),
};

export const supabase = createClient<Database>(supabaseUrl, supabaseAnonKey, {
  auth: {
    storage: ssrSafeStorage,
    autoRefreshToken: true,
    persistSession: true,
    // detectSessionInUrl is a browser-only mechanism (it reads
    // window.location) — a no-op on native, where there's no window.location
    // at all. It was silently doing nothing on Android/iOS the whole time;
    // app/reset-password.tsx now does the equivalent by hand (reading the
    // `code` param via expo-router and calling exchangeCodeForSession), which
    // works on every platform, so this is turned off rather than left as
    // dead weight that only ever worked when testing via --web.
    detectSessionInUrl: false,
    // PKCE puts the recovery/confirmation token in a plain `?code=` query
    // param instead of a `#access_token=...` URL fragment. That matters
    // specifically on native: expo-router's route params only ever see the
    // query string, not a fragment — a fragment attached to a deep link
    // that's also been wrapped by expo-dev-client's own redirect handling
    // (see the note on emailRedirectTo in contexts/auth-context.tsx) isn't
    // reliably preserved through to the app at all, whereas a query param
    // survives that wrapping intact.
    flowType: 'pkce',
  },
});
