import { useFocusEffect } from '@react-navigation/native';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccents } from '@/constants/theme';
import { showAlert } from '@/lib/alert';
import { formatDateDisplay, toDateOnlyString } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import type { AccountRow, CreditCardRow, CsvImportRow } from '@/types/database';

const ACCENT = ModuleAccents.spend;

export default function CsvImportHistoryScreen() {
  const [imports, setImports] = useState<CsvImportRow[]>([]);
  const [accounts, setAccounts] = useState<AccountRow[]>([]);
  const [cards, setCards] = useState<CreditCardRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const [importsResult, accountsResult, cardsResult] = await Promise.all([
      supabase.from('csv_imports').select('*').order('created_at', { ascending: false }),
      supabase.from('accounts').select('*'),
      supabase.from('credit_cards').select('*'),
    ]);

    if (importsResult.error) {
      setError(importsResult.error.message);
      setIsLoading(false);
      return;
    }

    setImports(importsResult.data ?? []);
    setAccounts(accountsResult.data ?? []);
    setCards(cardsResult.data ?? []);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  function targetLabel(row: CsvImportRow): string {
    if (row.target_type === 'account') {
      return accounts.find((a) => a.id === row.target_id)?.name ?? 'Deleted account';
    }
    const card = cards.find((c) => c.id === row.target_id);
    return card ? `${card.issuer} · ${card.name}` : 'Deleted card';
  }

  function handleDelete(row: CsvImportRow) {
    showAlert(
      'Delete this import',
      `This removes the file and every transaction it created (${row.row_count}). This cannot be undone.`,
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: async () => {
            setDeletingId(row.id);
            setError(null);
            // Order matters only in that a failed row delete would otherwise
            // leave an orphaned storage object; a failed storage remove is
            // harmless to leave for a retry since the row (and the
            // transactions it cascades to) still gets deleted either way.
            await supabase.storage.from('csv-imports').remove([row.storage_path]);
            const { error: deleteError } = await supabase.from('csv_imports').delete().eq('id', row.id);
            setDeletingId(null);
            if (deleteError) {
              setError(deleteError.message);
              return;
            }
            setImports((prev) => prev.filter((i) => i.id !== row.id));
          },
        },
      ]
    );
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedText type="title" style={{ color: ACCENT }}>
          Import History
        </ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {isLoading ? (
          <ActivityIndicator color={ACCENT} style={styles.loading} />
        ) : imports.length === 0 ? (
          <ThemedText style={styles.muted}>No CSV imports yet.</ThemedText>
        ) : (
          imports.map((row) => (
            <Surface key={row.id} accentColor={ACCENT} style={styles.row}>
              <ThemedView style={styles.rowInfo}>
                <ThemedText type="defaultSemiBold" numberOfLines={1}>
                  {row.file_name}
                </ThemedText>
                <ThemedText style={styles.muted}>
                  {targetLabel(row)} · {row.row_count} transaction{row.row_count === 1 ? '' : 's'}
                </ThemedText>
                <ThemedText style={styles.muted}>{formatDateDisplay(toDateOnlyString(new Date(row.created_at)))}</ThemedText>
              </ThemedView>
              {deletingId === row.id ? (
                <ActivityIndicator color={Colors.light.negative} />
              ) : (
                <Pressable onPress={() => handleDelete(row)} hitSlop={12}>
                  <IconSymbol name="trash" size={20} color={Colors.light.negative} />
                </Pressable>
              )}
            </Surface>
          ))
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  loading: {
    marginTop: 24,
  },
  muted: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 12,
  },
  rowInfo: {
    flex: 1,
    gap: 2,
  },
  error: {
    color: Colors.light.negative,
  },
});
