import { LinearGradient } from 'expo-linear-gradient';
import { StyleSheet, View } from 'react-native';

import { HomePalette } from '@/constants/theme';

/**
 * Home-only backdrop — pared down from an earlier three-layer animated
 * version (a moving multi-hue sweep, a rotating radial "swirl," and a
 * periodic sheen) down to a single static diagonal gradient over the pearl
 * base. That earlier version was also only ever an approximation of the
 * mockup's CSS mix-blend-mode layers, which React Native has no reliable
 * cross-platform equivalent for — simplifying to a plain gradient sidesteps
 * that entirely rather than continuing to chase the effect. Open to
 * revisiting with more motion/depth later.
 */
export function HomeIridescentBackground() {
  return (
    <View style={StyleSheet.absoluteFill} pointerEvents="none">
      <View style={[StyleSheet.absoluteFill, { backgroundColor: HomePalette.pearl }]} />
      <LinearGradient
        colors={['#F6C9D8', '#E3CDEE', '#C7D3F0', '#C3E8E4', '#D7EEBE', '#F3E3AE', '#F3CBB8']}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={[StyleSheet.absoluteFill, { opacity: 0.35 }]}
      />
    </View>
  );
}
