import worldPaths from '@/assets/data/world-paths.json';

import { COUNTRIES } from '@/lib/countries';

/**
 * Real country border shapes, projected to flat SVG path strings — see
 * scripts/build-world-boundaries.js and scripts/build-world-paths.js for
 * the full pipeline (Natural Earth boundary data, simplified, equirectangular-
 * projected). Used by the passport map (components/world-passport-map.tsx)
 * and the web connections map (components/connections-map.web.tsx).
 *
 * This replaced an earlier version of this file built on @svg-maps/world's
 * pre-made SVG paths, dropped for two reasons that data couldn't fix:
 * country names baked into map TILES read in whatever language a raster
 * tile source happened to use (never tried here — this was always a flat
 * vector map — but the same "not in English" complaint applies to any
 * non-controlled label source), and @svg-maps/world's own coverage/
 * precision didn't extend as reliably to small countries. This dataset's
 * projection is also a plain equirectangular one (see project() in
 * scripts/build-world-paths.js), unlike @svg-maps/world's oddly-cropped
 * viewBox that used to need calibrated regression constants for
 * projectLatLon below — worth remembering only if this ever needs
 * re-deriving.
 */
export const WORLD_MAP_VIEW_BOX = '0 0 360 180';
export const WORLD_MAP_LOCATIONS: { id: string; path: string }[] = worldPaths.map((p) => ({ id: p.code, path: p.path }));

const [, , VIEW_BOX_WIDTH, VIEW_BOX_HEIGHT] = WORLD_MAP_VIEW_BOX.split(' ').map(Number);
export const MAP_ASPECT_RATIO = VIEW_BOX_WIDTH / VIEW_BOX_HEIGHT;

// The UK's three constituent countries are tracked as their own
// countries_visited entries (see lib/countries.ts) but the map has no
// separate shape for them — only "gb" as a whole. Visiting any of them
// colors the same UK shape a visit to "United Kingdom" itself would.
const CODE_OVERRIDES: Record<string, string> = {
  'gb-sct': 'gb',
  'gb-wls': 'gb',
  'gb-eng': 'gb',
};

function mapIdForCountryName(name: string): string | null {
  const code = COUNTRIES.find((c) => c.name === name)?.code;
  if (!code) return null;
  const lower = code.toLowerCase();
  return CODE_OVERRIDES[lower] ?? lower;
}

/** Map-shape ids (lowercase) covered by at least one of the given country names — what the passport map colors as "visited." */
export function visitedMapIds(countryNames: Iterable<string>): Set<string> {
  const ids = new Set<string>();
  for (const name of countryNames) {
    const id = mapIdForCountryName(name);
    if (id) ids.add(id);
  }
  return ids;
}

// Reverse lookup, built once: a map-shape id -> the app's own canonical
// country name for it, so tapping a shape can route to its existing
// /countries/[country] detail page, and so map labels are drawn from this
// app's own English names rather than any third-party source. First entry
// for a given code wins (e.g. "United Kingdom" itself, listed in
// COUNTRIES before Scotland/Wales/England, so tapping the "gb" shape
// lands on the UK, not a constituent country it also happens to match).
const ID_TO_NAME = new Map<string, string>();
for (const country of COUNTRIES) {
  const lower = country.code.toLowerCase();
  const id = CODE_OVERRIDES[lower] ?? lower;
  if (!ID_TO_NAME.has(id)) ID_TO_NAME.set(id, country.name);
}

/** The app's own country name for a map-shape id (as tapped on the passport map), or null if this shape isn't in lib/countries.ts's list at all. */
export function countryNameForMapId(id: string): string | null {
  return ID_TO_NAME.get(id) ?? null;
}

const PATH_BY_ID = new Map(worldPaths.map((p) => [p.code, p]));

/** Where to place a pin for `countryName`, in the map's own SVG coordinate space (see WORLD_MAP_VIEW_BOX) — null if it isn't in lib/countries.ts's list. */
export function mapCentroidForCountryName(countryName: string): { x: number; y: number } | null {
  const id = mapIdForCountryName(countryName);
  if (!id) return null;
  const entry = PATH_BY_ID.get(id);
  return entry ? { x: entry.labelX, y: entry.labelY } : null;
}

/**
 * Every country whose name is ever worth showing on the map, in this
 * app's own English names (lib/countries.ts) — English by construction,
 * since it never touches any third-party place-name source. `minScale` is
 * how far the map's own pinch-zoom scale (see world-passport-map.tsx) has
 * to reach before that label actually appears — see
 * scripts/build-world-paths.js's own comment on why this is a per-country
 * threshold instead of one flat show/hide cutoff: showing every eligible
 * label regardless of zoom level was exactly what made the map unreadable
 * (the ~30 largest countries alone already crowd a fully-zoomed-out view;
 * showing all 154 at once was real, reported overlap, not a hypothetical
 * one). The smallest countries never appear at all (see
 * MAX_LABEL_SCALE) — still colored and tappable, just not labeled, since
 * there's no zoom level they'd render legibly at anyway.
 */
export const WORLD_MAP_LABELS: { id: string; name: string; x: number; y: number; minScale: number }[] = worldPaths
  .filter((p) => p.labelMinScale !== null)
  .map((p) => ({ id: p.code, name: ID_TO_NAME.get(p.code) ?? p.code, x: p.labelX, y: p.labelY, minScale: p.labelMinScale as number }))
  .filter((l) => ID_TO_NAME.has(l.id));

/** Projects a real lat/lon onto this map's SVG coordinate space — for placing a pin at an actual city/location rather than a whole country's rough centroid (see mapCentroidForCountryName). Plain equirectangular, matching scripts/build-world-paths.js's own project() exactly (x = lon + 180, y = 90 - lat) — this map's projection, unlike the old @svg-maps/world-backed version, needs no calibration. */
export function projectLatLon(lat: number, lon: number): { x: number; y: number } {
  return { x: lon + 180, y: 90 - lat };
}
