import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { Pressable, StyleSheet } from 'react-native';

import { CountryChecklist } from '@/components/country-checklist';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { healthChecklistItemsFor, TRAVEL_CHECKLIST_ITEMS } from '@/lib/countryChecklist';
import { formatDateDisplay, toDateOnlyString } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import { VISA_STATUS_LABELS, visaRequirementFor, type VisaRequirementResult } from '@/lib/visaRequirements';
import type { UserVisaRow } from '@/types/database';

type CitizenshipSuggestion = { country: string; result: VisaRequirementResult };

/**
 * Trip-prep checklist for a destination country (eSIM, insurance, etc. —
 * manual checkboxes via CountryChecklist) plus a visa status row derived
 * from user_visas — reports whether you have one logged and whether it's
 * expired, informing you rather than deciding for you. Below that, an
 * approximate reference suggestion per held citizenship (skipped for a
 * citizenship this destination is visa-free/on-arrival for, and once a
 * valid visa is already on file — nothing left to flag at that point) —
 * see lib/visaRequirements.ts for exactly how approximate this is and why.
 */
export function TravelChecklist({ country, accentColor }: { country: string; accentColor: string }) {
  const router = useRouter();
  const { session } = useAuth();
  const [visas, setVisas] = useState<UserVisaRow[]>([]);
  const [suggestions, setSuggestions] = useState<CitizenshipSuggestion[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const load = useCallback(async () => {
    if (!session) return;
    const [visasResult, citizenshipsResult] = await Promise.all([
      supabase.from('user_visas').select('*').eq('country', country),
      supabase.from('user_citizenships').select('country'),
    ]);
    setVisas(visasResult.data ?? []);
    const citizenshipCountries = Array.from(new Set((citizenshipsResult.data ?? []).map((c) => c.country)));
    const results = await Promise.all(
      citizenshipCountries.map(async (citizenshipCountry) => ({
        country: citizenshipCountry,
        result: await visaRequirementFor(citizenshipCountry, country),
      }))
    );
    setSuggestions(
      results.filter(
        (r): r is CitizenshipSuggestion => r.result !== null && r.result.status !== 'visa_free' && r.result.status !== 'visa_on_arrival'
      )
    );
    setIsLoading(false);
  }, [session, country]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  if (isLoading) return null;

  const today = toDateOnlyString(new Date());
  const validVisa = visas.find((v) => !v.expiry_date || v.expiry_date >= today);
  const expiredVisa = !validVisa ? visas.find((v) => v.expiry_date && v.expiry_date < today) : null;
  const healthItems = healthChecklistItemsFor(country);
  const items = [...TRAVEL_CHECKLIST_ITEMS, ...healthItems];

  return (
    <ThemedView style={styles.container}>
      {healthItems.length > 0 ? (
        <ThemedText style={styles.hint}>
          Includes general health guidance for {country}, not medical advice. Confirm current requirements with a
          doctor or travel clinic before you go.
        </ThemedText>
      ) : null}
      <CountryChecklist country={country} accentColor={accentColor} items={items} />

      <Pressable onPress={() => router.push('/account/citizenship')}>
        <Surface accentColor={validVisa ? accentColor : expiredVisa ? Colors.light.negative : Colors.light.icon}>
          <ThemedView style={styles.visaRow}>
            <IconSymbol
              name={validVisa ? 'checkmark.circle.fill' : expiredVisa ? 'circle' : 'info.circle'}
              size={22}
              color={validVisa ? accentColor : expiredVisa ? Colors.light.negative : Colors.light.textMuted}
            />
            <ThemedView style={styles.visaText}>
              <ThemedText>
                {validVisa
                  ? `Visa on file${validVisa.expiry_date ? ` (expires ${formatDateDisplay(validVisa.expiry_date)})` : ''}`
                  : expiredVisa
                    ? `Visa on file has expired (${formatDateDisplay(expiredVisa.expiry_date!)})`
                    : `Not tracking a visa for ${country}`}
              </ThemedText>
              <ThemedText style={styles.hint}>
                {validVisa || expiredVisa
                  ? 'Manage in Account > Citizenship'
                  : 'Cluster doesn’t know which destinations require one for you. Add one here only if yours does.'}
              </ThemedText>
            </ThemedView>
          </ThemedView>
        </Surface>
      </Pressable>

      {!validVisa && suggestions.length > 0 ? (
        <ThemedView style={styles.suggestionBlock}>
          {suggestions.map((s) => (
            <ThemedText key={s.country} style={styles.hint}>
              As a {s.country} citizen, you may need: {VISA_STATUS_LABELS[s.result.status].toLowerCase()} for {country}
              {s.result.visaFreeDays ? ` (${s.result.visaFreeDays} days)` : ''}.
            </ThemedText>
          ))}
          <ThemedText style={styles.hint}>Reference only, not a guarantee. Verify with an official source.</ThemedText>
        </ThemedView>
      ) : null}
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  container: {
    gap: 8,
  },
  visaRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
  },
  visaText: {
    flex: 1,
    gap: 2,
  },
  suggestionBlock: {
    gap: 2,
    paddingHorizontal: 4,
  },
  hint: {
    opacity: 0.7,
    fontSize: 12,
    color: Colors.light.textMuted,
  },
});
