import { Colors, ModuleAccents } from '@/constants/theme';
import { cityCoordinatesFor } from '@/lib/cityCoordinates';
import { COUNTRY_COORDINATES } from '@/lib/countryCoordinates';
import type { CountryVisitedRow, TripSegmentRow } from '@/types/database';

export type RoutePoint = { id: string; lat: number; lon: number; label: string };

export type TripLeg = {
  /** Stable key for this leg — used for both the color-override lookup and React keys. */
  id: string;
  /** Null when either end is a segment-only waypoint (e.g. a connecting flight's city, never one of the trip's own stays) rather than a real stop — trip_leg_colors' manual override needs a real countries_visited row on both ends, so a leg touching a waypoint can't be manually recolored, only auto-colored by its segment's mode. */
  fromStopId: string | null;
  toStopId: string | null;
  from: RoutePoint;
  to: RoutePoint;
  /** The segment this leg IS (an exact from/to label match), a manual mode override on a stop-to-stop leg with no segment of its own (see hasSegment), or the best-effort date-matched segment — see matchSegment. Drives the default color when there's no manual color override. */
  mode: TripSegmentRow['mode'] | null;
  /** True when `mode` came from a real trip_segment (matched exactly or by date window) — false when it's a manual tag on a stop-to-stop leg with no segment behind it at all. Drives the dotted-vs-solid line style: a tag alone isn't a fully logged leg of travel, just a label on the map. */
  hasSegment: boolean;
  color: string;
};

/** One color per transport mode, plus a neutral default for a leg with no matched segment — independent of ModuleAccents' own per-module meanings, just reusing hexes that already read well together. */
export const MODE_COLORS: Record<TripSegmentRow['mode'], string> = {
  flight: ModuleAccents.countries,
  train: ModuleAccents.wealth,
  car: ModuleAccents.cards,
  bus: ModuleAccents.accounts,
  ferry: '#0E7C86',
  other: ModuleAccents.documents,
};

export const DEFAULT_LEG_COLOR = Colors.light.icon;

function stopLabel(stop: CountryVisitedRow): string {
  return stop.city?.trim() || stop.country;
}

function normalizeLabel(label: string): string {
  return label.trim().toLowerCase();
}

/**
 * Best-effort coordinates for a stop: the row's own resolved lat/lon first
 * (set via a live lookup when the visit was saved — see lib/geocoding.ts —
 * real coordinates for whatever city was actually typed, not limited to
 * any curated list), then the small curated city list for a visit saved
 * before that existed, then the country's rough centroid, null if none of
 * those are known.
 */
export function coordinatesForStop(stop: CountryVisitedRow): { lat: number; lon: number } | null {
  if (stop.lat != null && stop.lon != null) return { lat: stop.lat, lon: stop.lon };
  const city = stop.city?.trim();
  if (city) {
    const cityCoords = cityCoordinatesFor(stop.country, city);
    if (cityCoords) return cityCoords;
  }
  return COUNTRY_COORDINATES[stop.country] ?? null;
}

type Candidate = {
  /** A real stop's id when this candidate came from one, else null (a segment-only waypoint, e.g. a connecting flight's city that was never one of the trip's own stays). */
  stopId: string | null;
  label: string;
  lat: number;
  lon: number;
  /** Sort key only — a stop uses its entry_date, a segment endpoint its depart/arrive date. */
  date: string;
  /** 'stop' for a real stay; 'from'/'to' for which end of segmentId's own leg this is — both only meaningful for same-date tie-breaking below. */
  kind: 'stop' | 'from' | 'to';
  segmentId: string | null;
  /** Only set for kind 'stop' — used to break a same-entry-date tie against another stop (see orderSameDateGroup). */
  exitDate: string | null;
  /** The owning stop's or segment's manual_order (supabase/087_manual_timeline_order.sql) — see orderSameDateGroup's own check for how a full same-date group of these overrides the automatic graph. */
  manualOrder: number | null;
};

/**
 * Orders the candidates that fall on one exact same day, mirroring
 * lib/trips.ts's computeTripTimeline: a segment's own from sorts before
 * its own to (you can't arrive before you leave); a stop sorts before a
 * same-dated segment departing FROM its own city (you were there, then
 * you left) and after a same-dated segment arriving INTO its own city
 * (you arrived, then you were there); two stops starting the same day
 * sort by exit_date, the same-day one first — no segment needed for that
 * rule at all, since it's a fact about the two stops themselves.
 *
 * This used to be a plain pairwise comparator, which is NOT a valid
 * total order once three or more same-date candidates chain through
 * each other — e.g. a same-day arrival into a stop, that stop itself,
 * its own same-day departure, AND that departure's own destination all
 * landing on one date (a real case: flying out same-day as your last
 * stop). A pairwise rule for "unrelated same-date item vs a stop" can't
 * see that the "unrelated" item is actually downstream of the stop via
 * a chain of other rules, which let Array.sort produce a cycle
 * (A before B before C before A) — confirmed against a real user trip
 * where this silently left the trip's own return-flight destination
 * undropped by the leading/trailing trim below.
 *
 * A real topological sort (Kahn's algorithm) is used instead of a
 * comparator, and for a reason beyond just avoiding that cycle: a
 * comparator's fallback for two genuinely unrelated candidates (compare
 * by original index) can ITSELF contradict an edge between two OTHER
 * candidates in the same group once transitive closure is added — e.g.
 * a same-date candidate with no matching label to anything else (a
 * mistyped city name is a real way this happens) can sort earlier by
 * plain index than a candidate two places ahead of it in the true
 * happens-before chain, splitting that chain apart. Kahn's algorithm
 * doesn't have this problem: it only ever picks from candidates with no
 * remaining unresolved dependency, breaking ties among those by
 * original index, so an edge is never overridden by an index
 * coincidence.
 */
function orderSameDateGroup<T extends { c: Candidate; index: number }>(group: T[]): T[] {
  const n = group.length;
  if (n <= 1) return group;
  // Mirrors lib/trips.ts's orderSameDateEntries — a fully manually-ordered
  // group (every entry's owning stop/segment has manual_order set) wins
  // outright, so the map stays consistent with whatever the Itinerary
  // list's reorder controls set.
  if (group.every((g) => g.c.manualOrder != null)) {
    return [...group].sort((a, b) => a.c.manualOrder! - b.c.manualOrder!);
  }
  const successors: number[][] = Array.from({ length: n }, () => []);
  const inDegree = new Array(n).fill(0);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) continue;
      const a = group[i].c;
      const b = group[j].c;
      const isEdge =
        (!!a.segmentId && a.segmentId === b.segmentId && a.kind === 'from' && b.kind === 'to') ||
        (a.kind === 'stop' && b.kind === 'from' && normalizeLabel(a.label) === normalizeLabel(b.label)) ||
        (a.kind === 'to' && b.kind === 'stop' && normalizeLabel(a.label) === normalizeLabel(b.label)) ||
        // Two stops starting the same day, independent of any segment: the
        // one you left same-day comes first, the one you actually stayed
        // in (a later exit_date) comes after.
        (a.kind === 'stop' && b.kind === 'stop' && a.exitDate != null && b.exitDate != null && a.exitDate < b.exitDate);
      if (isEdge) {
        successors[i].push(j);
        inDegree[j]++;
      }
    }
  }
  const used = new Array(n).fill(false);
  const result: T[] = [];
  for (let step = 0; step < n; step++) {
    let pick = -1;
    for (let i = 0; i < n; i++) {
      if (used[i] || inDegree[i] > 0) continue;
      if (pick === -1 || group[i].index < group[pick].index) pick = i;
    }
    if (pick === -1) break; // Only reachable if the edge rules ever produced a real cycle — they can't, but never hang the map over it.
    used[pick] = true;
    result.push(group[pick]);
    for (const j of successors[pick]) inDegree[j]--;
  }
  for (let i = 0; i < n; i++) if (!used[i]) result.push(group[i]);
  return result;
}

/**
 * The trip_segment (if any) whose from/to exactly names this leg's two
 * points — always correct when it applies, since the leg IS that segment,
 * not a guess. Falls back to the old date-window heuristic (departing
 * while still "at" the first stop, arriving while already "at" the
 * second) only for a stop-to-stop leg with no segment of its own — there's
 * no stored link between an segment and a stop pair for that case, so it's
 * inferred from dates alone. Ties broken by picking the segment departing
 * closest to `from`'s last day.
 */
function matchSegment(from: Candidate, to: Candidate, fromStop: CountryVisitedRow | null, toStop: CountryVisitedRow | null, segments: TripSegmentRow[]): TripSegmentRow | null {
  const exact = segments.find(
    (s) => normalizeLabel(s.from_label) === normalizeLabel(from.label) && normalizeLabel(s.to_label) === normalizeLabel(to.label)
  );
  if (exact) return exact;
  if (!fromStop || !toStop) return null;

  const fromWindowEnd = fromStop.exit_date ?? fromStop.entry_date;
  const toWindowStart = toStop.entry_date;
  const toWindowEnd = toStop.exit_date ?? toStop.entry_date;
  const candidates = segments.filter(
    (s) =>
      s.depart_date >= fromStop.entry_date &&
      s.depart_date <= fromWindowEnd &&
      s.arrive_date >= toWindowStart &&
      s.arrive_date <= toWindowEnd
  );
  if (candidates.length === 0) return null;
  return candidates.sort((a, b) => (a.depart_date < b.depart_date ? 1 : -1))[0];
}

/**
 * Ordered route points and the legs connecting them, for the trip map.
 * Every stop with known coordinates contributes one point; every segment
 * whose endpoint has its own resolved coordinates (see
 * components/city-autocomplete-input.tsx — set when that endpoint was
 * picked from a search suggestion) ALSO contributes a point, even when
 * that city was never one of the trip's own stays — an interior connecting
 * city (landing in Delhi on the way to Bikaner) is a real part of the
 * journey the map should show, not just the places you actually stopped.
 * The one exception is the sequence's own two endpoints: the city a trip
 * departs FROM and the city its last leg arrives INTO are trimmed when
 * neither is a real stop, since those are just where the trip starts and
 * ends from (e.g. Frankfurt, flying out to an India trip), not part of it
 * — see the trim step below for exactly what stays and what's cut. A
 * segment endpoint that names the same place as an adjacent stop (by city
 * name) collapses into that stop's own point rather than drawing two
 * overlapping dots, preferring the stop's coordinates (more authoritative
 * — resolved directly for that exact stay, not just a same-named
 * waypoint).
 */
export type LegOverride = { color: string | null; mode: TripSegmentRow['mode'] | null };

export function computeTripRoute(
  stops: CountryVisitedRow[],
  segments: TripSegmentRow[],
  legOverrides: Map<string, LegOverride>
): { points: RoutePoint[]; legs: TripLeg[] } {
  const candidates: Candidate[] = [];
  const stopByCandidateIndex = new Map<number, CountryVisitedRow>();

  for (const stop of stops) {
    const coords = coordinatesForStop(stop);
    if (!coords) continue;
    stopByCandidateIndex.set(candidates.length, stop);
    candidates.push({
      stopId: stop.id,
      label: stopLabel(stop),
      lat: coords.lat,
      lon: coords.lon,
      date: stop.entry_date,
      kind: 'stop',
      segmentId: null,
      exitDate: stop.exit_date,
      manualOrder: stop.manual_order,
    });
  }
  for (const segment of segments) {
    if (segment.from_lat != null && segment.from_lon != null) {
      candidates.push({
        stopId: null,
        label: segment.from_label,
        lat: segment.from_lat,
        lon: segment.from_lon,
        date: segment.depart_date,
        kind: 'from',
        segmentId: segment.id,
        exitDate: null,
        manualOrder: segment.manual_order,
      });
    }
    if (segment.to_lat != null && segment.to_lon != null) {
      candidates.push({
        stopId: null,
        label: segment.to_label,
        lat: segment.to_lat,
        lon: segment.to_lon,
        date: segment.arrive_date,
        kind: 'to',
        segmentId: segment.id,
        exitDate: null,
        manualOrder: segment.manual_order,
      });
    }
  }

  const withIndex = candidates.map((c, index) => ({ c, index }));
  const byDate = new Map<string, { c: Candidate; index: number }[]>();
  for (const item of withIndex) {
    const list = byDate.get(item.c.date);
    if (list) list.push(item);
    else byDate.set(item.c.date, [item]);
  }
  const order = Array.from(byDate.keys())
    .sort()
    .flatMap((date) => orderSameDateGroup(byDate.get(date)!));

  // Dedupe adjacent same-place candidates (by normalized city name) —
  // preferring one that came from a real stop over a segment waypoint
  // that just happens to name the same place.
  const withDupes: { candidate: Candidate; stop: CountryVisitedRow | null }[] = [];
  for (const { c, index } of order) {
    const stop = stopByCandidateIndex.get(index) ?? null;
    const prev = withDupes[withDupes.length - 1];
    if (prev && normalizeLabel(prev.candidate.label) === normalizeLabel(c.label)) {
      if (!prev.stop && stop) withDupes[withDupes.length - 1] = { candidate: c, stop };
      continue;
    }
    withDupes.push({ candidate: c, stop });
  }

  // Trim every leading/trailing waypoint that isn't a real stop — the
  // city you flew out FROM (e.g. Frankfurt, on the way to an India trip,
  // possibly via a connecting city too) and the city a return flight
  // lands back in aren't part of the trip, just where it starts and ends
  // from. An interior waypoint on the same segment chain (Delhi, landing
  // before continuing on to an actual stop) stays — this only ever peels
  // off from the two true endpoints inward, stopping the moment it hits
  // a real stop on each side. A single shift/pop (the old behavior) only
  // handled exactly one non-stop waypoint per side — a real connecting
  // flight (two non-stop cities in a row before the first stop) left the
  // inner one undropped.
  const deduped = [...withDupes];
  while (deduped.length > 0 && !deduped[0].stop) deduped.shift();
  while (deduped.length > 0 && !deduped[deduped.length - 1].stop) deduped.pop();

  const points: RoutePoint[] = deduped.map(({ candidate, stop }) => ({
    id: stop?.id ?? `${candidate.label}:${candidate.date}`,
    lat: candidate.lat,
    lon: candidate.lon,
    label: candidate.label,
  }));

  const legs: TripLeg[] = [];
  for (let i = 0; i + 1 < deduped.length; i++) {
    const from = deduped[i];
    const to = deduped[i + 1];
    const fromPoint = points[i];
    const toPoint = points[i + 1];
    const legId = `${fromPoint.id}:${toPoint.id}`;
    const matchedSegment = matchSegment(from.candidate, to.candidate, from.stop, to.stop, segments);
    // legId IS fromPoint.id:toPoint.id — the same from_point_key:to_point_key
    // pair trip_leg_colors is keyed by (086_trip_leg_colors_any_endpoint.sql),
    // so a manual override works whether or not either end is a real stop.
    const override = legOverrides.get(legId);
    const mode = override?.mode ?? matchedSegment?.mode ?? null;
    const color = override?.color || (mode ? MODE_COLORS[mode] : DEFAULT_LEG_COLOR);
    legs.push({
      id: legId,
      fromStopId: from.stop?.id ?? null,
      toStopId: to.stop?.id ?? null,
      from: fromPoint,
      to: toPoint,
      mode,
      hasSegment: !!matchedSegment,
      color,
    });
  }

  return { points, legs };
}

/**
 * Catmull-Rom interpolation for a smooth, flowing curve through the
 * route's waypoints instead of straight point-to-point segments. Each leg
 * (points[legIndex] -> points[legIndex + 1]) is still rendered as its own
 * separately-colored path, but the curve is shaped using the ONE point
 * before and the ONE point after it too — points[legIndex - 1] and
 * points[legIndex + 2] — so consecutive legs meet with a continuous
 * tangent instead of a visible kink at each waypoint, even though they're
 * drawn as separate Polylines. Points past either end of the route are
 * clamped to the route's own first/last point rather than extrapolated
 * (the standard "clamped" Catmull-Rom boundary condition), so the curve
 * doesn't overshoot past the real start or end.
 */
export function catmullRomLegPath(points: RoutePoint[], legIndex: number, steps = 16): { lat: number; lon: number }[] {
  const p0 = points[Math.max(0, legIndex - 1)];
  const p1 = points[legIndex];
  const p2 = points[legIndex + 1];
  const p3 = points[Math.min(points.length - 1, legIndex + 2)];
  const result: { lat: number; lon: number }[] = [];
  for (let step = 0; step <= steps; step++) {
    const t = step / steps;
    const t2 = t * t;
    const t3 = t2 * t;
    const lat =
      0.5 *
      (2 * p1.lat +
        (-p0.lat + p2.lat) * t +
        (2 * p0.lat - 5 * p1.lat + 4 * p2.lat - p3.lat) * t2 +
        (-p0.lat + 3 * p1.lat - 3 * p2.lat + p3.lat) * t3);
    const lon =
      0.5 *
      (2 * p1.lon +
        (-p0.lon + p2.lon) * t +
        (2 * p0.lon - 5 * p1.lon + 4 * p2.lon - p3.lon) * t2 +
        (-p0.lon + 3 * p1.lon - 3 * p2.lon + p3.lon) * t3);
    result.push({ lat, lon });
  }
  return result;
}

/**
 * A single gentle bow between two points — a quadratic Bezier through one
 * control point offset perpendicular to the straight line, proportional to
 * the leg's own length (bowFraction). Used by the passport screen's
 * all-trips overlay (components/multi-trip-route-map) instead of
 * catmullRomLegPath: that spline threads through a WHOLE trip's points
 * together, which only behaves well when there are enough closely-spaced
 * waypoints to constrain it — a short trip with few, widely-spaced stops
 * (especially one looping back to its own starting city) produced a real
 * self-intersecting loop instead of anything resembling the route,
 * confirmed directly against a live render. A per-leg arc can't do that:
 * each leg is independent, bounded by its own single control point, and
 * always bows the same rotational direction (the direction vector rotated
 * 90° counterclockwise) so multiple trips on one map read as a consistent
 * family of arcs rather than each bowing an arbitrary way.
 */
export function arcLegPath(
  from: { lat: number; lon: number },
  to: { lat: number; lon: number },
  steps = 24,
  bowFraction = 0.18
): { lat: number; lon: number }[] {
  const dLat = to.lat - from.lat;
  const dLon = to.lon - from.lon;
  const midLat = (from.lat + to.lat) / 2;
  const midLon = (from.lon + to.lon) / 2;
  const controlLat = midLat + -dLon * bowFraction;
  const controlLon = midLon + dLat * bowFraction;
  const result: { lat: number; lon: number }[] = [];
  for (let step = 0; step <= steps; step++) {
    const t = step / steps;
    const oneMinusT = 1 - t;
    result.push({
      lat: oneMinusT * oneMinusT * from.lat + 2 * oneMinusT * t * controlLat + t * t * to.lat,
      lon: oneMinusT * oneMinusT * from.lon + 2 * oneMinusT * t * controlLon + t * t * to.lon,
    });
  }
  return result;
}
