import { useFocusEffect } from '@react-navigation/native';
import { useCallback, useState } from 'react';

import { useAuth } from '@/contexts/auth-context';
import { supabase } from '@/lib/supabase';

export type ConnectionDisplay = {
  email: string | null;
  fullName: string | null;
  override: string | null;
  colorOverride: string | null;
  /** Display priority: viewer's own override -> the connection's real name -> their email's local-part. */
  displayName: string;
  isLoading: boolean;
  /** Set when the profile/override fetch itself failed — distinct from a successful fetch that simply has no name/email on file (that falls through to the 'Connection' placeholder silently, by design). */
  error: string | null;
  reload: () => Promise<void>;
  /** Empty string clears the override, reverting to name/email. Returns an error message, or null on success. */
  saveOverride: (label: string) => Promise<string | null>;
  /** null clears the override, reverting to their real calendar_color. Returns an error message, or null on success. */
  saveColorOverride: (color: string | null) => Promise<string | null>;
};

export function computeDisplayName(override: string | null, fullName: string | null, email: string | null): string {
  if (override) return override;
  if (fullName) return fullName;
  if (email) return email.split('@')[0];
  return 'Connection';
}

export function useConnectionDisplay(connectionId: string | undefined): ConnectionDisplay {
  const { session } = useAuth();
  const [email, setEmail] = useState<string | null>(null);
  const [fullName, setFullName] = useState<string | null>(null);
  const [override, setOverride] = useState<string | null>(null);
  const [colorOverride, setColorOverride] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const reload = useCallback(async () => {
    if (!session || !connectionId) return;
    setIsLoading(true);
    setError(null);

    const [profileResult, overrideResult] = await Promise.all([
      supabase.rpc('connection_partner_profile', { p_connection_id: connectionId }).maybeSingle(),
      supabase
        .from('connection_display_overrides')
        .select('label, color')
        .eq('connection_id', connectionId)
        .eq('viewer_user_id', session.user.id)
        .maybeSingle(),
    ]);

    // Surfaced rather than silently swallowed — a failed fetch here used to
    // fall through to the 'Connection' placeholder with no indication
    // anything had gone wrong, indistinguishable from "this person really
    // has no name/email on file."
    if (profileResult.error) {
      setError(profileResult.error.message);
    } else if (overrideResult.error) {
      setError(overrideResult.error.message);
    }

    setEmail(profileResult.data?.email ?? null);
    setFullName(profileResult.data?.full_name ?? null);
    setOverride(overrideResult.data?.label ?? null);
    setColorOverride(overrideResult.data?.color ?? null);
    setIsLoading(false);
  }, [session, connectionId]);

  // Refetches on every focus, not just mount — a screen you navigate "back"
  // to (rather than freshly mounting) would otherwise keep showing whatever
  // override/profile data it had when it first loaded, even after the
  // value was changed elsewhere (e.g. the color swatch picker) in the
  // meantime.
  useFocusEffect(
    useCallback(() => {
      reload();
    }, [reload])
  );

  async function saveOverride(label: string): Promise<string | null> {
    if (!session || !connectionId) return 'Not signed in.';
    const trimmed = label.trim();

    if (!trimmed) {
      if (colorOverride) {
        // A color override is still active — keep the row, just clear the label.
        const { error } = await supabase
          .from('connection_display_overrides')
          .update({ label: null })
          .eq('connection_id', connectionId)
          .eq('viewer_user_id', session.user.id);
        if (error) return error.message;
        setOverride(null);
        return null;
      }
      const { error } = await supabase
        .from('connection_display_overrides')
        .delete()
        .eq('connection_id', connectionId)
        .eq('viewer_user_id', session.user.id);
      if (error) return error.message;
      setOverride(null);
      return null;
    }

    const { error } = await supabase
      .from('connection_display_overrides')
      .upsert(
        { connection_id: connectionId, viewer_user_id: session.user.id, label: trimmed },
        { onConflict: 'connection_id,viewer_user_id' }
      );
    if (error) return error.message;
    setOverride(trimmed);
    return null;
  }

  async function saveColorOverride(color: string | null): Promise<string | null> {
    if (!session || !connectionId) return 'Not signed in.';

    if (!color) {
      if (override) {
        // A label override is still active — keep the row, just clear the color.
        const { error } = await supabase
          .from('connection_display_overrides')
          .update({ color: null })
          .eq('connection_id', connectionId)
          .eq('viewer_user_id', session.user.id);
        if (error) return error.message;
        setColorOverride(null);
        return null;
      }
      const { error } = await supabase
        .from('connection_display_overrides')
        .delete()
        .eq('connection_id', connectionId)
        .eq('viewer_user_id', session.user.id);
      if (error) return error.message;
      setColorOverride(null);
      return null;
    }

    const { error } = await supabase
      .from('connection_display_overrides')
      .upsert(
        { connection_id: connectionId, viewer_user_id: session.user.id, color },
        { onConflict: 'connection_id,viewer_user_id' }
      );
    if (error) return error.message;
    setColorOverride(color);
    return null;
  }

  return {
    email,
    fullName,
    override,
    colorOverride,
    displayName: computeDisplayName(override, fullName, email),
    isLoading,
    error,
    reload,
    saveOverride,
    saveColorOverride,
  };
}
