import { useFocusEffect } from '@react-navigation/native';
import { Image } from 'expo-image';
import { useLocalSearchParams, useRouter } from 'expo-router';
import * as WebBrowser from 'expo-web-browser';
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, TextInput } from 'react-native';

import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { DateInput } from '@/components/date-input';
import { SelectModal } from '@/components/select-modal';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { NOT_LINKED_VALUE, TripStopPicker, type TripLinkValue } from '@/components/trip-stop-picker';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { showAlert } from '@/lib/alert';
import { DOCUMENT_TYPE_OPTIONS, isImageFile } from '@/lib/documents';
import { toDateOnlyString } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import { computeTripSummaries } from '@/lib/trips';
import type { CountryVisitedRow, DocumentRow, DocumentType, TripRow, TripSegmentRow } from '@/types/database';

const ACCENT = ModuleAccents.documents;
const SIGNED_URL_EXPIRY_SECONDS = 300;

function parseDateOnly(dateString: string): Date {
  const [year, month, day] = dateString.split('-').map(Number);
  return new Date(year, month - 1, day);
}

export default function DocumentDetailScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const [doc, setDoc] = useState<DocumentRow | null>(null);
  const [signedUrl, setSignedUrl] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [docType, setDocType] = useState<DocumentType>('other');
  const [showTypePicker, setShowTypePicker] = useState(false);
  const [name, setName] = useState('');
  const [issueDate, setIssueDate] = useState<Date | null>(null);
  const [expiryDate, setExpiryDate] = useState<Date | null>(null);
  const [notes, setNotes] = useState('');

  const [trips, setTrips] = useState<TripRow[]>([]);
  const [stops, setStops] = useState<CountryVisitedRow[]>([]);
  const [segments, setSegments] = useState<TripSegmentRow[]>([]);
  const [tripDataLoaded, setTripDataLoaded] = useState(false);
  const [tripLinkValue, setTripLinkValue] = useState<TripLinkValue>(NOT_LINKED_VALUE);
  const [showTripPicker, setShowTripPicker] = useState(false);

  useEffect(() => {
    if (docType !== 'proof_of_travel' || tripDataLoaded) return;
    setTripDataLoaded(true);
    Promise.all([
      supabase.from('trips').select('*'),
      supabase.from('countries_visited').select('*'),
      supabase.from('trip_segments').select('*'),
    ]).then(([tripsResult, stopsResult, segmentsResult]) => {
      setTrips(tripsResult.data ?? []);
      setStops(stopsResult.data ?? []);
      setSegments(segmentsResult.data ?? []);
    });
  }, [docType, tripDataLoaded]);

  const load = useCallback(async () => {
    setError(null);
    const { data, error: fetchError } = await supabase.from('documents').select('*').eq('id', id).maybeSingle();

    if (fetchError) {
      setError(fetchError.message);
      setIsLoading(false);
      return;
    }
    if (!data) {
      setError('Document not found.');
      setIsLoading(false);
      return;
    }

    setDoc(data);
    setDocType(data.doc_type);
    setName(data.name);
    setIssueDate(data.issue_date ? parseDateOnly(data.issue_date) : null);
    setExpiryDate(data.expiry_date ? parseDateOnly(data.expiry_date) : null);
    setTripLinkValue(
      data.trip_stop_id ? `stop:${data.trip_stop_id}` : data.trip_segment_id ? `segment:${data.trip_segment_id}` : NOT_LINKED_VALUE
    );
    setNotes(data.notes ?? '');

    const { data: signedData, error: signedError } = await supabase.storage
      .from('documents')
      .createSignedUrl(data.file_ref, SIGNED_URL_EXPIRY_SECONDS);
    if (!signedError) setSignedUrl(signedData?.signedUrl ?? null);

    setIsLoading(false);
  }, [id]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  async function handleSave() {
    if (!doc) return;
    if (!name.trim()) {
      setError('Name is required.');
      return;
    }

    setError(null);
    setIsSaving(true);
    const { error: updateError } = await supabase
      .from('documents')
      .update({
        doc_type: docType,
        name: name.trim(),
        issue_date: issueDate ? toDateOnlyString(issueDate) : null,
        expiry_date: expiryDate ? toDateOnlyString(expiryDate) : null,
        notes: notes.trim() || null,
        trip_stop_id: tripLinkValue.startsWith('stop:') ? tripLinkValue.slice(5) : null,
        trip_segment_id: tripLinkValue.startsWith('segment:') ? tripLinkValue.slice(8) : null,
      })
      .eq('id', doc.id);
    setIsSaving(false);
    if (updateError) {
      setError(updateError.message);
      return;
    }
    router.back();
  }

  function handleDelete() {
    if (!doc) return;
    showAlert('Delete document', 'This cannot be undone.', [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Delete',
        style: 'destructive',
        onPress: async () => {
          setIsDeleting(true);
          const { error: storageError } = await supabase.storage.from('documents').remove([doc.file_ref]);
          if (storageError) {
            setIsDeleting(false);
            setError(storageError.message);
            return;
          }
          const { error: deleteError } = await supabase.from('documents').delete().eq('id', doc.id);
          setIsDeleting(false);
          if (deleteError) {
            setError(deleteError.message);
            return;
          }
          router.back();
        },
      },
    ]);
  }

  async function handleOpenFile() {
    if (signedUrl) await WebBrowser.openBrowserAsync(signedUrl);
  }

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  if (!doc) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered, styles.padded]}>
        <ThemedText style={styles.error}>{error ?? 'Document not found.'}</ThemedText>
        <Pressable onPress={() => router.back()}>
          <ThemedText type="link">Go back</ThemedText>
        </Pressable>
      </ThemedView>
    );
  }

  const isImage = isImageFile(null, doc.file_ref);
  const typeLabel = DOCUMENT_TYPE_OPTIONS.find((o) => o.value === docType)?.label ?? 'Other';

  const tripSummaries = computeTripSummaries(trips, stops, segments);
  let tripLinkLabel = 'Not linked';
  if (tripLinkValue.startsWith('stop:')) {
    const stop = stops.find((s) => s.id === tripLinkValue.slice(5));
    const summary = tripSummaries.find((t) => t.id === stop?.trip_id);
    if (stop) tripLinkLabel = `${summary?.displayName ?? 'Trip'}: ${stop.city?.trim() || stop.country}`;
  } else if (tripLinkValue.startsWith('segment:')) {
    const segment = segments.find((s) => s.id === tripLinkValue.slice(8));
    const summary = tripSummaries.find((t) => t.id === segment?.trip_id);
    if (segment) tripLinkLabel = `${summary?.displayName ?? 'Trip'}: ${segment.from_label} → ${segment.to_label}`;
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }} numberOfLines={1}>
            {doc.name}
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {signedUrl ? (
          isImage ? (
            <Image source={signedUrl} contentFit="contain" style={styles.preview} />
          ) : (
            <Pressable onPress={handleOpenFile} style={[styles.button, styles.buttonOutline, { borderColor: ACCENT }]}>
              <ThemedText style={{ color: ACCENT, fontWeight: '600' }}>Open document</ThemedText>
            </Pressable>
          )
        ) : null}

        <ThemedText type="defaultSemiBold" style={styles.sectionSpacing}>
          Type
        </ThemedText>
        <Pressable onPress={() => setShowTypePicker(true)} style={[styles.input, { borderColor: ACCENT }]}>
          <ThemedText>{typeLabel}</ThemedText>
        </Pressable>
        <SelectModal
          visible={showTypePicker}
          onClose={() => setShowTypePicker(false)}
          options={DOCUMENT_TYPE_OPTIONS}
          selectedValue={docType}
          onSelect={(value) => setDocType(value as DocumentType)}
        />

        {docType === 'proof_of_travel' ? (
          <>
            <ThemedText type="defaultSemiBold">Proof for</ThemedText>
            <ThemedText style={styles.hint}>
              Ties this document to a specific stop or leg, shows up as supporting evidence on that
              country&apos;s day-count.
            </ThemedText>
            <Pressable onPress={() => setShowTripPicker(true)} style={[styles.input, { borderColor: ACCENT }]}>
              <ThemedText>{tripLinkLabel}</ThemedText>
            </Pressable>
            <TripStopPicker
              visible={showTripPicker}
              onClose={() => setShowTripPicker(false)}
              trips={trips}
              stops={stops}
              segments={segments}
              selectedValue={tripLinkValue}
              onSelect={(value) => {
                setShowTripPicker(false);
                setTripLinkValue(value);
              }}
            />
          </>
        ) : null}

        <ThemedText type="defaultSemiBold">Name</ThemedText>
        <TextInput
          value={name}
          onChangeText={setName}
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        <ThemedText type="defaultSemiBold">Issue date</ThemedText>
        <ThemedView style={styles.dateRow}>
          <ThemedView style={styles.dateInput}>
            <DateInput
              value={issueDate}
              onChange={(date) => {
                setIssueDate(date);
                if (expiryDate && expiryDate < date) setExpiryDate(date);
              }}
              accentColor={ACCENT}
              placeholder="Not set"
            />
          </ThemedView>
          {issueDate ? (
            <Pressable onPress={() => setIssueDate(null)} hitSlop={8}>
              <ThemedText style={{ color: Colors.light.negative }}>Clear</ThemedText>
            </Pressable>
          ) : null}
        </ThemedView>

        <ThemedText type="defaultSemiBold">Expiry date</ThemedText>
        <ThemedView style={styles.dateRow}>
          <ThemedView style={styles.dateInput}>
            <DateInput
              value={expiryDate}
              onChange={setExpiryDate}
              accentColor={ACCENT}
              minimumDate={issueDate ?? undefined}
              placeholder="Not set"
            />
          </ThemedView>
          {expiryDate ? (
            <Pressable onPress={() => setExpiryDate(null)} hitSlop={8}>
              <ThemedText style={{ color: Colors.light.negative }}>Clear</ThemedText>
            </Pressable>
          ) : null}
        </ThemedView>

        <ThemedText type="defaultSemiBold">Notes</ThemedText>
        <TextInput
          value={notes}
          onChangeText={setNotes}
          placeholder="Optional"
          placeholderTextColor={Colors.light.textMuted}
          multiline
          numberOfLines={3}
          style={[styles.input, styles.notesInput, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        <Pressable onPress={handleSave} disabled={isSaving} style={[styles.button, { backgroundColor: ACCENT }]}>
          {isSaving ? (
            <ActivityIndicator color={ModuleAccentOnColor.documents} />
          ) : (
            <ThemedText style={{ color: ModuleAccentOnColor.documents, fontWeight: '600' }}>Save changes</ThemedText>
          )}
        </Pressable>

        <Pressable onPress={handleDelete} disabled={isDeleting} style={styles.deleteLink}>
          {isDeleting ? (
            <ActivityIndicator color={Colors.light.negative} />
          ) : (
            <ThemedText style={{ color: Colors.light.negative }}>Delete document</ThemedText>
          )}
        </Pressable>
      </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  centered: { alignItems: 'center', justifyContent: 'center' },
  padded: { padding: 16, gap: 8 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 8,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
    gap: 12,
  },
  preview: {
    width: '100%',
    height: 240,
    borderRadius: 8,
    marginBottom: 8,
  },
  sectionSpacing: {
    marginTop: 8,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  buttonOutline: {
    backgroundColor: 'transparent',
    borderWidth: StyleSheet.hairlineWidth,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  dateRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
  },
  dateInput: {
    flex: 1,
  },
  notesInput: {
    minHeight: 80,
    textAlignVertical: 'top',
  },
  deleteLink: {
    alignItems: 'center',
    marginTop: 16,
  },
  error: {
    color: Colors.light.negative,
  },
});
