import { ScrollView, StyleSheet } from 'react-native';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccents } from '@/constants/theme';
import { formatMoney } from '@/lib/currency';
import { DEMO_ACCOUNTS, demoIlliquidNetWorth, demoLiquidNetWorth } from '@/lib/demoData';

const ACCENT = ModuleAccents.accounts;
const LIQUID_COLOR = ModuleAccents.accounts;
const ILLIQUID_COLOR = ModuleAccents.documents;

/**
 * Illustrates the Accounts/Wealth screens' liquid-vs-illiquid net worth
 * split (see lib/liquidity.ts) with a fabricated portfolio — a brand new
 * account has no accounts logged yet, so there's nothing real to show a
 * liquidity split of. Pure presentation, no Supabase reads or writes.
 */
export default function DemoLiquidityScreen() {
  const liquid = demoLiquidNetWorth();
  const illiquid = demoIlliquidNetWorth();

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedText type="title" style={{ color: ACCENT }}>
          Liquidity
        </ThemedText>
        <ThemedText style={styles.muted}>
          Example portfolio, not your real accounts. Cash counts as liquid; investments and real estate (and debt
          secured against them, like a mortgage) count as illiquid, so unrealized gains don&apos;t read as spendable
          cash on hand.
        </ThemedText>

        <ThemedView style={styles.tierRow}>
          <Surface accentColor={LIQUID_COLOR} style={styles.tierTile}>
            <ThemedText style={styles.muted}>Liquid net worth</ThemedText>
            <ThemedText type="mono" style={styles.tierValue} numberOfLines={1} adjustsFontSizeToFit>
              {formatMoney(liquid, 'USD')}
            </ThemedText>
          </Surface>
          <Surface accentColor={ILLIQUID_COLOR} style={styles.tierTile}>
            <ThemedText style={styles.muted}>Illiquid net worth</ThemedText>
            <ThemedText type="mono" style={styles.tierValue} numberOfLines={1} adjustsFontSizeToFit>
              {formatMoney(illiquid, 'USD')}
            </ThemedText>
          </Surface>
        </ThemedView>

        <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
          Example accounts
        </ThemedText>
        {DEMO_ACCOUNTS.map((account) => (
          <Surface key={account.name} accentColor={account.liquid ? LIQUID_COLOR : ILLIQUID_COLOR}>
            <ThemedView style={styles.rowBetween}>
              <ThemedView>
                <ThemedText type="defaultSemiBold">{account.name}</ThemedText>
                <ThemedText style={styles.muted}>{account.institution}</ThemedText>
              </ThemedView>
              <ThemedView style={{ alignItems: 'flex-end' }}>
                <ThemedText type="mono">{formatMoney(account.balance, account.currency)}</ThemedText>
                <ThemedText style={styles.muted}>{account.liquid ? 'Liquid' : 'Illiquid'}</ThemedText>
              </ThemedView>
            </ThemedView>
          </Surface>
        ))}

        <ThemedText style={[styles.muted, styles.sectionSpacing]}>
          Your real accounts get the same breakdown automatically, on the Accounts and Wealth screens. Nothing to
          set up.
        </ThemedText>
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 96,
  },
  tierRow: {
    flexDirection: 'row',
    gap: 8,
    marginTop: 4,
  },
  tierTile: {
    flex: 1,
    gap: 4,
  },
  tierValue: {
    fontSize: 18,
  },
  sectionSpacing: {
    marginTop: 16,
  },
  rowBetween: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
});
