import { SelectModal, type SelectOption } from '@/components/select-modal';
import { computeTripSummaries } from '@/lib/trips';
import type { CountryVisitedRow, TripRow, TripSegmentRow } from '@/types/database';

const MODE_LABELS: Record<TripSegmentRow['mode'], string> = {
  flight: 'Flight',
  train: 'Train',
  car: 'Car',
  bus: 'Bus',
  ferry: 'Ferry',
  other: 'Travel',
};

export const NOT_LINKED_VALUE = 'none';

/** `stop:{id}` or `segment:{id}` — encodes which column the caller should set. */
export type TripLinkValue = string;

/**
 * Explicit "this expense is for this stop/leg" picker (app/transactions/[id].tsx's
 * override field) — one option per stop and per travel leg across every
 * trip, grouped by trip so a long trip history doesn't read as one flat
 * list. Mirrors components/category-picker.tsx's props-driven shape (caller
 * loads trips/stops/segments, this just renders them) rather than
 * self-fetching, so it stays a pure presentation component.
 */
export function TripStopPicker({
  visible,
  onClose,
  trips,
  stops,
  segments,
  selectedValue,
  onSelect,
}: {
  visible: boolean;
  onClose: () => void;
  trips: TripRow[];
  stops: CountryVisitedRow[];
  segments: TripSegmentRow[];
  selectedValue: TripLinkValue | null;
  onSelect: (value: TripLinkValue) => void;
}) {
  const summaries = computeTripSummaries(trips, stops, segments);
  const segmentsByTrip = new Map<string, TripSegmentRow[]>();
  for (const segment of segments) {
    const list = segmentsByTrip.get(segment.trip_id) ?? [];
    list.push(segment);
    segmentsByTrip.set(segment.trip_id, list);
  }

  const options: SelectOption[] = [{ value: NOT_LINKED_VALUE, label: 'Not linked (automatic)' }];

  for (const summary of summaries) {
    let firstInTrip = true;
    for (const stop of summary.stops) {
      options.push({
        value: `stop:${stop.id}`,
        label: `${summary.displayName}: ${stop.city?.trim() || stop.country}`,
        dividerBefore: firstInTrip,
      });
      firstInTrip = false;
    }
    for (const segment of segmentsByTrip.get(summary.id) ?? []) {
      options.push({
        value: `segment:${segment.id}`,
        label: `${summary.displayName}: ${segment.from_label} → ${segment.to_label} (${MODE_LABELS[segment.mode]})`,
        dividerBefore: firstInTrip,
      });
      firstInTrip = false;
    }
  }

  return (
    <SelectModal
      visible={visible}
      onClose={onClose}
      options={options}
      selectedValue={selectedValue ?? NOT_LINKED_VALUE}
      onSelect={onSelect}
    />
  );
}
