import { StyleSheet, Text, View } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { axisUnitFor, formatAxisTick, niceTicks } from '@/lib/chartScale';
import { formatMoney } from '@/lib/currency';
import type { BarBucket } from '@/lib/cardSpendDetail';

const CHART_HEIGHT = 140;
// Left gutter reserved for the Y-axis value labels, same treatment as
// components/candlestick-chart.tsx and components/line-chart.tsx.
const AXIS_GUTTER = 44;
const TICK_COUNT = 4;

export function SpendBarChart({ buckets, color, currency }: { buckets: BarBucket[]; color: string; currency: string }) {
  const maxAmount = Math.max(...buckets.map((b) => b.amount), 0);

  if (buckets.length === 0 || maxAmount <= 0) {
    return <ThemedText style={styles.muted}>No spend to chart yet.</ThemedText>;
  }

  const ticks = niceTicks(0, maxAmount, TICK_COUNT).filter((t) => t >= 0 && t <= maxAmount);
  const axisUnit = axisUnitFor(ticks);
  const topTick = ticks[ticks.length - 1];

  function yFor(value: number): number {
    return CHART_HEIGHT - (value / maxAmount) * CHART_HEIGHT;
  }

  return (
    <ThemedView style={styles.container}>
      <View style={styles.plotRow}>
        <View style={{ height: CHART_HEIGHT, width: AXIS_GUTTER }}>
          {ticks.map((tick) => (
            <Text
              key={tick}
              numberOfLines={1}
              style={[styles.axisLabel, { top: Math.min(Math.max(yFor(tick) - 7, 0), CHART_HEIGHT - 14) }]}>
              {formatAxisTick(tick, currency, axisUnit, tick === topTick)}
            </Text>
          ))}
        </View>
        <View style={styles.flexOne}>
          {/* Recessive gridlines — a visual reference for the labels, not a focal element. */}
          {ticks.map((tick) => (
            <View key={tick} style={[styles.gridline, { top: yFor(tick) }]} />
          ))}
          <ThemedView style={styles.barsRow}>
            {buckets.map((bucket, index) => {
              const barHeight = bucket.amount > 0 ? Math.max((bucket.amount / maxAmount) * CHART_HEIGHT, 4) : 0;
              return (
                <ThemedView key={index} style={styles.barColumn}>
                  <ThemedView style={styles.barTrack}>
                    <View style={[styles.bar, { height: barHeight, backgroundColor: color }]} />
                  </ThemedView>
                  <ThemedText style={styles.barLabel} numberOfLines={1}>
                    {bucket.label}
                  </ThemedText>
                </ThemedView>
              );
            })}
          </ThemedView>
        </View>
      </View>
      <ThemedText style={styles.muted}>Peak: {formatMoney(maxAmount, currency)}</ThemedText>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  container: {
    gap: 8,
  },
  plotRow: {
    flexDirection: 'row',
  },
  flexOne: {
    flex: 1,
  },
  axisLabel: {
    position: 'absolute',
    left: 0,
    width: AXIS_GUTTER - 8,
    fontSize: 10,
    lineHeight: 14,
    textAlign: 'right',
    color: Colors.light.textMuted,
    opacity: 0.8,
  },
  gridline: {
    position: 'absolute',
    left: 0,
    right: 0,
    borderTopWidth: 1,
    borderTopColor: Colors.light.cardBorder,
    opacity: 0.35,
  },
  barsRow: {
    flexDirection: 'row',
    alignItems: 'flex-end',
    justifyContent: 'space-around',
    height: CHART_HEIGHT + 20,
  },
  barColumn: {
    alignItems: 'center',
    gap: 4,
    flex: 1,
  },
  barTrack: {
    height: CHART_HEIGHT,
    justifyContent: 'flex-end',
  },
  bar: {
    width: 16,
    borderRadius: 4,
  },
  barLabel: {
    fontSize: 10,
    opacity: 0.6,
    color: Colors.light.textMuted,
  },
  muted: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    textAlign: 'center',
  },
});
