import { useFocusEffect } from '@react-navigation/native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, RefreshControl, ScrollView, StyleSheet } from 'react-native';

import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { SharedModuleNav } from '@/components/shared-module-nav';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useConnectionDisplay } from '@/hooks/use-connection-display';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { formatMoney } from '@/lib/currency';
import { supabase } from '@/lib/supabase';

const ACCENT = ModuleAccents.accounts;

type SharedAccount = {
  user_id: string;
  name: string;
  institution: string | null;
  currency: string;
  account_type: string;
  /** null unless the sharer opted into "Also share balances" for this connection. */
  balance: number | null;
};

export default function SharedAccountsScreen() {
  const { connectionId } = useLocalSearchParams<{ connectionId: string }>();
  const router = useRouter();
  const display = useConnectionDisplay(connectionId);
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const [accounts, setAccounts] = useState<SharedAccount[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const { data, error: fetchError } = await supabase.rpc('shared_accounts', { p_connection_id: connectionId });
    if (fetchError) {
      setError(fetchError.message);
    } else {
      setAccounts(data ?? []);
    }
    setIsLoading(false);
  }, [connectionId]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  const assets = accounts.filter((a) => a.account_type === 'asset');
  const liabilities = accounts.filter((a) => a.account_type === 'liability');

  function renderGroup(title: string, group: SharedAccount[]) {
    return (
      <>
        <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
          {title}
        </ThemedText>
        {group.length === 0 ? <ThemedText style={styles.muted}>None shared.</ThemedText> : null}
        {group.map((account, index) => (
          <Surface key={index} accentColor={ACCENT}>
            <ThemedText type="defaultSemiBold">
              {account.name}
              {account.institution ? ` · ${account.institution}` : ''}
            </ThemedText>
            {account.balance != null ? (
              <ThemedText type="mono">{formatMoney(account.balance, account.currency)}</ThemedText>
            ) : (
              <ThemedText style={styles.muted}>{account.currency}</ThemedText>
            )}
          </Surface>
        ))}
      </>
    );
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel
        connections={swipeConnections}
        isLoading={isConnectionsLoading}
        accentColor={ACCENT}
        activeConnectionId={connectionId}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }} numberOfLines={1} adjustsFontSizeToFit>
            {display.displayName}&apos;s Accounts
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <SharedModuleNav connectionId={connectionId} accentColor={ACCENT} active="accounts" />
        <ScrollView
          contentContainerStyle={styles.content}
          refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
          {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}
          <ThemedText style={styles.hint}>
            Balances only show if {display.displayName} has chosen to include them.
          </ThemedText>

          {isLoading ? (
            <ActivityIndicator color={ACCENT} />
          ) : (
            <>
              {renderGroup('Assets', assets)}
              {renderGroup('Liabilities', liabilities)}
            </>
          )}
        </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: 16,
    paddingBottom: 8,
  },
  sectionSpacing: {
    marginTop: 16,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
});
