import type { AccountRow, BalanceSnapshotRow, TransactionRow } from '@/types/database';

export type Period = { start: Date; end: Date };

export type Candle = {
  periodStart: string;
  periodEnd: string;
  open: number;
  close: number;
  high: number;
  low: number;
  income: number;
  spend: number;
  net: number;
};

type ConvertFn = (amount: number, fromCurrency: string) => number;

export type LedgerInput = {
  /** is_internal_transfer is optional — callers scoped to a narrower row shape (e.g. FBAR/T1135/UK peak calcs, which don't read income/spend off the result anyway) can omit it; absent just means "not a transfer." */
  transactions: (Pick<TransactionRow, 'date' | 'amount' | 'currency' | 'account_id'> & { is_internal_transfer?: boolean })[];
  accounts: Pick<AccountRow, 'id' | 'tracking_method' | 'currency' | 'account_type' | 'asset_category'>[];
  balanceSnapshots: Pick<BalanceSnapshotRow, 'account_id' | 'date' | 'balance'>[];
  convert: ConvertFn;
};

function toDateOnlyString(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function addDays(date: Date, days: number): Date {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

function startOfWeek(date: Date): Date {
  const d = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  const day = d.getDay();
  const diff = (day === 0 ? -6 : 1) - day; // shift to Monday
  d.setDate(d.getDate() + diff);
  return d;
}

/** Recent calendar-aligned periods (weekly = Mon-Sun, monthly = 1st-last day), most recent last. */
export function generatePeriods(granularity: 'week' | 'month', count: number, today: Date = new Date()): Period[] {
  const periods: Period[] = [];

  if (granularity === 'week') {
    const currentWeekStart = startOfWeek(today);
    for (let i = count - 1; i >= 0; i--) {
      const start = addDays(currentWeekStart, -i * 7);
      periods.push({ start, end: addDays(start, 6) });
    }
  } else {
    for (let i = count - 1; i >= 0; i--) {
      const start = new Date(today.getFullYear(), today.getMonth() - i, 1);
      const end = new Date(start.getFullYear(), start.getMonth() + 1, 0);
      periods.push({ start, end });
    }
  }

  return periods;
}

/**
 * Calendar-aligned periods spanning an arbitrary [start, end] range —
 * used by the Wealth screen's Custom view. Bucket size is chosen
 * automatically from the range's span (short range → weekly, long range →
 * monthly) rather than collapsing the whole range into one candle: a
 * single before/after candle for a multi-month custom range rendered as a
 * near-invisible flat 1-2px bar (open ≈ close, no visible price movement
 * shown at all), which read as "nothing's there" even though the data was
 * fine — this gives the same kind of real period-by-period history Week/
 * Month already show, just clipped to the chosen range.
 */
export function generatePeriodsInRange(start: Date, end: Date): Period[] {
  const spanDays = (end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24);
  const granularity: 'week' | 'month' = spanDays <= 90 ? 'week' : 'month';
  const periods: Period[] = [];

  if (granularity === 'week') {
    let cursor = startOfWeek(start);
    while (cursor <= end) {
      periods.push({ start: cursor, end: addDays(cursor, 6) });
      cursor = addDays(cursor, 7);
    }
  } else {
    let cursor = new Date(start.getFullYear(), start.getMonth(), 1);
    while (cursor <= end) {
      periods.push({ start: cursor, end: new Date(cursor.getFullYear(), cursor.getMonth() + 1, 0) });
      cursor = new Date(cursor.getFullYear(), cursor.getMonth() + 1, 1);
    }
  }

  return periods;
}

/**
 * Sign convention: a liability's stored amount is always a positive
 * magnitude — "amount owed" — exactly like an asset's balance is a positive
 * magnitude. You never enter a negative number to represent debt, whether
 * that's a balance_snapshots.balance or a transaction's amount on a
 * transaction_based liability account (there, positive = debt increased,
 * negative = debt paid down, same increase/decrease meaning as on an asset
 * account — only the account_type flips how it nets into wealth).
 *
 * The negation for net worth happens in exactly one place — here, via
 * signFor() — not at data-entry time and not anywhere else. Every other
 * screen (account detail, balance log) shows the raw positive magnitude.
 *
 * Card-linked transactions (card_id, no account_id) are untouched by this:
 * credit_cards has no asset/liability typing, so their sign is whatever the
 * user entered, same as before this fix.
 */
function buildBalanceModel({ transactions, accounts, balanceSnapshots, convert }: LedgerInput) {
  const accountTypeById = new Map(accounts.map((a) => [a.id, a.account_type]));
  const accountCurrencyById = new Map(accounts.map((a) => [a.id, a.currency]));
  const balanceBasedAccountIds = new Set(
    accounts.filter((a) => a.tracking_method === 'balance_based').map((a) => a.id)
  );
  const realEstateAccountIds = new Set(
    accounts.filter((a) => a.asset_category === 'real_estate').map((a) => a.id)
  );

  function netWorthSign(accountId: string | null): 1 | -1 {
    if (!accountId) return 1;
    return accountTypeById.get(accountId) === 'liability' ? -1 : 1;
  }

  // `raw` feeds income/spend, `netWorthDelta` feeds the running
  // balance/open/close/high/low. Three kinds of transaction are excluded
  // from income/spend entirely (all three still fully participate in net
  // worth via netWorthDelta, which was already correctly sign-flipped):
  //  - liability-account transactions (a loan/mortgage draw or paydown) —
  //    a draw isn't income and a paydown isn't spend in the everyday
  //    sense, it's financing activity.
  //  - real-estate-account transactions (asset side, e.g. logging a
  //    property's purchase price as a lump-sum transaction on the "Flat"
  //    account) — same reasoning as liabilities, just the other side of
  //    the same purchase: a capital/balance-sheet event, not income. A
  //    real_estate liability (a mortgage) was already excluded by the
  //    account_type check above, but the matching real_estate ASSET
  //    account wasn't — a $550,000 property purchase was showing up as
  //    $550,000 of "income" for that month.
  //  - is_internal_transfer transactions — a transfer between two of the
  //    user's own accounts is neither income nor spend, same distinction
  //    lib/csvExport.ts already draws (its own "Transfer" bucket).
  //
  // netWorthDelta is zeroed out (not raw, which still feeds income/spend)
  // for any transaction linked to a balance_based account: that account's
  // contribution to net worth already comes from balanceBasedContributionAsOf
  // below, off the latest snapshot. Balance-based accounts still commonly
  // have transactions recorded against them too (e.g. a CSV import, or
  // manual entries logged purely for spend categorization) — without this
  // exclusion those transactions' amounts were being summed into the
  // running balance a second time on top of the snapshot, double-counting
  // and inflating net worth for exactly that account. lib/accountBalance.ts
  // (used by the per-account list/detail screens) never had this bug — it
  // picks snapshot OR transaction sum per account, never both — which is
  // why a balance-based cash account's Home tile total could read higher
  // than what its own detail page showed for the same account.
  const txPoints = transactions
    .map((tx) => {
      const raw = convert(tx.amount, tx.currency);
      const isLiabilityAccount = !!tx.account_id && accountTypeById.get(tx.account_id) === 'liability';
      const isRealEstateAccount = !!tx.account_id && realEstateAccountIds.has(tx.account_id);
      const isBalanceBasedAccount = !!tx.account_id && balanceBasedAccountIds.has(tx.account_id);
      return {
        date: tx.date,
        raw,
        netWorthDelta: isBalanceBasedAccount ? 0 : raw * netWorthSign(tx.account_id),
        excludeFromIncomeSpend: isLiabilityAccount || isRealEstateAccount || !!tx.is_internal_transfer,
      };
    })
    .sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));

  const snapshotsByAccount = new Map<string, { date: string; value: number }[]>();
  for (const snap of balanceSnapshots) {
    if (!balanceBasedAccountIds.has(snap.account_id)) continue;
    const currency = accountCurrencyById.get(snap.account_id) ?? 'USD';
    const list = snapshotsByAccount.get(snap.account_id) ?? [];
    const value = convert(snap.balance, currency) * netWorthSign(snap.account_id);
    list.push({ date: snap.date, value });
    snapshotsByAccount.set(snap.account_id, list);
  }
  for (const list of snapshotsByAccount.values()) {
    list.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
  }

  function transactionSumUpTo(date: string): number {
    let sum = 0;
    for (const point of txPoints) {
      if (point.date > date) break;
      sum += point.netWorthDelta;
    }
    return sum;
  }

  function balanceBasedContributionAsOf(date: string): number {
    let total = 0;
    for (const list of snapshotsByAccount.values()) {
      let latest: number | null = null;
      for (const point of list) {
        if (point.date > date) break;
        latest = point.value;
      }
      total += latest ?? 0;
    }
    return total;
  }

  function runningBalanceAsOf(date: string): number {
    return transactionSumUpTo(date) + balanceBasedContributionAsOf(date);
  }

  return { txPoints, snapshotsByAccount, runningBalanceAsOf };
}

/** The current running balance as of a given date (defaults to today) — same model computeWealthSeries uses. */
export function computeCurrentBalance(params: LedgerInput & { asOf?: Date }): number {
  const { runningBalanceAsOf } = buildBalanceModel(params);
  return runningBalanceAsOf(toDateOnlyString(params.asOf ?? new Date()));
}

/**
 * Computes one candle per period from the raw transactions/accounts/balance_snapshots
 * ledger — no snapshot table for the chart itself, everything is derived live.
 *
 * Open/close/high/low come from evaluating the running balance at period
 * boundaries and at every date within the period where something changed.
 */
export function computeWealthSeries(params: LedgerInput & { periods: Period[] }): Candle[] {
  const { periods } = params;
  const { txPoints, snapshotsByAccount, runningBalanceAsOf } = buildBalanceModel(params);

  return periods.map(({ start, end }) => {
    const startStr = toDateOnlyString(start);
    const endStr = toDateOnlyString(end);
    const dayBeforeStart = toDateOnlyString(addDays(start, -1));

    const open = runningBalanceAsOf(dayBeforeStart);
    const close = runningBalanceAsOf(endStr);

    const eventDates = new Set<string>();
    for (const point of txPoints) {
      if (point.date >= startStr && point.date <= endStr) eventDates.add(point.date);
    }
    for (const list of snapshotsByAccount.values()) {
      for (const point of list) {
        if (point.date >= startStr && point.date <= endStr) eventDates.add(point.date);
      }
    }

    const values = [open, close, ...Array.from(eventDates).map((d) => runningBalanceAsOf(d))];
    const high = Math.max(...values);
    const low = Math.min(...values);

    let income = 0;
    let spend = 0;
    for (const point of txPoints) {
      if (point.date < startStr || point.date > endStr) continue;
      if (point.excludeFromIncomeSpend) continue;
      if (point.raw >= 0) income += point.raw;
      else spend += -point.raw;
    }

    return {
      periodStart: startStr,
      periodEnd: endStr,
      open,
      close,
      high,
      low,
      income,
      spend,
      net: close - open,
    };
  });
}
