import 'leaflet/dist/leaflet.css';

import type { Map as LeafletMap } from 'leaflet';
import { useEffect, useRef, useState } from 'react';

import { Colors, ModuleAccents } from '@/constants/theme';
import { catmullRomLegPath, type RoutePoint, type TripLeg } from '@/lib/tripRoute';

const MAP_HEIGHT = 260;
const BOUNDS_PADDING: [number, number] = [24, 24];
// See trip-route-map.tsx's own DASH_PATTERN — same idea, Leaflet's own
// dash syntax (a space-separated "dash gap" string) instead of an array.
const DASH_PATTERN = '8 6';

type LeafletModule = typeof import('react-leaflet');

// Expo Router's web build server-renders every route, and leaflet touches
// `window` the moment its module body runs (not just when a component
// mounts) — a static import of it crashes SSR outright with "window is not
// defined". Loading it via a dynamic import inside useEffect instead
// guarantees it's never touched until after the component has actually
// mounted in a real browser, which is the one thing React promises about
// effects regardless of the SSR setup's specific internals. Cached at
// module scope so a second TripRouteMap on the same page (or navigating
// back to one) doesn't re-fetch it. (The `leaflet/dist/leaflet.css` import
// above is fine to keep static — it's a stylesheet, not JS, and never
// touches `window`; only the type-only `Map` import from 'leaflet' below
// is used for the ref, which TypeScript strips entirely at compile time.)
let cachedModule: LeafletModule | null = null;

/**
 * Web's trip route map — react-native-maps has no web support at all (same
 * gap components/connections-map.web.tsx already works around), so this
 * uses Leaflet with real OpenStreetMap tiles instead, giving actual
 * streets and place names rather than a stylized stand-in. iOS/Android use
 * the real react-native-maps-backed component in trip-route-map.tsx;
 * Metro's platform extension resolution picks whichever matches the build
 * target, so callers just import from './trip-route-map'.
 */
export function TripRouteMap({
  points,
  legs,
  onSelectLeg,
  height = MAP_HEIGHT,
}: {
  points: RoutePoint[];
  legs: TripLeg[];
  onSelectLeg: (legId: string) => void;
  /** Overrides the default compact height — the fullscreen expand view passes a taller one. */
  height?: number;
}) {
  const [leaflet, setLeaflet] = useState<LeafletModule | null>(cachedModule);
  const mapInstanceRef = useRef<LeafletMap | null>(null);
  const pointsKey = points.map((p) => `${p.id}:${p.lat}:${p.lon}`).join('|');

  useEffect(() => {
    if (cachedModule) return;
    let cancelled = false;
    import('react-leaflet').then((mod) => {
      if (cancelled) return;
      cachedModule = mod;
      setLeaflet(mod);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  // The `bounds` prop on MapContainer only applies once, at creation — a
  // trip whose stops arrive gradually (older stops get their real
  // coordinates backfilled asynchronously, see
  // app/countries/trips/[id].tsx) would otherwise stay framed on wherever
  // the FIRST render's points happened to be, forcing a manual zoom-out
  // once the rest resolve. Re-fitting explicitly whenever the actual point
  // set changes keeps the view honest.
  useEffect(() => {
    if (points.length === 0 || !mapInstanceRef.current) return;
    if (points.length === 1) {
      mapInstanceRef.current.setView([points[0].lat, points[0].lon], 11);
      return;
    }
    mapInstanceRef.current.fitBounds(
      points.map((p): [number, number] => [p.lat, p.lon]),
      { padding: BOUNDS_PADDING }
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pointsKey, leaflet]);

  if (points.length === 0 || !leaflet) {
    return <div style={{ height, borderRadius: 12, overflow: 'hidden' }} />;
  }

  const { MapContainer, TileLayer, Polyline, CircleMarker } = leaflet;
  const bounds = points.map((p): [number, number] => [p.lat, p.lon]);

  return (
    <div style={{ height, borderRadius: 12, overflow: 'hidden' }}>
      <MapContainer
        ref={mapInstanceRef}
        bounds={bounds}
        boundsOptions={{ padding: BOUNDS_PADDING }}
        // Matches OSM's ocean tile color instead of Leaflet's default
        // gray container background (#ddd) — masks the hairline gaps that
        // show up between adjacent raster tiles on fractional-DPI
        // displays, a documented Leaflet rendering quirk, not a bug here.
        style={{ height: '100%', width: '100%', backgroundColor: '#aad3df' }}
        scrollWheelZoom={false}>
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        {legs.map((leg, index) => (
          <Polyline
            key={leg.id}
            positions={catmullRomLegPath(points, index).map((p): [number, number] => [p.lat, p.lon])}
            pathOptions={{
              color: leg.color,
              weight: 5,
              lineCap: 'round',
              lineJoin: 'round',
              dashArray: leg.hasSegment || leg.mode ? undefined : DASH_PATTERN,
            }}
            eventHandlers={{ click: () => onSelectLeg(leg.id) }}
          />
        ))}
        {points.map((point, index) => (
          <CircleMarker
            key={point.id}
            center={[point.lat, point.lon]}
            radius={7}
            pathOptions={{
              color: Colors.light.backgroundSolid,
              weight: 2,
              fillColor: index === 0 ? ModuleAccents.wealth : index === points.length - 1 ? Colors.light.negative : ModuleAccents.countries,
              fillOpacity: 1,
            }}
          />
        ))}
      </MapContainer>
    </div>
  );
}
