import { allowedDaysAwayFromHome, projectedDaysAwayFromHomeByYearEnd } from '@/lib/days';
import { FOREIGN_REPORTING_JURISDICTIONS } from '@/lib/foreignAssetReporting';
import { LOYALTY_EXPIRY_NOTICE_WINDOW_DAYS } from '@/lib/loyalty';
import { daysUntilRenewal, nextPaymentDueDate } from '@/lib/renewal';
import type { CountryVisitedRow, CreditCardRow, DocumentRow, LoyaltyAccountRow } from '@/types/database';

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export const RENEWAL_NOTICE_WINDOW_DAYS = 30;
export const PAYMENT_NOTICE_WINDOW_DAYS = 7;
export const DOCUMENT_EXPIRY_NOTICE_WINDOW_DAYS = 60;

/**
 * The full set of currently-active notice ids — a stable identifier per
 * notice (e.g. `renewal:<cardId>`, not just "a renewal notice exists") so
 * the TopBar badge can diff this against a snapshot taken at last Summary
 * view and count what's newly active, rather than just "is anything active
 * right now." See lib/notices.ts usage in app/summary.tsx and top-bar.tsx.
 */
export function computeActiveNotices(params: {
  cards: Pick<CreditCardRow, 'id' | 'renewal_date' | 'payment_due_day'>[];
  homeCountry: string | null;
  countryVisits: CountryVisitedRow[];
  /** Optional so existing callers that haven't been updated yet still compile — omitting it just means document-expiry notices aren't checked. */
  documents?: Pick<DocumentRow, 'id' | 'expiry_date'>[];
  /** Pre-computed via computeForeignAssetPeak (lib/foreignAssetReporting.ts) by the caller — notices.ts stays a thin aggregator rather than duplicating the wealth-series high-water-mark calculation itself. null/undefined just means the check is skipped. Each is additionally gated on the matching citizenship — FBAR/T1135 are US/Canada-citizen obligations, not something every user should be notified about. */
  fbarPeakUsd?: number | null;
  hasUsCitizenship?: boolean;
  t1135PeakCad?: number | null;
  hasCanadianCitizenship?: boolean;
  /** Ids of incoming connection_share_requests / trip_plan_requests rows still 'pending', and trip_plan_requests I made that are now 'accepted' — someone sharing/requesting/accepting something with you is exactly the kind of thing this badge exists for, and previously wasn't counted at all. Passed as plain id arrays (not full rows) since callers already have to fetch/filter these for Summary's own cards. */
  pendingShareRequestIds?: string[];
  pendingPlanRequestIds?: string[];
  acceptedPlanRequestIds?: string[];
  /** trips rows created via share_trip_with_connection (created_via_share = true) that belong to me — "X shared a trip with you." */
  sharedTripIds?: string[];
  /** trip_collaborators rows (068) still 'pending' where I'm the invited collaborator — "X wants your help with their trip." */
  pendingTripCollaborationInviteIds?: string[];
  /** countries_visited ids from city_visit_alerts() (069) — a connection's current/upcoming stop in my home city. Keyed per stop so a second visit by the same person is a fresh notice. */
  cityVisitStopIds?: string[];
  /** loyalty_accounts (071) with an expiry_date — points lapsing within LOYALTY_EXPIRY_NOTICE_WINDOW_DAYS get the same treatment as an expiring document. */
  loyaltyAccounts?: Pick<LoyaltyAccountRow, 'id' | 'expiry_date'>[];
  /** shared_trip_notes ids authored by a travel partner (not me) — "X commented on your trip planning." */
  tripNoteIds?: string[];
  today?: Date;
}): string[] {
  const today = params.today ?? new Date();
  const todayOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const notices: string[] = [];

  for (const card of params.cards) {
    if (daysUntilRenewal(card.renewal_date, today) <= RENEWAL_NOTICE_WINDOW_DAYS) {
      notices.push(`renewal:${card.id}`);
    }
    if (card.payment_due_day) {
      const due = nextPaymentDueDate(card.payment_due_day, today);
      const daysToDue = Math.round((due.getTime() - todayOnly.getTime()) / MS_PER_DAY);
      if (daysToDue <= PAYMENT_NOTICE_WINDOW_DAYS) {
        notices.push(`payment:${card.id}`);
      }
    }
  }

  // daysUntilRenewal is generic "days until this date string" math despite
  // its card-renewal-flavored name — reused as-is for document expiry
  // rather than duplicating the same calculation under a second name.
  // <= the window naturally also catches already-expired documents
  // (negative days-until), same as an overdue card renewal would be.
  for (const document of params.documents ?? []) {
    if (!document.expiry_date) continue;
    if (daysUntilRenewal(document.expiry_date, today) <= DOCUMENT_EXPIRY_NOTICE_WINDOW_DAYS) {
      notices.push(`document-expiry:${document.id}`);
    }
  }

  if (params.hasUsCitizenship && params.fbarPeakUsd != null && params.fbarPeakUsd > FOREIGN_REPORTING_JURISDICTIONS.fbar.threshold!) {
    notices.push('fbar-threshold');
  }

  if (
    params.hasCanadianCitizenship &&
    params.t1135PeakCad != null &&
    params.t1135PeakCad > FOREIGN_REPORTING_JURISDICTIONS.t1135.threshold!
  ) {
    notices.push('t1135-threshold');
  }

  if (!params.homeCountry) {
    notices.push('no-home-country');
  } else {
    const projected = projectedDaysAwayFromHomeByYearEnd(params.countryVisits, params.homeCountry, today);
    if (projected > allowedDaysAwayFromHome(params.homeCountry, today)) {
      notices.push('tax-warning');
    }
  }

  for (const id of params.pendingShareRequestIds ?? []) notices.push(`share-request:${id}`);
  for (const id of params.pendingPlanRequestIds ?? []) notices.push(`plan-request:${id}`);
  for (const id of params.acceptedPlanRequestIds ?? []) notices.push(`plan-accepted:${id}`);
  for (const id of params.sharedTripIds ?? []) notices.push(`shared-trip:${id}`);
  for (const id of params.pendingTripCollaborationInviteIds ?? []) notices.push(`trip-collab-invite:${id}`);
  for (const id of params.cityVisitStopIds ?? []) notices.push(`city-visit:${id}`);
  for (const id of params.tripNoteIds ?? []) notices.push(`trip-note:${id}`);

  for (const account of params.loyaltyAccounts ?? []) {
    if (!account.expiry_date) continue;
    if (daysUntilRenewal(account.expiry_date, today) <= LOYALTY_EXPIRY_NOTICE_WINDOW_DAYS) {
      notices.push(`loyalty-expiry:${account.id}`);
    }
  }

  return notices;
}

/** Notices in `current` that aren't in `lastViewedNotices` — what the TopBar badge counts. */
export function countUnviewedNotices(current: string[], lastViewedNotices: string[]): number {
  const seen = new Set(lastViewedNotices);
  return current.filter((id) => !seen.has(id)).length;
}
