import { useEffect, useRef, useState } from 'react';
import { Modal, Pressable, ScrollView, StyleSheet, View } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { Colors } from '@/constants/theme';
import { formatDateDisplay, toDateOnlyString } from '@/lib/format';
import { computeWeekRows } from '@/lib/tripCalendar';
import type { DateInputProps } from './date-input-types';

const WEEKDAY_LABELS = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];
const MONTH_LABELS = Array.from({ length: 12 }, (_, i) => new Date(2000, i, 1).toLocaleDateString(undefined, { month: 'short' }));
// A generous fixed window rather than deriving from minimumDate/maximumDate
// — those bounds vary per field (or are absent entirely) and a trip date
// can legitimately be well in the past (backfilling an old trip) or well in
// the future (planning ahead), so this just needs to comfortably cover
// both without being unbounded.
const YEAR_RANGE = { past: 80, future: 20 };

/**
 * A hand-rolled calendar-grid popover, not the OS-native date picker —
 * @react-native-community/datetimepicker's "inline" display mode (the only
 * one that looks like a real calendar rather than a spinner) turned out to
 * render broken under Expo Go on iOS, and Android's native picker can only
 * ever show as a popup dialog regardless of display mode, never truly
 * inline. Since neither platform's native widget could be made to actually
 * match the other, this replaces both with one plain-RN implementation —
 * identical on iOS, Android, and web (this file has no .web.tsx sibling
 * anymore; the same component renders everywhere). Reuses
 * lib/tripCalendar.ts's computeWeekRows for the month-grid math rather than
 * re-deriving it, same as the shared trip calendar.
 */
export function DateInput({
  value,
  onChange,
  accentColor,
  minimumDate,
  maximumDate,
  disabledRanges,
  placeholder = 'Select a date',
}: DateInputProps) {
  const [showPicker, setShowPicker] = useState(false);
  const [displayMonth, setDisplayMonth] = useState(() => value ?? new Date());
  // 'days' is the normal calendar grid; tapping the "March 2026" header
  // drills into 'months' (a 12-month grid for one year, for jumping
  // several months at once), and tapping the year there drills further
  // into 'years' (a scrollable list) — for reaching a date far from today
  // without clicking the ‹ › arrows one month at a time.
  const [viewMode, setViewMode] = useState<'days' | 'months' | 'years'>('days');

  const minStr = minimumDate ? toDateOnlyString(minimumDate) : null;
  const maxStr = maximumDate ? toDateOnlyString(maximumDate) : null;
  const selectedStr = value ? toDateOnlyString(value) : null;
  const todayStr = toDateOnlyString(new Date());

  function open() {
    setDisplayMonth(value ?? new Date());
    setViewMode('days');
    setShowPicker(true);
  }

  function changeMonth(delta: number) {
    setDisplayMonth((d) => new Date(d.getFullYear(), d.getMonth() + delta, 1));
  }

  function selectDay(day: Date) {
    onChange(day);
    setShowPicker(false);
  }

  function selectMonth(monthIndex: number) {
    setDisplayMonth((d) => new Date(d.getFullYear(), monthIndex, 1));
    setViewMode('days');
  }

  function selectYear(year: number) {
    setDisplayMonth((d) => new Date(year, d.getMonth(), 1));
    setViewMode('months');
  }

  const weeks = computeWeekRows(displayMonth, 'month');
  const currentYear = new Date().getFullYear();
  const years = Array.from(
    { length: YEAR_RANGE.past + YEAR_RANGE.future + 1 },
    (_, i) => currentYear - YEAR_RANGE.past + i
  );
  const yearScrollRef = useRef<ScrollView>(null);
  const YEAR_ROW_HEIGHT = 49;
  const YEAR_COLUMNS = 4;

  // Jumps straight to the displayed year (roughly centered) instead of
  // always starting the list at its oldest entry — the whole point of a
  // year picker is reaching a far-off date in one tap, not one long scroll.
  useEffect(() => {
    if (viewMode !== 'years') return;
    const index = years.indexOf(displayMonth.getFullYear());
    if (index < 0) return;
    const row = Math.floor(index / YEAR_COLUMNS);
    const targetY = Math.max(0, row * YEAR_ROW_HEIGHT - YEAR_ROW_HEIGHT * 2);
    // Deferred a frame so the ScrollView has actually laid out before
    // scrollTo runs — calling it in the same tick as the mode switch is a
    // no-op on some platforms since the view isn't measured yet.
    const timer = setTimeout(() => yearScrollRef.current?.scrollTo({ y: targetY, animated: false }), 0);
    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [viewMode]);

  return (
    <>
      <Pressable onPress={open} style={[styles.input, { borderColor: accentColor }]}>
        <ThemedText type="mono">{value ? formatDateDisplay(toDateOnlyString(value)) : placeholder}</ThemedText>
      </Pressable>

      <Modal visible={showPicker} transparent animationType="fade" onRequestClose={() => setShowPicker(false)}>
        <Pressable style={styles.backdrop} onPress={() => setShowPicker(false)}>
          <Pressable style={[styles.card, { borderColor: accentColor }]} onPress={(e) => e.stopPropagation()}>
            <View style={styles.header}>
              {viewMode !== 'years' ? (
                <Pressable
                  onPress={() => (viewMode === 'days' ? changeMonth(-1) : setDisplayMonth((d) => new Date(d.getFullYear() - 1, d.getMonth(), 1)))}
                  hitSlop={10}>
                  <ThemedText style={[styles.nav, { color: accentColor }]}>‹</ThemedText>
                </Pressable>
              ) : (
                <View style={styles.navPlaceholder} />
              )}
              {viewMode === 'days' ? (
                <Pressable onPress={() => setViewMode('months')} hitSlop={6}>
                  <ThemedText type="defaultSemiBold">
                    {displayMonth.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}
                  </ThemedText>
                </Pressable>
              ) : viewMode === 'months' ? (
                <Pressable onPress={() => setViewMode('years')} hitSlop={6}>
                  <ThemedText type="defaultSemiBold">{displayMonth.getFullYear()}</ThemedText>
                </Pressable>
              ) : (
                <ThemedText type="defaultSemiBold">Select a year</ThemedText>
              )}
              {viewMode !== 'years' ? (
                <Pressable
                  onPress={() => (viewMode === 'days' ? changeMonth(1) : setDisplayMonth((d) => new Date(d.getFullYear() + 1, d.getMonth(), 1)))}
                  hitSlop={10}>
                  <ThemedText style={[styles.nav, { color: accentColor }]}>›</ThemedText>
                </Pressable>
              ) : (
                <View style={styles.navPlaceholder} />
              )}
            </View>

            {viewMode === 'days' ? (
              <>
                <View style={styles.weekdayRow}>
                  {WEEKDAY_LABELS.map((label, i) => (
                    <ThemedText key={i} style={styles.weekdayLabel}>
                      {label}
                    </ThemedText>
                  ))}
                </View>

                {weeks.map((week, weekIndex) => (
                  <View key={weekIndex} style={styles.weekRow}>
                    {week.map((day) => {
                      const dayStr = toDateOnlyString(day);
                      const inMonth = day.getMonth() === displayMonth.getMonth();
                      const isDisabled =
                        (!!minStr && dayStr < minStr) ||
                        (!!maxStr && dayStr > maxStr) ||
                        (disabledRanges?.some((r) => dayStr >= r.start && dayStr <= r.end) ?? false);
                      const isSelected = dayStr === selectedStr;
                      const isToday = dayStr === todayStr;
                      return (
                        <Pressable
                          key={dayStr}
                          disabled={isDisabled}
                          onPress={() => selectDay(day)}
                          style={[styles.dayCell, isSelected ? { backgroundColor: accentColor } : null]}>
                          <ThemedText
                            style={[
                              styles.dayText,
                              !inMonth ? styles.dayTextOutOfMonth : null,
                              isDisabled ? styles.dayTextDisabled : null,
                              isSelected ? styles.dayTextSelected : null,
                              isToday && !isSelected ? { color: accentColor, fontWeight: '700' } : null,
                            ]}>
                            {day.getDate()}
                          </ThemedText>
                        </Pressable>
                      );
                    })}
                  </View>
                ))}
              </>
            ) : viewMode === 'months' ? (
              <View style={styles.monthGrid}>
                {MONTH_LABELS.map((label, index) => {
                  const isSelected = index === displayMonth.getMonth();
                  return (
                    <Pressable
                      key={label}
                      onPress={() => selectMonth(index)}
                      style={[styles.gridCell, isSelected ? { backgroundColor: accentColor } : null]}>
                      <ThemedText style={isSelected ? styles.dayTextSelected : styles.dayText}>{label}</ThemedText>
                    </Pressable>
                  );
                })}
              </View>
            ) : (
              <ScrollView ref={yearScrollRef} style={styles.yearScroll}>
                <View style={styles.monthGrid}>
                  {years.map((year) => {
                    const isSelected = year === displayMonth.getFullYear();
                    return (
                      <Pressable
                        key={year}
                        onPress={() => selectYear(year)}
                        style={[styles.gridCell, isSelected ? { backgroundColor: accentColor } : null]}>
                        <ThemedText style={isSelected ? styles.dayTextSelected : styles.dayText}>{year}</ThemedText>
                      </Pressable>
                    );
                  })}
                </View>
              </ScrollView>
            )}
          </Pressable>
        </Pressable>
      </Modal>
    </>
  );
}

const styles = StyleSheet.create({
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  backdrop: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: 'rgba(0,0,0,0.25)',
  },
  card: {
    width: 300,
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 14,
    padding: 14,
    backgroundColor: Colors.light.backgroundSolid,
    shadowColor: '#000',
    shadowOpacity: 0.15,
    shadowRadius: 8,
    shadowOffset: { width: 0, height: 4 },
    elevation: 6,
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 10,
  },
  nav: {
    fontSize: 20,
    fontWeight: '700',
    paddingHorizontal: 10,
  },
  navPlaceholder: {
    width: 20,
  },
  monthGrid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
  },
  gridCell: {
    width: '25%',
    aspectRatio: 1.4,
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: 10,
  },
  yearScroll: {
    maxHeight: 280,
  },
  weekdayRow: {
    flexDirection: 'row',
    marginBottom: 4,
  },
  weekdayLabel: {
    flex: 1,
    textAlign: 'center',
    fontSize: 11,
    fontWeight: '600',
    opacity: 0.6,
    color: Colors.light.textMuted,
  },
  weekRow: {
    flexDirection: 'row',
  },
  dayCell: {
    flex: 1,
    aspectRatio: 1,
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: 999,
  },
  dayText: {
    fontSize: 14,
    color: Colors.light.text,
  },
  dayTextOutOfMonth: {
    opacity: 0.3,
  },
  dayTextDisabled: {
    opacity: 0.25,
  },
  dayTextSelected: {
    color: Colors.light.backgroundSolid,
    fontWeight: '700',
  },
});
