import { File, Paths } from 'expo-file-system';
import { useRouter } from 'expo-router';
import * as Sharing from 'expo-sharing';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors } from '@/constants/theme';
import { buildTransactionsCsv } from '@/lib/csvExport';
import { fetchAllRows } from '@/lib/fetchAll';
import { supabase } from '@/lib/supabase';
import type { TransactionRow } from '@/types/database';

const TINT = Colors.light.tint;

export default function ExportDataScreen() {
  const router = useRouter();
  const currentYear = new Date().getFullYear();
  const [year, setYear] = useState(currentYear);
  const [isExporting, setIsExporting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const exportYear = useCallback(async () => {
    setError(null);
    setIsExporting(true);
    try {
      const start = `${year}-01-01`;
      const end = `${year}-12-31`;

      const [txResult, categoriesResult, accountsResult, cardsResult] = await Promise.all([
        fetchAllRows<TransactionRow>((from, to) =>
          supabase.from('transactions').select('*').gte('date', start).lte('date', end).order('date').order('id').range(from, to)
        ),
        supabase.from('categories').select('id, name'),
        supabase.from('accounts').select('id, name'),
        supabase.from('credit_cards').select('id, name'),
      ]);

      if (txResult.error) {
        setError(txResult.error.message);
        setIsExporting(false);
        return;
      }

      const transactions = txResult.data;
      if (transactions.length === 0) {
        setError(`No transactions found for ${year}.`);
        setIsExporting(false);
        return;
      }

      const categoryNameById = new Map((categoriesResult.data ?? []).map((c) => [c.id, c.name]));
      const accountNameById = new Map((accountsResult.data ?? []).map((a) => [a.id, a.name]));
      const cardNameById = new Map((cardsResult.data ?? []).map((c) => [c.id, c.name]));

      const csv = buildTransactionsCsv(transactions, categoryNameById, accountNameById, cardNameById);

      const filename = `cluster-transactions-${year}.csv`;
      const file = new File(Paths.cache, filename);
      if (file.exists) {
        file.delete();
      }
      file.create();
      file.write(csv);

      const canShare = await Sharing.isAvailableAsync();
      if (!canShare) {
        setError('Sharing is not available on this device. The file was generated but could not be shared.');
        setIsExporting(false);
        return;
      }

      await Sharing.shareAsync(file.uri, {
        mimeType: 'text/csv',
        UTI: 'public.comma-separated-values-text',
        dialogTitle: `Cluster transactions ${year}`,
      });
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Export failed.');
    } finally {
      setIsExporting(false);
    }
  }, [year]);

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: TINT }}>
            Export Transactions
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedText style={styles.muted}>
          A plain CSV of every transaction in the selected year: clear headers, no formatting, ready to hand to an
          accountant or tax preparer.
        </ThemedText>

        <Surface accentColor={TINT} style={styles.yearRow}>
          <Pressable onPress={() => setYear((y) => y - 1)} hitSlop={12}>
            <IconSymbol name="chevron.left" size={20} color={TINT} />
          </Pressable>
          <ThemedText type="mono" style={styles.yearValue}>
            {year}
          </ThemedText>
          <Pressable onPress={() => setYear((y) => Math.min(y + 1, currentYear))} hitSlop={12}>
            <IconSymbol name="chevron.right" size={20} color={TINT} />
          </Pressable>
        </Surface>

        <Pressable
          onPress={exportYear}
          disabled={isExporting}
          style={[styles.exportButton, { backgroundColor: TINT, opacity: isExporting ? 0.6 : 1 }]}>
          {isExporting ? (
            <ActivityIndicator color={Colors.light.backgroundSolid} />
          ) : (
            <ThemedText style={styles.exportButtonText}>Export {year} as CSV</ThemedText>
          )}
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 12,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  yearRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 24,
  },
  yearValue: {
    fontSize: 22,
  },
  exportButton: {
    borderRadius: 10,
    paddingVertical: 16,
    alignItems: 'center',
    justifyContent: 'center',
  },
  exportButtonText: {
    color: Colors.light.backgroundSolid,
    fontWeight: '600',
    fontSize: 16,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
});
