import { useFocusEffect } from '@react-navigation/native';
import { File } from 'expo-file-system';
import * as ImagePicker from 'expo-image-picker';
import { useRouter } from 'expo-router';
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, Switch } from 'react-native';

import { Avatar } from '@/components/avatar';
import { CityAutocompleteInput } from '@/components/city-autocomplete-input';
import { CountryAutocompleteInput } from '@/components/country-autocomplete-input';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { useCurrency } from '@/contexts/currency-context';
import { useTour } from '@/contexts/tour-context';
import { flagCodeForCountry } from '@/lib/countries';
import { supabase } from '@/lib/supabase';

const MAX_AVATAR_FILE_SIZE_BYTES = 5 * 1024 * 1024;

const TINT = Colors.light.tint;

type MenuHref =
  | '/account/details'
  | '/account/citizenship'
  | '/account/checklist'
  | '/account/data'
  | '/account/share'
  | '/account/referrals'
  | '/account/faq'
  | '/onboarding';

// Sharing settings moved off this menu — reachable from the settings icon
// on the connections swipe panel (any Countries/Cards/Accounts/Documents/
// Home screen) instead, now that it's tied to browsing a specific
// connection rather than being a standalone destination.
const MENU_ITEMS: { label: string; href: MenuHref }[] = [
  { label: 'Account Details', href: '/account/details' },
  { label: 'Citizenship', href: '/account/citizenship' },
  { label: 'Data & Import', href: '/account/data' },
  { label: 'Referrals', href: '/account/referrals' },
  { label: 'FAQs', href: '/account/faq' },
  { label: 'Replay Walkthrough', href: '/onboarding' },
];

export default function AccountScreen() {
  const router = useRouter();
  const { session, signOut } = useAuth();
  const { homeCountry, setHomeCountry, hiddenFlagCountries, settingsError, avatarUrl, avatarPath, setAvatarPath } =
    useCurrency();
  const { step } = useTour();
  const isHomeCountryHighlighted = step?.highlightAnchor === 'home-country-picker';
  // Free-typed draft, distinct from homeCountry itself — setHomeCountry
  // (from useCurrency) upserts to the database on every call, so raw
  // keystrokes can't flow straight into it (that would persist a partial
  // country name on every letter typed). Synced from homeCountry via the
  // effect below whenever it changes externally (initial load, or a
  // successful handleSelectHomeCountry save); committed back only via
  // onSelectCountry or an exact-match blur (see handleHomeCountryBlur).
  const [countryDraft, setCountryDraft] = useState('');
  useEffect(() => {
    setCountryDraft(homeCountry ?? '');
  }, [homeCountry]);
  const [homeCity, setHomeCityState] = useState('');
  const [isSavingCity, setIsSavingCity] = useState(false);
  const [wheelSpinOnLoad, setWheelSpinOnLoadState] = useState(true);
  // Gates the home-city section below so it doesn't render a wrong '' default
  // for an instant before the real saved value loads — the specific crash
  // this was originally added for (a structural swap between two different
  // city-picker branches racing the tour's router.replace, "addViewAt:
  // failed to insert view... already has a parent") no longer applies now
  // that there's a single CityAutocompleteInput instead of two branches, but
  // still worth avoiding a flash of the wrong value.
  const [isCitySettingsLoaded, setIsCitySettingsLoaded] = useState(false);
  const [isSavingPhoto, setIsSavingPhoto] = useState(false);
  const [photoError, setPhotoError] = useState<string | null>(null);

  // Named for its original purpose (home city) but now also loads the
  // wheel-spin-on-load setting below — kept as one fetch rather than a
  // second round trip for a single extra column.
  const loadHomeCity = useCallback(async () => {
    if (!session) return;
    const { data } = await supabase
      .from('user_settings')
      .select('home_city, wheel_spin_on_load')
      .eq('user_id', session.user.id)
      .maybeSingle();
    setHomeCityState(data?.home_city ?? '');
    setWheelSpinOnLoadState(data?.wheel_spin_on_load ?? true);
    setIsCitySettingsLoaded(true);
  }, [session]);

  useFocusEffect(
    useCallback(() => {
      loadHomeCity();
    }, [loadHomeCity])
  );

  async function handleToggleWheelSpin(value: boolean) {
    setWheelSpinOnLoadState(value);
    if (!session) return;
    const { error } = await supabase
      .from('user_settings')
      .upsert({ user_id: session.user.id, wheel_spin_on_load: value }, { onConflict: 'user_id' });
    if (error) {
      console.error('Failed to save wheel-spin preference:', error.message);
      setWheelSpinOnLoadState(!value);
    }
  }

  async function saveHomeCity(city: string) {
    if (!session) return;
    setHomeCityState(city);
    setIsSavingCity(true);
    await supabase
      .from('user_settings')
      .upsert({ user_id: session.user.id, home_city: city.trim() || null }, { onConflict: 'user_id' });
    setIsSavingCity(false);
  }

  // A "move" (worth prompting a fresh setup checklist for) is specifically
  // a CHANGE from an already-set home country — not the first time someone
  // ever sets one. Recorded here, before the value actually changes, so we
  // still have the old value to compare against.
  async function handleSelectHomeCountry(newCountry: string) {
    if (session && homeCountry && homeCountry !== newCountry) {
      await supabase
        .from('pending_moves')
        .insert({ user_id: session.user.id, from_country: homeCountry, to_country: newCountry });
    }
    setHomeCountry(newCountry);
    // The old city almost certainly doesn't belong to the new country —
    // clear it rather than leave a stale mismatch (same reasoning as the
    // country/city pair in app/countries/visit/[id].tsx).
    saveHomeCity('');
  }

  // Commits the typed draft only if it's an exact match for a real country
  // (flagCodeForCountry is an exact lookup against lib/countries.ts) — lets
  // someone type the full name and tab away without needing to tap a
  // suggestion first. Anything else on blur (a half-typed name, an actual
  // typo) reverts the draft back to the last saved value rather than
  // leaving invalid text sitting in the field.
  function handleHomeCountryBlur() {
    const trimmed = countryDraft.trim();
    if (trimmed && trimmed !== homeCountry && flagCodeForCountry(trimmed)) {
      handleSelectHomeCountry(trimmed);
    } else {
      setCountryDraft(homeCountry ?? '');
    }
  }

  async function handleChangePhoto() {
    if (!session) return;
    setPhotoError(null);
    const permission = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (!permission.granted) {
      setPhotoError('Photo library permission is required.');
      return;
    }

    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ['images'],
      quality: 0.8,
      allowsEditing: true,
      aspect: [1, 1],
    });
    if (result.canceled || !result.assets[0]) return;

    const asset = result.assets[0];
    if (asset.fileSize && asset.fileSize > MAX_AVATAR_FILE_SIZE_BYTES) {
      setPhotoError('That photo is larger than 5MB. Please choose a smaller one.');
      return;
    }

    setIsSavingPhoto(true);
    const previousPath = avatarPath;

    try {
      // Same file:// / content:// URI caveat as the documents upload flow —
      // fetch(uri).blob() is unreliable for picker URIs on device.
      const file = new File(asset.uri);
      const bytes = await file.bytes();
      const extension = (asset.mimeType ?? 'image/jpeg').includes('png') ? 'png' : 'jpg';
      // Timestamped, not a fixed "avatar.jpg" — the top bar renders this
      // photo's URL from every screen, and a fixed path would keep serving
      // a browser/CDN-cached copy of the old photo after a change.
      const path = `${session.user.id}/avatar-${Date.now()}.${extension}`;

      const { error: uploadError } = await supabase.storage
        .from('avatars')
        .upload(path, bytes, { contentType: asset.mimeType ?? 'image/jpeg' });
      if (uploadError) {
        setPhotoError(uploadError.message);
        setIsSavingPhoto(false);
        return;
      }

      await setAvatarPath(path);
      if (previousPath) {
        await supabase.storage.from('avatars').remove([previousPath]);
      }
    } catch (err) {
      setPhotoError(err instanceof Error ? err.message : 'Upload failed.');
    } finally {
      setIsSavingPhoto(false);
    }
  }

  async function handleRemovePhoto() {
    if (!session || !avatarPath) return;
    setPhotoError(null);
    const previousPath = avatarPath;
    await setAvatarPath(null);
    await supabase.storage.from('avatars').remove([previousPath]);
  }

  return (
    <ThemedView variant="screen" style={styles.container}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={isHomeCountryHighlighted ? styles.tourDimmed : undefined}>
          <ThemedText type="title">Account</ThemedText>
          <ThemedText type="mono" style={styles.muted}>
            {session?.user.email}
          </ThemedText>
          {settingsError ? <ThemedText style={styles.error}>{settingsError}</ThemedText> : null}

          <ThemedView style={styles.photoRow}>
            {session ? (
              <Avatar userId={session.user.id} email={session.user.email ?? ''} photoUrl={avatarUrl} size={72} />
            ) : null}
            <ThemedView style={styles.photoActions}>
              <Pressable onPress={handleChangePhoto} disabled={isSavingPhoto} hitSlop={4}>
                {isSavingPhoto ? (
                  <ActivityIndicator color={TINT} />
                ) : (
                  <ThemedText type="link">{avatarUrl ? 'Change Photo' : 'Add Photo'}</ThemedText>
                )}
              </Pressable>
              {avatarUrl && !isSavingPhoto ? (
                <Pressable onPress={handleRemovePhoto} hitSlop={4}>
                  <ThemedText style={{ color: Colors.light.negative }}>Remove</ThemedText>
                </Pressable>
              ) : null}
            </ThemedView>
          </ThemedView>
          {photoError ? <ThemedText style={styles.error}>{photoError}</ThemedText> : null}
        </ThemedView>

        <ThemedText type="defaultSemiBold" style={styles.fieldLabel}>
          Home country
        </ThemedText>
        <CountryAutocompleteInput
          value={countryDraft}
          onChangeText={setCountryDraft}
          onSelectCountry={handleSelectHomeCountry}
          onBlur={handleHomeCountryBlur}
          hiddenFlagCountries={hiddenFlagCountries}
          accentColor={TINT}
          inputStyle={isHomeCountryHighlighted ? styles.inputHighlighted : undefined}
        />
        <ThemedText style={styles.hint}>
          Used as a fallback currency for the wealth chart, and for tax-jurisdiction tracking.
        </ThemedText>

        <ThemedView style={isHomeCountryHighlighted ? styles.tourDimmed : undefined}>
          {homeCountry ? (
            <Pressable onPress={() => router.push('/account/checklist')} hitSlop={4}>
              <ThemedText type="link" style={styles.checklistLink}>
                View {homeCountry} setup checklist
              </ThemedText>
            </Pressable>
          ) : null}

          <ThemedText type="defaultSemiBold" style={styles.fieldLabel}>
            Home city
          </ThemedText>
          {!homeCountry ? (
            <ThemedText style={styles.hint}>Set your home country above first.</ThemedText>
          ) : !isCitySettingsLoaded ? null : (
            <CityAutocompleteInput
              value={homeCity}
              onChangeText={setHomeCityState}
              onSelectPlace={(place) => saveHomeCity(place.name)}
              onBlur={() => saveHomeCity(homeCity)}
              countryCode={flagCodeForCountry(homeCountry)?.split('-')[0] ?? undefined}
              placeholder="e.g. Austin"
              accentColor={TINT}
            />
          )}
          {homeCountry ? (
            <ThemedText style={styles.hint}>
              {isSavingCity ? 'Saving...' : "Used to flag when a connection's trip brings them to your city."}
            </ThemedText>
          ) : null}

          <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: TINT }]}>
            Settings
          </ThemedText>
          <Surface accentColor={TINT} style={styles.menuRow}>
            <ThemedView style={styles.toggleLabelColumn}>
              <ThemedText type="defaultSemiBold">Spin wheel on load</ThemedText>
              <ThemedText style={styles.hint}>Plays the Home screen wheel&apos;s entrance animation every time it loads.</ThemedText>
            </ThemedView>
            <Switch value={wheelSpinOnLoad} onValueChange={handleToggleWheelSpin} trackColor={{ true: TINT }} />
          </Surface>
          {MENU_ITEMS.map((item) => (
            <Pressable key={item.href} onPress={() => router.push(item.href)}>
              <Surface accentColor={TINT} style={styles.menuRow}>
                <ThemedText type="defaultSemiBold">{item.label}</ThemedText>
                <IconSymbol name="chevron.right" size={18} color={TINT} />
              </Surface>
            </Pressable>
          ))}

          <Pressable onPress={signOut} style={[styles.button, { backgroundColor: TINT }]}>
            <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Sign Out</ThemedText>
          </Pressable>

          <Pressable onPress={() => router.push('/account/delete')} style={styles.deleteLink} hitSlop={8}>
            <ThemedText style={{ color: Colors.light.negative }}>Close Account</ThemedText>
          </Pressable>
        </ThemedView>
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  // Applied to everything OTHER than the tour's currently-highlighted
  // element, when there is one — see app/index.tsx's own copy of this
  // style for why plain opacity on a wrapper beats a separately-positioned
  // overlay trying to track the element's screen position.
  tourDimmed: {
    opacity: 0.3,
  },
  container: {
    flex: 1,
  },
  content: {
    padding: 24,
    gap: 8,
    paddingBottom: 48,
  },
  muted: {
    opacity: 0.7,
    marginBottom: 8,
  },
  photoRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 16,
    marginTop: 8,
  },
  photoActions: {
    gap: 8,
  },
  fieldLabel: {
    marginTop: 8,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
  },
  inputHighlighted: {
    borderWidth: 3,
    shadowColor: TINT,
    shadowOpacity: 0.5,
    shadowRadius: 8,
    shadowOffset: { width: 0, height: 0 },
    elevation: 6,
  },
  inputRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
  },
  checklistLink: {
    fontSize: 13,
  },
  sectionSpacing: {
    marginTop: 16,
  },
  menuRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  toggleLabelColumn: {
    flex: 1,
    gap: 2,
    marginRight: 12,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 24,
  },
  deleteLink: {
    alignItems: 'center',
    marginTop: 16,
  },
  error: {
    color: Colors.light.negative,
  },
});
