import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, RefreshControl, ScrollView, StyleSheet } from 'react-native';

import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { supabase } from '@/lib/supabase';
import type { CategoryRow, CategoryRuleRow } from '@/types/database';

const ACCENT = ModuleAccents.spend;

/**
 * Manage the merchant → category rules that auto-categorize new
 * transactions (see the merchant-blur handler in app/transactions/new.tsx
 * and [id].tsx) — same rules CSV/PDF import has always applied silently,
 * now with somewhere to see, add, and delete them instead of only ever
 * being created one at a time from "Always categorize this as…" on a
 * transaction.
 */
export default function CategoryRulesScreen() {
  const router = useRouter();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();
  const [rules, setRules] = useState<CategoryRuleRow[]>([]);
  const [categories, setCategories] = useState<CategoryRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const [rulesResult, categoriesResult] = await Promise.all([
      supabase.from('category_rules').select('*').order('created_at', { ascending: false }),
      supabase.from('categories').select('*'),
    ]);
    if (rulesResult.error) {
      setError(rulesResult.error.message);
      setIsLoading(false);
      return;
    }
    setRules(rulesResult.data ?? []);
    setCategories(categoriesResult.data ?? []);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  const categoryNameById = new Map(categories.map((c) => [c.id, c.name]));

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView
        contentContainerStyle={styles.content}
        refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Category Rules
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedText style={styles.hint}>
          When a new transaction&apos;s merchant contains a rule&apos;s text, it&apos;s categorized automatically.
          You can always change it afterward on that transaction. Applied to manual entries and CSV/PDF imports;
          never changes a transaction you&apos;ve already categorized yourself.
        </ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {isLoading ? (
          <ActivityIndicator color={ACCENT} />
        ) : rules.length === 0 ? (
          <ThemedText style={styles.muted}>
            No rules yet. Add one below, or open any transaction and tap &quot;Always categorize this as…&quot;.
          </ThemedText>
        ) : (
          rules.map((rule) => (
            <Pressable key={rule.id} onPress={() => router.push(`/spend/rules/${rule.id}`)}>
              <Surface accentColor={ACCENT} style={styles.ruleRow}>
                <ThemedView style={styles.ruleText}>
                  <ThemedText type="defaultSemiBold" numberOfLines={1}>
                    &quot;{rule.merchant_pattern}&quot;
                  </ThemedText>
                  <ThemedText style={styles.muted} numberOfLines={1}>
                    → {categoryNameById.get(rule.category_id) ?? 'Unknown category'}
                  </ThemedText>
                </ThemedView>
                <IconSymbol name="chevron.right" size={16} color={ACCENT} />
              </Surface>
            </Pressable>
          ))
        )}

        <Pressable
          onPress={() => router.push('/spend/rules/new')}
          style={[styles.addButton, { borderColor: ACCENT }]}>
          <ThemedText style={{ color: ACCENT, fontWeight: '600' }}>+ Add rule</ThemedText>
        </Pressable>
      </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 4,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 8,
  },
  ruleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 8,
  },
  ruleText: {
    flex: 1,
    gap: 2,
  },
  addButton: {
    marginTop: 8,
    borderWidth: 1.5,
    borderStyle: 'dashed',
    borderRadius: 12,
    paddingVertical: 14,
    alignItems: 'center',
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
});
