import { useFocusEffect } from '@react-navigation/native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, View, useWindowDimensions } from 'react-native';

import { CategoryPieChart } from '@/components/category-pie-chart';
import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { DateInput } from '@/components/date-input';
import { ScopeSwitch } from '@/components/scope-switch';
import { SpendBarChart } from '@/components/spend-bar-chart';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { TransactionCategoryFilter } from '@/components/transaction-category-filter';
import { TransactionRow as TransactionRowItem } from '@/components/transaction-row';
import { TransactionSortControl } from '@/components/transaction-sort-control';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { useScope } from '@/contexts/scope-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { summarizeCardBalances } from '@/lib/cardBalance';
import { computeSpendBarBuckets, dueDayFractionOfMonth, type SpendGranularity } from '@/lib/cardSpendDetail';
import { formatMoney } from '@/lib/currency';
import { fetchAllRows } from '@/lib/fetchAll';
import { formatDateDisplay, toDateOnlyString } from '@/lib/format';
import { nextPaymentDueDate } from '@/lib/renewal';
import { summarizeSpendByCategory, type CategorySpend } from '@/lib/spend';
import { supabase } from '@/lib/supabase';
import { filterByCategory, type TransactionCategoryFilterValue } from '@/lib/transactionFilter';
import { sortTransactions, type TransactionSortDirection, type TransactionSortField } from '@/lib/transactionSort';
import { generatePeriods, type Period } from '@/lib/wealthSeries';
import type { CategoryRow, CategoryRuleRow, CountryVisitedRow, CreditCardRow, TransactionRow } from '@/types/database';

const ACCENT = ModuleAccents.cards;
const MARKER_SIZE = 20;
// Card-linked transactions never have an account_id, so account-level
// country-tracking exclusion never applies here — a stable empty Set
// avoids handing TransactionRow a fresh object identity every render.
const EMPTY_ACCOUNT_IDS = new Set<string>();

const GRANULARITY_OPTIONS: { value: SpendGranularity; label: string }[] = [
  { value: 'week', label: 'Week' },
  { value: 'month', label: 'Month' },
  { value: 'custom', label: 'Custom' },
];

function inPeriod(dateStr: string, period: Period): boolean {
  return dateStr >= toDateOnlyString(period.start) && dateStr <= toDateOnlyString(period.end);
}

function formatTotals(totals: { currency: string; amount: number }[]): string {
  if (totals.length === 0) return formatMoney(0, 'USD');
  return totals.map((t) => formatMoney(Math.abs(t.amount), t.currency)).join(' · ');
}

export default function CardSpendDetailScreen() {
  const router = useRouter();
  const { view } = useLocalSearchParams<{ view?: string }>();
  const { convert, displayCurrency, homeCountry } = useCurrency();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();
  const { width: windowWidth } = useWindowDimensions();

  const [viewTab, setViewTab] = useState<'summary' | 'transactions'>(
    view === 'transactions' ? 'transactions' : 'summary'
  );
  const [granularity, setGranularity] = useState<SpendGranularity>('month');
  const [customStart, setCustomStart] = useState(() => {
    const d = new Date();
    d.setDate(d.getDate() - 30);
    return d;
  });
  const [customEnd, setCustomEnd] = useState(new Date());
  const [chartMode, setChartMode] = useState<'pie' | 'bar'>('pie');

  const { filterCards, filterTransactions } = useScope();
  const [allCards, setCards] = useState<CreditCardRow[]>([]);
  const [allTransactions, setTransactions] = useState<TransactionRow[]>([]);
  const cards = filterCards(allCards);
  const transactions = filterTransactions(allTransactions);
  const [categories, setCategories] = useState<CategoryRow[]>([]);
  const [categoryRules, setCategoryRules] = useState<CategoryRuleRow[]>([]);
  const [visits, setVisits] = useState<CountryVisitedRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<TransactionSortField>('date');
  const [sortDirection, setSortDirection] = useState<TransactionSortDirection>('desc');
  const [categoryFilter, setCategoryFilter] = useState<TransactionCategoryFilterValue>('all');

  const load = useCallback(async () => {
    setError(null);
    const [cardsResult, transactionsResult, categoriesResult, categoryRulesResult, visitsResult] = await Promise.all([
      supabase.from('credit_cards').select('*').order('name', { ascending: true }),
      fetchAllRows<TransactionRow>((from, to) =>
        supabase.from('transactions').select('*').not('card_id', 'is', null).order('date', { ascending: false }).order('id').range(from, to)
      ),
      supabase.from('categories').select('*'),
      supabase.from('category_rules').select('*'),
      supabase.from('countries_visited').select('*'),
    ]);

    if (cardsResult.error) {
      setError(cardsResult.error.message);
      setIsLoading(false);
      return;
    }

    setCards(cardsResult.data ?? []);
    setTransactions(transactionsResult.data);
    setCategories(categoriesResult.data ?? []);
    setCategoryRules(categoryRulesResult.data ?? []);
    setVisits(visitsResult.data ?? []);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  const categoryNameById = new Map(categories.map((c) => [c.id, c.name]));
  const currentPeriod: Period =
    granularity === 'custom' ? { start: customStart, end: customEnd } : generatePeriods(granularity, 2)[1];

  // Spend only, and card transactions only — this page is scoped to credit
  // cards specifically, unlike the general Spend Detail which covers everything.
  // Feeds the Summary tab's stats (category/bar/pie breakdowns are spend-only
  // by design). The Transactions tab below shows everything on the card —
  // debits and credits both — since hiding payments/refunds there meant half
  // the card's activity was simply invisible.
  const cardSpendTx = transactions.filter((tx) => !tx.is_internal_transfer && tx.amount < 0);
  const periodTx = cardSpendTx.filter((tx) => inPeriod(tx.date, currentPeriod));
  const periodCardTxAll = transactions.filter((tx) => inPeriod(tx.date, currentPeriod));

  const categorySpend: CategorySpend[] = summarizeSpendByCategory(periodTx, categoryNameById, convert);
  const totalsByCurrency = new Map<string, number>();
  for (const cat of categorySpend) {
    for (const t of cat.totals) {
      totalsByCurrency.set(t.currency, (totalsByCurrency.get(t.currency) ?? 0) + t.amount);
    }
  }
  const totalSpend = Array.from(totalsByCurrency.entries()).map(([currency, amount]) => ({ currency, amount }));
  const chartCurrency = totalSpend[0]?.currency ?? displayCurrency;

  const pieSlices = categorySpend.map((c) => ({
    label: c.categoryName,
    amount: c.totals.reduce((sum, t) => sum + Math.abs(t.amount), 0),
    currency: c.totals[0]?.currency ?? chartCurrency,
  }));
  const barBuckets = computeSpendBarBuckets(currentPeriod, granularity, periodTx, convert);

  // Outstanding balance (all-time, not period-scoped) — the due-dates
  // timeline is about what's owed right now, not what was spent in the
  // currently-selected period.
  const cardBalances = summarizeCardBalances(transactions, convert);
  const today = new Date();
  // Matches the working renewal timeline on the Cards dashboard exactly
  // (single 32px subtraction for the ScrollView's own padding) — this had
  // drifted to subtracting 32 twice, narrowing the usable track for no reason.
  const trackWidth = windowWidth - 32 - MARKER_SIZE;
  const cardsWithDueDay = cards.filter((card) => card.payment_due_day);
  const sortedPeriodCardTxAll = sortTransactions(
    filterByCategory(periodCardTxAll, categoryRules, categoryFilter),
    sortField,
    sortDirection
  );

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView contentContainerStyle={styles.content}>
        <ScopeSwitch accent={ACCENT} onColor={ModuleAccentOnColor.cards} />
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Card Spend Detail
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedView style={styles.toggleRow}>
          <Pressable
            onPress={() => setViewTab('summary')}
            style={[styles.chip, { borderColor: ACCENT }, viewTab === 'summary' ? { backgroundColor: ACCENT } : null]}>
            <ThemedText style={viewTab === 'summary' ? styles.chipTextActive : undefined}>Summary</ThemedText>
          </Pressable>
          <Pressable
            onPress={() => setViewTab('transactions')}
            style={[
              styles.chip,
              { borderColor: ACCENT },
              viewTab === 'transactions' ? { backgroundColor: ACCENT } : null,
            ]}>
            <ThemedText style={viewTab === 'transactions' ? styles.chipTextActive : undefined}>
              Transactions
            </ThemedText>
          </Pressable>
        </ThemedView>

        {viewTab === 'transactions' ? (
          <>
            <ThemedView style={styles.filterSortRow}>
              <TransactionCategoryFilter
                categories={categories}
                value={categoryFilter}
                onChange={setCategoryFilter}
                accentColor={ACCENT}
              />
              <TransactionSortControl
                sortField={sortField}
                sortDirection={sortDirection}
                onChange={(field, direction) => {
                  setSortField(field);
                  setSortDirection(direction);
                }}
                accentColor={ACCENT}
              />
            </ThemedView>
            {sortedPeriodCardTxAll.length === 0 ? (
              <ThemedText style={styles.muted}>No transactions this period.</ThemedText>
            ) : null}
            {sortedPeriodCardTxAll.map((tx) => {
              const card = cards.find((c) => c.id === tx.card_id);
              return (
                <TransactionRowItem
                  key={tx.id}
                  transaction={tx}
                  accentColor={ACCENT}
                  convert={convert}
                  categories={categories}
                  categoryRules={categoryRules}
                  visits={visits}
                  homeCountry={homeCountry}
                  excludedAccountIds={EMPTY_ACCOUNT_IDS}
                  subtitle={card ? `${card.issuer} · ${card.name}` : 'Unknown card'}
                  onChange={(updated) => setTransactions((prev) => prev.map((t) => (t.id === updated.id ? updated : t)))}
                  onCategoryCreated={(category) => setCategories((prev) => [...prev, category])}
                />
              );
            })}
          </>
        ) : (
          <>
            <ThemedView style={styles.chipRow}>
              {GRANULARITY_OPTIONS.map((option) => {
                const isSelected = option.value === granularity;
                return (
                  <Pressable
                    key={option.value}
                    onPress={() => setGranularity(option.value)}
                    style={[
                      styles.chip,
                      { borderColor: ACCENT, backgroundColor: isSelected ? ACCENT : 'transparent' },
                    ]}>
                    <ThemedText style={isSelected ? styles.chipTextActive : undefined}>{option.label}</ThemedText>
                  </Pressable>
                );
              })}
            </ThemedView>

            {granularity === 'custom' ? (
              <ThemedView style={styles.customRow}>
                <DateInput
                  value={customStart}
                  onChange={(date) => {
                    setCustomStart(date);
                    if (customEnd < date) setCustomEnd(date);
                  }}
                  accentColor={ACCENT}
                />
                <ThemedText>&rarr;</ThemedText>
                <DateInput value={customEnd} onChange={setCustomEnd} accentColor={ACCENT} minimumDate={customStart} />
              </ThemedView>
            ) : null}

            <Surface accentColor={ACCENT}>
              <ThemedText style={styles.muted}>
                {formatDateDisplay(toDateOnlyString(currentPeriod.start))} &rarr;{' '}
                {formatDateDisplay(toDateOnlyString(currentPeriod.end))}
              </ThemedText>
              <ThemedText type="mono" style={styles.totalValue}>
                {totalSpend.length > 0 ? formatTotals(totalSpend) : formatMoney(0, 'USD')}
              </ThemedText>
              <ThemedText style={styles.muted}>Total card spend</ThemedText>
            </Surface>

            <Surface accentColor={ACCENT}>
              <ThemedText style={styles.muted}>
                {today.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })} due dates
              </ThemedText>
              {cardsWithDueDay.length === 0 ? (
                <ThemedText style={styles.muted}>
                  No payment due dates set yet. Add one from a card&apos;s details.
                </ThemedText>
              ) : (
                <>
                  <View style={[styles.timelineTrack, { marginHorizontal: MARKER_SIZE / 2 }]}>
                    <View style={styles.timelineLine} />
                    {cardsWithDueDay.map((card) => {
                      const fraction = dueDayFractionOfMonth(
                        card.payment_due_day!,
                        today.getFullYear(),
                        today.getMonth()
                      );
                      return (
                        <Pressable
                          key={card.id}
                          onPress={() => router.push(`/cards/${card.id}`)}
                          hitSlop={8}
                          style={[styles.timelineMarker, { left: fraction * trackWidth }]}>
                          <IconSymbol name="creditcard" size={12} color={ModuleAccentOnColor.cards} />
                        </Pressable>
                      );
                    })}
                  </View>
                  {cardsWithDueDay.map((card) => {
                    const dueDate = nextPaymentDueDate(card.payment_due_day!, today);
                    const owed = cardBalances.get(card.id) ?? [];
                    return (
                      <Pressable key={card.id} onPress={() => router.push(`/cards/${card.id}`)}>
                        <ThemedView style={styles.dueDateRow}>
                          <ThemedView style={styles.dueDateInfo}>
                            <ThemedText type="defaultSemiBold" numberOfLines={1}>
                              {card.issuer} · {card.name}
                            </ThemedText>
                            <ThemedText style={styles.muted}>
                              Due {formatDateDisplay(toDateOnlyString(dueDate))}
                            </ThemedText>
                          </ThemedView>
                          <ThemedText type="mono" style={[styles.dueAmountCallout, { color: ACCENT }]}>
                            {formatTotals(owed)}
                          </ThemedText>
                        </ThemedView>
                      </Pressable>
                    );
                  })}
                </>
              )}
            </Surface>

            <ThemedView style={styles.toggleRow}>
              <Pressable
                onPress={() => setChartMode('pie')}
                style={[styles.chip, { borderColor: ACCENT }, chartMode === 'pie' ? { backgroundColor: ACCENT } : null]}>
                <ThemedText style={chartMode === 'pie' ? styles.chipTextActive : undefined}>Pie</ThemedText>
              </Pressable>
              <Pressable
                onPress={() => setChartMode('bar')}
                style={[styles.chip, { borderColor: ACCENT }, chartMode === 'bar' ? { backgroundColor: ACCENT } : null]}>
                <ThemedText style={chartMode === 'bar' ? styles.chipTextActive : undefined}>Bar</ThemedText>
              </Pressable>
            </ThemedView>

            {chartMode === 'pie' ? (
              <CategoryPieChart slices={pieSlices} />
            ) : (
              <SpendBarChart buckets={barBuckets} color={ACCENT} currency={chartCurrency} />
            )}

            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
              By category
            </ThemedText>
            {categorySpend.length === 0 ? (
              <ThemedText style={styles.muted}>No spend logged this period.</ThemedText>
            ) : null}
            {categorySpend.map((entry) => (
              <Surface key={entry.categoryId ?? 'uncategorized'} accentColor={ACCENT}>
                <ThemedView style={styles.rowBetween}>
                  <ThemedText type="defaultSemiBold">{entry.categoryName}</ThemedText>
                  <ThemedText type="mono">{formatTotals(entry.totals)}</ThemedText>
                </ThemedView>
              </Surface>
            ))}

            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
              By card
            </ThemedText>
            {cards.length === 0 ? <ThemedText style={styles.muted}>No cards yet.</ThemedText> : null}
            {cards.map((card) => {
              const cardPeriodTx = periodTx.filter((tx) => tx.card_id === card.id);
              const cardTotalsByCurrency = new Map<string, number>();
              for (const tx of cardPeriodTx) {
                const { amount, currency } = convert(tx.amount, tx.currency);
                cardTotalsByCurrency.set(currency, (cardTotalsByCurrency.get(currency) ?? 0) + amount);
              }
              const cardTotals = Array.from(cardTotalsByCurrency.entries()).map(([currency, amount]) => ({
                currency,
                amount,
              }));
              const cardTopCategories = summarizeSpendByCategory(cardPeriodTx, categoryNameById, convert).slice(0, 3);

              return (
                <Pressable key={card.id} onPress={() => router.push(`/cards/${card.id}`)}>
                  <Surface accentColor={ACCENT} style={styles.cardBreakdownCard}>
                    <ThemedView style={styles.cardSplitRow}>
                      <ThemedView style={styles.cardVisual}>
                        <ThemedView style={[styles.cardIconBox, { backgroundColor: ACCENT }]}>
                          <IconSymbol name="creditcard" size={22} color={ModuleAccentOnColor.cards} />
                        </ThemedView>
                        <ThemedText type="defaultSemiBold" numberOfLines={1}>
                          {card.issuer}
                        </ThemedText>
                        <ThemedText style={styles.muted} numberOfLines={1}>
                          {card.name}
                        </ThemedText>
                      </ThemedView>
                      <ThemedView style={styles.cardSpendDetail}>
                        <ThemedText type="mono" style={styles.cardSpendValue} numberOfLines={1} adjustsFontSizeToFit>
                          {cardTotals.length > 0 ? formatTotals(cardTotals) : formatMoney(0, 'USD')}
                        </ThemedText>
                        <ThemedText style={styles.muted}>spend this period</ThemedText>
                      </ThemedView>
                    </ThemedView>
                    {cardTopCategories.length > 0 ? (
                      <ThemedView style={styles.topCategoriesRow}>
                        {cardTopCategories.map((cat) => (
                          <ThemedText
                            key={cat.categoryId ?? 'uncategorized'}
                            style={styles.muted}
                            numberOfLines={1}>
                            {cat.categoryName}: {formatTotals(cat.totals)}
                          </ThemedText>
                        ))}
                      </ThemedView>
                    ) : (
                      <ThemedText style={styles.muted}>No spend this period.</ThemedText>
                    )}
                  </Surface>
                </Pressable>
              );
            })}
          </>
        )}
      </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

