import worldBoundariesData from '@/assets/data/world-boundaries.json';

import { countryNameForMapId } from '@/lib/worldMapData';

/**
 * Real country border/coastline geometry (GeoJSON, EPSG:4326 lon/lat) for
 * the passport map's real MapLibre basemap (components/world-passport-map
 * .tsx / .web.tsx) — see scripts/build-world-boundaries.js for how this
 * was generated (Natural Earth via world-atlas, simplified, matched to
 * lib/countries.ts by ISO numeric->alpha-2 code). Each feature's
 * properties.code is a lowercase ISO 3166-1 alpha-2 code, the same scheme
 * lib/worldMapData.ts's visitedMapIds/countryNameForMapId already use.
 */
export type WorldBoundaryFeature = {
  type: 'Feature';
  properties: { code: string };
  geometry:
    | { type: 'Polygon'; coordinates: number[][][] }
    | { type: 'MultiPolygon'; coordinates: number[][][][] };
};

const WORLD_BOUNDARIES = worldBoundariesData as {
  type: 'FeatureCollection';
  features: WorldBoundaryFeature[];
};

export type CountryStatus = 'visited' | 'pending' | 'unvisited';

/**
 * The boundary GeoJSON, re-tagged with each feature's live visited/
 * pending/unvisited status and its English name — the two things a
 * data-driven MapLibre style expression needs (`['get', 'status']` for
 * fill color, `['get', 'name']` for the label layer) that can't be baked
 * in at build time since visited/pending depend on the signed-in user's
 * own data. `name` comes from lib/countries.ts via countryNameForMapId,
 * not any third-party source — guaranteed English by construction, same
 * as the flat-map version's labels were.
 */
export function statusTaggedBoundaries(visitedIds: Set<string>, pendingIds: Set<string>) {
  return {
    type: 'FeatureCollection' as const,
    features: WORLD_BOUNDARIES.features.map((f) => {
      const isVisited = visitedIds.has(f.properties.code);
      const isPending = !isVisited && pendingIds.has(f.properties.code);
      const status: CountryStatus = isVisited ? 'visited' : isPending ? 'pending' : 'unvisited';
      return {
        ...f,
        properties: { code: f.properties.code, status, name: countryNameForMapId(f.properties.code) ?? f.properties.code },
      };
    }),
  };
}

function ringArea(ring: number[][]): number {
  let area = 0;
  for (let i = 0; i < ring.length - 1; i++) {
    const [x1, y1] = ring[i];
    const [x2, y2] = ring[i + 1];
    area += x1 * y2 - x2 * y1;
  }
  return Math.abs(area) / 2;
}

function ringCentroid(ring: number[][]): [number, number] {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const [x, y] of ring) {
    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  }
  return [(minX + maxX) / 2, (minY + maxY) / 2];
}

/**
 * One label point per country (real lon/lat), at the centroid of its own
 * LARGEST landmass — computed once at module load since it's pure
 * geometry, independent of visited/pending status. Feeding the country
 * symbol layer straight from the polygon boundaries (like the fill/line
 * layers) instead of this would place one label per polygon PART, not per
 * country: a sprawling archipelago nation (Canada's Arctic islands,
 * Russia and Norway's fjord/island coastlines) would show its own name
 * repeated six or more times across the map — a real defect confirmed
 * against an actual render, not a hypothetical one. Same "largest ring
 * wins" approach scripts/build-world-paths.js already used for the flat
 * SVG map's labels.
 */
const COUNTRY_LABEL_POINTS: { code: string; name: string; center: [number, number] }[] = (() => {
  const byCode = new Map<string, { area: number; center: [number, number] }>();
  for (const f of WORLD_BOUNDARIES.features) {
    const polys = f.geometry.type === 'Polygon' ? [f.geometry.coordinates] : f.geometry.coordinates;
    for (const rings of polys) {
      const area = ringArea(rings[0]);
      const existing = byCode.get(f.properties.code);
      if (!existing || area > existing.area) {
        byCode.set(f.properties.code, { area, center: ringCentroid(rings[0]) });
      }
    }
  }
  return Array.from(byCode.entries()).map(([code, { center }]) => ({
    code,
    name: countryNameForMapId(code) ?? code,
    center,
  }));
})();

/** Point GeoJSON (one feature per country, static) for the label symbol layer — see COUNTRY_LABEL_POINTS's own comment on why this has to be separate from the polygon fill/line source. */
export function countryLabelPoints() {
  return {
    type: 'FeatureCollection' as const,
    features: COUNTRY_LABEL_POINTS.map(({ code, name, center }) => ({
      type: 'Feature' as const,
      properties: { code, name },
      geometry: { type: 'Point' as const, coordinates: center },
    })),
  };
}
