import { useState } from 'react';
import { Pressable, StyleSheet, TextInput, View, type StyleProp, type TextInputProps, type TextStyle } from 'react-native';

import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors } from '@/constants/theme';

type PasswordInputProps = {
  value: string;
  onChangeText: (text: string) => void;
  placeholder?: string;
  autoComplete?: TextInputProps['autoComplete'];
  accentColor: string;
  /** Same box styling the screen's other TextInputs use (border radius, padding, etc.) — color/borderColor are set internally. */
  style?: StyleProp<TextStyle>;
};

/** A password TextInput with a show/hide toggle — same secureTextEntry field every screen already had, just with an eye icon to reveal it. */
export function PasswordInput({ value, onChangeText, placeholder, autoComplete, accentColor, style }: PasswordInputProps) {
  const [isVisible, setIsVisible] = useState(false);

  return (
    <View style={styles.row}>
      <TextInput
        value={value}
        onChangeText={onChangeText}
        placeholder={placeholder}
        placeholderTextColor={Colors.light.textMuted}
        secureTextEntry={!isVisible}
        autoCapitalize="none"
        autoComplete={autoComplete}
        style={[style, styles.input, { color: Colors.light.text, borderColor: accentColor }]}
      />
      <Pressable onPress={() => setIsVisible((v) => !v)} hitSlop={8} style={styles.toggle}>
        <IconSymbol name={isVisible ? 'eye.slash' : 'eye'} size={20} color={accentColor} />
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  row: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  input: {
    flex: 1,
  },
  toggle: {
    position: 'absolute',
    right: 14,
  },
});
