import 'maplibre-gl/dist/maplibre-gl.css';

import type { FilterSpecification } from '@maplibre/maplibre-gl-style-spec';
import type { Map as MapLibreMap } from 'maplibre-gl';
import { useEffect, useRef } from 'react';

import { countryNameForMapId, type visitedMapIds } from '@/lib/worldMapData';
import { countryLabelPoints, statusTaggedBoundaries } from '@/lib/worldBoundaries';
import { countryFillColorExpression, FILL_INSERT_BEFORE_LAYER_ID, loadMapStyle, PAINTED_COUNTRY_FILTER } from '@/lib/worldMapStyle';

const MAP_HEIGHT = 420;

type MapLibreModule = typeof import('maplibre-gl');

// Same SSR-safe dynamic-import pattern the Leaflet-based maps in this app
// already use (react-leaflet's own maps, before this one) — a library
// that touches `window` at import time crashes Expo Router's web SSR
// build outright, and loading it inside useEffect guarantees it only
// runs after the component has actually mounted in a real browser.
let cachedModule: MapLibreModule | null = null;

/**
 * Web counterpart to world-passport-map.tsx — see that file for the full
 * reasoning (OpenFreeMap's free vector tiles, our own boundary data and
 * English labels, MapLibre's own built-in label collision handling).
 * maplibre-gl has no React wrapper bundled the way react-leaflet wraps
 * Leaflet, so this drives the imperative JS API directly inside a ref +
 * effect, same shape as the native version's declarative one underneath.
 */
export function WorldPassportMap({
  visitedIds,
  pendingIds,
  accentColor,
  pendingColor,
  onSelectCountry,
  style,
  height = MAP_HEIGHT,
  interactive = true,
}: {
  visitedIds: ReturnType<typeof visitedMapIds>;
  pendingIds: ReturnType<typeof visitedMapIds>;
  accentColor: string;
  pendingColor: string;
  onSelectCountry: (countryName: string) => void;
  style?: React.CSSProperties;
  height?: number;
  /** See world-passport-map.tsx's own comment — false for the embedded
   * card view, which sits inside the page's own scroll container. */
  interactive?: boolean;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<MapLibreMap | null>(null);
  const onSelectCountryRef = useRef(onSelectCountry);
  onSelectCountryRef.current = onSelectCountry;

  useEffect(() => {
    let cancelled = false;
    async function init() {
      // maplibre-gl is deliberately pinned to v5.x (a classic, single-file
      // UMD bundle) rather than the latest v6 — v6's ESM build resolves
      // its Web Worker via `new URL(..., import.meta.url)`, which Metro's
      // web bundler can't statically analyze, producing a real "Requiring
      // unknown module" crash on the actual deployed site (confirmed via
      // a real headless-browser reproduction against the exported bundle
      // with a genuine auth session, not assumed from reading about the
      // issue). v5's Blob-based inlined worker needs no such bundler
      // support at all. Dynamic-importing a UMD module through Metro's
      // CJS interop puts the real namespace on `.default`, not as
      // top-level named exports — falling back to the module itself keeps
      // this working if that ever changes (a true ESM build would put
      // named exports at the top level, no `.default` needed).
      if (!cachedModule) {
        const mod = await import('maplibre-gl');
        cachedModule = (mod as unknown as { default?: MapLibreModule }).default ?? mod;
      }
      const maplibregl = cachedModule;
      const mapStyle = await loadMapStyle();
      if (cancelled || !containerRef.current) return;
      const map = new maplibregl.Map({
        container: containerRef.current,
        style: mapStyle as unknown as string,
        center: [0, 20],
        zoom: 1.2,
        minZoom: 1,
        maxZoom: 14,
        interactive,
      });
      if (interactive) {
        map.addControl(new maplibregl.NavigationControl({ showCompass: false }), 'bottom-right');
      }
      map.on('load', () => {
        if (cancelled) return;
        map.addSource('countries', { type: 'geojson', data: statusTaggedBoundaries(visitedIds, pendingIds) as GeoJSON.FeatureCollection });
        // Only visited/pending countries get drawn at all — see
        // lib/worldMapStyle.ts's PAINTED_COUNTRY_FILTER comment on why an
        // unvisited country shows nothing but the clean basemap
        // underneath, rather than a gray tint over the whole rest of the
        // world.
        map.addLayer(
          {
            id: 'countries-fill',
            type: 'fill',
            source: 'countries',
            filter: PAINTED_COUNTRY_FILTER as unknown as FilterSpecification,
            paint: {
              'fill-color': countryFillColorExpression(accentColor, pendingColor) as unknown as string,
              'fill-opacity': 0.75,
            },
          },
          FILL_INSERT_BEFORE_LAYER_ID
        );
        map.addLayer(
          {
            id: 'countries-line',
            type: 'line',
            source: 'countries',
            filter: PAINTED_COUNTRY_FILTER as unknown as FilterSpecification,
            paint: { 'line-color': countryFillColorExpression(accentColor, pendingColor) as unknown as string, 'line-width': 1 },
          },
          FILL_INSERT_BEFORE_LAYER_ID
        );
        // A separate point source, not the polygon boundaries above — one
        // label per country at its largest landmass's centroid (see
        // lib/worldBoundaries.ts's countryLabelPoints), rather than one
        // label per polygon PART, which repeated a sprawling archipelago's
        // name six-plus times across the map (confirmed against a real
        // render, e.g. Canada/Russia's Arctic islands each getting their
        // own copy of the country name).
        map.addSource('country-labels', { type: 'geojson', data: countryLabelPoints() as GeoJSON.FeatureCollection });
        map.addLayer({
          id: 'countries-label',
          type: 'symbol',
          source: 'country-labels',
          layout: { 'text-field': ['get', 'name'], 'text-size': 12, 'text-font': ['Noto Sans Regular'] },
          paint: { 'text-color': '#1A241F', 'text-halo-color': '#FBFBF9', 'text-halo-width': 1.2 },
        });
        map.on('click', 'countries-fill', (e) => {
          const code = e.features?.[0]?.properties?.code as string | undefined;
          const countryName = code ? countryNameForMapId(code) : null;
          if (countryName) onSelectCountryRef.current(countryName);
        });
        map.on('mouseenter', 'countries-fill', () => {
          map.getCanvas().style.cursor = 'pointer';
        });
        map.on('mouseleave', 'countries-fill', () => {
          map.getCanvas().style.cursor = '';
        });
      });
      mapRef.current = map;
    }
    init();
    return () => {
      cancelled = true;
      mapRef.current?.remove();
      mapRef.current = null;
    };
    // visitedIds/pendingIds/accentColor/pendingColor intentionally only
    // read once at map creation here — updated live by the effect below
    // instead of tearing down and recreating the whole map on every
    // status change.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !map.getSource('countries')) return;
    const source = map.getSource('countries') as unknown as { setData: (data: GeoJSON.FeatureCollection) => void };
    source.setData(statusTaggedBoundaries(visitedIds, pendingIds) as GeoJSON.FeatureCollection);
    map.setPaintProperty('countries-fill', 'fill-color', countryFillColorExpression(accentColor, pendingColor) as unknown as string);
    map.setPaintProperty('countries-line', 'line-color', countryFillColorExpression(accentColor, pendingColor) as unknown as string);
  }, [visitedIds, pendingIds, accentColor, pendingColor]);

  return <div ref={containerRef} style={{ height, borderRadius: 12, overflow: 'hidden', ...style }} />;
}
