import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { computeDisplayName } from '@/hooks/use-connection-display';
import { CALENDAR_COLOR_PRESETS } from '@/lib/tripCalendar';
import { supabase } from '@/lib/supabase';
import type { ConnectionRow } from '@/types/database';

const TINT = Colors.light.tint;

type ConnectionWithPartner = ConnectionRow & { displayName: string };

export default function ShareHubScreen() {
  const router = useRouter();
  const { session } = useAuth();

  const [connections, setConnections] = useState<ConnectionWithPartner[]>([]);
  const [calendarColor, setCalendarColor] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [busyConnectionId, setBusyConnectionId] = useState<string | null>(null);

  const load = useCallback(async () => {
    if (!session) return;
    setError(null);
    const myId = session.user.id;

    const [connectionsResult, settingsResult] = await Promise.all([
      supabase
        .from('connections')
        .select('*')
        .or(`requester_id.eq.${myId},recipient_id.eq.${myId}`)
        .order('created_at', { ascending: false }),
      supabase.from('user_settings').select('calendar_color').eq('user_id', myId).maybeSingle(),
    ]);

    if (connectionsResult.error) {
      setError(connectionsResult.error.message);
      setIsLoading(false);
      return;
    }

    setCalendarColor(settingsResult.data?.calendar_color ?? null);

    const rows = connectionsResult.data ?? [];
    let partnerFetchError: string | null = null;
    const withPartners = await Promise.all(
      rows.map(async (row) => {
        const [profileResult, overrideResult] = await Promise.all([
          supabase.rpc('connection_partner_profile', { p_connection_id: row.id }).maybeSingle(),
          supabase
            .from('connection_display_overrides')
            .select('label')
            .eq('connection_id', row.id)
            .eq('viewer_user_id', myId)
            .maybeSingle(),
        ]);
        // Surfaced rather than silently swallowed — a failed fetch here
        // used to fall straight through to the 'Connection' placeholder
        // with no indication anything had gone wrong.
        if (profileResult.error && !partnerFetchError) partnerFetchError = profileResult.error.message;
        const displayName = computeDisplayName(
          overrideResult.data?.label ?? null,
          profileResult.data?.full_name ?? null,
          profileResult.data?.email ?? null
        );
        return { ...row, displayName };
      })
    );

    if (partnerFetchError) setError(partnerFetchError);
    setConnections(withPartners);
    setIsLoading(false);
  }, [session]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  async function handlePickColor(color: string) {
    if (!session) return;
    setCalendarColor(color);
    const { error: saveError } = await supabase
      .from('user_settings')
      .upsert({ user_id: session.user.id, calendar_color: color }, { onConflict: 'user_id' });
    if (saveError) setError(saveError.message);
  }

  async function handleAccept(connectionId: string) {
    setBusyConnectionId(connectionId);
    const { error: updateError } = await supabase
      .from('connections')
      .update({ status: 'accepted' })
      .eq('id', connectionId);
    setBusyConnectionId(null);
    if (updateError) {
      setError(updateError.message);
      return;
    }
    load();
  }

  async function handleDecline(connectionId: string) {
    setBusyConnectionId(connectionId);
    const { error: updateError } = await supabase
      .from('connections')
      .update({ status: 'declined' })
      .eq('id', connectionId);
    setBusyConnectionId(null);
    if (updateError) {
      setError(updateError.message);
      return;
    }
    load();
  }

  async function handleCancel(connectionId: string) {
    setBusyConnectionId(connectionId);
    const { error: updateError } = await supabase
      .from('connections')
      .update({ status: 'removed' })
      .eq('id', connectionId);
    setBusyConnectionId(null);
    if (updateError) {
      setError(updateError.message);
      return;
    }
    load();
  }

  const myId = session?.user.id;
  const incoming = connections.filter((c) => c.status === 'pending' && c.recipient_id === myId);
  const outgoing = connections.filter((c) => c.status === 'pending' && c.requester_id === myId);
  const accepted = connections.filter((c) => c.status === 'accepted');

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: TINT }}>
            Share Cluster
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedText type="defaultSemiBold">Your calendar color</ThemedText>
        <ThemedText style={styles.hint}>
          Used to tell your trips apart from a connection&apos;s on the shared calendar.
        </ThemedText>
        <ThemedView style={styles.swatchRow}>
          {CALENDAR_COLOR_PRESETS.map((color) => (
            <Pressable
              key={color}
              onPress={() => handlePickColor(color)}
              style={[
                styles.swatch,
                { backgroundColor: color },
                calendarColor === color ? styles.swatchSelected : null,
              ]}
            />
          ))}
        </ThemedView>

        <Pressable onPress={() => router.push('/account/share/add')} style={[styles.button, { backgroundColor: TINT }]}>
          <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Add someone</ThemedText>
        </Pressable>

        {isLoading ? (
          <ActivityIndicator color={TINT} style={styles.sectionSpacing} />
        ) : (
          <>
            {incoming.length > 0 ? (
              <>
                <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: TINT }]}>
                  Requests to you
                </ThemedText>
                {incoming.map((connection) => (
                  <Surface key={connection.id} accentColor={TINT} style={styles.requestCard}>
                    <ThemedText type="defaultSemiBold">{connection.displayName}</ThemedText>
                    <ThemedView style={styles.requestActions}>
                      <Pressable
                        disabled={busyConnectionId === connection.id}
                        onPress={() => handleAccept(connection.id)}
                        style={[styles.smallButton, { backgroundColor: TINT }]}>
                        <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>
                          Accept
                        </ThemedText>
                      </Pressable>
                      <Pressable
                        disabled={busyConnectionId === connection.id}
                        onPress={() => handleDecline(connection.id)}
                        style={[styles.smallButton, styles.smallButtonOutline, { borderColor: Colors.light.negative }]}>
                        <ThemedText style={{ color: Colors.light.negative }}>Decline</ThemedText>
                      </Pressable>
                    </ThemedView>
                  </Surface>
                ))}
              </>
            ) : null}

            {outgoing.length > 0 ? (
              <>
                <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: TINT }]}>
                  Awaiting response
                </ThemedText>
                {outgoing.map((connection) => (
                  <Surface key={connection.id} accentColor={TINT} style={styles.requestCard}>
                    <ThemedText type="defaultSemiBold">{connection.displayName}</ThemedText>
                    <ThemedView style={styles.requestActions}>
                      <ThemedText style={styles.muted}>Pending</ThemedText>
                      <Pressable disabled={busyConnectionId === connection.id} onPress={() => handleCancel(connection.id)}>
                        <ThemedText style={{ color: Colors.light.negative }}>Cancel</ThemedText>
                      </Pressable>
                    </ThemedView>
                  </Surface>
                ))}
              </>
            ) : null}

            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: TINT }]}>
              Already shared
            </ThemedText>
            {accepted.length === 0 ? (
              <ThemedText style={styles.muted}>No connections yet. Add someone above.</ThemedText>
            ) : null}
            {accepted.map((connection) => (
              <Pressable key={connection.id} onPress={() => router.push(`/account/share/${connection.id}`)}>
                <Surface accentColor={TINT} style={styles.requestCard}>
                  <ThemedText type="defaultSemiBold">{connection.displayName}</ThemedText>
                </Surface>
              </Pressable>
            ))}
          </>
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 4,
  },
  swatchRow: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 10,
    marginBottom: 8,
  },
  swatch: {
    width: 32,
    height: 32,
    borderRadius: 16,
  },
  swatchSelected: {
    borderWidth: 3,
    borderColor: Colors.light.text,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  sectionSpacing: {
    marginTop: 16,
  },
  requestCard: {
    gap: 8,
  },
  requestActions: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
  },
  smallButton: {
    borderRadius: 8,
    paddingVertical: 8,
    paddingHorizontal: 16,
  },
  smallButtonOutline: {
    backgroundColor: 'transparent',
    borderWidth: StyleSheet.hairlineWidth,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
});
