import { useRouter } from 'expo-router';
import { useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, TextInput } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { supabase } from '@/lib/supabase';

const NEGATIVE = Colors.light.negative;
const CONFIRM_WORD = 'DELETE';

/**
 * Storage files can't be touched by the delete_my_account() SQL function
 * (Storage's actual blob deletion only happens through its own API, not
 * plain SQL against storage.objects) — removed here first, client-side,
 * same supabase.storage.remove() calls used everywhere else in the app.
 * Stops and reports an error rather than proceeding if any of this fails,
 * so the irreversible database wipe never runs against a user who might
 * still have orphaned files.
 */
async function wipeStorageFiles(userId: string): Promise<string | null> {
  const [documentsResult, csvImportsResult, settingsResult] = await Promise.all([
    supabase.from('documents').select('file_ref').eq('user_id', userId),
    supabase.from('csv_imports').select('storage_path').eq('user_id', userId),
    supabase.from('user_settings').select('avatar_path').eq('user_id', userId).maybeSingle(),
  ]);
  if (documentsResult.error) return documentsResult.error.message;
  if (csvImportsResult.error) return csvImportsResult.error.message;
  if (settingsResult.error) return settingsResult.error.message;

  const documentPaths = (documentsResult.data ?? []).map((d) => d.file_ref);
  if (documentPaths.length > 0) {
    const { error } = await supabase.storage.from('documents').remove(documentPaths);
    if (error) return error.message;
  }

  const csvPaths = (csvImportsResult.data ?? []).map((c) => c.storage_path);
  if (csvPaths.length > 0) {
    const { error } = await supabase.storage.from('csv-imports').remove(csvPaths);
    if (error) return error.message;
  }

  const avatarPath = settingsResult.data?.avatar_path;
  if (avatarPath) {
    const { error } = await supabase.storage.from('avatars').remove([avatarPath]);
    if (error) return error.message;
  }

  return null;
}

export default function DeleteAccountScreen() {
  const router = useRouter();
  const { session, signOut } = useAuth();

  const [confirmText, setConfirmText] = useState('');
  const [isDeleting, setIsDeleting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const canDelete = confirmText.trim().toUpperCase() === CONFIRM_WORD;

  async function handleDelete() {
    if (!canDelete || !session) return;
    setError(null);
    setIsDeleting(true);

    const storageError = await wipeStorageFiles(session.user.id);
    if (storageError) {
      setIsDeleting(false);
      setError(storageError);
      return;
    }

    // Everything else — every data table AND the login itself — happens
    // atomically in one Postgres transaction (supabase/061_delete_my_account.sql):
    // either the whole account is gone, or (on any error) none of it is.
    const { error: deleteError } = await supabase.rpc('delete_my_account');
    if (deleteError) {
      setIsDeleting(false);
      setError(deleteError.message);
      return;
    }

    await signOut();
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: NEGATIVE }}>
            Close Account
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Cancel</ThemedText>
          </Pressable>
        </ThemedView>

        <ThemedView style={[styles.warningBox, { borderColor: NEGATIVE }]}>
          <ThemedText type="defaultSemiBold" style={{ color: NEGATIVE }}>
            This cannot be undone
          </ThemedText>
          <ThemedText style={styles.warningText}>
            This permanently deletes every account, card, transaction, trip, document, connection, and setting you
            have logged in Cluster, and removes your login itself. You will not be able to sign back in with this
            email afterward.
          </ThemedText>
        </ThemedView>

        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedText type="defaultSemiBold" style={styles.fieldLabel}>
          Type {CONFIRM_WORD} to confirm
        </ThemedText>
        <TextInput
          value={confirmText}
          onChangeText={setConfirmText}
          autoCapitalize="characters"
          autoCorrect={false}
          placeholder={CONFIRM_WORD}
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: NEGATIVE }]}
        />

        <Pressable
          onPress={handleDelete}
          disabled={!canDelete || isDeleting}
          style={[styles.button, { backgroundColor: NEGATIVE, opacity: canDelete ? 1 : 0.5 }]}>
          {isDeleting ? (
            <ActivityIndicator color={Colors.light.backgroundSolid} />
          ) : (
            <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>
              Permanently delete my account
            </ThemedText>
          )}
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

