import { useFocusEffect } from '@react-navigation/native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, RefreshControl, ScrollView, StyleSheet } from 'react-native';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccents } from '@/constants/theme';
import { formatDateDisplay, toDateOnlyString } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import type { CountryVisitedRow } from '@/types/database';

const ACCENT = ModuleAccents.countries;

/**
 * The individual trip-level list (dates, city, notes per visit) — preserved
 * here rather than removed when the country detail page was rebuilt into a
 * richer spend-focused view.
 *
 * Deliberately unfiltered by date — no .gte/.lte clause on entry_date or
 * exit_date, and no client-side date filtering below either. This is the
 * one guaranteed place to find and delete a visit regardless of whether
 * it's past, current, or future-dated; don't add a date restriction here
 * even if a future feature wants to filter the list elsewhere.
 */
export default function CountryVisitsScreen() {
  const { country } = useLocalSearchParams<{ country: string }>();
  const router = useRouter();

  const [visits, setVisits] = useState<CountryVisitedRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const { data, error: fetchError } = await supabase
      .from('countries_visited')
      .select('*')
      .eq('country', country)
      .order('entry_date', { ascending: false });

    if (fetchError) {
      setError(fetchError.message);
    } else {
      setVisits(data ?? []);
    }
    setIsLoading(false);
  }, [country]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView
        contentContainerStyle={styles.content}
        refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            {country} Visits
          </ThemedText>
          <Pressable
            onPress={() => router.push(`/countries/visit/new?country=${encodeURIComponent(country)}`)}
            hitSlop={12}>
            <IconSymbol name="plus" size={24} color={ACCENT} />
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {isLoading ? (
          <ActivityIndicator color={ACCENT} />
        ) : (
          <>
            {visits.length === 0 ? <ThemedText style={styles.muted}>No visits logged yet.</ThemedText> : null}
            {visits.map((visit) => {
              const isUpcoming = visit.entry_date > toDateOnlyString(new Date());
              return (
                <Pressable key={visit.id} onPress={() => router.push(`/countries/visit/${visit.id}`)}>
                  <Surface accentColor={ACCENT}>
                    <ThemedView style={styles.dateRow}>
                      <ThemedText type="mono" style={styles.dates}>
                        {formatDateDisplay(visit.entry_date)} &rarr; {formatDateDisplay(visit.exit_date)}
                      </ThemedText>
                      {isUpcoming ? <ThemedText style={[styles.muted, styles.upcoming]}>Upcoming</ThemedText> : null}
                    </ThemedView>
                    {visit.city ? <ThemedText type="defaultSemiBold">{visit.city}</ThemedText> : null}
                    {visit.notes ? (
                      <ThemedText style={styles.muted} numberOfLines={2}>
                        {visit.notes}
                      </ThemedText>
                    ) : null}
                  </Surface>
                </Pressable>
              );
            })}
          </>
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  dateRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  dates: {
    fontSize: 15,
  },
  upcoming: {
    textTransform: 'uppercase',
    fontSize: 11,
    letterSpacing: 0.5,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
});
