import { Directory, File, Paths } from 'expo-file-system';
import { useRouter } from 'expo-router';
import * as Sharing from 'expo-sharing';
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, Switch } from 'react-native';

import { DateInput } from '@/components/date-input';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { DOCUMENT_TYPE_OPTIONS, guessMimeTypeFromName } from '@/lib/documents';
import { toDateOnlyString } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import { buildZip, type ZipEntry } from '@/lib/zip';
import type { CountryVisitedRow, DocumentRow, DocumentType, TripSegmentRow } from '@/types/database';

const ACCENT = ModuleAccents.documents;
const SIGNED_URL_EXPIRY_SECONDS = 300;

type RangeMode = 'all' | 'custom';
type SourceDoc = Pick<DocumentRow, 'id' | 'name' | 'doc_type' | 'issue_date' | 'expiry_date' | 'trip_stop_id' | 'trip_segment_id' | 'file_ref'>;

function sanitizeFilename(name: string): string {
  return name.trim().replace(/[/\\?%*:|"<>]/g, '-') || 'document';
}

export default function ExportDocumentsScreen() {
  const router = useRouter();
  const { session } = useAuth();

  const [documents, setDocuments] = useState<SourceDoc[]>([]);
  const [stops, setStops] = useState<CountryVisitedRow[]>([]);
  const [segments, setSegments] = useState<TripSegmentRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [docTypeSelection, setDocTypeSelection] = useState<Record<DocumentType, boolean>>(() => {
    const initial = {} as Record<DocumentType, boolean>;
    for (const opt of DOCUMENT_TYPE_OPTIONS) initial[opt.value] = true;
    return initial;
  });
  const [rangeMode, setRangeMode] = useState<RangeMode>('all');
  const [rangeStart, setRangeStart] = useState(() => {
    const d = new Date();
    d.setMonth(d.getMonth() - 1);
    return d;
  });
  const [rangeEnd, setRangeEnd] = useState(new Date());

  const load = useCallback(async () => {
    if (!session) return;
    setIsLoading(true);
    const [docsResult, stopsResult, segmentsResult] = await Promise.all([
      supabase.from('documents').select('id, name, doc_type, issue_date, expiry_date, trip_stop_id, trip_segment_id, file_ref'),
      supabase.from('countries_visited').select('*'),
      supabase.from('trip_segments').select('*'),
    ]);
    setDocuments(docsResult.data ?? []);
    setStops(stopsResult.data ?? []);
    setSegments(segmentsResult.data ?? []);
    setIsLoading(false);
  }, [session]);

  useEffect(() => {
    load();
  }, [load]);

  function toggleDocType(key: DocumentType) {
    setDocTypeSelection((prev) => ({ ...prev, [key]: !prev[key] }));
  }

  const stopsById = new Map(stops.map((s) => [s.id, s]));
  const segmentsById = new Map(segments.map((s) => [s.id, s]));

  /** True if any date associated with the document (issue, expiry, or a linked trip stop/leg's dates) falls within the picked range — a document with no dates at all is only ever included in "All time." */
  function matchesRange(doc: SourceDoc): boolean {
    if (rangeMode === 'all') return true;
    const rangeStartStr = toDateOnlyString(rangeStart);
    const rangeEndStr = toDateOnlyString(rangeEnd);
    const candidateRanges: [string, string][] = [];
    if (doc.issue_date) candidateRanges.push([doc.issue_date, doc.issue_date]);
    if (doc.expiry_date) candidateRanges.push([doc.expiry_date, doc.expiry_date]);
    if (doc.trip_stop_id) {
      const stop = stopsById.get(doc.trip_stop_id);
      if (stop) candidateRanges.push([stop.entry_date, stop.exit_date ?? stop.entry_date]);
    }
    if (doc.trip_segment_id) {
      const segment = segmentsById.get(doc.trip_segment_id);
      if (segment) candidateRanges.push([segment.depart_date, segment.arrive_date]);
    }
    if (candidateRanges.length === 0) return false;
    return candidateRanges.some(([start, end]) => start <= rangeEndStr && end >= rangeStartStr);
  }

  const matched = documents.filter((d) => docTypeSelection[d.doc_type] && matchesRange(d));

  async function handleGenerate() {
    if (!session || matched.length === 0) return;
    setError(null);
    setIsGenerating(true);
    const tempDir = new Directory(Paths.cache, `cluster-doc-export-${Date.now()}`);
    try {
      tempDir.create();

      const usedNames = new Set<string>();
      const downloaded: { file: File; entryName: string }[] = [];
      for (const doc of matched) {
        const { data: signedData, error: signedError } = await supabase.storage
          .from('documents')
          .createSignedUrl(doc.file_ref, SIGNED_URL_EXPIRY_SECONDS);
        if (signedError || !signedData) continue;

        const extMatch = doc.file_ref.match(/\.[a-zA-Z0-9]+$/);
        const ext = extMatch ? extMatch[0] : '';
        let entryName = `${sanitizeFilename(doc.name)}${ext}`;
        let suffix = 2;
        while (usedNames.has(entryName)) {
          entryName = `${sanitizeFilename(doc.name)} (${suffix})${ext}`;
          suffix++;
        }
        usedNames.add(entryName);

        // Passing a File (not a Directory) as the destination pins the
        // result to exactly this path, so `destination` itself is the
        // downloaded file — sidesteps an expo-file-system typing quirk where
        // downloadFileAsync's declared return type doesn't match the local
        // File class.
        const destination = new File(tempDir, `${doc.id}${ext}`);
        await File.downloadFileAsync(signedData.signedUrl, destination, { idempotent: true });
        downloaded.push({ file: destination, entryName });
      }

      if (downloaded.length === 0) {
        setError('Could not download any matching documents.');
        return;
      }

      if (downloaded.length === 1) {
        const { file, entryName } = downloaded[0];
        const canShare = await Sharing.isAvailableAsync();
        if (!canShare) {
          setError('Sharing is not available on this device.');
          return;
        }
        await Sharing.shareAsync(file.uri, { mimeType: guessMimeTypeFromName(entryName), dialogTitle: entryName });
      } else {
        const entries: ZipEntry[] = [];
        for (const { file, entryName } of downloaded) {
          entries.push({ name: entryName, data: await file.bytes() });
        }
        const zipBytes = buildZip(entries);
        const zipFile = new File(Paths.cache, `cluster-documents-${new Date().toISOString().slice(0, 10)}.zip`);
        if (zipFile.exists) zipFile.delete();
        zipFile.create();
        zipFile.write(zipBytes);

        const canShare = await Sharing.isAvailableAsync();
        if (!canShare) {
          setError('Sharing is not available on this device.');
          return;
        }
        await Sharing.shareAsync(zipFile.uri, { mimeType: 'application/zip', dialogTitle: 'Cluster Documents' });
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Export failed.');
    } finally {
      if (tempDir.exists) tempDir.delete();
      setIsGenerating(false);
    }
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Export Documents
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedText style={styles.muted}>
          Download the actual document files, not just their metadata. Filter by type and, optionally, by date.
        </ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {isLoading ? (
          <ActivityIndicator style={styles.loading} color={ACCENT} />
        ) : (
          <>
            <ThemedText type="defaultSemiBold" style={styles.sectionLabel}>
              Document type
            </ThemedText>
            <ThemedView style={styles.list}>
              {DOCUMENT_TYPE_OPTIONS.map((opt) => (
                <Surface key={opt.value} accentColor={ACCENT} style={styles.row}>
                  <ThemedText type="defaultSemiBold" style={styles.rowText}>
                    {opt.label}
                  </ThemedText>
                  <Switch
                    value={docTypeSelection[opt.value]}
                    onValueChange={() => toggleDocType(opt.value)}
                    trackColor={{ true: ACCENT }}
                  />
                </Surface>
              ))}
            </ThemedView>

            <ThemedText type="defaultSemiBold" style={styles.sectionLabel}>
              Range
            </ThemedText>
            <ThemedView style={styles.rangeChips}>
              {(['all', 'custom'] as RangeMode[]).map((mode) => {
                const isSelected = rangeMode === mode;
                return (
                  <Pressable
                    key={mode}
                    onPress={() => setRangeMode(mode)}
                    style={[styles.chip, { borderColor: ACCENT, backgroundColor: isSelected ? ACCENT : 'transparent' }]}>
                    <ThemedText style={isSelected ? { color: Colors.light.backgroundSolid } : undefined}>
                      {mode === 'all' ? 'All time' : 'Custom range'}
                    </ThemedText>
                  </Pressable>
                );
              })}
            </ThemedView>
            {rangeMode === 'custom' ? (
              <>
                <ThemedView style={styles.rangeRow}>
                  <DateInput
                    value={rangeStart}
                    onChange={(date) => {
                      setRangeStart(date);
                      if (rangeEnd < date) setRangeEnd(date);
                    }}
                    accentColor={ACCENT}
                  />
                  <ThemedText>&rarr;</ThemedText>
                  <DateInput value={rangeEnd} onChange={setRangeEnd} accentColor={ACCENT} minimumDate={rangeStart} />
                </ThemedView>
                <ThemedText style={styles.caution}>
                  Matches a document&apos;s issue date, expiry date, or (for Proof of Travel) its linked stop/leg
                  dates. A document with none of those set is left out of a custom range.
                </ThemedText>
              </>
            ) : null}

            <ThemedText style={styles.matchCount}>
              {matched.length} of {documents.length} document{documents.length === 1 ? '' : 's'} match
              {matched.length > 1 ? ', delivered as a single .zip' : ''}
            </ThemedText>

            <Pressable
              onPress={handleGenerate}
              disabled={isGenerating || matched.length === 0}
              style={[styles.button, { backgroundColor: ACCENT, opacity: matched.length > 0 ? 1 : 0.5 }]}>
              {isGenerating ? (
                <ActivityIndicator color={Colors.light.backgroundSolid} />
              ) : (
                <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>
                  {matched.length > 1 ? 'Download as .zip' : 'Download'}
                </ThemedText>
              )}
            </Pressable>
          </>
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 4,
  },
  muted: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 8,
  },
  loading: {
    marginTop: 32,
  },
  sectionLabel: {
    marginTop: 16,
  },
  list: {
    gap: 8,
    marginTop: 8,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  rowText: {
    flex: 1,
    marginRight: 12,
  },
  rangeChips: {
    flexDirection: 'row',
    gap: 8,
    marginTop: 8,
  },
  chip: {
    borderWidth: 1,
    borderRadius: 999,
    paddingVertical: 6,
    paddingHorizontal: 14,
  },
  rangeRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
    marginTop: 10,
  },
  caution: {
    fontSize: 12,
    color: Colors.light.textMuted,
    marginTop: 8,
    fontStyle: 'italic',
  },
  matchCount: {
    fontSize: 13,
    color: Colors.light.textMuted,
    marginTop: 16,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 12,
  },
  error: {
    color: Colors.light.negative,
  },
});
