import { attributedCountryForDate, isExcludedFromCountryTracking } from '@/lib/spend';
import { generatePeriods } from '@/lib/wealthSeries';
import type { AccountRow, BudgetRow, CountryVisitedRow, TransactionRow } from '@/types/database';

export type BudgetProgress = {
  budget: BudgetRow;
  spent: number;
  remaining: number;
  percentUsed: number;
};

function toDateOnlyString(date: Date): string {
  return date.toISOString().slice(0, 10);
}

/**
 * Current-month spend against each budget, converted into the BUDGET'S OWN
 * currency (not the caller's display currency) — a budget set in EUR
 * always compares against EUR-converted spend, so the limit itself doesn't
 * silently drift if the user later changes their display currency.
 * Country-scoped budgets reuse lib/spend.ts's exact attribution logic
 * (attributedCountryForDate/isExcludedFromCountryTracking) so a budget's
 * "spent" figure always matches what the Spend Detail screen's own
 * by-country breakdown would show for that country.
 */
export function computeBudgetProgress(
  budgets: BudgetRow[],
  transactions: TransactionRow[],
  visits: Pick<CountryVisitedRow, 'country' | 'city' | 'entry_date' | 'exit_date'>[],
  homeCountry: string | null,
  accounts: Pick<AccountRow, 'id' | 'excluded_from_country_tracking'>[],
  convertToCurrency: (amount: number, fromCurrency: string, toCurrency: string) => number,
  today: Date = new Date()
): BudgetProgress[] {
  const period = generatePeriods('month', 1, today)[0];
  const start = toDateOnlyString(period.start);
  const end = toDateOnlyString(period.end);
  const spendTx = transactions.filter(
    (tx) => !tx.is_internal_transfer && tx.amount < 0 && tx.date >= start && tx.date <= end
  );
  const excludedAccountIds = new Set(accounts.filter((a) => a.excluded_from_country_tracking).map((a) => a.id));

  return budgets
    .map((budget) => {
      let spent = 0;
      if (budget.category_id) {
        for (const tx of spendTx) {
          if (tx.category_id !== budget.category_id) continue;
          spent += Math.abs(convertToCurrency(tx.amount, tx.currency, budget.currency));
        }
      } else if (budget.country) {
        for (const tx of spendTx) {
          const country = attributedCountryForDate(
            tx.date,
            visits,
            homeCountry,
            isExcludedFromCountryTracking(tx, excludedAccountIds)
          );
          if (country !== budget.country) continue;
          spent += Math.abs(convertToCurrency(tx.amount, tx.currency, budget.currency));
        }
      }
      const remaining = budget.amount - spent;
      const percentUsed = budget.amount > 0 ? (spent / budget.amount) * 100 : 0;
      return { budget, spent, remaining, percentUsed };
    })
    .sort((a, b) => b.percentUsed - a.percentUsed);
}
