import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { ConnectionsMap } from '@/components/connections-map';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { cityCoordinatesFor } from '@/lib/cityCoordinates';
import { COUNTRY_COORDINATES } from '@/lib/countryCoordinates';
import { toDateOnlyString } from '@/lib/format';
import type { MapMarker } from '@/lib/mapMarker';
import { supabase } from '@/lib/supabase';

const ACCENT = ModuleAccents.countries;

type LocatedConnection = {
  id: string;
  displayName: string;
  country: string | null;
  city: string | null;
  /** The stop's own real geocoded coordinates (see countries_visited.lat/lon) — only ever set for a traveling connection, since a home location has no such row to carry them. Preferred over the city/country fallbacks below when present. */
  lat: number | null;
  lon: number | null;
  /** True when this location came from a currently-ongoing trip rather than the home location — takes priority when both are shared. */
  isTraveling: boolean;
};

export default function ConnectionsMapScreen() {
  const router = useRouter();
  const { connections } = useSwipeConnections();
  const [located, setLocated] = useState<LocatedConnection[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const load = useCallback(async () => {
    setIsLoading(true);
    const today = toDateOnlyString(new Date());
    const results = await Promise.all(
      connections.map(async (c) => {
        const [homeResult, visitedResult, plannedResult] = await Promise.all([
          supabase.rpc('shared_home_location', { p_connection_id: c.id }).maybeSingle(),
          supabase.rpc('shared_countries_visited', { p_connection_id: c.id }),
          supabase.rpc('shared_trips_planned', { p_connection_id: c.id }),
        ]);

        // A trip "now" — logged as either a past/current visit or a planned
        // one, doesn't matter which, only that today falls inside its
        // range (open-ended if no exit_date yet) — takes priority over home
        // location, since it's the more relevant "where are they" answer.
        const allTrips = [...(visitedResult.data ?? []), ...(plannedResult.data ?? [])];
        const ongoing = allTrips.find((t) => t.entry_date <= today && (!t.exit_date || t.exit_date >= today));

        if (ongoing) {
          return {
            id: c.id,
            displayName: c.displayName,
            country: ongoing.country,
            city: ongoing.city,
            lat: ongoing.lat,
            lon: ongoing.lon,
            isTraveling: true,
          };
        }
        return {
          id: c.id,
          displayName: c.displayName,
          country: homeResult.data?.home_country ?? null,
          city: homeResult.data?.home_city ?? null,
          lat: null,
          lon: null,
          isTraveling: false,
        };
      })
    );
    setLocated(results);
    setIsLoading(false);
  }, [connections]);

  useFocusEffect(
    useCallback(() => {
      if (connections.length > 0) load();
      else setIsLoading(false);
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [connections.length])
  );

  // Real per-CITY coordinates, preferred in this order: the stop's own
  // geocoded lat/lon (a traveling connection only — see LocatedConnection),
  // then the curated city list also used for the trip map (lib/cityCoordinates.ts),
  // then finally the whole country's centroid — a pin should land on the
  // actual city whenever that's knowable, not just somewhere inside the
  // right country, since the label right next to it already names the city.
  function coordinatesFor(c: LocatedConnection): { lat: number; lon: number } | null {
    if (c.lat != null && c.lon != null) return { lat: c.lat, lon: c.lon };
    if (c.country && c.city) {
      const cityCoords = cityCoordinatesFor(c.country, c.city);
      if (cityCoords) return cityCoords;
    }
    return c.country && COUNTRY_COORDINATES[c.country] ? COUNTRY_COORDINATES[c.country] : null;
  }

  const markers: MapMarker[] = located
    .filter((c) => c.country && coordinatesFor(c))
    .map((c) => {
      const coords = coordinatesFor(c)!;
      return {
        id: c.id,
        label: `${c.displayName}${c.city ? ` (${c.city})` : ''}${c.isTraveling ? ' · traveling' : ''}`,
        lat: coords.lat,
        lon: coords.lon,
        country: c.country!,
      };
    });
  const unlocated = located.filter((c) => !coordinatesFor(c));

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Map
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedText style={styles.hint}>
          Shows where a connection is currently traveling if they have an ongoing trip, otherwise their home
          country/city. Only for connections sharing Countries or Trips planned with you.
        </ThemedText>

        {isLoading ? (
          <ActivityIndicator color={ACCENT} />
        ) : markers.length === 0 ? (
          <ThemedText style={styles.muted}>
            No locations to show yet. No connections have a home country shared with you.
          </ThemedText>
        ) : (
          <Surface accentColor={ACCENT}>
            <ConnectionsMap
              markers={markers}
              accentColor={ACCENT}
              onSelectMarker={(id) => router.push(`/connections/${id}/travel`)}
            />
          </Surface>
        )}

        {unlocated.length > 0 ? (
          <>
            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
              No location shared
            </ThemedText>
            {unlocated.map((c) => (
              <ThemedText key={c.id} style={styles.muted}>
                {c.displayName}
              </ThemedText>
            ))}
          </>
        ) : null}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  sectionSpacing: {
    marginTop: 16,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
});
