import { currencySymbol, formatMoney } from '@/lib/currency';

/**
 * "Nice round numbers" tick algorithm (Heckbert) — shared by every chart
 * with a Y-axis scale (candlestick, line, bar) so they all pick the same
 * kind of human-friendly step sizes (1/2/5 x a power of ten) instead of
 * raw min/max divided evenly, which would land labels on odd values like
 * 47,332 instead of 50,000.
 */
function niceNum(range: number, round: boolean): number {
  if (range === 0) return 1;
  const exponent = Math.floor(Math.log10(range));
  const fraction = range / 10 ** exponent;
  let niceFraction: number;
  if (round) {
    if (fraction < 1.5) niceFraction = 1;
    else if (fraction < 3) niceFraction = 2;
    else if (fraction < 7) niceFraction = 5;
    else niceFraction = 10;
  } else {
    if (fraction <= 1) niceFraction = 1;
    else if (fraction <= 2) niceFraction = 2;
    else if (fraction <= 5) niceFraction = 5;
    else niceFraction = 10;
  }
  return niceFraction * 10 ** exponent;
}

/** Evenly-ish spaced "nice" tick values spanning [min, max] — may include values slightly outside the range at either end (the usual axis behavior), so callers who only want in-range ticks should filter the result. */
export function niceTicks(min: number, max: number, count: number): number[] {
  if (min === max) return [min];
  const step = niceNum((max - min) / Math.max(count - 1, 1), true);
  const niceMin = Math.floor(min / step) * step;
  const niceMax = Math.ceil(max / step) * step;
  const ticks: number[] = [];
  for (let v = niceMin; v <= niceMax + step * 0.5; v += step) {
    ticks.push(v);
  }
  return ticks;
}

export type AxisUnit = { suffix: string; divisor: number };

/**
 * Picks ONE shared unit (K, M, or none) for an entire axis, based on
 * whether EVERY tick divides evenly into it — 30,000 becomes "30" under a
 * shared K unit, but a step like 500 (ticks 500/1500/2500...) would turn
 * into 0.5/1.5/2.5 under K, which is a decimal, so in that case this
 * deliberately doesn't scale at all rather than ever showing one.
 */
export function axisUnitFor(ticks: number[]): AxisUnit {
  const rounded = ticks.map((t) => Math.round(t));
  const divides = (divisor: number) => rounded.length > 0 && rounded.every((t) => t % divisor === 0);
  const hasMagnitude = (threshold: number) => rounded.some((t) => Math.abs(t) >= threshold);

  if (hasMagnitude(1_000_000) && divides(1_000_000)) return { suffix: 'M', divisor: 1_000_000 };
  if (hasMagnitude(1_000) && divides(1_000)) return { suffix: 'K', divisor: 1_000 };
  return { suffix: '', divisor: 1 };
}

/**
 * A single tick's label under a shared axisUnitFor() unit — e.g. 30,000
 * under the K unit becomes "$30" (bare, no repeated suffix) or "$30K" when
 * showUnit is set. Convention: only the axis's top (largest-magnitude)
 * tick carries the suffix — the rest imply the same shared scale, same as
 * how a chart's Y-axis title ("in $K") would normally do it, just inline
 * since there's no room here for a separate axis title. Falls back to a
 * plain grouped whole-number currency label when no unit applies —
 * always a whole number either way, never a decimal.
 */
export function formatAxisTick(value: number, currency: string, unit: AxisUnit, showUnit: boolean): string {
  const scaled = Math.round(value) / unit.divisor;
  if (unit.divisor === 1) {
    return formatMoney(scaled, currency, { decimals: 0 });
  }
  return `${currencySymbol(currency)}${scaled.toLocaleString()}${showUnit ? unit.suffix : ''}`;
}
