import { useFocusEffect } from '@react-navigation/native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, RefreshControl, ScrollView, StyleSheet, Switch } from 'react-native';

import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { CountryFlag } from '@/components/country-flag';
import { Surface } from '@/components/surface';
import { TravelChecklist } from '@/components/travel-checklist';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { formatMoney } from '@/lib/currency';
import { toDateOnlyString } from '@/lib/format';
import {
  daysInCountryForYear,
  daysInYear,
  daysRemainingInYear,
  effectiveHomeCountryFor,
  homeCountryDaysForYear,
  homeCountryDaysThisYear,
  lifetimeDaysInCountry,
  projectedDaysInCountryByYearEnd,
  projectedHomeCountryDaysByYearEnd,
  summarizeCountries,
  type PriorResidencyLike,
} from '@/lib/days';
import {
  attributedLocationForTransaction,
  isExcludedFromCountryTracking,
  summarizeSpendByCategory,
  summarizeSpendByCity,
  yearsSpannedByRanges,
  yearsWithData,
  type TripLinkMaps,
} from '@/lib/spend';
import { fetchAllRows } from '@/lib/fetchAll';
import { isCitizenshipTaxed } from '@/lib/residencyRules';
import { supabase } from '@/lib/supabase';
import { computeSameCountryOverlaps } from '@/lib/tripCalendar';
import { computeTripSummaries } from '@/lib/trips';
import type { AccountRow, CategoryRow, CountryVisitedRow, TransactionRow, TripRow, TripSegmentRow } from '@/types/database';

type SharedWithConnection = { connectionId: string; displayName: string };

const ACCENT = ModuleAccents.countries;
type YearOption = 'all' | number;

function formatTotals(totals: { currency: string; amount: number }[]): string {
  if (totals.length === 0) return formatMoney(0, 'USD');
  return totals.map((t) => formatMoney(Math.abs(t.amount), t.currency)).join(' · ');
}

export default function CountryDetailScreen() {
  const { country, year: yearParam } = useLocalSearchParams<{ country: string; year?: string }>();
  const router = useRouter();
  const { hiddenFlagCountries, setFlagHidden, homeCountry, convert } = useCurrency();
  const isFlagHidden = hiddenFlagCountries.includes(country);
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const [visits, setVisits] = useState<CountryVisitedRow[]>([]);
  const [transactions, setTransactions] = useState<TransactionRow[]>([]);
  const [categories, setCategories] = useState<CategoryRow[]>([]);
  const [accounts, setAccounts] = useState<AccountRow[]>([]);
  const [trips, setTrips] = useState<TripRow[]>([]);
  const [tripSegments, setTripSegments] = useState<TripSegmentRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  // Defaults to a specific year (this year, or whatever year a residency
  // notice linked here with), not "All-time" — presence and spend are both
  // more meaningful scoped to a year; "All-time" stays available as a chip
  // for browsing full history.
  const [selectedYear, setSelectedYear] = useState<YearOption>(() => {
    const parsed = yearParam ? Number(yearParam) : null;
    return parsed && !Number.isNaN(parsed) ? parsed : new Date().getFullYear();
  });
  const [sharedWithConnections, setSharedWithConnections] = useState<SharedWithConnection[]>([]);
  const [citizenshipCountries, setCitizenshipCountries] = useState<string[]>([]);
  const [priorResidencies, setPriorResidencies] = useState<PriorResidencyLike[]>([]);

  const load = useCallback(async () => {
    setError(null);
    const [
      visitsResult,
      transactionsResult,
      categoriesResult,
      accountsResult,
      tripsResult,
      segmentsResult,
      citizenshipsResult,
      priorResidenciesResult,
    ] = await Promise.all([
      supabase.from('countries_visited').select('*').order('entry_date', { ascending: false }),
      fetchAllRows<TransactionRow>((from, to) =>
        supabase.from('transactions').select('*').order('date').order('id').range(from, to)
      ),
      supabase.from('categories').select('*'),
      supabase.from('accounts').select('*'),
      supabase.from('trips').select('*'),
      supabase.from('trip_segments').select('*'),
      supabase.from('user_citizenships').select('country'),
      supabase.from('prior_residencies').select('*'),
    ]);

    if (visitsResult.error) {
      setError(visitsResult.error.message);
      setIsLoading(false);
      return;
    }

    setVisits(visitsResult.data ?? []);
    setTransactions(transactionsResult.data);
    setCategories(categoriesResult.data ?? []);
    setAccounts(accountsResult.data ?? []);
    setCitizenshipCountries((citizenshipsResult.data ?? []).map((c) => c.country));
    setTrips(tripsResult.data ?? []);
    setTripSegments(segmentsResult.data ?? []);
    setPriorResidencies(priorResidenciesResult.data ?? []);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  // Which connections have a shared trip note thread for THIS country —
  // computed the same way travel.tsx's "traveled/planned together" sections
  // do (computeSameCountryOverlaps against each connection's shared rows),
  // just filtered down to one country and without splitting past/future.
  // No new RPCs: shared_countries_visited/shared_trips_planned already gate
  // on accepted share status server-side, so an unshared connection simply
  // contributes no rows and no overlap.
  useEffect(() => {
    if (isLoading || swipeConnections.length === 0) {
      setSharedWithConnections([]);
      return;
    }
    let cancelled = false;
    async function loadOverlaps() {
      const results = await Promise.all(
        swipeConnections.map(async (c) => {
          const [visitedResult, plannedResult] = await Promise.all([
            supabase.rpc('shared_countries_visited', { p_connection_id: c.id }),
            supabase.rpc('shared_trips_planned', { p_connection_id: c.id }),
          ]);
          const partnerRows = [...(visitedResult.data ?? []), ...(plannedResult.data ?? [])];
          const overlaps = computeSameCountryOverlaps(visits, partnerRows);
          const hasOverlap = overlaps.some((o) => o.country === country);
          return hasOverlap ? { connectionId: c.id, displayName: c.displayName } : null;
        })
      );
      if (!cancelled) {
        setSharedWithConnections(results.filter((r): r is SharedWithConnection => r !== null));
      }
    }
    loadOverlaps();
    return () => {
      cancelled = true;
    };
    // swipeConnections is refetched on its own focus effect inside the hook
    // — depending on its array identity (not .length) here would refire
    // every render, since useSwipeConnections returns a fresh array each
    // time regardless of content.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isLoading, swipeConnections.length, visits, country]);

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  const countryVisits = visits.filter((v) => v.country === country);
  // "Home" isn't a single fixed fact — wherever you lived at a given
  // year's December 31 is that year's home country, per prior_residencies
  // (see lib/days.ts's effectiveHomeCountryFor and app/account/prior-
  // residencies.tsx). isHomeCountryNow covers the live/current-year tiles
  // below (Tier 1 stats, the travel checklist); isHomeCountryForYear
  // covers the year-chip-scoped stats further down — they're deliberately
  // different checks, not the same boolean reused, since a past year can
  // have had a different home country than today does.
  const today = toDateOnlyString(new Date());
  const isHomeCountryNow = country === effectiveHomeCountryFor(today, homeCountry, priorResidencies);
  function isHomeCountryForYear(year: number): boolean {
    return country === effectiveHomeCountryFor(`${year}-12-31`, homeCountry, priorResidencies);
  }
  const [summary] = summarizeCountries(countryVisits);
  const isCountryCitizenshipTaxed = isCitizenshipTaxed(country, citizenshipCountries);
  // Home country has no countries_visited rows of its own — it's the fallback
  // when no trip covers a date, not something with logged trips — so its
  // days figure reuses the same home-country tally shown on the dashboard's
  // Tier 1, instead of the rolling-365-day per-trip calculation below.
  const homeDaysTraveled = isHomeCountryNow ? homeCountryDaysThisYear(visits, country) : null;
  const homeDaysLeft = isHomeCountryNow ? daysRemainingInYear() : null;
  const homeDaysProjected = isHomeCountryNow ? projectedHomeCountryDaysByYearEnd(visits, country) : null;
  const projectedDays = !isHomeCountryNow ? projectedDaysInCountryByYearEnd(visits, country) : null;

  const categoryNameById = new Map(categories.map((c) => [c.id, c.name]));
  const excludedAccountIds = new Set(accounts.filter((a) => a.excluded_from_country_tracking).map((a) => a.id));

  const tripSummaries = computeTripSummaries(trips, visits, tripSegments);
  const links: TripLinkMaps = {
    stopsById: new Map(visits.map((v) => [v.id, { country: v.country, city: v.city }])),
    segmentCountryById: new Map(
      tripSegments.map((s) => [
        s.id,
        tripSummaries.find((t) => t.id === s.trip_id)?.countries[0] ?? homeCountry ?? 'Unknown',
      ])
    ),
  };

  // Spend only (excludes internal transfers and income/refunds), attributed to this country, all-time —
  // the year chips below then narrow this down further.
  const countrySpendAllTime = transactions.filter(
    (tx) =>
      !tx.is_internal_transfer &&
      tx.amount < 0 &&
      attributedLocationForTransaction(
        tx,
        visits,
        homeCountry,
        isExcludedFromCountryTracking(tx, excludedAccountIds),
        links,
        priorResidencies
      ).country === country
  );
  const countryPriorResidencies = priorResidencies.filter((r) => r.country === country);
  // Union of years with spend, years with a logged stay, AND years this
  // country was a prior residency (which, being a plain "this was home"
  // record rather than a trip, has no countries_visited row and may have
  // no spend logged either — without this, a quiet residency year would
  // never surface a chip at all). Stays use yearsSpannedByRanges, not
  // yearsWithData(entry_dates) — a single stop that ran from 2019 through
  // 2022 only has one entry_date, so an entry-only year list would show
  // just "2019" even though the stay also covered 2020-2022.
  const availableYearsRaw = Array.from(
    new Set([
      ...yearsWithData(countrySpendAllTime.map((tx) => tx.date)),
      ...yearsSpannedByRanges(countryVisits.map((v) => ({ start: v.entry_date, end: v.exit_date }))),
      ...yearsSpannedByRanges(countryPriorResidencies.map((r) => ({ start: r.start_date, end: r.end_date }))),
    ])
  ).sort((a, b) => b - a);
  // A year chip is only meaningful, for a year this country was actually
  // home (see isHomeCountryForYear), if some of it was actually spent away
  // — home has no countries_visited rows of its own (see homeDaysTraveled's
  // comment above), so a home year with nothing else going on has nothing
  // to show once picked (0 days traveled), so it's filtered out rather than
  // left as a chip that just restates "you were home the whole time." A
  // year this country ISN'T home for passes through unfiltered, exactly
  // like any other visited-country year.
  const availableYears = availableYearsRaw.filter((year) =>
    isHomeCountryForYear(year) ? homeCountryDaysForYear(visits, country, year) < daysInYear(year) : true
  );
  const yearOptions: YearOption[] = ['all', ...availableYears];
  // 'all' is a genuine lifetime total (every distinct day ever logged here,
  // via lib/days.ts's lifetimeDaysInCountry) — NOT the rolling/tax-year
  // residency-test tally the hero block above shows, which is deliberately
  // scoped to one compliance window and can read lower than this once
  // older visits age out of it. Previously this was just null (hidden)
  // for 'all', when the "All-time" chip was still standing in for that
  // same compliance tally instead of having its own real meaning.
  const yearDaysUsed =
    selectedYear === 'all'
      ? lifetimeDaysInCountry(visits, country)
      : isHomeCountryForYear(selectedYear)
        ? homeCountryDaysForYear(visits, country, selectedYear)
        : daysInCountryForYear(visits, country, selectedYear);

  const scopedTx =
    selectedYear === 'all'
      ? countrySpendAllTime
      : countrySpendAllTime.filter((tx) => tx.date.startsWith(String(selectedYear)));

  const totalsByCurrency = new Map<string, number>();
  for (const tx of scopedTx) {
    const { amount, currency } = convert(tx.amount, tx.currency);
    totalsByCurrency.set(currency, (totalsByCurrency.get(currency) ?? 0) + amount);
  }
  const totalSpend = Array.from(totalsByCurrency.entries()).map(([currency, amount]) => ({ currency, amount }));
  const topCategory = summarizeSpendByCategory(scopedTx, categoryNameById, convert)[0] ?? null;
  const cities = summarizeSpendByCity(
    scopedTx,
    visits,
    homeCountry,
    categoryNameById,
    convert,
    excludedAccountIds,
    links,
    priorResidencies
  );

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView
        contentContainerStyle={styles.content}
        refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            {country}
          </ThemedText>
          <Pressable
            onPress={() => router.push(`/countries/visit/new?country=${encodeURIComponent(country)}`)}
            hitSlop={12}>
            <IconSymbol name="plus" size={24} color={ACCENT} />
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedView style={styles.flagBox}>
          <CountryFlag countryName={country} hiddenFlagCountries={hiddenFlagCountries} size={64} />
        </ThemedView>

        <ThemedView style={styles.flagToggleRow}>
          <ThemedText style={styles.muted}>Show flag</ThemedText>
          <Switch
            value={!isFlagHidden}
            onValueChange={(value) => setFlagHidden(country, !value)}
            trackColor={{ true: ACCENT }}
          />
        </ThemedView>

        {isHomeCountryNow ? (
          <Surface accentColor={ACCENT}>
            <ThemedText type="mono" style={styles.homeStatValue}>
              {homeDaysTraveled} days home
            </ThemedText>
            <ThemedText type="mono" style={styles.homeStatValue}>
              {homeDaysLeft} days left
            </ThemedText>
            <ThemedText type="mono" style={[styles.homeStatValue, styles.muted]}>
              {homeDaysProjected} projected by year-end
            </ThemedText>
          </Surface>
        ) : summary ? (
          <Surface accentColor={ACCENT}>
            <ThemedText type="defaultSemiBold">
              {summary.daysUsed} / {summary.thresholdDays} days used
            </ThemedText>
            <ThemedText style={summary.overLimit && !isCountryCitizenshipTaxed ? styles.overLimit : styles.muted}>
              {summary.daysRemaining} remaining
            </ThemedText>
            {isCountryCitizenshipTaxed ? (
              <ThemedText style={[styles.muted, styles.projectedLine]}>
                You&apos;re a citizen of {country}, which taxes citizens regardless of day count, so this threshold
                doesn&apos;t change your filing obligation there.
              </ThemedText>
            ) : (
              <ThemedText style={[styles.muted, styles.projectedLine]}>
                {summary.windowLabel}
                {summary.ruleIsDefault ? " (general default, this country's own test isn't modeled yet)" : ''}. Day-count
                trigger only. Home, family and economic-ties tests can apply on fewer days.
              </ThemedText>
            )}
            <ThemedText style={[styles.muted, styles.projectedLine]}>
              {projectedDays} projected by year-end (incl. planned trips)
            </ThemedText>
          </Surface>
        ) : null}

        <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chipRow}>
          {yearOptions.map((option) => {
            const isSelected = selectedYear === option;
            return (
              <Pressable
                key={String(option)}
                onPress={() => setSelectedYear(option)}
                style={[styles.chip, { borderColor: ACCENT, backgroundColor: isSelected ? ACCENT : 'transparent' }]}>
                <ThemedText style={isSelected ? { color: ModuleAccentOnColor.countries } : undefined}>
                  {option === 'all' ? 'Current' : String(option)}
                </ThemedText>
              </Pressable>
            );
          })}
        </ScrollView>

        {yearDaysUsed !== null ? (
          <Pressable
            onPress={() => router.push(`/countries/${encodeURIComponent(country)}/calendar?year=${selectedYear}`)}>
            <Surface accentColor={ACCENT} style={styles.yearDaysRow}>
              <ThemedView>
                <ThemedText style={styles.muted}>{selectedYear === 'all' ? 'Days, all-time' : `Days in ${selectedYear}`}</ThemedText>
                <ThemedText type="mono" style={styles.yearDaysValue}>
                  {yearDaysUsed}
                </ThemedText>
              </ThemedView>
              <ThemedText type="link">View calendar ›</ThemedText>
            </Surface>
          </Pressable>
        ) : null}

        <ThemedView style={styles.tierTwoRow}>
          <Pressable
            style={styles.tierTwoTile}
            onPress={() =>
              router.push(`/countries/${encodeURIComponent(country)}/spend?year=${encodeURIComponent(String(selectedYear))}`)
            }>
            <Surface accentColor={ACCENT} style={styles.tierTwoTile}>
              <ThemedText style={styles.muted}>Total spend</ThemedText>
              <ThemedText type="mono" style={styles.tierTwoValue} numberOfLines={1} adjustsFontSizeToFit>
                {formatTotals(totalSpend)}
              </ThemedText>
            </Surface>
          </Pressable>
          <Surface accentColor={ACCENT} style={styles.tierTwoTile}>
            <ThemedText style={styles.muted}>Top category</ThemedText>
            <ThemedText type="defaultSemiBold" numberOfLines={1} adjustsFontSizeToFit>
              {topCategory ? topCategory.categoryName : '-'}
            </ThemedText>
          </Surface>
        </ThemedView>

        {!isHomeCountryNow ? (
          <>
            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
              Travel checklist
            </ThemedText>
            <TravelChecklist country={country} accentColor={ACCENT} />
          </>
        ) : null}

        {sharedWithConnections.length > 0 ? (
          <>
            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
              Shared with connections
            </ThemedText>
            {sharedWithConnections.map((c) => (
              <Pressable
                key={c.connectionId}
                onPress={() =>
                  router.push(`/connections/${c.connectionId}/trip-notes?country=${encodeURIComponent(country)}`)
                }>
                <Surface accentColor={ACCENT}>
                  <ThemedText type="defaultSemiBold">Traveled/planned with {c.displayName}</ThemedText>
                  <ThemedText style={styles.notesHint}>Tap for shared planning notes</ThemedText>
                </Surface>
              </Pressable>
            ))}
          </>
        ) : null}

        {countryVisits.length > 0 ? (
          <>
            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
              Cities visited
            </ThemedText>
            {cities.length === 0 ? <ThemedText style={styles.muted}>No city-attributed spend yet.</ThemedText> : null}
            <ThemedView style={styles.grid}>
              {cities.map((city) => (
                <Pressable
                  key={city.city}
                  style={styles.gridTile}
                  onPress={() =>
                    router.push(`/countries/${encodeURIComponent(country)}/${encodeURIComponent(city.city)}`)
                  }>
                  <Surface accentColor={ACCENT}>
                    <ThemedText type="defaultSemiBold" numberOfLines={1}>
                      {city.city}
                    </ThemedText>
                    <ThemedText type="mono" style={styles.muted} numberOfLines={1}>
                      {formatTotals(city.totals)}
                    </ThemedText>
                    <ThemedText style={styles.muted} numberOfLines={1}>
                      {city.topCategory ? city.topCategory.categoryName : '-'}
                    </ThemedText>
                  </Surface>
                </Pressable>
              ))}
            </ThemedView>

            <Pressable
              onPress={() => router.push(`/countries/${encodeURIComponent(country)}/visits`)}
              style={[styles.viewVisitsButton, { borderColor: ACCENT }]}>
              <ThemedText style={{ color: ACCENT }}>View all visits</ThemedText>
            </Pressable>
          </>
        ) : null}
      </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

