import { useRouter } from 'expo-router';
import { Pressable, StyleSheet } from 'react-native';

import { AccountList } from '@/components/account-list';
import { CategoryPieChart } from '@/components/category-pie-chart';
import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { ModuleAccents } from '@/constants/theme';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';

const ACCENT = ModuleAccents.wealth;

export default function CashAccountsScreen() {
  const router = useRouter();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ThemedView style={styles.titleRow}>
        <ThemedText type="title" style={{ color: ACCENT }}>
          Cash
        </ThemedText>
        <Pressable onPress={() => router.back()} hitSlop={12}>
          <ThemedText type="link">Done</ThemedText>
        </Pressable>
      </ThemedView>
      <AccountList
        accent={ACCENT}
        matches={(a) => a.account_type === 'asset' && a.asset_category === 'cash'}
        emptyLabel="No cash accounts yet."
        renderExtra={(rows) =>
          rows.length > 0 ? (
            <CategoryPieChart
              slices={rows.map((r) => ({ label: r.account.name, amount: Math.abs(r.amount), currency: r.currency }))}
            />
          ) : null
        }
      />
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: 16,
    paddingBottom: 0,
  },
});
