import { Pressable, StyleSheet } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { OWNERSHIP_OPTIONS, type Ownership } from '@/lib/scope';

/** Personal / Business chips for the account and card edit screens — the tag the All/Personal/Business scope switch filters on. */
export function OwnershipPicker({
  value,
  onChange,
  accent,
  onColor = Colors.light.backgroundSolid,
}: {
  value: Ownership;
  onChange: (value: Ownership) => void;
  accent: string;
  onColor?: string;
}) {
  return (
    <>
      <ThemedText type="defaultSemiBold" style={styles.label}>
        Owner
      </ThemedText>
      <ThemedView style={styles.row}>
        {OWNERSHIP_OPTIONS.map((option) => {
          const isSelected = option.value === value;
          return (
            <Pressable
              key={option.value}
              onPress={() => onChange(option.value)}
              style={[styles.chip, { borderColor: accent, backgroundColor: isSelected ? accent : 'transparent' }]}>
              <ThemedText style={isSelected ? { color: onColor } : undefined}>{option.label}</ThemedText>
            </Pressable>
          );
        })}
      </ThemedView>
      <ThemedText style={styles.hint}>
        Business items stay out of your personal totals when the Personal scope is on, and get their own view under
        Business. Transactions follow whichever account or card they came from.
      </ThemedText>
    </>
  );
}

const styles = StyleSheet.create({
  label: {
    marginTop: 12,
  },
  row: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
    marginTop: 6,
    marginBottom: 6,
  },
  chip: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 16,
    paddingHorizontal: 12,
    paddingVertical: 8,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 8,
  },
});
