import { useRouter } from 'expo-router';
import { createContext, useCallback, useContext, useMemo, useState, type PropsWithChildren } from 'react';

import { useCurrency } from '@/contexts/currency-context';

/** Ids a real on-screen element checks itself against via useTour().step?.highlightAnchor — the element renders its OWN highlight styling (a bold border/glow on itself), and dims every OTHER element around it via a plain opacity wrapper, rather than a separate overlay trying to track its position (that approach — measuring the element and drawing a matching cutout elsewhere — was tried and kept coming out misaligned; see components/tour-overlay.tsx's note). See components/home-wheel.tsx, app/accounts/index.tsx, app/account/index.tsx, components/top-bar.tsx, and components/connections-swipe-panel.tsx for the current call sites. Also used by reportTap()'s gating — despite the name, that gate isn't limited to literal taps; connections-swipe-panel.tsx reports it on a successful edge-swipe gesture too. */
export type TourAnchorId =
  | 'home-wheel'
  | 'accounts-fab'
  | 'home-country-picker'
  | 'top-bar-home'
  | 'connections-swipe'
  | 'swipe-panel-settings';

export type TourStep = {
  key: string;
  /** Navigated to (via router.replace, not push — the tour shouldn't balloon the nav stack) when this step becomes active. Omit to stay wherever the previous step's own real navigation already left off (used right after a tap-gated step, since that tap itself navigates). */
  route?:
    | '/'
    | '/account'
    | '/account/share'
    | '/accounts'
    | '/countries'
    | '/summary'
    | '/onboarding/demo-liquidity'
    | '/onboarding/demo-csv-import'
    | '/onboarding/demo-country'
    | '/onboarding/demo-accounts';
  title: string;
  body: string;
  /** If set, this step has no Next button — forward progress waits for a matching reportTap(anchorId) from the real UI, then auto-advances. Back/Skip still work normally. */
  waitForTapAnchor?: TourAnchorId;
  /** If set, the real element with this id highlights itself and dims everything around it while this step is active. Usually the same id as waitForTapAnchor, but doesn't have to be. Omit for pure-narration steps with no single element to point at. */
  highlightAnchor?: TourAnchorId;
  /** Where the instruction card sits. Defaults to 'bottom'; steps whose highlighted element is itself near the bottom (the Accounts "+" FAB) need 'top' instead so the card doesn't cover it. A static per-step choice, not something computed from a live measurement — we know ahead of time which screens have a bottom-anchored target. */
  cardPosition?: 'top' | 'bottom';
};

