type TourContextValue = {
  isActive: boolean;
  stepIndex: number;
  step: TourStep | null;
  totalSteps: number;
  startTour: () => void;
  nextStep: () => void;
  prevStep: () => void;
  skipTour: () => void;
  finishTour: () => void;
  /** Call from a real UI element's own onPress — a no-op unless the tour is active and currently waiting on this exact anchor. */
  reportTap: (anchorId: TourAnchorId) => void;
};

const TourContext = createContext<TourContextValue | null>(null);

export function TourProvider({ children }: PropsWithChildren) {
  const router = useRouter();
  const { completeOnboarding } = useCurrency();
  const [isActive, setIsActive] = useState(false);
  const [stepIndex, setStepIndex] = useState(0);

  // router.replace() — not push() — reuses the CURRENT screen's native view
  // slot instead of mounting a fresh one, which is exactly the code path a
  // known, still-open upstream react-native-screens bug lives in under
  // Fabric/New Architecture: the recycled slot's old view can still be
  // attached to its previous parent when Fabric tries to insert the new
  // content into it, throwing "addViewAt: failed to insert view... The
  // specified child already has a parent." (github.com/software-mansion/
  // react-native-screens issues #2803, #4137, #3249, #1422 — all the same
  // failure signature, all still open, all specifically tied to view
  // recycling during rapid/replace-style navigation). That's why patching
  // individual destination screens and deferring the call via
  // InteractionManager never actually fixed it — the race is inside the
  // navigation library's own native layer, not anything in this app's
  // render timing. push() mounts a genuinely new screen instead of
  // recycling a slot, so it never enters that code path. The tradeoff
  // (noted where replace used to be deliberate) is a growing nav stack
  // across the tour's ~13 steps — endTour() below collapses it back to a
  // single Home entry with dismissTo, so it's still just a normal single
  // Home stack afterward, not window dressing over an ever-growing history.
  const goToStep = useCallback(
    (index: number) => {
      setStepIndex(index);
      const route = TOUR_STEPS[index]?.route;
      if (route) router.push(route);
    },
    [router]
  );

  const startTour = useCallback(() => {
    setIsActive(true);
    // Stops app/index.tsx's needsOnboarding redirect from fighting the
    // tour's own navigation back to "/" on its very first step — once the
    // tour has genuinely started, the app shouldn't keep trying to shove
    // the user back onto a dedicated onboarding screen.
    completeOnboarding();
    goToStep(0);
  }, [completeOnboarding, goToStep]);

  const endTour = useCallback(() => {
    setIsActive(false);
    // dismissTo (not replace) — pops back through however many screens
    // goToStep's push()es have accumulated, landing on the ORIGINAL Home
    // screen from step 0 rather than stacking yet another one on top. Falls
    // back to a plain replace on its own if '/' somehow isn't found in the
    // stack, per its own documented behavior.
    router.dismissTo('/');
  }, [router]);

  const nextStep = useCallback(() => {
    const next = stepIndex + 1;
    if (next >= TOUR_STEPS.length) {
      endTour();
      return;
    }
    goToStep(next);
  }, [stepIndex, goToStep, endTour]);

  const prevStep = useCallback(() => {
    goToStep(Math.max(stepIndex - 1, 0));
  }, [stepIndex, goToStep]);

  const reportTap = useCallback(
    (anchorId: TourAnchorId) => {
      if (!isActive) return;
      if (TOUR_STEPS[stepIndex]?.waitForTapAnchor !== anchorId) return;
      nextStep();
    },
    [isActive, stepIndex, nextStep]
  );

  const value = useMemo<TourContextValue>(
    () => ({
      isActive,
      stepIndex,
      step: isActive ? (TOUR_STEPS[stepIndex] ?? null) : null,
      totalSteps: TOUR_STEPS.length,
      startTour,
      nextStep,
      prevStep,
      skipTour: endTour,
      finishTour: endTour,
      reportTap,
    }),
    [isActive, stepIndex, startTour, nextStep, prevStep, endTour, reportTap]
  );

  return <TourContext.Provider value={value}>{children}</TourContext.Provider>;
}

export function useTour() {
  const context = useContext(TourContext);
  if (!context) {
    throw new Error('useTour must be used within a TourProvider');
  }
  return context;
}
