import { LinearGradient } from 'expo-linear-gradient';
import { useRouter } from 'expo-router';
import { useEffect, useId, useRef } from 'react';
import { Animated, Easing, Pressable, StyleSheet, View, useWindowDimensions } from 'react-native';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';
import ReanimatedAnimated, {
  runOnJS,
  useAnimatedStyle,
  useSharedValue,
  withDecay,
  type SharedValue,
} from 'react-native-reanimated';
import Svg, { Defs, LinearGradient as SvgLinearGradient, Path, Stop } from 'react-native-svg';

import { ThemedText } from '@/components/themed-text';
import { IconSymbol, type IconSymbolName } from '@/components/ui/icon-symbol';
import { Colors, HomeFonts, ModuleWheelColors, type ModuleName } from '@/constants/theme';
import { useTour } from '@/contexts/tour-context';
import { formatMoney } from '@/lib/currency';

type SegmentHref = '/countries' | '/wealth' | '/cards' | '/spend' | '/accounts' | '/documents';

type Segment = {
  key: ModuleName;
  href: SegmentHref;
  icon: IconSymbolName;
};

// Order (and the -150° base angle below, vs. the usual -90°/12-o'clock
// start) is deliberately matched to the reference mockup's layout: airplane
// upper-left, money bag upper-right, folder right, credit card lower-right,
// scale lower-left, cart left — not just "however the modules happen to be
// listed elsewhere."
const SEGMENTS: Segment[] = [
  { key: 'countries', href: '/countries', icon: 'airplane' },
  { key: 'wealth', href: '/wealth', icon: 'banknote.fill' },
  { key: 'documents', href: '/documents', icon: 'folder.fill' },
  { key: 'cards', href: '/cards', icon: 'creditcard' },
  { key: 'accounts', href: '/accounts', icon: 'scalemass' },
  { key: 'spend', href: '/spend', icon: 'cart' },
];

const GAP_DEGREES = 5;
/** Amplifies a flick's raw physical angular velocity before handing it to withDecay — see the onEnd handler for why. */
const SPIN_VELOCITY_GAIN = 1.8;
const SEGMENT_DEGREES = 360 / SEGMENTS.length;
const ARC_DEGREES = SEGMENT_DEGREES - GAP_DEGREES;
/** -90 (12 o'clock) shifted back one slot so the first segment lands upper-left, matching the mockup. */
const BASE_ANGLE_DEGREES = -90 - SEGMENT_DEGREES;

/**
 * Plain, crisp icon — no offset-copy trick. An earlier version stacked 4
 * slightly-offset copies of the icon behind it to fake a colored glow, but
 * multiple offset copies is inherently a "poor man's blur," and now that
 * the wedge itself carries real color/glow (via home-wheel.tsx's actual
 * SVG Gaussian blur layers), stacking a second, cruder blur trick on the
 * icon on top of that just reads as smeared rather than glowing. The wedge
 * does the glow work now; the icon just needs to stay sharp against it.
 */
function WheelIcon({ name, color }: { name: IconSymbolName; color: string }) {
  return <IconSymbol name={name} size={26} color={color} />;
}

/**
 * The icon moves around the circle with the dial (its x/y position is
 * computed for wherever the wheel currently sits), but must always render
 * upright — it sits inside the same rotating layer as the colored wedges,
 * so without this it'd visibly tilt by however far the wheel has been
 * spun. Counter-rotates by -userRotation only (not the one-time entrance
 * spin, which nets to a full 720°/identity anyway and is fine to let the
 * icon ride along with as a brief flourish).
 */
function WheelIconButton({
  segment,
  x,
  y,
  userRotation,
  onPress,
}: {
  segment: Segment;
  x: number;
  y: number;
  userRotation: SharedValue<number>;
  onPress: () => void;
}) {
  const uprightStyle = useAnimatedStyle(() => ({
    transform: [{ rotate: `${-userRotation.value}deg` }],
  }));
  return (
    <Pressable onPress={onPress} hitSlop={10} style={[styles.iconButton, { left: x - 24, top: y - 24 }]}>
      <ReanimatedAnimated.View style={uprightStyle}>
        <WheelIcon name={segment.icon} color={ModuleWheelColors[segment.key].icon} />
      </ReanimatedAnimated.View>
    </Pressable>
  );
}

export function HomeWheel({
  netWorth,
  currency,
  isLoading,
  hideValue = false,
  rotationDegrees = 0,
  onRotationChange,
  spinOnLoad = true,
}: {
  netWorth: number;
  currency: string;
  isLoading: boolean;
  /** Privacy toggle — masks the net worth figure without hiding the wheel itself. */
  hideValue?: boolean;
  /** Persisted spin — how far the dial sits from its default resting angle. The wheel's position on screen never changes, only this rotation. */
  rotationDegrees?: number;
  /** Called once per drag, on release — not per-frame, so the caller can persist without spamming writes. */
  onRotationChange?: (degrees: number) => void;
  /** Settings toggle — the one-time 720° entrance-spin plays on every mount unless this is false, in which case the dial just appears at rest immediately (same final position either way — the animation is purely decorative, never net-rotates). */
  spinOnLoad?: boolean;
}) {
  const router = useRouter();
  const { reportTap, step } = useTour();
  const isTourHighlighted = step?.highlightAnchor === 'home-wheel';
  // Each segment gets its own <RadialGradient>, so each needs a distinct id
  // — a hardcoded one would collide if this component were ever mounted
  // twice (url(#id) resolves against the whole document on web). Same
  // pattern as components/surface.tsx's own corner glow.
  const gradientIdBase = useId().replace(/[^a-zA-Z0-9]/g, '');
  // Guards the entrance-spin effect below so it only ever acts once, and
  // only once the REAL spinOnLoad value is known.
  const hasHandledEntranceRef = useRef(false);
  const { width: windowWidth } = useWindowDimensions();
  const spin = useRef(new Animated.Value(0)).current;
  const sheen = useRef(new Animated.Value(0)).current;
  // The wheel stays centered at all times — dragging spins the dial in
  // place (like a real wheel) rather than moving the whole component.
  const userRotation = useSharedValue(rotationDegrees);
  const rotationAtGestureStart = useSharedValue(rotationDegrees);
  // Tracks whether the CURRENT gesture's onStart landed inside the drawn
  // circle — see the circular hit-test note by wheelRadiusSq below.
  const isTouchInsideWheel = useSharedValue(true);

  // rotationDegrees starts at 0 and only gets its real persisted value once
  // the parent's own load() resolves (after this component's first mount) —
  // sync the shared value when that arrives. Harmless to also run after a
  // drag ends, since the parent's prop by then already matches what we just
  // set it to.
  useEffect(() => {
    userRotation.value = rotationDegrees;
  }, [rotationDegrees, userRotation]);

  function persistRotation(degrees: number) {
    onRotationChange?.(degrees);
  }

  // Same -32 inset (16px each side) as Home's tile row and YTD card use for
  // their own horizontal padding/margin — matching that exactly, not an
  // arbitrary independent size, is the point: all three should read as the
  // same width. The 480 ceiling only ever matters on a tablet-width screen;
  // it's not a normal-phone constraint like the old 340 cap was (which sat
  // below windowWidth-32 on most phones and made the wheel visibly
  // narrower than the tiles/graph below it). Deliberately NOT capped by
  // available height — the wheel is the centerpiece of Home and stays
  // full width-based size regardless of viewport height; a page that's too
  // tight to fit it is handled by tightening everything ELSE on the
  // screen (see app/index.tsx), not by shrinking this.
  const size = Math.min(windowWidth - 32, 480);
  const center = size / 2;
  // Floor for the onEnd velocity conversion below — a quarter of the wheel's
  // radius, well clear of the center hub, so a release point that happens
  // to land near the middle can't blow up the ω = (r×v)/|r|² division.
  const minSpinRadiusSq = (center * 0.25) ** 2;
  // GestureDetector's hit area follows the wrapped View's box — a SQUARE of
  // side `size` — not the visible circle drawn inside it, so the square's
  // four corners (outside the drawn wheel entirely) were still capturing
  // drags and spinning the dial from what looked like empty page. Gate
  // on the touch actually falling within the drawn circle's radius.
  const wheelRadiusSq = (center - 4) ** 2;

  const panGesture = Gesture.Pan()
    .minDistance(10)
    .onStart((event) => {
      'worklet';
      const dx = event.x - center;
      const dy = event.y - center;
      isTouchInsideWheel.value = dx * dx + dy * dy <= wheelRadiusSq;
      if (!isTouchInsideWheel.value) return;
      const startTouchAngle = (Math.atan2(event.y - center, event.x - center) * 180) / Math.PI;
      rotationAtGestureStart.value = userRotation.value - startTouchAngle;
    })
    .onUpdate((event) => {
      'worklet';
      if (!isTouchInsideWheel.value) return;
      const touchAngle = (Math.atan2(event.y - center, event.x - center) * 180) / Math.PI;
      userRotation.value = rotationAtGestureStart.value + touchAngle;
    })
    .onEnd((event) => {
      'worklet';
      if (!isTouchInsideWheel.value) return;
      // A slow, deliberate release (or letting go after just holding it in
      // place) has near-zero velocity here, so withDecay barely moves it —
      // it "just stays" exactly where it was left, same as before. A quick
      // flick keeps spinning and eases down to a stop instead of dead-
      // stopping the instant the finger lifts.
      //
      // event.velocityX/Y are LINEAR (px/s) at the release point, but
      // userRotation is an ANGLE — converting one to the other is the
      // standard 2D "linear velocity of a point on a rotating body" formula,
      // ω = (r × v) / |r|², where r is the touch point's position relative
      // to the wheel's center and r × v is the 2D cross product
      // (r.x*v.y - r.y*v.x). This is the same atan2(y-center, x-center)
      // convention onStart/onUpdate already use for the angle itself, so
      // the sign comes out consistent with how userRotation is defined.
      const dx = event.x - center;
      const dy = event.y - center;
      // ω = (r×v)/|r|² blows up as the release point approaches the
      // wheel's center — a flick whose finger happens to end near the
      // middle (very plausible, since a natural flick arcs inward) divides
      // by a tiny |r|² and produces a wildly oversized angular velocity
      // from what felt like an ordinary touch, reading as "too sensitive"
      // / spinning on its own. Flooring |r|² at a reasonable minimum
      // radius keeps the conversion physically sane regardless of where
      // exactly the release lands.
      const distSq = Math.max(dx * dx + dy * dy, minSpinRadiusSq);
      const angularVelocityRad = (dx * event.velocityY - dy * event.velocityX) / distSq;
      // Gained up and given a slower decay than the raw physical
      // conversion alone produces — the literal ω from a typical flick's
      // velocity settled too quickly to read as "spin," more like a
      // shrug. SPIN_VELOCITY_GAIN amplifies how far a given flick throws
      // it; the higher deceleration (closer to 1 = less friction per
      // frame) makes it carry for longer once thrown, both in service of
      // the same "more powerful" ask — a flick should feel like it's
      // spinning a real wheel with some weight to it, not a light switch.
      const angularVelocityDeg = (angularVelocityRad * 180) / Math.PI * SPIN_VELOCITY_GAIN;

      userRotation.value = withDecay({ velocity: angularVelocityDeg, deceleration: 0.998 }, (finished) => {
        if (finished) {
          runOnJS(persistRotation)(userRotation.value);
        }
      });
    });

  const userSpinStyle = useAnimatedStyle(() => ({
    transform: [{ rotate: `${userRotation.value}deg` }],
  }));

  useEffect(() => {
    // spinOnLoad defaults to true and only reflects the real persisted
    // setting once the parent's own user_settings fetch resolves — while
    // isLoading is still true, spinOnLoad may be wrong. Previously this
    // effect ran immediately on mount assuming the default, so a user with
    // the setting turned OFF would still see the animation kick off for
    // however long the fetch took, then get yanked to a stop the instant
    // the real (false) value arrived — a visible, unwanted partial spin.
    // Waiting for isLoading to actually clear (guarded so this only ever
    // fires once) means the very first thing that runs already has the
    // correct answer.
    if (isLoading || hasHandledEntranceRef.current) return;
    hasHandledEntranceRef.current = true;
    if (spinOnLoad) {
      Animated.timing(spin, {
        toValue: 1,
        duration: 1400,
        easing: Easing.out(Easing.cubic),
        useNativeDriver: true,
      }).start();
      Animated.timing(sheen, {
        toValue: 1,
        duration: 1400,
        easing: Easing.out(Easing.quad),
        useNativeDriver: true,
      }).start();
    } else {
      // Jump straight to the animation's resting value (net rotation is
      // always a full 720° = identity either way) instead of animating —
      // the dial just appears already settled, no spin or sheen sweep.
      spin.setValue(1);
      sheen.setValue(1);
    }
  }, [isLoading, spin, sheen, spinOnLoad]);

  const rotate = spin.interpolate({ inputRange: [0, 1], outputRange: ['0deg', '720deg'] });

  // Geometry ported directly from the mockup's own wheel (outerR=140,
  // innerR=86 of a 300px canvas — the ratios below match exactly): a flat
  // donut of crisp pie-wedge Paths, no bezel rings, no halo, no blur. The
  // white hub sits flush against the wedges' inner edge, same as the
  // mockup's .hub div (172px = 2×86 against a 280px wedge diameter).
  const outerRadius = size / 2 - size * 0.033;
  const innerRadius = outerRadius * (86 / 140);
  const segmentRingRadius = (outerRadius + innerRadius) / 2;
  const centerRadius = innerRadius;

  // Computed once and shared by the wedge paths and the icon buttons below,
  // rather than each recomputing its own angle/position.
  const segmentGeometry = SEGMENTS.map((segment, index) => {
    const startAngle = index * SEGMENT_DEGREES + BASE_ANGLE_DEGREES + GAP_DEGREES / 2;
    const endAngle = startAngle + ARC_DEGREES;
    const midAngleDeg = index * SEGMENT_DEGREES + BASE_ANGLE_DEGREES + SEGMENT_DEGREES / 2;
    const midAngleRad = (midAngleDeg * Math.PI) / 180;
    return {
      segment,
      startAngle,
      endAngle,
      x: center + segmentRingRadius * Math.cos(midAngleRad),
      y: center + segmentRingRadius * Math.sin(midAngleRad),
    };
  });

  function wheelPoint(r: number, deg: number) {
    const rad = (deg * Math.PI) / 180;
    return { x: center + r * Math.cos(rad), y: center + r * Math.sin(rad) };
  }

  /** Same donut-wedge path construction as the mockup's own sectorPath(): outer arc, straight edge in to the inner ring, inner arc back, close. */
  function sectorPath(startDeg: number, endDeg: number): string {
    const o1 = wheelPoint(outerRadius, startDeg);
    const o2 = wheelPoint(outerRadius, endDeg);
    const i1 = wheelPoint(innerRadius, endDeg);
    const i2 = wheelPoint(innerRadius, startDeg);
    const large = endDeg - startDeg <= 180 ? 0 : 1;
    return `M ${o1.x} ${o1.y} A ${outerRadius} ${outerRadius} 0 ${large} 1 ${o2.x} ${o2.y} L ${i1.x} ${i1.y} A ${innerRadius} ${innerRadius} 0 ${large} 0 ${i2.x} ${i2.y} Z`;
  }

  const sheenTranslate = sheen.interpolate({
    inputRange: [0, 1],
    outputRange: [-size * 1.4, size * 1.4],
  });

  return (
    <GestureDetector gesture={panGesture}>
      <View style={{ width: size, height: size }}>
      {/* User-driven spin (persisted) wraps the one-time entrance animation
          (also a rotation) — nesting two rotating layers composes their
          angles additively, so the dial ends up at entrance-rotation +
          user-rotation. */}
      <ReanimatedAnimated.View style={[StyleSheet.absoluteFill, userSpinStyle]}>
      <Animated.View style={[StyleSheet.absoluteFill, { transform: [{ rotate }] }]}>
        <Svg width={size} height={size}>
          {/* Crisp flat pie wedges — one <Path> per module, filled with a
              plain diagonal 2-stop gradient (light -> base, matching the
              mockup's own makeGradient/sectorPath exactly) and a thin white
              stroke as the divider between segments. No blur, no bezel
              ring, no radial glow layer — those all belonged to an earlier,
              much glassier treatment this component used to have; the
              mockup's wheel has none of them. */}
          <Defs>
            {segmentGeometry.map(({ segment }) => (
              <SvgLinearGradient key={segment.key} id={`wheelGrad-${gradientIdBase}-${segment.key}`} x1="0" y1="0" x2="1" y2="1">
                <Stop offset="0%" stopColor={ModuleWheelColors[segment.key].light} />
                <Stop offset="100%" stopColor={ModuleWheelColors[segment.key].base} />
              </SvgLinearGradient>
            ))}
          </Defs>
          {segmentGeometry.map(({ segment, startAngle, endAngle }) => (
            <Path
              key={segment.key}
              d={sectorPath(startAngle, endAngle)}
              fill={`url(#wheelGrad-${gradientIdBase}-${segment.key})`}
              stroke="rgba(255, 255, 255, 0.9)"
              strokeWidth={2}
            />
          ))}
        </Svg>

        {segmentGeometry.map(({ segment, x, y }) => (
          <WheelIconButton
            key={segment.key}
            segment={segment}
            x={x}
            y={y}
            userRotation={userRotation}
            onPress={() => {
              reportTap('home-wheel');
              router.push(segment.href);
            }}
          />
        ))}
      </Animated.View>
      </ReanimatedAnimated.View>

      {/* Sheen sweep: a diagonal highlight band crossing the wheel once on mount, clipped to the circle. */}
      <View
        style={[styles.sheenClip, { width: size, height: size, borderRadius: size / 2 }]}
        pointerEvents="none">
        <Animated.View
          style={[
            styles.sheenBand,
            {
              width: size * 2,
              height: size * 2,
              left: -size * 0.5,
              top: -size * 0.5,
              transform: [{ translateX: sheenTranslate }, { rotate: '25deg' }],
            },
          ]}>
          <LinearGradient
            colors={['rgba(255, 255, 255, 0)', 'rgba(255, 255, 255, 0.55)', 'rgba(255, 255, 255, 0)']}
            locations={[0.46, 0.5, 0.54]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 0 }}
            style={StyleSheet.absoluteFillObject}
          />
        </Animated.View>
      </View>

      <Pressable
        onPress={() => router.push('/summary')}
        style={[
          styles.center,
          {
            width: centerRadius * 2,
            height: centerRadius * 2,
            borderRadius: centerRadius,
            left: center - centerRadius,
            top: center - centerRadius,
            backgroundColor: 'rgba(255, 255, 255, 0.9)',
          },
        ]}>
        <ThemedText style={styles.centerLabel}>SUMMARY</ThemedText>
        <ThemedText style={styles.centerValue} numberOfLines={1} adjustsFontSizeToFit>
          {isLoading ? '···' : hideValue ? '••••••' : formatMoney(netWorth, currency)}
        </ThemedText>
        <ThemedText style={styles.centerCaption}>Net worth</ThemedText>
      </Pressable>

      {/* Tour highlight — a ring drawn around the wheel itself rather than a
          separate overlay trying to track its position (see
          components/tour-overlay.tsx's own note on why that approach was
          dropped). pointerEvents="none" so it doesn't block the drag
          gesture or any of the tappable icons/center button underneath. */}
      {isTourHighlighted ? (
        <View
          pointerEvents="none"
          style={[
            styles.tourHighlightRing,
            { width: size + 16, height: size + 16, borderRadius: (size + 16) / 2, left: -8, top: -8 },
          ]}
        />
      ) : null}
      </View>
    </GestureDetector>
  );
}

const styles = StyleSheet.create({
  tourHighlightRing: {
    position: 'absolute',
    borderWidth: 4,
    borderColor: Colors.light.tint,
  },
  iconButton: {
    position: 'absolute',
    width: 48,
    height: 48,
    alignItems: 'center',
    justifyContent: 'center',
  },
  sheenClip: {
    position: 'absolute',
    overflow: 'hidden',
  },
  sheenBand: {
    position: 'absolute',
  },
  center: {
    position: 'absolute',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 2,
    paddingHorizontal: 8,
    shadowColor: '#26251A',
    shadowOffset: { width: 0, height: 3 },
    shadowOpacity: 0.12,
    shadowRadius: 10,
    elevation: 3,
  },
  centerLabel: {
    fontSize: 9.5,
    letterSpacing: 1.3,
    opacity: 0.7,
    fontFamily: HomeFonts.bodySemiBold,
    textTransform: 'uppercase',
  },
  centerValue: {
    fontSize: 23,
    marginTop: 6,
    fontFamily: HomeFonts.display,
  },
  centerCaption: {
    fontSize: 10.5,
    fontWeight: '600',
    marginTop: 5,
    opacity: 0.85,
  },
});
