import { useRouter } from 'expo-router';
import { Pressable, ScrollView, StyleSheet } from 'react-native';

import { AssetLiabilitySunburst, type SunburstAccount } from '@/components/asset-liability-sunburst';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useTour } from '@/contexts/tour-context';
import { formatMoney } from '@/lib/currency';
import { DEMO_ACCOUNTS } from '@/lib/demoData';

const ACCENT = ModuleAccents.accounts;
const ASSETS_COLOR = ModuleAccents.wealth;
const LIABILITIES_COLOR = ModuleAccents.spend;

const DEMO_ASSETS: SunburstAccount[] = DEMO_ACCOUNTS.filter((a) => a.balance > 0).map((a) => ({
  id: a.name,
  label: a.name,
  amount: a.balance,
}));
const DEMO_LIABILITIES: SunburstAccount[] = DEMO_ACCOUNTS.filter((a) => a.balance < 0).map((a) => ({
  id: a.name,
  label: a.name,
  amount: -a.balance,
}));
const DEMO_ASSETS_TOTAL = DEMO_ASSETS.reduce((sum, a) => sum + a.amount, 0);
const DEMO_LIABILITIES_TOTAL = DEMO_LIABILITIES.reduce((sum, a) => sum + a.amount, 0);

/**
 * Stand-in for the real Accounts overview during the walkthrough — same
 * layout (assets/liabilities tiles, sunburst, legend), but built from the
 * same fixed DEMO_ACCOUNTS the liquidity step already uses instead of the
 * real, async-loaded, data-shape-dependent version. The real screen only
 * mounts AssetLiabilitySunburst once its Supabase fetch resolves (and
 * renders a totally different, much simpler tree for a brand-new/empty
 * account than for one with real accounts logged) — an async structural
 * change landing in the same commit as the tour's own router.replace is
 * exactly the kind of Fabric mounting race ("addViewAt: failed to insert
 * view... already has a parent") that was crashing the walkthrough. This
 * screen has no loading state and no data-dependent branching at all — its
 * whole tree is available synchronously on first paint — so there's no
 * async window left for that race to land in, regardless of whether the
 * account doing the tour is brand new or has years of real data.
 */
export default function DemoAccountsScreen() {
  const router = useRouter();
  const { reportTap, step } = useTour();
  const isFabHighlighted = step?.highlightAnchor === 'accounts-fab';

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView style={isFabHighlighted ? styles.tourDimmed : undefined} contentContainerStyle={styles.content}>
        <ThemedText type="title" style={{ color: ACCENT }}>
          Accounts
        </ThemedText>
        <ThemedText style={styles.muted}>Example portfolio, not your real accounts.</ThemedText>

        <ThemedView style={styles.tierRow}>
          <Surface accentColor={ASSETS_COLOR} style={styles.tierTile}>
            <ThemedText style={styles.muted}>Assets</ThemedText>
            <ThemedText type="mono" style={styles.tierValue} numberOfLines={1} adjustsFontSizeToFit>
              {formatMoney(DEMO_ASSETS_TOTAL, 'USD')}
            </ThemedText>
          </Surface>
          <Surface accentColor={LIABILITIES_COLOR} style={styles.tierTile}>
            <ThemedText style={styles.muted}>Liabilities</ThemedText>
            <ThemedText type="mono" style={styles.tierValue} numberOfLines={1} adjustsFontSizeToFit>
              {formatMoney(DEMO_LIABILITIES_TOTAL, 'USD')}
            </ThemedText>
          </Surface>
        </ThemedView>

        <AssetLiabilitySunburst
          assets={DEMO_ASSETS}
          liabilities={DEMO_LIABILITIES}
          assetsColor={ASSETS_COLOR}
          liabilitiesColor={LIABILITIES_COLOR}
        />

        <ThemedView style={styles.legendRow}>
          <ThemedView style={styles.legendItem}>
            <ThemedView style={[styles.swatch, { backgroundColor: ASSETS_COLOR }]} />
            <ThemedText style={styles.muted}>Assets ({DEMO_ASSETS.length})</ThemedText>
          </ThemedView>
          <ThemedView style={styles.legendItem}>
            <ThemedView style={[styles.swatch, { backgroundColor: LIABILITIES_COLOR }]} />
            <ThemedText style={styles.muted}>Liabilities ({DEMO_LIABILITIES.length})</ThemedText>
          </ThemedView>
        </ThemedView>
      </ScrollView>

      {/* Genuinely functional, unlike the rest of this screen — tapping it
          both advances the tour and takes you to the real add-account
          form, matching the next step's "fill this in for real whenever
          you're ready" copy. */}
      <Pressable
        onPress={() => {
          reportTap('accounts-fab');
          router.push('/accounts/new/edit');
        }}
        style={[styles.fab, { backgroundColor: ACCENT }, isFabHighlighted ? styles.fabHighlighted : null]}>
        <IconSymbol name="plus" size={28} color={ModuleAccentOnColor.accounts} />
      </Pressable>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 16,
    paddingBottom: 96,
  },
  tierRow: {
    flexDirection: 'row',
    gap: 8,
    alignSelf: 'stretch',
  },
  tierTile: {
    flex: 1,
    gap: 4,
  },
  tierValue: {
    fontSize: 18,
  },
  legendRow: {
    flexDirection: 'row',
    gap: 20,
  },
  legendItem: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
  },
  swatch: {
    width: 12,
    height: 12,
    borderRadius: 6,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  fab: {
    position: 'absolute',
    right: 20,
    bottom: 28,
    width: 56,
    height: 56,
    borderRadius: 28,
    alignItems: 'center',
    justifyContent: 'center',
    shadowColor: '#000',
    shadowOpacity: 0.2,
    shadowRadius: 6,
    shadowOffset: { width: 0, height: 3 },
    elevation: 4,
  },
  fabHighlighted: {
    borderWidth: 4,
    borderColor: Colors.light.tint,
    shadowColor: Colors.light.tint,
    shadowOpacity: 0.6,
    shadowRadius: 10,
    elevation: 10,
  },
  tourDimmed: {
    opacity: 0.3,
  },
});
