import { useState } from 'react';
import { ScrollView, StyleSheet } from 'react-native';

import { CountryFlag } from '@/components/country-flag';
import { DemoTransactionRow } from '@/components/demo-transaction-row';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { TransactionSortControl } from '@/components/transaction-sort-control';
import { Colors, ModuleAccents } from '@/constants/theme';
import { formatMoney } from '@/lib/currency';
import { DEMO_TRANSACTIONS, DEMO_TRIP_COUNTRY, type DemoTransaction } from '@/lib/demoData';
import { sortTransactions, type TransactionSortDirection, type TransactionSortField } from '@/lib/transactionSort';

const ACCENT = ModuleAccents.countries;

/**
 * Illustrates a country detail screen's spend tracking — including the
 * "Not related to this trip" toggle (transactions.excluded_from_travel_spend)
 * actually changing what counts toward the country's total, live, using a
 * fabricated France trip. A brand-new account has no logged trips or spend
 * yet, so there's nothing real to demonstrate this with. Pure local state;
 * DemoTransactionRow makes no Supabase calls (unlike the real TransactionRow).
 */
export default function DemoCountryScreen() {
  const [transactions, setTransactions] = useState<DemoTransaction[]>(DEMO_TRANSACTIONS);
  const [sortField, setSortField] = useState<TransactionSortField>('date');
  const [sortDirection, setSortDirection] = useState<TransactionSortDirection>('desc');

  // Excluded transactions fall back to the home country, same as the real
  // attribution logic — they simply drop out of this country's totals.
  const attributedTx = transactions.filter((t) => !t.excludedFromTrip);
  const sortedTx = sortTransactions(transactions, sortField, sortDirection);

  const totalSpend = attributedTx.reduce((sum, t) => sum + Math.abs(t.amount), 0);
  const byCategory = new Map<string, number>();
  for (const t of attributedTx) {
    byCategory.set(t.categoryName, (byCategory.get(t.categoryName) ?? 0) + Math.abs(t.amount));
  }
  const categoryBreakdown = Array.from(byCategory.entries()).sort((a, b) => b[1] - a[1]);
  const cities = Array.from(new Set(attributedTx.map((t) => t.city)));

  function handleChange(updated: DemoTransaction) {
    setTransactions((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <CountryFlag countryName={DEMO_TRIP_COUNTRY} hiddenFlagCountries={[]} size={40} />
          <ThemedText type="title" style={{ color: ACCENT }}>
            {DEMO_TRIP_COUNTRY}
          </ThemedText>
        </ThemedView>
        <ThemedText style={styles.muted}>
          Example trip, not your real travel. Try flipping &quot;Not related to this trip&quot; on the Netflix
          charge below and watch the total change.
        </ThemedText>

        <Surface accentColor={ACCENT}>
          <ThemedText style={styles.muted}>Total spend</ThemedText>
          <ThemedText type="mono" style={styles.totalValue}>
            {formatMoney(totalSpend, 'EUR')}
          </ThemedText>
        </Surface>

        <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
          By category
        </ThemedText>
        {categoryBreakdown.map(([name, amount]) => (
          <Surface key={name} accentColor={ACCENT}>
            <ThemedView style={styles.rowBetween}>
              <ThemedText type="defaultSemiBold">{name}</ThemedText>
              <ThemedText type="mono">{formatMoney(amount, 'EUR')}</ThemedText>
            </ThemedView>
          </Surface>
        ))}

        <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
          Cities visited
        </ThemedText>
        <ThemedView style={styles.chipRow}>
          {cities.map((city) => (
            <ThemedView key={city} style={[styles.cityChip, { borderColor: ACCENT }]}>
              <ThemedText style={{ color: ACCENT }}>{city}</ThemedText>
            </ThemedView>
          ))}
        </ThemedView>

        <ThemedView style={[styles.sectionSpacing, styles.sectionHeaderRow]}>
          <ThemedText type="subtitle" style={{ color: ACCENT }}>
            Transactions
          </ThemedText>
          <TransactionSortControl
            sortField={sortField}
            sortDirection={sortDirection}
            onChange={(field, direction) => {
              setSortField(field);
              setSortDirection(direction);
            }}
            accentColor={ACCENT}
          />
        </ThemedView>
        {sortedTx.map((tx) => (
          <DemoTransactionRow key={tx.id} transaction={tx} accentColor={ACCENT} onChange={handleChange} />
        ))}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 96,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
  },
  totalValue: {
    fontSize: 26,
  },
  sectionSpacing: {
    marginTop: 16,
  },
  sectionHeaderRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    flexWrap: 'wrap',
    gap: 8,
  },
  rowBetween: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  chipRow: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
  },
  cityChip: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 16,
    paddingHorizontal: 16,
    paddingVertical: 8,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
});
