import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { CityAutocompleteInput } from '@/components/city-autocomplete-input';
import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { CountryAutocompleteInput } from '@/components/country-autocomplete-input';
import { CountryFlag } from '@/components/country-flag';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { useCurrency } from '@/contexts/currency-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { flagCodeForCountry } from '@/lib/countries';
import { showAlert } from '@/lib/alert';
import { supabase } from '@/lib/supabase';
import { computeDisplayName } from '@/hooks/use-connection-display';
import type { WishlistCityRow } from '@/types/database';

const ACCENT = ModuleAccents.countries;

type SharedWishlistItem = Pick<WishlistCityRow, 'id' | 'country' | 'city' | 'fulfilled_visit_id'> & {
  sharerName: string;
};

export default function WishlistScreen() {
  const router = useRouter();
  const { session } = useAuth();
  const { hiddenFlagCountries } = useCurrency();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();
  const [items, setItems] = useState<WishlistCityRow[]>([]);
  const [sharedItems, setSharedItems] = useState<SharedWishlistItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [country, setCountry] = useState('');
  const [city, setCity] = useState('');
  const [isSaving, setIsSaving] = useState(false);

  // CountryAutocompleteInput's value is free-typed text, only a real
  // selection (or a typed exact match) is an actual, valid country — unlike
  // the old SelectModal, which could only ever produce one. Gates the city
  // field and the save button so a half-typed or misspelled country can't
  // be saved (cities stay free-typed on purpose since there's no complete
  // list to validate against; countries do have one).
  const isValidCountry = !!flagCodeForCountry(country.trim());

  const load = useCallback(async () => {
    // Explicit user_id filter, not just RLS — wishlist_cities now has a
    // SECOND select policy (084, can_access_wishlist_item) so a shared
    // item's detail screen can load it by id, which means an unfiltered
    // query like this one would otherwise also pull in items connections
    // have shared with you, merging them into "your own" list instead of
    // the separate "Shared with you" section below (confirmed directly —
    // Jada's shared Amsterdam showed up with a delete button, as if owned).
    if (!session) {
      setItems([]);
    } else {
      const { data, error: fetchError } = await supabase
        .from('wishlist_cities')
        .select('*')
        .eq('user_id', session.user.id)
        .order('created_at', { ascending: false });
      if (fetchError) setError(fetchError.message);
      setItems(data ?? []);
    }

    // Cities connections have shared with ME — per-city, one-way, no accept
    // step on my end (see supabase/078_wishlist_sharing_one_way.sql). The
    // RPC is per-connection (same one app/connections/[connectionId]/
    // wishlist.tsx uses for its own deep-dive view), so this fans out
    // across every accepted connection and only resolves a display name
    // for the ones that actually shared something — same
    // fetch-connections-then-resolve-names-in-parallel pattern already
    // used for wishlist note authors in app/countries/wishlist/[id].tsx.
    const { data: connections } = await supabase
      .from('connections')
      .select('id, requester_id, recipient_id')
      .eq('status', 'accepted');
    if (connections && connections.length > 0) {
      const perConnection = await Promise.all(
        connections.map(async (c) => {
          const { data: sharedRows } = await supabase.rpc('shared_wishlist_cities', { p_connection_id: c.id });
          if (!sharedRows || sharedRows.length === 0) return [];
          const [profileResult, overrideResult] = await Promise.all([
            supabase.rpc('connection_partner_profile', { p_connection_id: c.id }).maybeSingle(),
            session
              ? supabase
                  .from('connection_display_overrides')
                  .select('label')
                  .eq('connection_id', c.id)
                  .eq('viewer_user_id', session.user.id)
                  .maybeSingle()
              : Promise.resolve({ data: null }),
          ]);
          const sharerName = computeDisplayName(
            overrideResult.data?.label ?? null,
            profileResult.data?.full_name ?? null,
            profileResult.data?.email ?? null
          );
          return sharedRows.map((r) => ({
            id: r.id,
            country: r.country,
            city: r.city,
            fulfilled_visit_id: r.fulfilled_visit_id,
            sharerName,
          }));
        })
      );
      setSharedItems(perConnection.flat());
    } else {
      setSharedItems([]);
    }

    setIsLoading(false);
  }, [session]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  async function handleAdd() {
    if (!session || !isValidCountry || !city.trim()) return;
    setIsSaving(true);
    setError(null);
    const { error: insertError } = await supabase.from('wishlist_cities').insert({
      user_id: session.user.id,
      country: country.trim(),
      city: city.trim(),
    });
    setIsSaving(false);
    if (insertError) {
      // A repeat add of the same still-active city hits the partial unique
      // index (wishlist_cities_active_city_idx) — that's a friendly no-op,
      // not a real error, since the city's already on the list.
      if (insertError.code !== '23505') setError(insertError.message);
      setCountry('');
      setCity('');
      await load();
      return;
    }
    setCountry('');
    setCity('');
    await load();
  }

  async function handleDelete(id: string) {
    showAlert('Remove from wishlist?', undefined, [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Remove',
        style: 'destructive',
        onPress: async () => {
          const { error: deleteError } = await supabase.from('wishlist_cities').delete().eq('id', id);
          if (deleteError) {
            setError(deleteError.message);
            return;
          }
          setItems((prev) => prev.filter((i) => i.id !== id));
        },
      },
    ]);
  }

  const active = items.filter((i) => !i.fulfilled_visit_id);
  const fulfilled = items.filter((i) => i.fulfilled_visit_id);

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Wishlist
          </ThemedText>
          <ThemedView style={styles.titleLinks}>
            <Pressable onPress={() => router.back()} hitSlop={12}>
              <ThemedText type="link">Done</ThemedText>
            </Pressable>
          </ThemedView>
        </ThemedView>
        <ThemedText style={styles.hint}>
          Cities you want to go to, not places you&apos;ve been. Open a city to share it directly with a connection,
          no request or acceptance needed on their end. Turn any of them into a real trip whenever it&apos;s time.
        </ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <Surface accentColor={ACCENT} style={styles.formSurface}>
          <ThemedText type="defaultSemiBold">Add a city</ThemedText>
          <CountryAutocompleteInput
            value={country}
            onChangeText={setCountry}
            onSelectCountry={(name) => {
              setCountry(name);
              setCity('');
            }}
            hiddenFlagCountries={hiddenFlagCountries}
            accentColor={ACCENT}
          />

          {isValidCountry ? (
            <CityAutocompleteInput
              value={city}
              onChangeText={setCity}
              onSelectPlace={(place) => setCity(place.name)}
              countryCode={flagCodeForCountry(country)?.split('-')[0] ?? undefined}
              placeholder="e.g. Venice"
              accentColor={ACCENT}
            />
          ) : null}

          <Pressable
            onPress={handleAdd}
            disabled={isSaving || !isValidCountry || !city.trim()}
            style={[
              styles.addButton,
              { backgroundColor: ACCENT, opacity: isSaving || !isValidCountry || !city.trim() ? 0.5 : 1 },
            ]}>
            <ThemedText style={{ color: ModuleAccentOnColor.countries, fontWeight: '600' }}>
              {isSaving ? 'Adding…' : '+ Add to wishlist'}
            </ThemedText>
          </Pressable>
        </Surface>

        {isLoading ? (
          <ActivityIndicator color={ACCENT} style={styles.loading} />
        ) : (
          <>
            {active.length === 0 ? (
              <ThemedText style={styles.muted}>Nothing on the wishlist yet. Add your first city above.</ThemedText>
            ) : (
              active.map((item) => (
                <Pressable key={item.id} onPress={() => router.push(`/countries/wishlist/${item.id}`)}>
                  <Surface accentColor={ACCENT} style={styles.itemRow}>
                    <CountryFlag countryName={item.country} hiddenFlagCountries={hiddenFlagCountries} size={24} />
                    <ThemedView style={styles.itemText}>
                      <ThemedText type="defaultSemiBold">{item.city}</ThemedText>
                      <ThemedText style={styles.muted}>{item.country}</ThemedText>
                    </ThemedView>
                    <Pressable onPress={() => handleDelete(item.id)} hitSlop={12}>
                      <IconSymbol name="trash" size={18} color={Colors.light.negative} />
                    </Pressable>
                  </Surface>
                </Pressable>
              ))
            )}

            {sharedItems.length > 0 ? (
              <>
                <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
                  Shared with you
                </ThemedText>
                {sharedItems.map((item) => (
                  <Pressable key={item.id} onPress={() => router.push(`/countries/wishlist/${item.id}`)}>
                    <Surface accentColor={ACCENT} style={styles.itemRow}>
                      <CountryFlag countryName={item.country} hiddenFlagCountries={hiddenFlagCountries} size={24} />
                      <ThemedView style={styles.itemText}>
                        <ThemedText type="defaultSemiBold">{item.city}</ThemedText>
                        <ThemedText style={styles.muted}>
                          {item.country}
                          {item.fulfilled_visit_id ? ' · already planned' : ''}
                        </ThemedText>
                      </ThemedView>
                      <ThemedText numberOfLines={1} style={[styles.sharerLabel, { color: ACCENT }]}>
                        {item.sharerName}
                      </ThemedText>
                    </Surface>
                  </Pressable>
                ))}
              </>
            ) : null}

            {fulfilled.length > 0 ? (
              <>
                <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
                  Already planned
                </ThemedText>
                {fulfilled.map((item) => (
                  <Pressable key={item.id} onPress={() => router.push(`/countries/wishlist/${item.id}`)}>
                    <Surface accentColor={ACCENT} style={[styles.itemRow, styles.fulfilledRow]}>
                      <CountryFlag countryName={item.country} hiddenFlagCountries={hiddenFlagCountries} size={24} />
                      <ThemedView style={styles.itemText}>
                        <ThemedText type="defaultSemiBold">{item.city}</ThemedText>
                        <ThemedText style={styles.muted}>{item.country} · linked to a trip</ThemedText>
                      </ThemedView>
                    </Surface>
                  </Pressable>
                ))}
              </>
            ) : null}
          </>
        )}
      </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 10,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 4,
  },
  titleLinks: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 14,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
  formSurface: {
    gap: 8,
    // Without its own stacking context, this card's z-index:auto means its
    // open dropdown (deep inside, z-index:100 of its OWN local context)
    // only wins against siblings within that same local context — it does
    // nothing against the wishlist item cards below, which come later in
    // the DOM and paint on top of this whole card regardless, since
    // z-index never applies outside the ancestor that establishes it.
    // Confirmed directly: a real screenshot showed a city picked up from
    // the dropdown's own content bleeding through an item card below it.
    position: 'relative',
    zIndex: 10,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 10,
  },
  inputRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  addButton: {
    borderRadius: 10,
    paddingVertical: 12,
    alignItems: 'center',
    marginTop: 4,
  },
  loading: {
    marginTop: 24,
  },
  muted: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  sectionSpacing: {
    marginTop: 16,
  },
  itemRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
  },
  fulfilledRow: {
    opacity: 0.6,
  },
  itemText: {
    flex: 1,
    gap: 2,
  },
  sharerLabel: {
    maxWidth: 90,
    fontSize: 13,
    fontWeight: '600',
  },
});
