import type { CityTripLike } from '@/lib/cityOverlap';
import { toDateOnlyString } from '@/lib/format';

export type TripLike = { country: string; entry_date: string; exit_date: string | null };

export type CalendarViewMode = 'month' | 'week';

// Not deeply validated for colorblind-safe adjacency — that pass happens
// when colors are actually used side by side in the calendar/pie chart,
// where it matters. This is just a v1 identity-swatch picker, shared by the
// "your own calendar color" picker and the per-connection color override.
export const CALENDAR_COLOR_PRESETS = [
  '#2E7D6B',
  '#4A90D9',
  '#D9822B',
  '#B24C9C',
  '#C0392B',
  '#5AA469',
  '#8E6ACF',
  '#D9B23C',
];

function startOfWeekSunday(date: Date): Date {
  const d = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  d.setDate(d.getDate() - d.getDay());
  return d;
}

export function addDays(date: Date, days: number): Date {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

/** Week-row grid for the current view — month mode returns 4-6 rows (padded to full weeks), week mode returns exactly one. */
export function computeWeekRows(currentDate: Date, viewMode: CalendarViewMode): Date[][] {
  if (viewMode === 'week') {
    const start = startOfWeekSunday(currentDate);
    return [Array.from({ length: 7 }, (_, i) => addDays(start, i))];
  }

  const firstOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1);
  const lastOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0);
  const gridStart = startOfWeekSunday(firstOfMonth);
  const gridEndRowStart = startOfWeekSunday(lastOfMonth);

  const rows: Date[][] = [];
  let rowStart = gridStart;
  while (rowStart <= gridEndRowStart) {
    rows.push(Array.from({ length: 7 }, (_, i) => addDays(rowStart, i)));
    rowStart = addDays(rowStart, 7);
  }
  return rows;
}

/** The "real" dates in the current view (no padding from adjacent months) — what the pie chart should count over. */
export function computeRangeDays(currentDate: Date, viewMode: CalendarViewMode): Date[] {
  if (viewMode === 'week') {
    const start = startOfWeekSunday(currentDate);
    return Array.from({ length: 7 }, (_, i) => addDays(start, i));
  }
  const firstOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1);
  const lastOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0);
  const days: Date[] = [];
  for (let d = firstOfMonth; d <= lastOfMonth; d = addDays(d, 1)) {
    days.push(d);
  }
  return days;
}

function countryOnDate(trips: TripLike[], dateStr: string): string | null {
  const trip = trips.find((t) => dateStr >= t.entry_date && (!t.exit_date || dateStr <= t.exit_date));
  return trip ? trip.country : null;
}

export type CalendarLocation = { country: string; city: string | null };

function locationOnDate(trips: CityTripLike[], dateStr: string): CalendarLocation | null {
  const trip = trips.find((t) => dateStr >= t.entry_date && (!t.exit_date || dateStr <= t.exit_date));
  return trip ? { country: trip.country, city: trip.city?.trim() || null } : null;
}

function sameLocation(a: CalendarLocation | null, b: CalendarLocation | null): boolean {
  if (a === null || b === null) return a === b;
  return a.country === b.country && a.city === b.city;
}

export type DayCell = {
  date: string;
  inRange: boolean;
  myLocation: CalendarLocation | null;
  partnerLocation: CalendarLocation | null;
};

/**
 * City-granularity, not just country — two people in the same country but
 * different cities are two DIFFERENT locations here (see computeRowBands,
 * which only blends on an exact city match and otherwise renders them as
 * separate parallel bands, same as it always has for different countries).
 *
 * myHome/partnerHome are a ONE-DIRECTIONAL, per-day fallback: a person's
 * home only ever substitutes for their location on a day where the OTHER
 * side has a real, bounded trip landing on that exact city — never as a
 * blanket fallback for days neither side is traveling. That gating is what
 * keeps this from producing a permanent band: two people who simply live
 * in the same city would otherwise show a same-city blend on every single
 * day forever, which is noise, not signal, on a calendar meant to
 * highlight actual trips. Bounding it to "the other side is actually
 * traveling there" means the band only ever extends an existing trip
 * ("and they're home there too"), naturally sized to that trip's own
 * dates. (The Venn diagram's cityOnDate — see computeVennBuckets — falls
 * back to home unconditionally instead; that's intentional there, since
 * it's summarizing a whole range's overlap total rather than drawing
 * bands, so permanent overlap is real signal, not noise.)
 */
export function computeDayCells(
  days: Date[],
  myTrips: CityTripLike[],
  partnerTrips: CityTripLike[],
  currentDate: Date,
  viewMode: CalendarViewMode,
  myHome?: HomeLocation | null,
  partnerHome?: HomeLocation | null
): DayCell[] {
  return days.map((day) => {
    const dateStr = toDateOnlyString(day);
    const inRange =
      viewMode === 'week'
        ? true
        : day.getMonth() === currentDate.getMonth() && day.getFullYear() === currentDate.getFullYear();

    const myTripLocation = locationOnDate(myTrips, dateStr);
    const partnerTripLocation = locationOnDate(partnerTrips, dateStr);
    const myLocation =
      myTripLocation ?? (myHome && sameLocation(partnerTripLocation, myHome) ? myHome : null);
    const partnerLocation =
      partnerTripLocation ?? (partnerHome && sameLocation(myTripLocation, partnerHome) ? partnerHome : null);

    return { date: dateStr, inRange, myLocation, partnerLocation };
  });
}

/**
 * Combines two RPC results for the same connection — shared_countries_visited
 * and shared_trips_planned both select every row from countries_visited for
 * that connection, gated by two DIFFERENT sharing-permission flags rather
 * than a past/future split (see supabase/022_shared_functions_fixes.sql) —
 * so a connection that's enabled both permissions would otherwise have
 * every trip double-plotted. Dedupes by the full row identity rather than
 * relying on an id, since neither RPC returns one.
 */
export function mergeTripLists(a: TripLike[], b: TripLike[]): TripLike[] {
  const seen = new Map<string, TripLike>();
  for (const trip of [...a, ...b]) {
    const key = `${trip.country}|${trip.entry_date}|${trip.exit_date ?? ''}`;
    if (!seen.has(key)) seen.set(key, trip);
  }
  return Array.from(seen.values());
}

/**
 * N-party generalization of DayCell/computeRowBands below — kept as
 * separate additive functions rather than changing those, since the
 * existing single-connection travel page's 2-color gradient blend is
 * staying exactly as it is (confirmed with the user rather than assumed;
 * blending doesn't generalize past 2 parties without turning to mud, so
 * this uses stacked same-color bands instead — see computeMultiRowBands).
 */
export type MultiParty = { id: string; color: string; trips: TripLike[] };

export type MultiDayCell = { date: string; inRange: boolean; countryByParty: Record<string, string | null> };

export function computeMultiDayCells(
  days: Date[],
  parties: MultiParty[],
  currentDate: Date,
  viewMode: CalendarViewMode
): MultiDayCell[] {
  return days.map((day) => {
    const dateStr = toDateOnlyString(day);
    const inRange =
      viewMode === 'week'
        ? true
        : day.getMonth() === currentDate.getMonth() && day.getFullYear() === currentDate.getFullYear();
    const countryByParty: Record<string, string | null> = {};
    for (const party of parties) {
      countryByParty[party.id] = countryOnDate(party.trips, dateStr);
    }
    return { date: dateStr, inRange, countryByParty };
  });
}

export type MultiBand = { key: string; startIndex: number; endIndex: number; track: number; country: string; color: string };

/**
 * Groups a week row's day-cells into one band per contiguous run where a
 * given party has a non-null country — track is always that party's fixed
 * index in `parties` (not compacted), so the same person renders in the
 * same vertical slot across every row, scannable like a real calendar
 * app's multi-calendar view. Two parties sharing a country the same day
 * just become two adjacent same-height bands in their own colors, not a
 * blend.
 */
export function computeMultiRowBands(cells: MultiDayCell[], parties: MultiParty[]): MultiBand[] {
  const bands: MultiBand[] = [];
  parties.forEach((party, track) => {
    let i = 0;
    while (i < cells.length) {
      const country = cells[i].countryByParty[party.id];
      if (!country) {
        i++;
        continue;
      }
      let j = i;
      while (j + 1 < cells.length && cells[j + 1].countryByParty[party.id] === country) {
        j++;
      }
      bands.push({ key: `${party.id}-${i}`, startIndex: i, endIndex: j, track, country, color: party.color });
      i = j + 1;
    }
  });
  return bands;
}

export type Band = {
  key: string;
  startIndex: number;
  endIndex: number;
  track: 0 | 1;
  label: string;
  colors: string[];
  isBlend: boolean;
};

/**
 * Groups a week row's 7 day-cells into bands: solo (1 color), blended
 * SAME-CITY overlap (2 colors, 1 band), or parallel overlap (2 bands, 2
 * tracks) — used both for two different countries and, deliberately, for
 * the same country but different cities: sharing a country isn't sharing a
 * place, so that case renders as two separate lines rather than implying
 * togetherness a blend would. A band's label prefers city over country
 * (more specific, and what actually distinguishes two same-country bands
 * from each other).
 */
export function computeRowBands(cells: DayCell[], myColor: string, partnerColor: string): Band[] {
  const bands: Band[] = [];
  let i = 0;
  while (i < cells.length) {
    const { myLocation, partnerLocation } = cells[i];
    if (!myLocation && !partnerLocation) {
      i++;
      continue;
    }

    let j = i;
    while (
      j + 1 < cells.length &&
      sameLocation(cells[j + 1].myLocation, myLocation) &&
      sameLocation(cells[j + 1].partnerLocation, partnerLocation)
    ) {
      j++;
    }

    if (
      myLocation &&
      partnerLocation &&
      myLocation.country === partnerLocation.country &&
      myLocation.city &&
      myLocation.city.toLowerCase() === partnerLocation.city?.toLowerCase()
    ) {
      bands.push({
        key: `blend-${i}`,
        startIndex: i,
        endIndex: j,
        track: 0,
        label: myLocation.city,
        colors: [myColor, partnerColor],
        isBlend: true,
      });
    } else {
      if (myLocation) {
        bands.push({
          key: `mine-${i}`,
          startIndex: i,
          endIndex: j,
          track: 0,
          label: myLocation.city ?? myLocation.country,
          colors: [myColor],
          isBlend: false,
        });
      }
      if (partnerLocation) {
        bands.push({
          key: `partner-${i}`,
          startIndex: i,
          endIndex: j,
          track: myLocation ? 1 : 0,
          label: partnerLocation.city ?? partnerLocation.country,
          colors: [partnerColor],
          isBlend: false,
        });
      }
    }

    i = j + 1;
  }
  return bands;
}

export type VennBuckets = { totalDays: number; sameCityDays: number };

export type HomeLocation = { country: string; city: string };

// Falls back to `home` when no logged trip covers the date — same reasoning
// as countryOnDate above, just requiring a full country+city pair since the
// Venn diagram is intentionally city-granularity, not country-granularity.
function cityOnDate(
  trips: CityTripLike[],
  dateStr: string,
  home?: HomeLocation | null
): { country: string; city: string } | null {
  const trip = trips.find((t) => dateStr >= t.entry_date && (!t.exit_date || dateStr <= t.exit_date));
  if (trip?.city?.trim()) return { country: trip.country, city: trip.city.trim() };
  return home ?? null;
}

/**
 * For the Venn diagram view — each circle represents the FULL period
 * (totalDays, the same number for both people: the point of a Venn
 * diagram is comparing how much of "my whole month" vs. "their whole
 * month" overlaps, not just travel days), with the intersection sized to
 * how many of those days were spent in the exact same city — stricter
 * than a same-country match, per the user's own framing that a Venn
 * diagram should show real togetherness, not just "traveling at the same
 * time somewhere in the same country."
 *
 * myHome/partnerHome are each person's home country+city, used as the
 * fallback location for any day with no logged trip — without this, two
 * people simply living in the same home city would never count as
 * "together" since neither side has a countries_visited row for it, and a
 * partner visiting your home city while you're just there normally
 * wouldn't register either.
 */
export function computeVennBuckets(
  days: Date[],
  myTrips: CityTripLike[],
  partnerTrips: CityTripLike[],
  myHome?: HomeLocation | null,
  partnerHome?: HomeLocation | null
): VennBuckets {
  let sameCityDays = 0;

  for (const day of days) {
    const dateStr = toDateOnlyString(day);
    const mine = cityOnDate(myTrips, dateStr, myHome);
    const partner = cityOnDate(partnerTrips, dateStr, partnerHome);
    if (mine && partner && mine.country === partner.country && mine.city.toLowerCase() === partner.city.toLowerCase()) {
      sameCityDays++;
    }
  }

  return { totalDays: days.length, sameCityDays };
}

export type OverlapRange = { start: string; end: string | null; isPast: boolean };
export type CountryOverlap = { country: string; ranges: OverlapRange[] };

// Sorts after any real YYYY-MM-DD date — used only as an internal sortable
// stand-in for "no exit_date yet", never surfaced to callers/UI.
const OPEN_ENDED_SENTINEL = '9999-12-31';

/**
 * Same-country simultaneous travel — pairs of (my trip, their trip) to the
 * identical country whose date ranges overlap. Not restricted to past/
 * current trips: this returns both, tagging each range with `isPast` so
 * callers can split by tense via filterOverlapsByTense — Countries Visited
 * shows only past/current overlaps, Trips Planned shows only future ones,
 * but both read from this one function rather than duplicating detection.
 *
 * An ongoing trip (no exit_date) is treated as open-ended here, not clamped
 * to today — confirmed with the user rather than assumed, since this is a
 * different rule than how ongoing trips are clamped-to-today elsewhere
 * (e.g. summarizeCountries' rolling day tallies). That means an ongoing
 * trip can match a connection's future booking to the same country even
 * before either trip has a real end date; a range whose end is still open
 * is returned as `end: null` ("Present" via formatDateDisplay), same
 * convention used for exit_date elsewhere in this app.
 */
/**
 * Collapses overlapping/adjacent ranges into the fewest spans that cover
 * the same days — the raw per-pair output below is O(my stops × partner
 * stops), so a multi-stop trip (e.g. 5 stops each side to the same
 * country) produces dozens of near-duplicate pairwise ranges instead of
 * the one overall trip span a person actually wants to see. Two ranges
 * merge when one starts on or before the other's end (open-ended ranges
 * always merge with anything starting before OPEN_ENDED_SENTINEL, i.e.
 * everything). isPast is recomputed per merged range rather than merged
 * itself, since a span can start in the past and still be "ongoing."
 */
function mergeOverlapRanges(ranges: OverlapRange[]): OverlapRange[] {
  const today = toDateOnlyString(new Date());
  const sorted = [...ranges].sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0));

  const merged: { start: string; endSortable: string }[] = [];
  for (const range of sorted) {
    const endSortable = range.end ?? OPEN_ENDED_SENTINEL;
    const last = merged[merged.length - 1];
    if (last && range.start <= last.endSortable) {
      if (endSortable > last.endSortable) last.endSortable = endSortable;
    } else {
      merged.push({ start: range.start, endSortable });
    }
  }

  return merged.map((m) => ({
    start: m.start,
    end: m.endSortable === OPEN_ENDED_SENTINEL ? null : m.endSortable,
    isPast: m.start <= today,
  }));
}

export function computeSameCountryOverlaps(myTrips: TripLike[], partnerTrips: TripLike[]): CountryOverlap[] {
  const today = toDateOnlyString(new Date());
  const byCountry = new Map<string, OverlapRange[]>();

  for (const mine of myTrips) {
    for (const partner of partnerTrips) {
      if (mine.country !== partner.country) continue;

      const myEndSortable = mine.exit_date ?? OPEN_ENDED_SENTINEL;
      const partnerEndSortable = partner.exit_date ?? OPEN_ENDED_SENTINEL;
      const overlapStart = mine.entry_date > partner.entry_date ? mine.entry_date : partner.entry_date;
      const overlapEndSortable = myEndSortable < partnerEndSortable ? myEndSortable : partnerEndSortable;
      if (overlapStart > overlapEndSortable) continue;

      const overlapEnd = overlapEndSortable === OPEN_ENDED_SENTINEL ? null : overlapEndSortable;
      const isPast = overlapStart <= today;

      const existing = byCountry.get(mine.country) ?? [];
      existing.push({ start: overlapStart, end: overlapEnd, isPast });
      byCountry.set(mine.country, existing);
    }
  }

  return Array.from(byCountry.entries())
    .map(([country, ranges]) => ({
      country,
      ranges: mergeOverlapRanges(ranges),
    }))
    .sort((a, b) => (a.country < b.country ? -1 : a.country > b.country ? 1 : 0));
}

/** Countries Visited uses 'past' (overlap has started); Trips Planned uses 'future' (hasn't started yet). Drops any country left with zero ranges after filtering. */
export function filterOverlapsByTense(overlaps: CountryOverlap[], tense: 'past' | 'future'): CountryOverlap[] {
  return overlaps
    .map((overlap) => ({
      country: overlap.country,
      ranges: overlap.ranges.filter((r) => (tense === 'past' ? r.isPast : !r.isPast)),
    }))
    .filter((overlap) => overlap.ranges.length > 0);
}

/** Every calendar day in the year containing `date` — for the pie chart's year granularity. */
export function computeYearRangeDays(date: Date): Date[] {
  const start = new Date(date.getFullYear(), 0, 1);
  const end = new Date(date.getFullYear(), 11, 31);
  const days: Date[] = [];
  for (let d = start; d <= end; d = addDays(d, 1)) {
    days.push(d);
  }
  return days;
}
