import type { ConvertedAmount } from '@/contexts/currency-context';
import type { CountryVisitedRow, TransactionRow, TripSegmentRow } from '@/types/database';

export type MoneyTotal = { currency: string; amount: number };

export type TripBudgetLeg =
  | {
      kind: 'stop';
      date: string;
      label: string;
      stop: CountryVisitedRow;
      expenses: TransactionRow[];
      totals: MoneyTotal[];
      plannedTotal: MoneyTotal | null;
    }
  | {
      kind: 'segment';
      date: string;
      label: string;
      segment: TripSegmentRow;
      expenses: TransactionRow[];
      totals: MoneyTotal[];
      plannedTotal: MoneyTotal | null;
    };

export type TripBudgetCategory = { label: string; totals: MoneyTotal[]; count: number };

export type TripBudget = {
  legs: TripBudgetLeg[];
  categories: TripBudgetCategory[];
  grandTotal: MoneyTotal[];
  /** Sum of every stop's/leg's own cost/cost_currency (supabase/053_trip_costs.sql) — a budgeted figure, independent of grandTotal's linked-transaction actuals. */
  plannedGrandTotal: MoneyTotal[];
};

const MODE_CATEGORY_LABELS: Record<TripSegmentRow['mode'], string> = {
  flight: 'Flights',
  train: 'Trains',
  car: 'Car',
  bus: 'Bus',
  ferry: 'Ferry',
  other: 'Travel',
};

function sumTotals(
  transactions: TransactionRow[],
  convert: (amount: number, currency: string) => ConvertedAmount
): MoneyTotal[] {
  const byCurrency = new Map<string, number>();
  for (const tx of transactions) {
    const { amount, currency } = convert(tx.amount, tx.currency);
    byCurrency.set(currency, (byCurrency.get(currency) ?? 0) + Math.abs(amount));
  }
  return Array.from(byCurrency.entries()).map(([currency, amount]) => ({ currency, amount }));
}

function plannedCostOf(
  row: Pick<CountryVisitedRow | TripSegmentRow, 'cost' | 'cost_currency'>,
  convert: (amount: number, currency: string) => ConvertedAmount
): MoneyTotal | null {
  if (row.cost == null || !row.cost_currency) return null;
  const converted = convert(row.cost, row.cost_currency);
  return { currency: converted.currency, amount: converted.amount };
}

function sumMoneyTotals(totals: (MoneyTotal | null)[]): MoneyTotal[] {
  const byCurrency = new Map<string, number>();
  for (const total of totals) {
    if (!total) continue;
    byCurrency.set(total.currency, (byCurrency.get(total.currency) ?? 0) + total.amount);
  }
  return Array.from(byCurrency.entries()).map(([currency, amount]) => ({ currency, amount }));
}

/**
 * The cost side of a trip's itinerary — one leg per stop/travel segment
 * (same chronological order as lib/trips.ts's computeTripTimeline), each
 * carrying whatever transactions have been linked to it via
 * trip_stop_id/trip_segment_id, plus a Hotels/Flights/Trains-style category
 * breakdown and a grand total. Entirely derived from linked transactions,
 * nothing stored — same "computed, not stored" spirit as lib/spend.ts.
 */
export function computeTripBudget(
  stops: CountryVisitedRow[],
  segments: TripSegmentRow[],
  linkedExpenses: TransactionRow[],
  convert: (amount: number, currency: string) => ConvertedAmount
): TripBudget {
  const expensesByStop = new Map<string, TransactionRow[]>();
  const expensesBySegment = new Map<string, TransactionRow[]>();
  for (const tx of linkedExpenses) {
    if (tx.trip_stop_id) {
      const list = expensesByStop.get(tx.trip_stop_id) ?? [];
      list.push(tx);
      expensesByStop.set(tx.trip_stop_id, list);
    } else if (tx.trip_segment_id) {
      const list = expensesBySegment.get(tx.trip_segment_id) ?? [];
      list.push(tx);
      expensesBySegment.set(tx.trip_segment_id, list);
    }
  }

  const stopLegs: TripBudgetLeg[] = [...stops]
    .sort((a, b) => (a.entry_date < b.entry_date ? -1 : a.entry_date > b.entry_date ? 1 : 0))
    .map((stop) => {
      const expenses = expensesByStop.get(stop.id) ?? [];
      return {
        kind: 'stop' as const,
        date: stop.entry_date,
        label: stop.city?.trim() || stop.country,
        stop,
        expenses,
        totals: sumTotals(expenses, convert),
        plannedTotal: plannedCostOf(stop, convert),
      };
    });

  const segmentLegs: TripBudgetLeg[] = [...segments]
    .sort((a, b) => (a.depart_date < b.depart_date ? -1 : a.depart_date > b.depart_date ? 1 : 0))
    .map((segment) => {
      const expenses = expensesBySegment.get(segment.id) ?? [];
      return {
        kind: 'segment' as const,
        date: segment.depart_date,
        label: `${segment.from_label} → ${segment.to_label}`,
        segment,
        expenses,
        totals: sumTotals(expenses, convert),
        plannedTotal: plannedCostOf(segment, convert),
      };
    });

  const legs = [...stopLegs, ...segmentLegs].sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));

  const categoryExpenses = new Map<string, TransactionRow[]>();
  const allStopExpenses = Array.from(expensesByStop.values()).flat();
  if (allStopExpenses.length > 0) categoryExpenses.set('Hotels', allStopExpenses);
  for (const segment of segments) {
    const expenses = expensesBySegment.get(segment.id) ?? [];
    if (expenses.length === 0) continue;
    const label = MODE_CATEGORY_LABELS[segment.mode];
    categoryExpenses.set(label, [...(categoryExpenses.get(label) ?? []), ...expenses]);
  }
  const categories: TripBudgetCategory[] = Array.from(categoryExpenses.entries()).map(([label, expenses]) => ({
    label,
    totals: sumTotals(expenses, convert),
    count: expenses.length,
  }));

  const grandTotal = sumTotals(linkedExpenses, convert);
  const plannedGrandTotal = sumMoneyTotals(legs.map((leg) => leg.plannedTotal));

  return { legs, categories, grandTotal, plannedGrandTotal };
}
