import { computeCurrentBalance } from '@/lib/wealthSeries';
import type { AccountRow, BalanceSnapshotRow, TransactionRow } from '@/types/database';

type ConvertFn = (amount: number, fromCurrency: string) => number;

export type TileValue = {
  current: number;
  /** null whenever "prior" is zero — no meaningful percent to show, per the home screen's "nothing → 0, no change" rule. */
  changePct: number | null;
};

function toDateOnlyString(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/** Last calendar day of the month before `today` — the MTD tiles' comparison point. */
export function endOfPriorMonth(today: Date): Date {
  return new Date(today.getFullYear(), today.getMonth(), 0);
}

function changePct(current: number, prior: number): number | null {
  if (prior === 0) return null;
  return ((current - prior) / Math.abs(prior)) * 100;
}

/**
 * Balance for a filtered subset of accounts (e.g. just cash, just
 * investments, just non-card liabilities) as of today vs. the end of the
 * prior month — the home screen's MTD tiles.
 *
 * Filters transactions/balanceSnapshots down to the matching account ids
 * first: computeCurrentBalance treats any account id it doesn't recognize as
 * a plain asset (sign +1), so handing it the full unfiltered ledger
 * alongside a filtered accounts list would silently pull in unrelated
 * accounts' activity.
 *
 * `negate` flips the sign — liability accounts net into computeCurrentBalance
 * as negative (they subtract from net worth), but a liability tile should
 * read as a positive "amount owed."
 */
export function computeCategoryTile(
  accounts: AccountRow[],
  transactions: Pick<TransactionRow, 'date' | 'amount' | 'currency' | 'account_id'>[],
  balanceSnapshots: Pick<BalanceSnapshotRow, 'account_id' | 'date' | 'balance'>[],
  matches: (account: AccountRow) => boolean,
  convert: ConvertFn,
  today: Date,
  { negate = false }: { negate?: boolean } = {}
): TileValue {
  const filteredAccounts = accounts.filter(matches);
  const ids = new Set(filteredAccounts.map((a) => a.id));
  const filteredTransactions = transactions.filter((t) => t.account_id && ids.has(t.account_id));
  const filteredSnapshots = balanceSnapshots.filter((s) => ids.has(s.account_id));

  function balanceAsOf(asOf: Date): number {
    const raw = computeCurrentBalance({
      transactions: filteredTransactions,
      accounts: filteredAccounts,
      balanceSnapshots: filteredSnapshots,
      convert,
      asOf,
    });
    return negate ? -raw : raw;
  }

  const current = balanceAsOf(today);
  const prior = balanceAsOf(endOfPriorMonth(today));
  return { current, changePct: changePct(current, prior) };
}

/** Month-end dates for the `count` months before `today`, oldest first — the sparkline tiles' trend points. Exported so callers (the Home tile's expanded-graph X-axis) can label each point with the same dates this file's own history builders used to compute it. */
export function priorMonthEnds(today: Date, count: number): Date[] {
  const ends: Date[] = [];
  for (let i = count; i >= 1; i--) {
    ends.push(new Date(today.getFullYear(), today.getMonth() - i + 1, 0));
  }
  return ends;
}

/** Same filtering/scoping as computeCategoryTile, but returns a short trailing series (5 month-ends plus today) instead of a single current/prior pair — feeds the Home tiles' tap-to-expand sparkline. */
export function computeCategoryTileHistory(
  accounts: AccountRow[],
  transactions: Pick<TransactionRow, 'date' | 'amount' | 'currency' | 'account_id'>[],
  balanceSnapshots: Pick<BalanceSnapshotRow, 'account_id' | 'date' | 'balance'>[],
  matches: (account: AccountRow) => boolean,
  convert: ConvertFn,
  today: Date,
  { negate = false }: { negate?: boolean } = {}
): number[] {
  const filteredAccounts = accounts.filter(matches);
  const ids = new Set(filteredAccounts.map((a) => a.id));
  const filteredTransactions = transactions.filter((t) => t.account_id && ids.has(t.account_id));
  const filteredSnapshots = balanceSnapshots.filter((s) => ids.has(s.account_id));

  function balanceAsOf(asOf: Date): number {
    const raw = computeCurrentBalance({
      transactions: filteredTransactions,
      accounts: filteredAccounts,
      balanceSnapshots: filteredSnapshots,
      convert,
      asOf,
    });
    return negate ? -raw : raw;
  }

  return [...priorMonthEnds(today, 5).map(balanceAsOf), balanceAsOf(today)];
}

/**
 * Outstanding credit card balance as of today vs. the end of the prior
 * month — derived from card-linked transactions (transactions.card_id, no
 * account_id), since credit_cards has no balance/liability tracking of its
 * own. Spend is a negative amount (same income/spend sign convention as
 * lib/wealthSeries.ts), so -sum(amount) is the positive magnitude owed.
 */
export function computeCardOutstandingTile(
  transactions: Pick<TransactionRow, 'date' | 'amount' | 'currency' | 'card_id'>[],
  convert: ConvertFn,
  today: Date
): TileValue {
  function outstandingAsOf(asOf: Date): number {
    const cutoff = toDateOnlyString(asOf);
    let total = 0;
    for (const tx of transactions) {
      if (!tx.card_id || tx.date > cutoff) continue;
      total += -convert(tx.amount, tx.currency);
    }
    return total;
  }

  const current = outstandingAsOf(today);
  const prior = outstandingAsOf(endOfPriorMonth(today));
  return { current, changePct: changePct(current, prior) };
}

/** Same scoping as computeCardOutstandingTile, but a 5-month-end-plus-today series for the sparkline. */
export function computeCardOutstandingHistory(
  transactions: Pick<TransactionRow, 'date' | 'amount' | 'currency' | 'card_id'>[],
  convert: ConvertFn,
  today: Date
): number[] {
  function outstandingAsOf(asOf: Date): number {
    const cutoff = toDateOnlyString(asOf);
    let total = 0;
    for (const tx of transactions) {
      if (!tx.card_id || tx.date > cutoff) continue;
      total += -convert(tx.amount, tx.currency);
    }
    return total;
  }

  return [...priorMonthEnds(today, 5).map(outstandingAsOf), outstandingAsOf(today)];
}
