import { useFocusEffect } from '@react-navigation/native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, RefreshControl, ScrollView, StyleSheet } from 'react-native';

import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { ScopeSwitch } from '@/components/scope-switch';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { TransactionRow as TransactionRowItem } from '@/components/transaction-row';
import { TransactionSortControl } from '@/components/transaction-sort-control';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { useScope } from '@/contexts/scope-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { fetchAllRows } from '@/lib/fetchAll';
import { formatDateDisplay } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import { sortTransactions, type TransactionSortDirection, type TransactionSortField } from '@/lib/transactionSort';
import type { AccountRow, CategoryRow, CategoryRuleRow, CountryVisitedRow, CreditCardRow, TransactionRow } from '@/types/database';

const ACCENT = ModuleAccents.spend;

export default function SpendCategoryDetailScreen() {
  const { categoryId, start, end } = useLocalSearchParams<{ categoryId: string; start?: string; end?: string }>();
  const router = useRouter();
  const { convert, homeCountry } = useCurrency();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const { filterTransactions, filterAccounts, filterCards } = useScope();
  const [allTransactions, setTransactions] = useState<TransactionRow[]>([]);
  const [categories, setCategories] = useState<CategoryRow[]>([]);
  const [categoryRules, setCategoryRules] = useState<CategoryRuleRow[]>([]);
  const [visits, setVisits] = useState<CountryVisitedRow[]>([]);
  const [allAccounts, setAccounts] = useState<AccountRow[]>([]);
  const [allCards, setCards] = useState<CreditCardRow[]>([]);
  const transactions = filterTransactions(allTransactions);
  const accounts = filterAccounts(allAccounts);
  const cards = filterCards(allCards);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<TransactionSortField>('date');
  const [sortDirection, setSortDirection] = useState<TransactionSortDirection>('desc');

  const load = useCallback(async () => {
    setError(null);
    const [txResult, categoriesResult, categoryRulesResult, visitsResult, accountsResult, cardsResult] =
      await Promise.all([
        fetchAllRows<TransactionRow>((from, to) =>
          supabase.from('transactions').select('*').order('date', { ascending: false }).order('id').range(from, to)
        ),
        supabase.from('categories').select('*'),
        supabase.from('category_rules').select('*'),
        supabase.from('countries_visited').select('*'),
        supabase.from('accounts').select('*'),
        supabase.from('credit_cards').select('*'),
      ]);

    if (txResult.error) {
      setError(txResult.error.message);
      setIsLoading(false);
      return;
    }

    setTransactions(txResult.data);
    setCategories(categoriesResult.data ?? []);
    setCategoryRules(categoryRulesResult.data ?? []);
    setVisits(visitsResult.data ?? []);
    setAccounts(accountsResult.data ?? []);
    setCards(cardsResult.data ?? []);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  const targetCategoryId = categoryId === 'uncategorized' ? null : categoryId;
  const categoryName = targetCategoryId
    ? (categories.find((c) => c.id === targetCategoryId)?.name ?? 'Category')
    : 'Uncategorized';

  const filteredUnsorted = transactions.filter((tx) => {
    if (tx.is_internal_transfer || tx.amount >= 0) return false;
    if (tx.category_id !== targetCategoryId) return false;
    if (start && tx.date < start) return false;
    if (end && tx.date > end) return false;
    return true;
  });
  const filtered = sortTransactions(filteredUnsorted, sortField, sortDirection);

  const accountNameById = new Map(accounts.map((a) => [a.id, a.name]));
  const cardNameById = new Map(cards.map((c) => [c.id, `${c.issuer} · ${c.name}`]));
  const excludedAccountIds = new Set(accounts.filter((a) => a.excluded_from_country_tracking).map((a) => a.id));

  function sourceLabel(tx: TransactionRow): string {
    if (tx.account_id) return accountNameById.get(tx.account_id) ?? 'Account';
    if (tx.card_id) return cardNameById.get(tx.card_id) ?? 'Card';
    return 'Unknown source';
  }

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView
        contentContainerStyle={styles.content}
        refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
        <ScopeSwitch accent={ACCENT} />
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            {categoryName}
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}
        {start && end ? (
          <ThemedText style={styles.muted}>
            {formatDateDisplay(start)} &rarr; {formatDateDisplay(end)}
          </ThemedText>
        ) : null}

        <ThemedView style={styles.sectionHeaderRow}>
          <ThemedText type="subtitle" style={{ color: ACCENT }}>
            Transactions
          </ThemedText>
          <TransactionSortControl
            sortField={sortField}
            sortDirection={sortDirection}
            onChange={(field, direction) => {
              setSortField(field);
              setSortDirection(direction);
            }}
            accentColor={ACCENT}
          />
        </ThemedView>
        {filtered.length === 0 ? <ThemedText style={styles.muted}>No transactions here.</ThemedText> : null}
        {filtered.map((tx) => (
          <TransactionRowItem
            key={tx.id}
            transaction={tx}
            accentColor={ACCENT}
            convert={convert}
            categories={categories}
            categoryRules={categoryRules}
            visits={visits}
            homeCountry={homeCountry}
            excludedAccountIds={excludedAccountIds}
            subtitle={sourceLabel(tx)}
            onChange={(updated) => setTransactions((prev) => prev.map((t) => (t.id === updated.id ? updated : t)))}
            onCategoryCreated={(category) => setCategories((prev) => [...prev, category])}
          />
        ))}
      </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  centered: { alignItems: 'center', justifyContent: 'center' },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  rowBetween: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  sectionHeaderRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    flexWrap: 'wrap',
    gap: 8,
    marginBottom: 4,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
});
