import { useState } from 'react';
import { Pressable, View } from 'react-native';
import Svg, { Circle, Path, Rect } from 'react-native-svg';

import { ThemedText } from '@/components/themed-text';
import { Colors, ModuleAccentPastel } from '@/constants/theme';
import type { MapMarker } from '@/lib/mapMarker';
import { projectLatLon, WORLD_MAP_LOCATIONS, WORLD_MAP_VIEW_BOX } from '@/lib/worldMapData';

const OCEAN_COLOR = ModuleAccentPastel.countries;
const LAND_COLOR = ModuleAccentPastel.wealth;

// viewBox is "minX minY width height" — the map's true proportions. The
// container's height is DERIVED from its measured width using this ratio
// (styles below / aspectRatio), not a fixed pixel height independent of
// container width — a mismatch there is what made the map look
// stretched/squashed on a wide desktop window.
const [, , VIEW_BOX_WIDTH, VIEW_BOX_HEIGHT] = WORLD_MAP_VIEW_BOX.split(' ').map(Number);
const MAP_ASPECT_RATIO = VIEW_BOX_WIDTH / VIEW_BOX_HEIGHT;

/**
 * Web's map — react-native-maps has no web support at all (confirmed, not
 * assumed), so this stands in specifically for the web build. iOS/Android
 * use the real react-native-maps-backed component in connections-map.tsx
 * instead; Metro's platform extension resolution picks whichever of the
 * two matches the build target, so callers just import from
 * './connections-map' and never see the split.
 *
 * Real country shapes (same Natural Earth-derived data as the passport
 * map, see lib/worldMapData.ts) rather than the hand-drawn continent silhouettes
 * this used to be — those read as a rough blob at a glance; this reads as
 * an actual map. Markers are placed by projecting each marker's own
 * lat/lon onto the map (see lib/worldMapData.ts's projectLatLon) — an
 * earlier version placed every marker at its whole COUNTRY's shape
 * centroid instead, which is how "New York" and "London" ended up pinned
 * in Kansas and the English Midlands respectively, nowhere near the city
 * the label actually named.
 */
export function ConnectionsMap({ markers, accentColor, onSelectMarker }: { markers: MapMarker[]; accentColor: string; onSelectMarker: (id: string) => void }) {
  const [width, setWidth] = useState(0);
  const height = width / MAP_ASPECT_RATIO;
  // Container's aspect ratio now matches the viewBox exactly (see the
  // style below), so a single uniform scale is enough — no letterbox
  // offset needed, since the map fills the container edge to edge without
  // distortion by construction.
  const scale = width / VIEW_BOX_WIDTH;

  function toScreen(point: { x: number; y: number }): { left: number; top: number } {
    return { left: point.x * scale, top: point.y * scale };
  }

  const placedMarkers = markers.map((m) => ({ marker: m, centroid: projectLatLon(m.lat, m.lon) }));

  return (
    <View
      onLayout={(e) => setWidth(e.nativeEvent.layout.width)}
      style={{ aspectRatio: MAP_ASPECT_RATIO, borderRadius: 12, overflow: 'hidden' }}>
      {width > 0 ? (
        <Svg width={width} height={height} viewBox={WORLD_MAP_VIEW_BOX}>
          <Rect x={0} y={0} width={VIEW_BOX_WIDTH} height={VIEW_BOX_HEIGHT} fill={OCEAN_COLOR} />
          {WORLD_MAP_LOCATIONS.map((location) => (
            <Path key={location.id} d={location.path} fill={LAND_COLOR} stroke={Colors.light.icon} strokeOpacity={0.4} strokeWidth={0.5} />
          ))}
          {placedMarkers.map(({ marker, centroid }) => (
            <Circle key={marker.id} cx={centroid.x} cy={centroid.y} r={5} fill={accentColor} stroke={Colors.light.backgroundSolid} strokeWidth={1} />
          ))}
        </Svg>
      ) : null}
      {width > 0
        ? placedMarkers.map(({ marker, centroid }) => {
            const { left, top } = toScreen(centroid);
            return (
              <Pressable
                key={marker.id}
                onPress={() => onSelectMarker(marker.id)}
                hitSlop={10}
                style={{ position: 'absolute', left: left - 45, top: top - 32, width: 90, alignItems: 'center' }}>
                <ThemedText numberOfLines={1} style={{ fontSize: 11, maxWidth: 90, textAlign: 'center' }}>
                  {marker.label}
                </ThemedText>
              </Pressable>
            );
          })
        : null}
    </View>
  );
}
