import { useFocusEffect } from '@react-navigation/native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, TextInput } from 'react-native';

import { CountryFlag } from '@/components/country-flag';
import { SharedModuleNav } from '@/components/shared-module-nav';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { useConnectionDisplay } from '@/hooks/use-connection-display';
import { useCurrency } from '@/contexts/currency-context';
import { formatDateTimeDisplay } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import type { WishlistNoteRow } from '@/types/database';

const ACCENT = ModuleAccents.countries;

type SharedWishlistItem = { id: string; user_id: string; country: string; city: string; fulfilled_visit_id: string | null; created_at: string };

export default function SharedWishlistScreen() {
  const { connectionId } = useLocalSearchParams<{ connectionId: string }>();
  const router = useRouter();
  const { session } = useAuth();
  const { hiddenFlagCountries } = useCurrency();
  const display = useConnectionDisplay(connectionId);

  const [items, setItems] = useState<SharedWishlistItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [notesByItem, setNotesByItem] = useState<Map<string, WishlistNoteRow[]>>(new Map());
  const [draft, setDraft] = useState('');
  const [isSaving, setIsSaving] = useState(false);

  const load = useCallback(async () => {
    setError(null);
    const { data, error: fetchError } = await supabase.rpc('shared_wishlist_cities', { p_connection_id: connectionId });
    if (fetchError) setError(fetchError.message);
    setItems(data ?? []);
    setIsLoading(false);
  }, [connectionId]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  async function toggleExpand(itemId: string) {
    if (expandedId === itemId) {
      setExpandedId(null);
      return;
    }
    setExpandedId(itemId);
    setDraft('');
    if (!notesByItem.has(itemId)) {
      const { data } = await supabase
        .from('wishlist_notes')
        .select('*')
        .eq('wishlist_id', itemId)
        .order('created_at', { ascending: true });
      setNotesByItem((prev) => new Map(prev).set(itemId, data ?? []));
    }
  }

  async function handlePostNote(itemId: string) {
    if (!session || !draft.trim()) return;
    setIsSaving(true);
    const { error: insertError } = await supabase.from('wishlist_notes').insert({
      wishlist_id: itemId,
      author_id: session.user.id,
      note: draft.trim(),
    });
    setIsSaving(false);
    if (insertError) {
      setError(insertError.message);
      return;
    }
    setDraft('');
    const { data } = await supabase
      .from('wishlist_notes')
      .select('*')
      .eq('wishlist_id', itemId)
      .order('created_at', { ascending: true });
    setNotesByItem((prev) => new Map(prev).set(itemId, data ?? []));
  }

  async function handleDeleteNote(itemId: string, noteId: string) {
    const { error: deleteError } = await supabase.from('wishlist_notes').delete().eq('id', noteId);
    if (deleteError) {
      setError(deleteError.message);
      return;
    }
    setNotesByItem((prev) => {
      const next = new Map(prev);
      next.set(itemId, (next.get(itemId) ?? []).filter((n) => n.id !== noteId));
      return next;
    });
  }

  return (
    <ThemedView variant="screen" style={styles.flex} keyboardAvoiding={false}>
      <ThemedView style={styles.titleRow}>
        <ThemedText type="title" style={{ color: ACCENT }}>
          {display.displayName}&apos;s wishlist
        </ThemedText>
        <Pressable onPress={() => router.back()} hitSlop={12}>
          <ThemedText type="link">Done</ThemedText>
        </Pressable>
      </ThemedView>
      <SharedModuleNav connectionId={connectionId} accentColor={ACCENT} active="wishlist" />
      <ThemedText style={styles.hint}>
        Cities {display.displayName} wants to go to. Add notes or ideas &mdash; they&apos;ll see them too.
      </ThemedText>
      {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

      {isLoading ? (
        <ActivityIndicator color={ACCENT} style={styles.loading} />
      ) : (
        <ScrollView contentContainerStyle={styles.content}>
          {items.length === 0 ? <ThemedText style={styles.muted}>Nothing on their wishlist yet.</ThemedText> : null}
          {items.map((item) => {
            const isExpanded = expandedId === item.id;
            const notes = notesByItem.get(item.id) ?? [];
            return (
              <Surface key={item.id} accentColor={ACCENT} style={styles.itemCard}>
                <Pressable onPress={() => toggleExpand(item.id)} style={styles.itemRow}>
                  <CountryFlag countryName={item.country} hiddenFlagCountries={hiddenFlagCountries} size={24} />
                  <ThemedView style={styles.itemText}>
                    <ThemedText type="defaultSemiBold">{item.city}</ThemedText>
                    <ThemedText style={styles.muted}>
                      {item.country}
                      {item.fulfilled_visit_id ? ' · already planned' : ''}
                    </ThemedText>
                  </ThemedView>
                  <IconSymbol name={isExpanded ? 'chevron.left' : 'chevron.right'} size={16} color={Colors.light.textMuted} />
                </Pressable>

                {isExpanded ? (
                  <ThemedView style={styles.notesSection}>
                    {notes.length === 0 ? <ThemedText style={styles.muted}>No notes yet.</ThemedText> : null}
                    {notes.map((n) => {
                      const isMine = n.author_id === session?.user.id;
                      return (
                        <ThemedView key={n.id} style={styles.noteRow}>
                          <ThemedView style={styles.noteHeader}>
                            <ThemedView style={styles.noteMeta}>
                              <ThemedText style={styles.noteAuthor}>{isMine ? 'You' : display.displayName}</ThemedText>
                              <ThemedText style={styles.noteTimestamp}>{formatDateTimeDisplay(n.updated_at)}</ThemedText>
                            </ThemedView>
                            {isMine ? (
                              <Pressable onPress={() => handleDeleteNote(item.id, n.id)} hitSlop={12}>
                                <IconSymbol name="trash" size={13} color={Colors.light.negative} />
                              </Pressable>
                            ) : null}
                          </ThemedView>
                          <ThemedText>{n.note}</ThemedText>
                        </ThemedView>
                      );
                    })}
                    <ThemedView style={styles.composerRow}>
                      <TextInput
                        value={draft}
                        onChangeText={setDraft}
                        placeholder="Add a note or idea..."
                        placeholderTextColor={Colors.light.textMuted}
                        style={[styles.input, { borderColor: ACCENT }]}
                        multiline
                      />
                      <Pressable
                        onPress={() => handlePostNote(item.id)}
                        disabled={isSaving || !draft.trim()}
                        style={[styles.sendButton, { backgroundColor: ACCENT, opacity: isSaving || !draft.trim() ? 0.5 : 1 }]}>
                        <IconSymbol name="paperplane.fill" size={16} color={Colors.light.backgroundSolid} />
                      </Pressable>
                    </ThemedView>
                  </ThemedView>
                ) : null}
              </Surface>
            );
          })}
        </ScrollView>
      )}
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: 16,
    paddingBottom: 0,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    paddingHorizontal: 16,
  },
  error: {
    color: Colors.light.negative,
    paddingHorizontal: 16,
  },
  loading: {
    marginTop: 32,
  },
  content: {
    padding: 16,
    gap: 10,
    paddingBottom: 48,
  },
  muted: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  itemCard: {
    gap: 0,
  },
  itemRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
  },
  itemText: {
    flex: 1,
    gap: 2,
  },
  notesSection: {
    marginTop: 12,
    gap: 8,
  },
  noteRow: {
    gap: 2,
  },
  noteHeader: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  noteMeta: {
    flexDirection: 'row',
    alignItems: 'baseline',
    gap: 6,
  },
  noteAuthor: {
    fontSize: 12,
    fontWeight: '600',
    opacity: 0.7,
  },
  noteTimestamp: {
    fontSize: 11,
    opacity: 0.55,
    color: Colors.light.textMuted,
  },
  composerRow: {
    flexDirection: 'row',
    alignItems: 'flex-end',
    gap: 8,
    marginTop: 4,
  },
  input: {
    flex: 1,
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 12,
    paddingVertical: 8,
    maxHeight: 100,
  },
  sendButton: {
    width: 38,
    height: 38,
    borderRadius: 19,
    alignItems: 'center',
    justifyContent: 'center',
  },
});
