import type { AccountRow, BalanceSnapshotRow, CreditCardRow, TransactionRow } from '@/types/database';

export type Ownership = 'personal' | 'business';
export type FinanceScope = 'all' | Ownership;

export const SCOPE_OPTIONS: { value: FinanceScope; label: string }[] = [
  { value: 'all', label: 'All' },
  { value: 'personal', label: 'Personal' },
  { value: 'business', label: 'Business' },
];

export const OWNERSHIP_OPTIONS: { value: Ownership; label: string }[] = [
  { value: 'personal', label: 'Personal' },
  { value: 'business', label: 'Business' },
];

export function ownershipInScope(ownership: Ownership, scope: FinanceScope): boolean {
  return scope === 'all' || ownership === scope;
}

export function filterAccountsByScope<T extends Pick<AccountRow, 'ownership'>>(accounts: T[], scope: FinanceScope): T[] {
  return scope === 'all' ? accounts : accounts.filter((a) => a.ownership === scope);
}

export function filterCardsByScope<T extends Pick<CreditCardRow, 'ownership'>>(cards: T[], scope: FinanceScope): T[] {
  return scope === 'all' ? cards : cards.filter((c) => c.ownership === scope);
}

/**
 * A transaction is in scope when the account or card it came from is. The
 * id→ownership maps come from ScopeProvider (which loads every account and
 * card id once), so a screen that only fetched transactions — Home,
 * Subscriptions — doesn't need to fetch cards just to filter. A
 * transaction attached to neither (shouldn't exist, but be safe) shows
 * only in the unfiltered "All" view.
 */
export function filterTransactionsByScope<T extends Pick<TransactionRow, 'account_id' | 'card_id'>>(
  transactions: T[],
  scope: FinanceScope,
  accountOwnership: ReadonlyMap<string, Ownership>,
  cardOwnership: ReadonlyMap<string, Ownership>
): T[] {
  if (scope === 'all') return transactions;
  return transactions.filter((tx) => {
    const ownership = tx.account_id
      ? accountOwnership.get(tx.account_id)
      : tx.card_id
        ? cardOwnership.get(tx.card_id)
        : undefined;
    return ownership === scope;
  });
}

export function filterSnapshotsByScope<T extends Pick<BalanceSnapshotRow, 'account_id'>>(
  snapshots: T[],
  scope: FinanceScope,
  accountOwnership: ReadonlyMap<string, Ownership>
): T[] {
  if (scope === 'all') return snapshots;
  return snapshots.filter((s) => accountOwnership.get(s.account_id) === scope);
}

/** Anything keyed only by account_id (e.g. a `select('account_id, amount')` ledger slice) — no card_id to fall back to. */
export function filterAccountLinkedByScope<T extends { account_id: string | null }>(
  rows: T[],
  scope: FinanceScope,
  accountOwnership: ReadonlyMap<string, Ownership>
): T[] {
  if (scope === 'all') return rows;
  return rows.filter((r) => !!r.account_id && accountOwnership.get(r.account_id) === scope);
}

/** For report headers and the like — null when nothing is filtered. */
export function scopeLabel(scope: FinanceScope): string | null {
  return scope === 'all' ? null : scope === 'personal' ? 'Personal only' : 'Business only';
}
