import type { AlertButton } from './alert-types';

/**
 * Web counterpart to alert.ts. window.confirm/alert don't support custom
 * button labels or more than two options, but every current call site in
 * this app is either a plain info message or a Cancel + one action confirm,
 * so that's all this needs to handle.
 */
export function showAlert(title: string, message?: string, buttons?: AlertButton[]): void {
  const text = message ? `${title}\n\n${message}` : title;

  if (!buttons || buttons.length <= 1) {
    window.alert(text);
    buttons?.[0]?.onPress?.();
    return;
  }

  if (window.confirm(text)) {
    const actionButton = buttons.find((b) => b.style !== 'cancel');
    actionButton?.onPress?.();
  } else {
    const cancelButton = buttons.find((b) => b.style === 'cancel');
    cancelButton?.onPress?.();
  }
}
