import { latestSnapshotByAccount, transactionSumByAccount } from '@/lib/accountBalance';
import type { AccountRow, BalanceSnapshotRow, CreditCardRow } from '@/types/database';

export type FundMovementAlert = {
  card: CreditCardRow;
  paymentAccount: AccountRow;
  /** Fee amount, in the payment account's own currency. */
  feeInAccountCurrency: number;
  /** Payment account's current balance, in its own currency. */
  accountBalance: number;
  /** Best alternate account to draw from, if any with sufficient balance exists. */
  suggestedAccount: (AccountRow & { balance: number }) | null;
};

/**
 * Checks whether each card's linked payment_account_id can cover that
 * card's annual fee — the only recurring fee actually modeled (credit_cards
 * has no separate "monthly fee" field), so "monthly or annual fee" is
 * interpreted as annual_fee specifically. If the linked account is short,
 * looks for a better-funded alternative among the user's other active
 * asset accounts, preferring an exact currency match (zero conversion
 * loss) and otherwise whichever account needs the SMALLEST amount of its
 * own currency to cover the fee (the "best FX rate" reading — least costly
 * conversion, not a shortest-path currency-arbitrage optimizer).
 */
export function computeFundMovementAlerts(
  cards: CreditCardRow[],
  accounts: AccountRow[],
  accountTransactions: { account_id: string | null; amount: number }[],
  balanceSnapshots: BalanceSnapshotRow[],
  convertToCurrency: (amount: number, fromCurrency: string, toCurrency: string) => number
): FundMovementAlert[] {
  const latestSnapshots = latestSnapshotByAccount(balanceSnapshots);
  const transactionSums = transactionSumByAccount(accountTransactions);

  const balanceByAccountId = new Map<string, number>();
  for (const account of accounts) {
    if (account.tracking_method === 'balance_based') {
      balanceByAccountId.set(account.id, latestSnapshots.get(account.id)?.balance ?? 0);
    } else {
      balanceByAccountId.set(account.id, transactionSums.get(account.id) ?? 0);
    }
  }

  const alerts: FundMovementAlert[] = [];

  for (const card of cards) {
    if (!card.is_active || !card.payment_account_id || card.annual_fee <= 0) continue;
    const paymentAccount = accounts.find((a) => a.id === card.payment_account_id);
    if (!paymentAccount) continue;

    const feeInAccountCurrency = convertToCurrency(card.annual_fee, card.fee_currency, paymentAccount.currency);
    const accountBalance = balanceByAccountId.get(paymentAccount.id) ?? 0;
    if (accountBalance >= feeInAccountCurrency) continue;

    const candidates = accounts
      .filter((a) => a.id !== paymentAccount.id && a.is_active && a.account_type === 'asset')
      .map((a) => {
        const balance = balanceByAccountId.get(a.id) ?? 0;
        const neededInThisCurrency = convertToCurrency(card.annual_fee, card.fee_currency, a.currency);
        return { account: a, balance, neededInThisCurrency, sufficient: balance >= neededInThisCurrency };
      })
      .filter((c) => c.sufficient);

    candidates.sort((a, b) => {
      const aMatches = a.account.currency === card.fee_currency;
      const bMatches = b.account.currency === card.fee_currency;
      if (aMatches !== bMatches) return aMatches ? -1 : 1;
      return a.neededInThisCurrency - b.neededInThisCurrency;
    });

    const best = candidates[0] ?? null;

    alerts.push({
      card,
      paymentAccount,
      feeInAccountCurrency,
      accountBalance,
      suggestedAccount: best ? { ...best.account, balance: best.balance } : null,
    });
  }

  return alerts;
}
