import { useFocusEffect } from '@react-navigation/native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, Switch, TextInput } from 'react-native';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { computeDisplayName, useConnectionDisplay } from '@/hooks/use-connection-display';
import { showAlert } from '@/lib/alert';
import {
  fetchConnectionShareRequests,
  respondToShareRequest,
  revokeShareRequest,
  sendShareRequest,
  setShareBalances,
  SHARE_MODULES,
  SHARE_MODULE_LABELS,
} from '@/lib/shareRequests';
import { supabase } from '@/lib/supabase';
import { CALENDAR_COLOR_PRESETS } from '@/lib/tripCalendar';
import type { ConnectionShareRequestRow, ShareModule } from '@/types/database';

const TINT = Colors.light.tint;

const MODULE_NOTES: Partial<Record<ShareModule, string>> = {
  cards: 'Card names and renewal dates always shared. Balances are optional, below.',
  accounts: 'Account names and currencies always shared. Balances are optional, below.',
  documents: 'Names, types, and expiry dates only, not the files.',
};

/** Only these two modules have a balance figure worth gating separately. */
const BALANCE_CAPABLE_MODULES: ShareModule[] = ['cards', 'accounts'];

export default function ConnectionSettingsScreen() {
  const { connectionId } = useLocalSearchParams<{ connectionId: string }>();
  const router = useRouter();
  const { session } = useAuth();
  const display = useConnectionDisplay(connectionId);

  const [partnerId, setPartnerId] = useState<string | null>(null);
  const [myRequests, setMyRequests] = useState<Partial<Record<ShareModule, ConnectionShareRequestRow>>>({});
  const [theirRequests, setTheirRequests] = useState<Partial<Record<ShareModule, ConnectionShareRequestRow>>>({});
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [nickname, setNickname] = useState('');
  const [isSavingNickname, setIsSavingNickname] = useState(false);
  const [busyModule, setBusyModule] = useState<ShareModule | null>(null);

  useEffect(() => {
    setNickname(display.override ?? '');
  }, [display.override]);

  const load = useCallback(async () => {
    if (!session) return;
    setError(null);
    const myId = session.user.id;

    const [connectionResult, requestsResult] = await Promise.all([
      supabase.from('connections').select('*').eq('id', connectionId).maybeSingle(),
      fetchConnectionShareRequests(connectionId),
    ]);

    if (connectionResult.error) {
      setError(connectionResult.error.message);
      setIsLoading(false);
      return;
    }
    if (requestsResult.error) {
      setError(requestsResult.error);
      setIsLoading(false);
      return;
    }

    const connection = connectionResult.data;
    const otherId = connection ? (connection.requester_id === myId ? connection.recipient_id : connection.requester_id) : null;
    setPartnerId(otherId);

    const mine: Partial<Record<ShareModule, ConnectionShareRequestRow>> = {};
    const theirs: Partial<Record<ShareModule, ConnectionShareRequestRow>> = {};
    for (const row of requestsResult.data) {
      if (row.from_user_id === myId) mine[row.module] = row;
      else theirs[row.module] = row;
    }
    setMyRequests(mine);
    setTheirRequests(theirs);
    setIsLoading(false);
  }, [session, connectionId]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  async function handleToggleShare(module: ShareModule, value: boolean) {
    if (!session) return;
    if (!partnerId) {
      setError("Couldn't determine who this connection is with yet. Try again in a moment.");
      return;
    }
    setBusyModule(module);
    const { error: saveError } = value
      ? await sendShareRequest(connectionId, session.user.id, partnerId, module)
      : await revokeShareRequest(connectionId, session.user.id, module);
    setBusyModule(null);
    if (saveError) {
      setError(saveError);
      return;
    }
    load();
  }

  async function handleToggleBalances(module: ShareModule, value: boolean) {
    if (!session) return;
    setBusyModule(module);
    const { error: saveError } = await setShareBalances(connectionId, session.user.id, module, value);
    setBusyModule(null);
    if (saveError) {
      setError(saveError);
      return;
    }
    load();
  }

  async function handleRespond(module: ShareModule, status: 'accepted' | 'declined') {
    const request = theirRequests[module];
    if (!request) return;
    setBusyModule(module);
    const { error: respondError } = await respondToShareRequest(request.id, status);
    setBusyModule(null);
    if (respondError) {
      setError(respondError);
      return;
    }
    load();
  }

  async function handleSaveNickname() {
    setIsSavingNickname(true);
    const saveError = await display.saveOverride(nickname);
    setIsSavingNickname(false);
    if (saveError) setError(saveError);
  }

  async function handlePickColorOverride(color: string | null) {
    const saveError = await display.saveColorOverride(color);
    if (saveError) setError(saveError);
  }

  function handleRemove() {
    showAlert('Remove connection', `This removes your connection with ${display.displayName}.`, [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Remove',
        style: 'destructive',
        onPress: async () => {
          const { error: removeError } = await supabase
            .from('connections')
            .update({ status: 'removed' })
            .eq('id', connectionId);
          if (removeError) {
            setError(removeError.message);
            return;
          }
          router.back();
        },
      },
    ]);
  }

  if (isLoading || display.isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={TINT} />
      </ThemedView>
    );
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: TINT }}>
            {display.displayName}
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}
        {display.error ? <ThemedText style={styles.error}>{display.error}</ThemedText> : null}
        <ThemedText style={styles.hint}>
          Turning a module on sends {display.displayName} a request. They need to accept it before it shows up on
          their side. The same goes the other way: anything they&apos;ve offered you needs your accept below.
        </ThemedText>

        <ThemedText type="defaultSemiBold">Your label for them</ThemedText>
        <ThemedText style={styles.hint}>
          Only visible to you. Doesn&apos;t change their real name or what anyone else sees. Leave blank to use their
          name{display.fullName ? '' : ' or email'}.
        </ThemedText>
        <TextInput
          value={nickname}
          onChangeText={setNickname}
          placeholder={computeDisplayName(null, display.fullName, display.email)}
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: TINT }]}
        />
        <Pressable
          onPress={handleSaveNickname}
          disabled={isSavingNickname}
          style={[styles.smallButton, { backgroundColor: TINT, alignSelf: 'flex-start' }]}>
          {isSavingNickname ? (
            <ActivityIndicator color={Colors.light.backgroundSolid} />
          ) : (
            <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Save label</ThemedText>
          )}
        </Pressable>

        <ThemedText type="defaultSemiBold" style={styles.sectionSpacing}>
          Their calendar color, for you
        </ThemedText>
        <ThemedText style={styles.hint}>
          Overrides how their trips are colored on your shared calendar only. Doesn&apos;t change their real color
          or anything anyone else sees.
        </ThemedText>
        <ThemedView style={styles.swatchRow}>
          {CALENDAR_COLOR_PRESETS.map((color) => (
            <Pressable
              key={color}
              onPress={() => handlePickColorOverride(color)}
              style={[
                styles.swatch,
                { backgroundColor: color },
                display.colorOverride === color ? styles.swatchSelected : null,
              ]}
            />
          ))}
          <Pressable onPress={() => handlePickColorOverride(null)} style={[styles.swatch, styles.swatchClear]}>
            <ThemedText style={styles.swatchClearText}>✕</ThemedText>
          </Pressable>
        </ThemedView>

        {SHARE_MODULES.map((module, index) => {
          const mine = myRequests[module];
          const theirs = theirRequests[module];
          const isBusy = busyModule === module;
          return (
            <Surface key={module} accentColor={TINT} style={[styles.toggleCard, index === 0 ? styles.sectionSpacing : null]}>
              <ThemedView style={styles.toggleRow}>
                <ThemedView style={styles.toggleLabel}>
                  <ThemedText type="defaultSemiBold">{SHARE_MODULE_LABELS[module]}</ThemedText>
                  <ThemedText style={styles.muted}>
                    {!mine
                      ? "You're not sharing this."
                      : mine.status === 'accepted'
                        ? `${display.displayName} accepted.`
                        : mine.status === 'declined'
                          ? `${display.displayName} declined.`
                          : `Waiting on ${display.displayName} to accept.`}
                  </ThemedText>
                  {MODULE_NOTES[module] ? <ThemedText style={styles.muted}>{MODULE_NOTES[module]}</ThemedText> : null}
                </ThemedView>
                <Switch
                  value={!!mine}
                  disabled={isBusy}
                  onValueChange={(value) => handleToggleShare(module, value)}
                  trackColor={{ true: TINT }}
                />
              </ThemedView>

              {mine && BALANCE_CAPABLE_MODULES.includes(module) ? (
                <ThemedView style={styles.balanceRow}>
                  <ThemedView style={styles.toggleLabel}>
                    <ThemedText>Also share balances</ThemedText>
                    <ThemedText style={styles.muted}>
                      {module === 'cards' ? "Include each card's outstanding balance." : "Include each account's balance."}
                    </ThemedText>
                  </ThemedView>
                  <Switch
                    value={mine.share_balances}
                    disabled={isBusy}
                    onValueChange={(value) => handleToggleBalances(module, value)}
                    trackColor={{ true: TINT }}
                  />
                </ThemedView>
              ) : null}

              {theirs?.status === 'pending' ? (
                <ThemedView style={styles.incomingRow}>
                  <ThemedText style={styles.muted}>
                    {display.displayName} wants to share their {SHARE_MODULE_LABELS[module].toLowerCase()} with you.
                  </ThemedText>
                  <ThemedView style={styles.incomingActions}>
                    <Pressable
                      disabled={isBusy}
                      onPress={() => handleRespond(module, 'accepted')}
                      style={[styles.smallButton, { backgroundColor: TINT }]}>
                      <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Accept</ThemedText>
                    </Pressable>
                    <Pressable
                      disabled={isBusy}
                      onPress={() => handleRespond(module, 'declined')}
                      style={[styles.smallButton, styles.smallButtonOutline, { borderColor: Colors.light.negative }]}>
                      <ThemedText style={{ color: Colors.light.negative }}>Decline</ThemedText>
                    </Pressable>
                  </ThemedView>
                </ThemedView>
              ) : theirs?.status === 'accepted' ? (
                <ThemedText style={styles.muted}>
                  You&apos;re viewing {display.displayName}&apos;s {SHARE_MODULE_LABELS[module].toLowerCase()}.
                </ThemedText>
              ) : null}
            </Surface>
          );
        })}

        <Pressable onPress={handleRemove} style={styles.removeLink}>
          <ThemedText style={{ color: Colors.light.negative }}>Remove connection</ThemedText>
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

