import { useEffect, useState } from 'react';

import { useAuth } from '@/contexts/auth-context';
import { useCurrency } from '@/contexts/currency-context';
import { fetchAllRows } from '@/lib/fetchAll';
import { computeForeignAssetPeak, hasReportingCitizenship } from '@/lib/foreignAssetReporting';
import { computeActiveNotices, countUnviewedNotices } from '@/lib/notices';
import { supabase } from '@/lib/supabase';
import type { BalanceSnapshotRow } from '@/types/database';

/**
 * How many of lib/notices.ts's active notices are new since the user's last
 * Summary visit — the one computation TopBar's badge and Home's "items to
 * review" prompt both need, kept in exactly one place so they can never
 * silently disagree with each other (they used to be two separately
 * hand-maintained copies of the same ~60-line fetch+compute block).
 *
 * `refreshKey` re-runs the fetch when it changes — TopBar passes its
 * pathname so the badge updates promptly right after visiting Summary
 * (which resets it) or editing a card; Home can omit it and just rely on
 * its own focus-driven remount/refetch cadence.
 *
 * When `refreshKey` is literally the Summary route, this skips the fetch
 * and returns 0 directly rather than computing-then-diffing. Summary's own
 * load() (and, same reasoning, Insights' — see lib/noticeSnapshot.ts) is
 * what actually writes the "seen" snapshot, and it runs independently of
 * this hook (they're siblings, not parent/child) — if this hook raced
 * ahead and read last_viewed_summary_notices before that write landed, it
 * would compute a stale non-zero count and then never naturally re-check
 * (it only reruns when refreshKey changes again), so the badge would look
 * stuck even though the user is looking straight at a screen that just
 * cleared it. Being on either screen is itself sufficient information —
 * no read needed.
 */
export function useNoticeCount(refreshKey?: unknown): number {
  const { session } = useAuth();
  const { homeCountry, convertToCurrency } = useCurrency();
  const [count, setCount] = useState(0);
  const isOnSummary = refreshKey === '/summary' || refreshKey === '/summary/insights';

  useEffect(() => {
    if (!session) return;
    if (isOnSummary) {
      setCount(0);
      return;
    }
    let cancelled = false;

    async function load() {
      const [
        cardsResult,
        visitsResult,
        documentsResult,
        accountsResult,
        transactionsResult,
        snapshotsResult,
        citizenshipsResult,
        settingsResult,
        pendingShareRequestIdsResult,
        pendingPlanRequestIdsResult,
        acceptedPlanRequestIdsResult,
        sharedTripIdsResult,
        pendingTripCollaborationInvitesResult,
        cityVisitsResult,
        loyaltyResult,
      ] = await Promise.all([
        supabase.from('credit_cards').select('id, renewal_date, payment_due_day'),
        supabase.from('countries_visited').select('*'),
        supabase.from('documents').select('id, expiry_date'),
        supabase.from('accounts').select('*'),
        fetchAllRows<{ date: string; amount: number; currency: string; account_id: string | null }>((from, to) =>
          supabase.from('transactions').select('date, amount, currency, account_id').order('date').order('id').range(from, to)
        ),
        fetchAllRows<BalanceSnapshotRow>((from, to) =>
          supabase.from('balance_snapshots').select('*').order('date').order('id').range(from, to)
        ),
        supabase.from('user_citizenships').select('country'),
        supabase.from('user_settings').select('last_viewed_summary_notices').eq('user_id', session!.user.id).maybeSingle(),
        // Same ids app/summary/index.tsx feeds into computeActiveNotices —
        // kept in sync with that call so the badge and Summary's own
        // snapshot-write never disagree about what counts as "new."
        supabase.from('connection_share_requests').select('id').eq('to_user_id', session!.user.id).eq('status', 'pending'),
        supabase.from('trip_plan_requests').select('id').eq('status', 'pending').neq('requested_by', session!.user.id),
        supabase.from('trip_plan_requests').select('id').eq('requested_by', session!.user.id).eq('status', 'accepted'),
        supabase.from('trips').select('id').eq('user_id', session!.user.id).eq('created_via_share', true),
        supabase.rpc('pending_trip_collaboration_invites'),
        supabase.rpc('city_visit_alerts'),
        supabase.from('loyalty_accounts').select('id, expiry_date'),
      ]);
      if (cancelled) return;

      const accounts = accountsResult.data ?? [];
      const transactions = transactionsResult.data ?? [];
      const snapshots = snapshotsResult.data ?? [];
      const citizenships = citizenshipsResult.data ?? [];
      const hasUsCitizenship = hasReportingCitizenship(citizenships, 'fbar');
      const hasCanadianCitizenship = hasReportingCitizenship(citizenships, 't1135');

      const active = computeActiveNotices({
        cards: cardsResult.data ?? [],
        homeCountry,
        countryVisits: visitsResult.data ?? [],
        documents: documentsResult.data ?? [],
        fbarPeakUsd: hasUsCitizenship
          ? computeForeignAssetPeak(accounts, transactions, snapshots, 'fbar', convertToCurrency)
          : null,
        hasUsCitizenship,
        t1135PeakCad: hasCanadianCitizenship
          ? computeForeignAssetPeak(accounts, transactions, snapshots, 't1135', convertToCurrency)
          : null,
        hasCanadianCitizenship,
        pendingShareRequestIds: (pendingShareRequestIdsResult.data ?? []).map((r) => r.id),
        pendingPlanRequestIds: (pendingPlanRequestIdsResult.data ?? []).map((r) => r.id),
        acceptedPlanRequestIds: (acceptedPlanRequestIdsResult.data ?? []).map((r) => r.id),
        sharedTripIds: (sharedTripIdsResult.data ?? []).map((r) => r.id),
        pendingTripCollaborationInviteIds: (pendingTripCollaborationInvitesResult.data ?? []).map((r) => r.id),
        cityVisitStopIds: (cityVisitsResult.data ?? []).map((r) => r.stop_id),
        loyaltyAccounts: loyaltyResult.data ?? [],
      });
      const lastViewed = settingsResult.data?.last_viewed_summary_notices ?? [];
      setCount(countUnviewedNotices(active, lastViewed));
    }

    load();
    return () => {
      cancelled = true;
    };
  }, [session, homeCountry, convertToCurrency, refreshKey, isOnSummary]);

  return count;
}
