import { createElement } from 'react';

import { Colors } from '@/constants/theme';
import type { TimeInputProps } from './time-input-types';

/**
 * Web counterpart to time-input.tsx — same reasoning as date-input.web.tsx:
 * @react-native-community/datetimepicker has no web implementation, so this
 * renders a real HTML5 <input type="time"> instead, which every browser
 * backs with its own native time picker.
 */
export function TimeInput({ value, onChange, accentColor }: TimeInputProps) {
  return createElement('input', {
    type: 'time',
    value: value ?? '',
    onChange: (event: { target: { value: string } }) => {
      if (event.target.value) onChange(event.target.value);
    },
    style: {
      borderWidth: 1,
      borderColor: accentColor,
      borderRadius: 8,
      paddingLeft: 16,
      paddingRight: 16,
      paddingTop: 12,
      paddingBottom: 12,
      fontSize: 16,
      marginBottom: 8,
      fontFamily: 'inherit',
      color: Colors.light.text,
      background: 'transparent',
    },
  });
}
