import { usePathname, useRouter } from 'expo-router';
import { useState } from 'react';
import { Pressable, StyleSheet, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { Avatar } from '@/components/avatar';
import { CountryFlag } from '@/components/country-flag';
import { SelectModal, type SelectOption } from '@/components/select-modal';
import { ThemedText } from '@/components/themed-text';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, Fonts } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { LOCAL_CURRENCY, useCurrency } from '@/contexts/currency-context';
import { useTour } from '@/contexts/tour-context';
import { useNoticeCount } from '@/hooks/use-notice-count';
import { NEUTRAL_FLAG_ICON } from '@/lib/countries';
import { fetchAllRows } from '@/lib/fetchAll';
import { supabase } from '@/lib/supabase';

// Layout (left avatar+name, centered flag, right icon cluster) is ported
// from the wheel-mockup's nav bar, but the COLORS stay the app's normal
// shared palette (Colors.light), not Home's own HomePalette — a single
// top bar rendered above every screen can't read as a different colorway
// depending which screen happens to be underneath it.
const ICON_COLOR = Colors.light.tintHighlight;

export function TopBar() {
  const router = useRouter();
  const pathname = usePathname();
  const insets = useSafeAreaInsets();
  const { session } = useAuth();
  const { step: tourStep } = useTour();
  const isHomeIconHighlighted = tourStep?.highlightAnchor === 'top-bar-home';
  const {
    displayCurrency,
    availableCurrencies,
    currencyNames,
    setDisplayCurrency,
    homeCountry,
    hiddenFlagCountries,
    avatarUrl,
    fullName,
  } = useCurrency();
  const rawName = fullName?.trim() || session?.user.email?.split('@')[0] || null;
  const firstName = rawName ? rawName.split(/\s+/)[0] : null;
  const [showPicker, setShowPicker] = useState(false);
  const [inUseCurrencies, setInUseCurrencies] = useState<Set<string>>(new Set());
  // Re-checked on every navigation (pathname) rather than a fixed interval —
  // cheap enough, and it means the badge updates promptly right after
  // visiting Summary (which resets it) or editing a card.
  const noticeBadgeCount = useNoticeCount(pathname);
  const isHome = pathname === '/';

  async function openCurrencyPicker() {
    // Computed fresh each time rather than cached alongside the rest of
    // useCurrency()'s state — accounts/cards/transactions change far more
    // often than that context refetches, and this is cheap enough (three
    // small selects) to just run whenever the picker actually opens.
    const [accountsResult, cardsResult, transactionsResult] = await Promise.all([
      supabase.from('accounts').select('currency'),
      supabase.from('credit_cards').select('fee_currency'),
      fetchAllRows<{ currency: string }>((from, to) =>
        supabase.from('transactions').select('currency').order('id').range(from, to)
      ),
    ]);
    const inUse = new Set<string>();
    for (const a of accountsResult.data ?? []) inUse.add(a.currency);
    for (const c of cardsResult.data ?? []) inUse.add(c.fee_currency);
    for (const t of transactionsResult.data) inUse.add(t.currency);
    setInUseCurrencies(inUse);
    setShowPicker(true);
  }

  // Falls back to the bare code if the name hasn't been populated yet (e.g. rows seeded before exchange_rates.name existed).
  function currencyLabel(code: string): string {
    const name = currencyNames[code];
    return name ? `${name} (${code})` : code;
  }

  // availableCurrencies is already A-Z (see CurrencyProvider), so both tiers stay sorted after filtering.
  const inUseTier = availableCurrencies.filter((c) => inUseCurrencies.has(c));
  const otherTier = availableCurrencies.filter((c) => !inUseCurrencies.has(c));

  const currencyOptions: SelectOption[] = [
    { value: LOCAL_CURRENCY, label: 'Local' },
    ...inUseTier.map((code) => ({ value: code, label: currencyLabel(code) })),
    ...otherTier.map((code, i) => ({
      value: code,
      label: currencyLabel(code),
      dividerBefore: i === 0 && inUseTier.length > 0,
    })),
  ];

  return (
    <View style={[styles.wrapper, { paddingTop: insets.top + 8 }]}>
      <View style={styles.nav}>
        <View style={[styles.navLeft, isHomeIconHighlighted ? styles.tourDimmed : null]}>
          {/* Back-chevron shifts in ahead of the avatar on every screen
              except Home — there's nowhere to go "back" to from Home
              itself, so it simply isn't rendered there rather than being
              present-but-disabled. */}
          {!isHome ? (
            <Pressable onPress={() => router.back()} hitSlop={10}>
              <IconSymbol name="chevron.left" size={22} color={ICON_COLOR} />
            </Pressable>
          ) : null}
          {/* Avatar, name, and flag are grouped together — all three
              navigate to the same /account destination, so they read as
              one "profile" affordance rather than icons split across the
              bar. Flag comes last, small — a secondary detail trailing the
              name, not competing with the avatar for attention. */}
          <Pressable onPress={() => router.push('/account')} hitSlop={12}>
            {session ? (
              <Avatar userId={session.user.id} email={session.user.email ?? ''} photoUrl={avatarUrl} size={29} />
            ) : (
              <IconSymbol name="person.crop.circle" size={26} color={ICON_COLOR} />
            )}
          </Pressable>
          {firstName ? <ThemedText style={styles.navTitle}>{firstName}</ThemedText> : null}
          <Pressable onPress={() => router.push('/account')} hitSlop={10}>
            {homeCountry ? (
              <CountryFlag countryName={homeCountry} hiddenFlagCountries={hiddenFlagCountries} size={13} />
            ) : (
              <ThemedText style={styles.flagIcon}>{NEUTRAL_FLAG_ICON}</ThemedText>
            )}
          </Pressable>
        </View>

        {/* Centered the same way the flag used to be — a plain (non-flex)
            child between two flex:1 siblings, so it stays truly centered
            regardless of how wide navLeft/navRight get. */}
        <Pressable
          onPress={() => router.push('/')}
          hitSlop={10}
          style={[styles.navIconBtn, isHomeIconHighlighted ? styles.iconHighlighted : undefined]}>
          <IconSymbol name="house.fill" size={17} color={ICON_COLOR} />
        </Pressable>

        <View style={styles.navRight}>
          <Pressable
            onPress={() => router.push('/search')}
            hitSlop={10}
            style={[styles.navIconBtn, isHomeIconHighlighted ? styles.tourDimmed : null]}>
            <IconSymbol name="magnifyingglass" size={17} color={ICON_COLOR} />
          </Pressable>

          <Pressable
            onPress={() => router.push('/summary')}
            hitSlop={10}
            style={[styles.navIconBtn, isHomeIconHighlighted ? styles.tourDimmed : null]}>
            <IconSymbol name="exclamationmark" size={17} color={ICON_COLOR} />
            {noticeBadgeCount > 0 ? (
              <View style={styles.badge}>
                <ThemedText style={styles.badgeText}>{noticeBadgeCount > 9 ? '9+' : noticeBadgeCount}</ThemedText>
              </View>
            ) : null}
          </Pressable>

          <Pressable
            onPress={openCurrencyPicker}
            hitSlop={10}
            style={[styles.currencyPill, isHomeIconHighlighted ? styles.tourDimmed : null]}>
            <ThemedText style={styles.currencyLabel}>
              {displayCurrency === LOCAL_CURRENCY ? 'Local' : displayCurrency}
            </ThemedText>
          </Pressable>
        </View>
      </View>

      <SelectModal
        visible={showPicker}
        onClose={() => setShowPicker(false)}
        options={currencyOptions}
        selectedValue={displayCurrency}
        onSelect={setDisplayCurrency}
        containerStyle={{ position: 'absolute', top: insets.top + 56, right: 16, width: 260 }}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  wrapper: {
    paddingHorizontal: 20,
    paddingBottom: 6,
  },
  // No pill/border/fill — the mockup's nav sits directly on the page
  // background, unlike the previous full-width evenly-flexed pill. Left
  // avatar+name, right icon cluster, matching that layout exactly.
  nav: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 8,
  },
  // navLeft and navRight both flex:1, with the Home icon as a plain
  // (non-flex) child between them — that's what actually centers Home
  // regardless of how wide the left group gets (back-chevron + avatar +
  // flag + name is variable width); space-between across 3 unequal-width
  // children doesn't true-center the middle one, only evenly gaps them.
  navLeft: {
    flex: 1,
    flexDirection: 'row',
    alignItems: 'center',
    gap: 9,
  },
  navTitle: {
    fontSize: 13,
    fontWeight: '600',
    color: Colors.light.text,
    fontFamily: Fonts.bodySemiBold,
  },
  navRight: {
    flex: 1,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'flex-end',
    gap: 14,
  },
  navIconBtn: {
    width: 26,
    height: 26,
    alignItems: 'center',
    justifyContent: 'center',
  },
  iconHighlighted: {
    backgroundColor: `${Colors.light.tint}33`,
    borderRadius: 20,
    borderWidth: 2,
    borderColor: Colors.light.tint,
  },
  // Applied to every OTHER slot than the tour's currently-highlighted one
  // — see app/index.tsx's own copy of this style for why plain opacity on
  // a wrapper beats a separately-positioned overlay trying to track the
  // element's screen position.
  tourDimmed: {
    opacity: 0.3,
  },
  currencyPill: {
    backgroundColor: Colors.light.navBarBackground,
    borderRadius: 12,
    paddingVertical: 6,
    paddingHorizontal: 10,
  },
  currencyLabel: {
    fontSize: 12,
    fontWeight: '700',
    color: Colors.light.text,
    letterSpacing: 0.2,
  },
  flagIcon: {
    fontSize: 13,
  },
  badge: {
    position: 'absolute',
    top: -4,
    right: -6,
    minWidth: 16,
    height: 16,
    borderRadius: 8,
    backgroundColor: Colors.light.negative,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 3,
  },
  badgeText: {
    fontSize: 10,
    fontWeight: '700',
    color: '#FFFFFF',
    lineHeight: 12,
  },
});
