import { supabase } from '@/lib/supabase';

const PALETTE = [
  '#F97066',
  '#F79009',
  '#EEAA05',
  '#66C61C',
  '#15B79E',
  '#2E90FA',
  '#7A5AF8',
  '#EE46BC',
  '#875BF7',
  '#F63D68',
];

export function initialsFromEmail(email: string): string {
  const local = email.split('@')[0] ?? '';
  const parts = local.split(/[._\-+]/).filter(Boolean);
  if (parts.length >= 2) {
    return (parts[0][0] + parts[1][0]).toUpperCase();
  }
  return (local.slice(0, 2) || '?').toUpperCase();
}

/** Stable color for a given id, e.g. a user id, so it stays consistent across sessions. */
export function colorForId(id: string): string {
  let hash = 0;
  for (let i = 0; i < id.length; i++) {
    hash = (hash * 31 + id.charCodeAt(i)) | 0;
  }
  return PALETTE[Math.abs(hash) % PALETTE.length];
}

/** Public URL for a storage path in the "avatars" bucket, or null if no path is set. The bucket is public, so this is a plain URL — no signed-URL refresh needed. */
export function avatarPublicUrl(path: string | null): string | null {
  if (!path) return null;
  return supabase.storage.from('avatars').getPublicUrl(path).data.publicUrl;
}
