import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { Pressable, RefreshControl, ScrollView, StyleSheet } from 'react-native';

import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { CountryFlag } from '@/components/country-flag';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { formatDateDisplay, toDateOnlyString } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import { computeTripSummaries, isTripUpcomingOrOngoing, type TripSummary } from '@/lib/trips';
import type { CountryVisitedRow, TripRow, TripSegmentRow } from '@/types/database';

const ACCENT = ModuleAccents.countries;

type TripCollaboration = { id: string; trip_id: string; trip_name: string | null; role: 'full' | 'contributor'; owner_display_name: string };

export default function TripsListScreen() {
  const router = useRouter();
  const { hiddenFlagCountries } = useCurrency();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();
  const [trips, setTrips] = useState<TripRow[]>([]);
  const [stops, setStops] = useState<CountryVisitedRow[]>([]);
  const [segments, setSegments] = useState<TripSegmentRow[]>([]);
  const [collaborations, setCollaborations] = useState<TripCollaboration[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const [tripsResult, stopsResult, segmentsResult, collaborationsResult] = await Promise.all([
      supabase.from('trips').select('*'),
      supabase.from('countries_visited').select('*'),
      supabase.from('trip_segments').select('*'),
      // A 'full' collaboration already surfaces here via its own copy in
      // tripsResult above — this only ever needs 'contributor' rows in
      // practice, which have no trips row of their own to show otherwise.
      supabase.rpc('my_trip_collaborations'),
    ]);
    if (tripsResult.error) {
      setError(tripsResult.error.message);
    } else if (stopsResult.error) {
      setError(stopsResult.error.message);
    } else {
      setTrips(tripsResult.data ?? []);
      setStops(stopsResult.data ?? []);
      setSegments(segmentsResult.data ?? []);
    }
    if (!collaborationsResult.error) {
      setCollaborations((collaborationsResult.data ?? []).filter((c) => c.role === 'contributor'));
    }
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  const today = toDateOnlyString(new Date());
  const summaries = computeTripSummaries(trips, stops, segments);
  const upcoming = summaries
    .filter((s) => isTripUpcomingOrOngoing(s, today))
    .sort((a, b) => (a.startDate < b.startDate ? -1 : 1));
  const past = summaries
    .filter((s) => !isTripUpcomingOrOngoing(s, today))
    .sort((a, b) => (a.startDate < b.startDate ? 1 : -1));

  function renderTrip(summary: TripSummary) {
    return (
      <Pressable key={summary.id} onPress={() => router.push(`/countries/trips/${summary.id}`)}>
        <Surface accentColor={ACCENT} style={styles.card}>
          <ThemedView style={styles.cardTop}>
            <ThemedView style={styles.flagRow}>
              {summary.countries.map((country) => (
                <CountryFlag key={country} countryName={country} hiddenFlagCountries={hiddenFlagCountries} size={20} />
              ))}
            </ThemedView>
            <ThemedView style={[styles.stopChip, { backgroundColor: ACCENT }]}>
              <ThemedText style={styles.stopChipText}>
                {summary.stops.length} stop{summary.stops.length === 1 ? '' : 's'}
              </ThemedText>
            </ThemedView>
          </ThemedView>
          <ThemedText type="defaultSemiBold" numberOfLines={1}>
            {summary.displayName}
          </ThemedText>
          <ThemedText type="mono" style={styles.muted}>
            {formatDateDisplay(summary.startDate)} → {formatDateDisplay(summary.endDate)}
          </ThemedText>
        </Surface>
      </Pressable>
    );
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView
        contentContainerStyle={styles.content}
        refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Trips
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedText type="subtitle" style={{ color: ACCENT }}>
          Upcoming
        </ThemedText>
        {upcoming.length === 0 && !isLoading ? <ThemedText style={styles.muted}>No upcoming trips yet.</ThemedText> : null}
        {upcoming.map(renderTrip)}

        <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
          Past
        </ThemedText>
        {past.length === 0 && !isLoading ? <ThemedText style={styles.muted}>No past trips logged.</ThemedText> : null}
        {past.map(renderTrip)}

        {collaborations.length > 0 ? (
          <>
            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
              Trips I&apos;m helping with
            </ThemedText>
            {collaborations.map((c) => (
              <Pressable key={c.id} onPress={() => router.push(`/countries/trips/shared/${c.trip_id}`)}>
                <Surface accentColor={ACCENT} style={styles.card}>
                  <ThemedText type="defaultSemiBold" numberOfLines={1}>
                    {c.trip_name ?? 'Trip'}
                  </ThemedText>
                  <ThemedText style={styles.muted}>{c.owner_display_name}&apos;s trip · Contributor</ThemedText>
                </Surface>
              </Pressable>
            ))}
          </>
        ) : null}
      </ScrollView>

      <Pressable
        onPress={() => router.push('/countries/visit/new?newTrip=1')}
        style={[styles.fab, { backgroundColor: ACCENT }]}>
        <IconSymbol name="plus" size={28} color={ModuleAccentOnColor.countries} />
      </Pressable>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 96,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 4,
  },
  sectionSpacing: {
    marginTop: 16,
  },
  card: {
    gap: 4,
  },
  cardTop: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  flagRow: {
    flexDirection: 'row',
    gap: 4,
  },
  stopChip: {
    borderRadius: 20,
    paddingHorizontal: 9,
    paddingVertical: 3,
  },
  stopChipText: {
    color: Colors.light.backgroundSolid,
    fontSize: 11,
    fontWeight: '600',
  },
  muted: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
  fab: {
    position: 'absolute',
    right: 20,
    bottom: 28,
    width: 56,
    height: 56,
    borderRadius: 28,
    alignItems: 'center',
    justifyContent: 'center',
    shadowColor: '#000',
    shadowOpacity: 0.2,
    shadowRadius: 6,
    shadowOffset: { width: 0, height: 3 },
    elevation: 4,
  },
});
