import { File, Paths } from 'expo-file-system';
import { useRouter } from 'expo-router';
import * as Sharing from 'expo-sharing';
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, Switch } from 'react-native';

import { DateInput } from '@/components/date-input';
import { ScopeSwitch } from '@/components/scope-switch';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { useCurrency } from '@/contexts/currency-context';
import { useScope } from '@/contexts/scope-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { formatDateDisplay, toDateOnlyString } from '@/lib/format';
import { summarizeCountries, summarizeCountriesInRange } from '@/lib/days';
import { fetchAllRows } from '@/lib/fetchAll';
import {
  buildReportHtml,
  type ReportAccount,
  type ReportBudget,
  type ReportCard,
  type ReportCategorySpend,
  type ReportCitizenship,
  type ReportConnection,
  type ReportCountryRow,
  type ReportDocument,
  type ReportSelection,
  type ReportVisa,
} from '@/lib/reportPdf';
import { scopeLabel } from '@/lib/scope';
import { supabase } from '@/lib/supabase';
import { computeTripSummaries } from '@/lib/trips';
import { computeCurrentBalance } from '@/lib/wealthSeries';
import type { AccountRow, BalanceSnapshotRow, CreditCardRow, TransactionRow } from '@/types/database';

const TINT = Colors.light.tint;

const SHARE_MODULE_LABELS: { key: 'share_countries' | 'share_trips_planned' | 'share_cards' | 'share_accounts' | 'share_documents'; label: string }[] = [
  { key: 'share_countries', label: 'Countries' },
  { key: 'share_trips_planned', label: 'Trips' },
  { key: 'share_cards', label: 'Cards' },
  { key: 'share_accounts', label: 'Accounts' },
  { key: 'share_documents', label: 'Documents' },
];

type Category = keyof ReportSelection;

const CATEGORIES: { key: Category; label: string; defaultOn: boolean }[] = [
  { key: 'transactions', label: 'Transactions', defaultOn: true },
  { key: 'accounts', label: 'Accounts', defaultOn: true },
  { key: 'cards', label: 'Cards & points', defaultOn: true },
  { key: 'travel', label: 'Countries & trips', defaultOn: true },
  { key: 'citizenship', label: 'Citizenship, visas & budgets', defaultOn: true },
  { key: 'documents', label: 'Documents (metadata only)', defaultOn: true },
  { key: 'connections', label: 'Connections', defaultOn: false },
];

type RangeMode = 'all' | 'custom';

export default function ExportReportScreen() {
  const router = useRouter();
  const { session } = useAuth();
  const { homeCountry, displayCurrency, convertToCurrency, fullName } = useCurrency();
  const { scope, filterAccounts, filterCards, filterSnapshots, filterTransactions } = useScope();
  const { connections: swipeConnections } = useSwipeConnections();

  const [selection, setSelection] = useState<ReportSelection>(() => {
    const initial = {} as ReportSelection;
    for (const c of CATEGORIES) initial[c.key] = c.defaultOn;
    return initial;
  });
  const [counts, setCounts] = useState<Record<Category, number> | null>(null);
  const [isLoadingCounts, setIsLoadingCounts] = useState(true);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  // Not exposed by useCurrency() (only home_country is lifted into that
  // context) — fetched directly here, same as Account's own home-city field.
  const [homeCity, setHomeCity] = useState<string | null>(null);

  const [rangeMode, setRangeMode] = useState<RangeMode>('all');
  const [rangeStart, setRangeStart] = useState(() => {
    const d = new Date();
    d.setMonth(d.getMonth() - 1);
    return d;
  });
  const [rangeEnd, setRangeEnd] = useState(new Date());

  const loadCounts = useCallback(async () => {
    if (!session) return;
    setIsLoadingCounts(true);
    const [txResult, accountsResult, cardsResult, visitsResult, tripsResult, docsResult, visasResult, citizenshipsResult, budgetsResult] =
      await Promise.all([
        supabase.from('transactions').select('id', { count: 'exact', head: true }),
        supabase.from('accounts').select('id', { count: 'exact', head: true }),
        supabase.from('credit_cards').select('id', { count: 'exact', head: true }),
        supabase.from('countries_visited').select('id', { count: 'exact', head: true }),
        supabase.from('trips').select('id', { count: 'exact', head: true }),
        supabase.from('documents').select('id', { count: 'exact', head: true }),
        supabase.from('user_visas').select('id', { count: 'exact', head: true }),
        supabase.from('user_citizenships').select('id', { count: 'exact', head: true }),
        supabase.from('budgets').select('id', { count: 'exact', head: true }),
      ]);
    setCounts({
      transactions: txResult.count ?? 0,
      accounts: accountsResult.count ?? 0,
      cards: cardsResult.count ?? 0,
      travel: (visitsResult.count ?? 0) + (tripsResult.count ?? 0),
      citizenship: (visasResult.count ?? 0) + (citizenshipsResult.count ?? 0) + (budgetsResult.count ?? 0),
      documents: docsResult.count ?? 0,
      connections: swipeConnections.length,
    });
    setIsLoadingCounts(false);
  }, [session, swipeConnections.length]);

  useEffect(() => {
    loadCounts();
  }, [loadCounts]);

  useEffect(() => {
    if (!session) return;
    supabase
      .from('user_settings')
      .select('home_city')
      .eq('user_id', session.user.id)
      .maybeSingle()
      .then(({ data }) => setHomeCity(data?.home_city ?? null));
  }, [session]);

  function toggleCategory(key: Category) {
    setSelection((prev) => ({ ...prev, [key]: !prev[key] }));
  }

  async function handleGenerate() {
    if (!session) return;
    setError(null);
    setIsGenerating(true);
    try {
      const userId = session.user.id;
      const isRanged = rangeMode === 'custom';
      const rangeStartStr = toDateOnlyString(rangeStart);
      const rangeEndStr = toDateOnlyString(rangeEnd);
      // Trip/document linking needs stops+segments whenever travel or
      // documents is selected — documents' "proof for" label and travel's
      // per-country "Documented" flag both resolve through the same stop/
      // segment lookup.
      const needsTripContext = selection.travel || selection.documents;

      const [
        accountsResult,
        snapshotsResult,
        cardsResult,
        pointsResult,
        visitsResult,
        tripsResult,
        segmentsResult,
        docsResult,
        visasResult,
        citizenshipsResult,
        budgetsResult,
        categoriesResult,
        connectionSettingsResult,
      ] = await Promise.all([
        // Scope (All / Personal / Business) is applied to each result as it
        // lands so everything downstream — net worth, account rows, card
        // rows — reflects it without threading the filter through every
        // consumer; the report's header says which scope it was built in.
        selection.accounts
          ? supabase
              .from('accounts')
              .select('*')
              .then((r) => ({ ...r, data: filterAccounts(r.data ?? []) }))
          : Promise.resolve({ data: [] as AccountRow[], error: null }),
        selection.accounts
          ? fetchAllRows<BalanceSnapshotRow>((from, to) =>
              supabase.from('balance_snapshots').select('*').order('date', { ascending: false }).range(from, to)
            ).then((r) => ({ ...r, data: filterSnapshots(r.data) }))
          : Promise.resolve({ data: [] as BalanceSnapshotRow[], error: null }),
        selection.cards
          ? supabase
              .from('credit_cards')
              .select('*')
              .then((r) => ({ ...r, data: filterCards(r.data ?? []) }))
          : Promise.resolve({ data: [] as CreditCardRow[], error: null }),
        selection.cards
          ? supabase.from('loyalty_accounts').select('card_id, balance')
          : Promise.resolve({ data: [], error: null }),
        needsTripContext ? supabase.from('countries_visited').select('*') : Promise.resolve({ data: [], error: null }),
        needsTripContext ? supabase.from('trips').select('*') : Promise.resolve({ data: [], error: null }),
        needsTripContext ? supabase.from('trip_segments').select('*') : Promise.resolve({ data: [], error: null }),
        selection.documents
          ? supabase.from('documents').select('name, doc_type, expiry_date, trip_stop_id, trip_segment_id')
          : Promise.resolve({ data: [], error: null }),
        selection.citizenship
          ? supabase.from('user_visas').select('country, visa_type, expiry_date')
          : Promise.resolve({ data: [], error: null }),
        selection.citizenship
          ? supabase.from('user_citizenships').select('country, is_primary')
          : Promise.resolve({ data: [], error: null }),
        selection.citizenship
          ? supabase.from('budgets').select('category_id, country, amount, currency')
          : Promise.resolve({ data: [], error: null }),
        selection.citizenship || selection.transactions
          ? supabase.from('categories').select('id, name')
          : Promise.resolve({ data: [], error: null }),
        selection.connections
          ? supabase.from('connection_sharing_settings').select('connection_id, share_countries, share_trips_planned, share_cards, share_accounts, share_documents').eq('user_id', userId)
          : Promise.resolve({ data: [], error: null }),
      ]);

      const categoryNameById = new Map((categoriesResult.data ?? []).map((c) => [c.id, c.name]));

      const latestSnapshotByAccount = new Map<string, BalanceSnapshotRow>();
      for (const snap of snapshotsResult.data ?? []) {
        if (!latestSnapshotByAccount.has(snap.account_id)) latestSnapshotByAccount.set(snap.account_id, snap);
      }
      const reportAccounts: ReportAccount[] = (accountsResult.data ?? []).map((a) => ({
        name: a.name,
        institution: a.institution,
        account_type: a.account_type,
        currency: a.currency,
        latestBalance: latestSnapshotByAccount.get(a.id)?.balance ?? null,
      }));

      const pointsByCard = new Map<string, number>();
      for (const p of pointsResult.data ?? []) {
        if (!p.card_id) continue;
        pointsByCard.set(p.card_id, (pointsByCard.get(p.card_id) ?? 0) + p.balance);
      }
      const reportCards: ReportCard[] = (cardsResult.data ?? []).map((c) => ({
        issuer: c.issuer,
        name: c.name,
        renewal_date: c.renewal_date,
        points_program: c.points_program,
        pointsBalance: pointsByCard.get(c.id) ?? null,
      }));

      const visits = visitsResult.data ?? [];
      const trips = tripsResult.data ?? [];
      const segments = segmentsResult.data ?? [];
      const tripSummaries = needsTripContext ? computeTripSummaries(trips, visits, segments) : [];

      // A segment's own from_label/to_label are free text, not a country
      // reference, and a leg can cross borders — so a linked segment is
      // attributed to its trip's first country, same approximation
      // lib/spend.ts's TripLinkMaps uses for expense-linked segments.
      const tripCountryById = new Map(tripSummaries.map((t) => [t.id, t.countries[0] ?? null]));
      const stopsById = new Map(visits.map((s) => [s.id, s]));
      const segmentsById = new Map(segments.map((s) => [s.id, s]));

      function linkedLabelFor(tripStopId: string | null, tripSegmentId: string | null): string | null {
        if (tripStopId) {
          const stop = stopsById.get(tripStopId);
          if (!stop) return null;
          const summary = tripSummaries.find((t) => t.id === stop.trip_id);
          return `${summary?.displayName ?? 'Trip'}: ${stop.city?.trim() || stop.country}`;
        }
        if (tripSegmentId) {
          const segment = segmentsById.get(tripSegmentId);
          if (!segment) return null;
          const summary = tripSummaries.find((t) => t.id === segment.trip_id);
          return `${summary?.displayName ?? 'Trip'}: ${segment.from_label} → ${segment.to_label}`;
        }
        return null;
      }

      function linkedCountryFor(tripStopId: string | null, tripSegmentId: string | null): string | null {
        if (tripStopId) return stopsById.get(tripStopId)?.country ?? null;
        if (tripSegmentId) {
          const segment = segmentsById.get(tripSegmentId);
          return segment ? (tripCountryById.get(segment.trip_id) ?? null) : null;
        }
        return null;
      }

      let countrySummaries: ReportCountryRow[] = [];
      let reportTrips = tripSummaries;
      if (selection.travel) {
        const documentedCountries = new Set(
          (docsResult.data ?? [])
            .filter((d) => d.doc_type === 'proof_of_travel')
            .map((d) => linkedCountryFor(d.trip_stop_id, d.trip_segment_id))
            .filter((c): c is string => !!c)
        );

        if (isRanged) {
          const rangeSummaries = summarizeCountriesInRange(visits, rangeStart, rangeEnd);
          countrySummaries = rangeSummaries.map((c) => ({
            country: c.country,
            daysUsed: c.daysUsed,
            daysRemaining: null,
            overLimit: false,
            thresholdDays: null,
            documented: documentedCountries.has(c.country),
          }));
          reportTrips = tripSummaries.filter((t) => (t.endDate ?? '9999-12-31') >= rangeStartStr && t.startDate <= rangeEndStr);
        } else {
          const fullSummaries = summarizeCountries(visits);
          countrySummaries = fullSummaries.map((c) => ({
            country: c.country,
            daysUsed: c.daysUsed,
            daysRemaining: c.daysRemaining,
            overLimit: c.overLimit,
            thresholdDays: c.thresholdDays,
            documented: documentedCountries.has(c.country),
          }));
        }
      }

      const reportDocuments: ReportDocument[] = selection.documents
        ? (docsResult.data ?? []).map((d) => ({
            name: d.name,
            doc_type: d.doc_type,
            expiry_date: d.expiry_date,
            linkedLabel: linkedLabelFor(d.trip_stop_id, d.trip_segment_id),
          }))
        : [];
      const reportVisas: ReportVisa[] = (visasResult.data ?? []) as ReportVisa[];
      const reportCitizenships: ReportCitizenship[] = (citizenshipsResult.data ?? []) as ReportCitizenship[];
      const reportBudgets: ReportBudget[] = (budgetsResult.data ?? []).map((b) => ({
        category: b.category_id ? (categoryNameById.get(b.category_id) ?? null) : null,
        country: b.country,
        amount: b.amount,
        currency: b.currency,
      }));

      // Fetched whenever either Accounts (net worth needs the full ledger,
      // unfiltered by range — computeCurrentBalance sums everything up to
      // asOf itself) or Transactions (category spend, filtered by range
      // below) is selected.
      let allTransactions: (Pick<TransactionRow, 'id' | 'date' | 'amount' | 'currency' | 'category_id' | 'is_internal_transfer' | 'account_id' | 'card_id'>)[] = [];
      if (selection.accounts || selection.transactions) {
        const { data } = await fetchAllRows<
          Pick<TransactionRow, 'id' | 'date' | 'amount' | 'currency' | 'category_id' | 'is_internal_transfer' | 'account_id' | 'card_id'>
        >((from, to) =>
          supabase
            .from('transactions')
            .select('id, date, amount, currency, category_id, is_internal_transfer, account_id, card_id')
            .order('id')
            .range(from, to)
        );
        allTransactions = filterTransactions(data);
      }

      let netWorth: number | null = null;
      const netWorthAsOfLabel = isRanged ? formatDateDisplay(rangeEndStr) : 'today';
      if (selection.accounts) {
        netWorth = computeCurrentBalance({
          transactions: allTransactions,
          accounts: accountsResult.data ?? [],
          balanceSnapshots: snapshotsResult.data ?? [],
          convert: (amount, fromCurrency) => convertToCurrency(amount, fromCurrency, displayCurrency),
          asOf: isRanged ? rangeEnd : new Date(),
        });
      }

      let categorySpend: ReportCategorySpend[] = [];
      let transactionCount = 0;
      if (selection.transactions) {
        const scopedTx = isRanged
          ? allTransactions.filter((tx) => tx.date >= rangeStartStr && tx.date <= rangeEndStr)
          : allTransactions;
        transactionCount = scopedTx.length;
        const totalsByCategory = new Map<string, number>();
        for (const tx of scopedTx) {
          if (tx.is_internal_transfer || tx.amount >= 0) continue; // spend only, not income/transfers
          const label = tx.category_id ? (categoryNameById.get(tx.category_id) ?? 'Uncategorized') : 'Uncategorized';
          const converted = convertToCurrency(Math.abs(tx.amount), tx.currency, displayCurrency);
          totalsByCategory.set(label, (totalsByCategory.get(label) ?? 0) + converted);
        }
        categorySpend = Array.from(totalsByCategory.entries())
          .map(([category, total]) => ({ category, total }))
          .sort((a, b) => b.total - a.total);
      }

      const shareSettingsByConnection = new Map((connectionSettingsResult.data ?? []).map((s) => [s.connection_id, s]));
      const reportConnections: ReportConnection[] = selection.connections
        ? swipeConnections.map((c) => {
            const settings = shareSettingsByConnection.get(c.id);
            const shared = settings
              ? SHARE_MODULE_LABELS.filter((m) => settings[m.key]).map((m) => m.label)
              : [];
            return { displayName: c.displayName, shared };
          })
        : [];

      const html = buildReportHtml(
        {
          fullName,
          email: session.user.email ?? '',
          homeCountry,
          homeCity,
          displayCurrency,
          generatedAt: new Date(),
          dateRangeLabel: isRanged ? `${formatDateDisplay(rangeStartStr)} – ${formatDateDisplay(rangeEndStr)}` : null,
          scopeLabel: scopeLabel(scope),
          netWorth,
          netWorthAsOfLabel,
          accounts: reportAccounts,
          cards: reportCards,
          countrySummaries,
          trips: reportTrips,
          documents: reportDocuments,
          citizenships: reportCitizenships,
          visas: reportVisas,
          budgets: reportBudgets,
          categorySpend,
          transactionCount,
          connections: reportConnections,
        },
        selection
      );

      // Shared as HTML rather than rendered to an actual PDF for now — real
      // PDF generation needs expo-print, a native module Expo Go doesn't
      // bundle; using it crashes immediately on import (native module
      // lookup happens at module-evaluation time, not lazily on first
      // call), not just when actually invoked. Swap this back to
      // Print.printToFileAsync({ html }) once a custom dev client with
      // expo-print built in exists — buildReportHtml's output doesn't need
      // to change at all, only how it's delivered.
      const filename = `cluster-summary-${new Date().toISOString().slice(0, 10)}.html`;
      const file = new File(Paths.cache, filename);
      if (file.exists) {
        file.delete();
      }
      file.create();
      file.write(html);

      const canShare = await Sharing.isAvailableAsync();
      if (!canShare) {
        setError('Sharing is not available on this device. The file was generated but could not be shared.');
        return;
      }
      await Sharing.shareAsync(file.uri, { mimeType: 'text/html', dialogTitle: 'Cluster Data & Travel Summary' });
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Export failed.');
    } finally {
      setIsGenerating(false);
    }
  }

  const hasSelection = CATEGORIES.some((c) => selection[c.key]);

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ScopeSwitch accent={TINT} />
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: TINT }}>
            Export Summary Report
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedText style={styles.muted}>
          A readable summary of what you&apos;ve logged in Cluster, for backup, sharing, or peace of mind before
          closing your account. Choose what to include below.
        </ThemedText>
        <ThemedText style={styles.caution}>
          Shares as a webpage for now, not a PDF file directly. Open it and use your browser&apos;s Print → Save as
          PDF if you want an actual PDF. Direct PDF export is coming once the app has a custom build.
        </ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedView style={styles.list}>
          {CATEGORIES.map((c) => (
            <Surface key={c.key} accentColor={TINT} style={styles.row}>
              <ThemedView style={styles.rowText}>
                <ThemedText type="defaultSemiBold">{c.label}</ThemedText>
                <ThemedText style={styles.count}>
                  {isLoadingCounts || !counts ? '…' : `${counts[c.key].toLocaleString()} item${counts[c.key] === 1 ? '' : 's'}`}
                </ThemedText>
              </ThemedView>
              <Switch value={selection[c.key]} onValueChange={() => toggleCategory(c.key)} trackColor={{ true: TINT }} />
            </Surface>
          ))}
        </ThemedView>

        {selection.documents ? (
          <ThemedText style={styles.caution}>
            Document metadata (name, type, expiry) is listed. The actual files aren&apos;t included in this export.
            Documents marked Proof of Travel and linked to a trip show which stop or leg they back up.
          </ThemedText>
        ) : null}

        <ThemedText type="defaultSemiBold" style={styles.sectionLabel}>
          Range
        </ThemedText>
        <ThemedView style={styles.rangeChips}>
          {(['all', 'custom'] as RangeMode[]).map((mode) => {
            const isSelected = rangeMode === mode;
            return (
              <Pressable
                key={mode}
                onPress={() => setRangeMode(mode)}
                style={[styles.chip, { borderColor: TINT, backgroundColor: isSelected ? TINT : 'transparent' }]}>
                <ThemedText style={isSelected ? { color: Colors.light.backgroundSolid } : undefined}>
                  {mode === 'all' ? 'All time' : 'Custom range'}
                </ThemedText>
              </Pressable>
            );
          })}
        </ThemedView>
        {rangeMode === 'custom' ? (
          <ThemedView style={styles.rangeRow}>
            <DateInput
              value={rangeStart}
              onChange={(date) => {
                setRangeStart(date);
                if (rangeEnd < date) setRangeEnd(date);
              }}
              accentColor={TINT}
            />
            <ThemedText>&rarr;</ThemedText>
            <DateInput value={rangeEnd} onChange={setRangeEnd} accentColor={TINT} minimumDate={rangeStart} />
          </ThemedView>
        ) : null}
        {rangeMode === 'custom' ? (
          <ThemedText style={styles.caution}>
            Transactions, spend, and country day-counts are scoped to this range. Accounts, cards, documents, and
            citizenship always reflect current state. Net worth is shown as of the range end date instead of today.
          </ThemedText>
        ) : null}

        <Pressable
          onPress={handleGenerate}
          disabled={isGenerating || !hasSelection}
          style={[styles.button, { backgroundColor: TINT, opacity: hasSelection ? 1 : 0.5 }]}>
          {isGenerating ? (
            <ActivityIndicator color={Colors.light.backgroundSolid} />
          ) : (
            <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>
              Generate Report
            </ThemedText>
          )}
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 4,
  },
  muted: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 8,
  },
  list: {
    gap: 8,
    marginTop: 8,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  rowText: {
    flex: 1,
    gap: 2,
    marginRight: 12,
  },
  count: {
    fontSize: 12,
    color: Colors.light.textMuted,
  },
  caution: {
    fontSize: 12,
    color: Colors.light.textMuted,
    marginTop: 8,
    fontStyle: 'italic',
  },
  sectionLabel: {
    marginTop: 16,
  },
  rangeChips: {
    flexDirection: 'row',
    gap: 8,
    marginTop: 8,
  },
  chip: {
    borderWidth: 1,
    borderRadius: 999,
    paddingVertical: 6,
    paddingHorizontal: 14,
  },
  rangeRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
    marginTop: 10,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 16,
  },
  error: {
    color: Colors.light.negative,
  },
});
