import 'maplibre-gl/dist/maplibre-gl.css';

import type { LngLatBoundsLike, Map as MapLibreMap } from 'maplibre-gl';
import { useEffect, useRef } from 'react';

import { loadMapStyle } from '@/lib/worldMapStyle';
import { arcLegPath, type RoutePoint } from '@/lib/tripRoute';

// Deliberately compact — a full-height navigable map read as too big/heavy
// for a passport-screen overview compared to a static preview; this is
// meant to be glanced at and tapped, not panned/zoomed extensively.
const MAP_HEIGHT = 180;
const BOUNDS_PADDING = 24;
const DIMMED_OPACITY = 0.25;

export type TripOverlay = {
  tripId: string;
  name: string;
  dateRange: string;
  color: string;
  points: RoutePoint[];
};

type MapLibreModule = typeof import('maplibre-gl');

// Same pinned-to-v5, .default-fallback dynamic-import pattern as
// world-passport-map.web.tsx — see that file's own comment for why (v6's
// Web Worker loading is incompatible with Metro's web bundler).
let cachedModule: MapLibreModule | null = null;

function tripLegsGeoJSON(trips: TripOverlay[], selectedTripId: string | null) {
  return {
    type: 'FeatureCollection' as const,
    features: trips.flatMap((trip) =>
      trip.points.slice(0, -1).map((point, legIndex) => ({
        type: 'Feature' as const,
        properties: {
          tripId: trip.tripId,
          color: trip.color,
          dimmed: !!selectedTripId && selectedTripId !== trip.tripId,
        },
        // One gentle bow per leg (see arcLegPath's own comment) instead of
        // catmullRomLegPath's whole-trip spline — that one produced a
        // self-intersecting loop on a short, widely-spaced trip, confirmed
        // against a real render.
        geometry: {
          type: 'LineString' as const,
          coordinates: arcLegPath(point, trip.points[legIndex + 1]).map((p) => [p.lon, p.lat]),
        },
      }))
    ),
  };
}

function tripStopsGeoJSON(trips: TripOverlay[], selectedTripId: string | null) {
  return {
    type: 'FeatureCollection' as const,
    features: trips.flatMap((trip) =>
      trip.points.map((point) => ({
        type: 'Feature' as const,
        properties: { tripId: trip.tripId, color: trip.color, dimmed: !!selectedTripId && selectedTripId !== trip.tripId },
        geometry: { type: 'Point' as const, coordinates: [point.lon, point.lat] },
      }))
    ),
  };
}

/**
 * The passport screen's "all my trips at once" overlay — every trip's own
 * route curve drawn on one shared map, each in that trip's own color
 * (lib/tripColors.ts), instead of the per-leg mode colors a single trip's
 * own map uses (those only read clearly zoomed into one trip; at a
 * world/country zoom level, one color per TRIP is what's legible).
 * Tapping any trip's line calls onSelectTrip with its id — the caller owns
 * what "selected" means (this component just dims every other trip's
 * lines while one is selected, so the tapped trip visually pops).
 *
 * Same MapLibre + OpenFreeMap Positron engine as the Countries/Cities
 * map (world-passport-map.web.tsx) instead of the raster-tile Leaflet map
 * this used to be — the passport screen's two tabs looked like two
 * different products before, reported directly as a real inconsistency,
 * not a style nitpick.
 */
export function MultiTripRouteMap({
  trips,
  selectedTripId,
  onSelectTrip,
  height = MAP_HEIGHT,
}: {
  trips: TripOverlay[];
  selectedTripId: string | null;
  onSelectTrip: (tripId: string) => void;
  height?: number;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<MapLibreMap | null>(null);
  const onSelectTripRef = useRef(onSelectTrip);
  onSelectTripRef.current = onSelectTrip;
  const allPoints = trips.flatMap((t) => t.points);
  const pointsKey = allPoints.map((p) => `${p.id}:${p.lat}:${p.lon}`).join('|');

  useEffect(() => {
    let cancelled = false;
    async function init() {
      if (!cachedModule) {
        const mod = await import('maplibre-gl');
        cachedModule = (mod as unknown as { default?: MapLibreModule }).default ?? mod;
      }
      const maplibregl = cachedModule;
      const mapStyle = await loadMapStyle();
      if (cancelled || !containerRef.current) return;
      const map = new maplibregl.Map({
        container: containerRef.current,
        style: mapStyle as unknown as string,
        center: [0, 20],
        zoom: 1,
        scrollZoom: false,
      });
      map.on('load', () => {
        if (cancelled) return;
        map.addSource('trip-legs', { type: 'geojson', data: tripLegsGeoJSON(trips, selectedTripId) });
        map.addLayer({
          id: 'trip-legs-line',
          type: 'line',
          source: 'trip-legs',
          layout: { 'line-cap': 'round', 'line-join': 'round' },
          paint: {
            'line-color': ['get', 'color'],
            'line-width': 4,
            'line-opacity': ['case', ['get', 'dimmed'], DIMMED_OPACITY, 1],
          },
        });
        map.addSource('trip-stops', { type: 'geojson', data: tripStopsGeoJSON(trips, selectedTripId) });
        map.addLayer({
          id: 'trip-stops-circle',
          type: 'circle',
          source: 'trip-stops',
          paint: {
            'circle-color': ['get', 'color'],
            'circle-radius': 5,
            'circle-stroke-width': 2,
            'circle-stroke-color': '#FBFBF9',
            'circle-opacity': ['case', ['get', 'dimmed'], DIMMED_OPACITY, 1],
            'circle-stroke-opacity': ['case', ['get', 'dimmed'], DIMMED_OPACITY, 1],
          },
        });
        for (const layerId of ['trip-legs-line', 'trip-stops-circle']) {
          map.on('click', layerId, (e) => {
            const tripId = e.features?.[0]?.properties?.tripId as string | undefined;
            if (tripId) onSelectTripRef.current(tripId);
          });
          map.on('mouseenter', layerId, () => {
            map.getCanvas().style.cursor = 'pointer';
          });
          map.on('mouseleave', layerId, () => {
            map.getCanvas().style.cursor = '';
          });
        }
        if (allPoints.length === 1) {
          map.setCenter([allPoints[0].lon, allPoints[0].lat]);
          map.setZoom(4);
        } else if (allPoints.length > 1) {
          const lons = allPoints.map((p) => p.lon);
          const lats = allPoints.map((p) => p.lat);
          const bounds: LngLatBoundsLike = [
            [Math.min(...lons), Math.min(...lats)],
            [Math.max(...lons), Math.max(...lats)],
          ];
          map.fitBounds(bounds, { padding: BOUNDS_PADDING, animate: false });
        }
      });
      mapRef.current = map;
    }
    init();
    return () => {
      cancelled = true;
      mapRef.current?.remove();
      mapRef.current = null;
    };
    // Initial trips/selectedTripId only — updated live below instead of
    // tearing down and recreating the whole map on every change.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !map.getSource('trip-legs')) return;
    (map.getSource('trip-legs') as unknown as { setData: (d: GeoJSON.FeatureCollection) => void }).setData(
      tripLegsGeoJSON(trips, selectedTripId) as GeoJSON.FeatureCollection
    );
    (map.getSource('trip-stops') as unknown as { setData: (d: GeoJSON.FeatureCollection) => void }).setData(
      tripStopsGeoJSON(trips, selectedTripId) as GeoJSON.FeatureCollection
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pointsKey, selectedTripId]);

  return <div ref={containerRef} style={{ height, borderRadius: 12, overflow: 'hidden' }} />;
}
