import { useRouter, type Href } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, TextInput } from 'react-native';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { runGlobalSearch, type SearchResultSection } from '@/lib/search';

const ACCENT = Colors.light.tint;
const MIN_QUERY_LENGTH = 2;
const DEBOUNCE_MS = 300;

export default function SearchScreen() {
  const router = useRouter();
  const { connections } = useSwipeConnections();
  const [query, setQuery] = useState('');
  const [sections, setSections] = useState<SearchResultSection[]>([]);
  const [isSearching, setIsSearching] = useState(false);

  useEffect(() => {
    const trimmed = query.trim();
    if (trimmed.length < MIN_QUERY_LENGTH) {
      setSections([]);
      setIsSearching(false);
      return;
    }
    let cancelled = false;
    setIsSearching(true);
    const timeout = setTimeout(async () => {
      const results = await runGlobalSearch(trimmed, connections);
      if (!cancelled) {
        setSections(results);
        setIsSearching(false);
      }
    }, DEBOUNCE_MS);
    return () => {
      cancelled = true;
      clearTimeout(timeout);
    };
  }, [query, connections]);

  const trimmedQuery = query.trim();
  const hasQuery = trimmedQuery.length >= MIN_QUERY_LENGTH;
  const hasResults = sections.length > 0;

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ThemedView style={styles.titleRow}>
        <ThemedText type="title" style={{ color: ACCENT }}>
          Search
        </ThemedText>
        <Pressable onPress={() => router.back()} hitSlop={12}>
          <ThemedText type="link">Done</ThemedText>
        </Pressable>
      </ThemedView>

      <TextInput
        value={query}
        onChangeText={setQuery}
        placeholder="Merchants, documents, trips, cards, accounts…"
        placeholderTextColor={Colors.light.textMuted}
        autoFocus
        autoCapitalize="none"
        returnKeyType="search"
        style={[styles.input, { borderColor: ACCENT }]}
      />

      <ScrollView contentContainerStyle={styles.content} keyboardShouldPersistTaps="handled">
        {!hasQuery ? (
          <ThemedText style={styles.muted}>
            Search across everything you&apos;ve logged: merchants, documents, trips, cards, accounts, and connections.
          </ThemedText>
        ) : isSearching ? (
          <ActivityIndicator color={ACCENT} style={styles.spinner} />
        ) : !hasResults ? (
          <ThemedText style={styles.muted}>No results for &quot;{trimmedQuery}&quot;.</ThemedText>
        ) : (
          sections.map((section) => (
            <ThemedView key={section.key} style={styles.section}>
              <ThemedText type="subtitle" style={[styles.sectionTitle, { color: ACCENT }]}>
                {section.label}
              </ThemedText>
              {section.items.map((item) => (
                <Pressable key={item.id} onPress={() => router.push(item.href as Href)}>
                  <Surface accentColor={ACCENT} style={styles.resultCard}>
                    <ThemedText type="defaultSemiBold" numberOfLines={1}>
                      {item.title}
                    </ThemedText>
                    <ThemedText style={styles.muted} numberOfLines={1}>
                      {item.subtitle}
                    </ThemedText>
                  </Surface>
                </Pressable>
              ))}
            </ThemedView>
          ))
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 16,
    marginBottom: 8,
  },
  input: {
    marginHorizontal: 16,
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  content: {
    padding: 16,
    paddingTop: 0,
    gap: 8,
    paddingBottom: 48,
  },
  section: {
    gap: 8,
    marginBottom: 8,
  },
  sectionTitle: {
    marginBottom: 2,
  },
  resultCard: {
    gap: 2,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  spinner: {
    marginTop: 24,
  },
});
