import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { ScopeSwitch } from '@/components/scope-switch';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { useScope } from '@/contexts/scope-context';
import { latestSnapshotByAccount, transactionSumByAccount } from '@/lib/accountBalance';
import { formatMoney } from '@/lib/currency';
import { fetchAllRows } from '@/lib/fetchAll';
import { supabase } from '@/lib/supabase';
import type { AccountRow, BalanceSnapshotRow, CreditCardRow, TransactionRow } from '@/types/database';

const ACCENT = ModuleAccents.cards;

type AccountOption = { account: AccountRow; balanceInDisplayCurrency: number };
type CardRecommendation = {
  card: CreditCardRow;
  typicalMonthlySpend: number;
  ranked: AccountOption[];
  recommended: AccountOption | null;
  current: AccountOption | null;
  annualOpportunityCost: number;
};

export default function FloatOptimizerScreen() {
  const router = useRouter();
  const { displayCurrency, convertToCurrency, isLoading: isCurrencyLoading } = useCurrency();

  const { filterCards, filterAccounts, filterSnapshots, filterTransactions } = useScope();
  const [allCards, setCards] = useState<CreditCardRow[]>([]);
  const [allAccounts, setAccounts] = useState<AccountRow[]>([]);
  const [allSnapshots, setSnapshots] = useState<BalanceSnapshotRow[]>([]);
  const [allTransactions, setTransactions] = useState<TransactionRow[]>([]);
  const cards = filterCards(allCards);
  const accounts = filterAccounts(allAccounts);
  const snapshots = filterSnapshots(allSnapshots);
  const transactions = filterTransactions(allTransactions);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const [cardsResult, accountsResult, snapshotsResult, txResult] = await Promise.all([
      supabase.from('credit_cards').select('*').eq('is_active', true),
      supabase.from('accounts').select('*').eq('is_active', true),
      fetchAllRows<BalanceSnapshotRow>((from, to) =>
        supabase.from('balance_snapshots').select('*').order('date', { ascending: false }).range(from, to)
      ),
      fetchAllRows<TransactionRow>((from, to) => supabase.from('transactions').select('*').order('date').order('id').range(from, to)),
    ]);
    if (cardsResult.error) {
      setError(cardsResult.error.message);
      setIsLoading(false);
      return;
    }
    setCards(cardsResult.data ?? []);
    setAccounts(accountsResult.data ?? []);
    setSnapshots(snapshotsResult.data);
    setTransactions(txResult.data);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  const showLoading = isLoading || isCurrencyLoading;

  const cashAccounts = accounts.filter((a) => a.account_type === 'asset' && a.asset_category === 'cash');
  const anyRateSet = cashAccounts.some((a) => a.interest_rate != null);

  const latestSnapshots = latestSnapshotByAccount(snapshots);
  const transactionSums = transactionSumByAccount(transactions);

  function balanceInDisplayCurrency(account: AccountRow): number {
    const nativeBalance =
      account.tracking_method === 'balance_based'
        ? (latestSnapshots.get(account.id)?.balance ?? 0)
        : (transactionSums.get(account.id) ?? 0);
    return convertToCurrency(nativeBalance, account.currency, displayCurrency);
  }

  const recommendations: CardRecommendation[] = cards
    .filter((card) => card.payment_due_day != null)
    .map((card) => {
      const cardSpend = transactions.filter((tx) => tx.card_id === card.id && tx.amount < 0);
      const months = new Set(cardSpend.map((tx) => tx.date.slice(0, 7)));
      const totalSpend = cardSpend.reduce((sum, tx) => sum + convertToCurrency(Math.abs(tx.amount), tx.currency, displayCurrency), 0);
      const typicalMonthlySpend = months.size > 0 ? totalSpend / months.size : 0;

      const ranked: AccountOption[] = cashAccounts
        .map((account) => ({ account, balanceInDisplayCurrency: balanceInDisplayCurrency(account) }))
        .sort((a, b) => (a.account.interest_rate ?? 0) - (b.account.interest_rate ?? 0));

      const sufficient = ranked.filter((r) => typicalMonthlySpend === 0 || r.balanceInDisplayCurrency >= typicalMonthlySpend);
      const recommended = sufficient[0] ?? ranked[0] ?? null;
      const current = card.payment_account_id ? (ranked.find((r) => r.account.id === card.payment_account_id) ?? null) : null;

      const currentRate = current?.account.interest_rate ?? 0;
      const recommendedRate = recommended?.account.interest_rate ?? 0;
      const annualOpportunityCost =
        current && recommended && current.account.id !== recommended.account.id && currentRate > recommendedRate
          ? ((currentRate - recommendedRate) / 100) * typicalMonthlySpend * 12
          : 0;

      return { card, typicalMonthlySpend, ranked, recommended, current, annualOpportunityCost };
    });

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ScopeSwitch accent={ACCENT} />
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Pay Bills From
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedText style={styles.muted}>
          Which cash account to pay each card&apos;s bill from, to leave your highest-yield accounts untouched the
          longest. A rough estimate, not financial advice.
        </ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {showLoading ? (
          <ActivityIndicator style={styles.loading} color={ACCENT} />
        ) : cashAccounts.length === 0 ? (
          <Surface accentColor={ACCENT}>
            <ThemedText style={styles.muted}>No cash accounts yet. Add one under Accounts first.</ThemedText>
          </Surface>
        ) : !anyRateSet ? (
          <Surface accentColor={ACCENT}>
            <ThemedText style={styles.muted}>
              None of your cash accounts have an interest rate set, so there&apos;s nothing to rank yet. Add an APY
              on each cash account&apos;s edit screen to get a real recommendation here.
            </ThemedText>
          </Surface>
        ) : recommendations.length === 0 ? (
          <Surface accentColor={ACCENT}>
            <ThemedText style={styles.muted}>
              No active cards have a payment due day set. Add one on a card&apos;s edit screen to get a
              recommendation.
            </ThemedText>
          </Surface>
        ) : (
          recommendations.map(({ card, typicalMonthlySpend, ranked, recommended, current, annualOpportunityCost }) => {
            const isAligned = !current || !recommended || current.account.id === recommended.account.id;
            return (
              <Pressable key={card.id} onPress={() => router.push(`/cards/${card.id}`)}>
                <Surface accentColor={isAligned ? ACCENT : Colors.light.negative}>
                  <ThemedText type="defaultSemiBold">
                    {card.issuer} · {card.name}
                  </ThemedText>
                  <ThemedText style={styles.muted}>
                    {typicalMonthlySpend > 0
                      ? `Typically ${formatMoney(typicalMonthlySpend, displayCurrency)}/month`
                      : 'No spend history on this card yet'}
                  </ThemedText>

                  {recommended ? (
                    <ThemedText style={styles.recommendation}>
                      Recommended: <ThemedText type="defaultSemiBold">{recommended.account.name}</ThemedText>
                      {recommended.account.interest_rate != null ? ` (${recommended.account.interest_rate}% APY)` : ' (no rate set)'}
                      {', '}
                      {formatMoney(recommended.balanceInDisplayCurrency, displayCurrency)} available
                    </ThemedText>
                  ) : null}

                  {current ? (
                    <ThemedText style={isAligned ? styles.muted : styles.flagged}>
                      {isAligned
                        ? `Currently paid from ${current.account.name}, already the recommended choice.`
                        : `Currently paid from ${current.account.name} (${current.account.interest_rate ?? 0}% APY)${
                            annualOpportunityCost > 0
                              ? `. Switching could leave roughly ${formatMoney(annualOpportunityCost, displayCurrency)}/year more sitting in interest.`
                              : '.'
                          }`}
                    </ThemedText>
                  ) : (
                    <ThemedText style={styles.flagged}>No payment account set for this card yet.</ThemedText>
                  )}

                  {ranked.length > 1 ? (
                    <ThemedView style={styles.rankList}>
                      {ranked.map((r) => (
                        <ThemedView key={r.account.id} style={styles.rankRow}>
                          <ThemedText style={styles.rankName} numberOfLines={1}>
                            {r.account.name}
                          </ThemedText>
                          <ThemedText type="mono" style={styles.rankValue}>
                            {r.account.interest_rate != null ? `${r.account.interest_rate}%` : '-'}
                          </ThemedText>
                        </ThemedView>
                      ))}
                    </ThemedView>
                  ) : null}
                </Surface>
              </Pressable>
            );
          })
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 12,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 4,
  },
  muted: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  flagged: {
    fontSize: 13,
    color: Colors.light.negative,
  },
  recommendation: {
    fontSize: 13,
    marginTop: 6,
  },
  loading: {
    marginTop: 32,
  },
  rankList: {
    marginTop: 10,
    gap: 4,
  },
  rankRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    gap: 8,
  },
  rankName: {
    flex: 1,
    fontSize: 12,
    opacity: 0.7,
    color: Colors.light.textMuted,
  },
  rankValue: {
    fontSize: 12,
  },
  error: {
    color: Colors.light.negative,
  },
});
