import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { Pressable, StyleSheet, View } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { IconSymbol, type IconSymbolName } from '@/components/ui/icon-symbol';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { SHARE_MODULE_ROUTE } from '@/lib/shareRequests';
import { supabase } from '@/lib/supabase';

type ModuleKey = 'travel' | 'cards' | 'accounts' | 'documents' | 'wishlist';

const MODULE_DEFS: { key: ModuleKey; label: string; icon: IconSymbolName }[] = [
  { key: 'travel', label: 'Travel', icon: 'airplane' },
  { key: 'cards', label: 'Cards', icon: 'creditcard' },
  { key: 'accounts', label: 'Accounts', icon: 'scalemass' },
  { key: 'documents', label: 'Documents', icon: 'folder.fill' },
  { key: 'wishlist', label: 'Wishlist', icon: 'mappin.and.ellipse' },
];

/**
 * Second nav row shown under a shared page's own title — every module the
 * partner has an ACCEPTED share to me for on this connection, so I can jump
 * between a connection's shared pages without going back through the swipe
 * panel each time. One-directional (checks requests to me, not a mutual
 * toggle) — matches the accept-based sharing model in lib/shareRequests.ts.
 *
 * A plain static row, NOT a horizontally-scrolling strip of auto-width
 * chips. Each tile is flex:1 so the row always exactly fills the available
 * width and splits it evenly across however many modules are shared on
 * THIS connection — a fixed pixel width was tried here before and
 * overflowed off the right edge of the screen once a connection had all 4
 * modules shared (4 * 84px + gaps exceeds most phones' usable width). Since
 * every shared page renders this same component, the layout is identical
 * across pages for a given connection by construction.
 */
export function SharedModuleNav({
  connectionId,
  accentColor,
  active,
}: {
  connectionId: string;
  accentColor: string;
  active: ModuleKey;
}) {
  const router = useRouter();
  const { session } = useAuth();
  const [enabled, setEnabled] = useState<Set<ModuleKey>>(new Set());
  const [isLoading, setIsLoading] = useState(true);

  const load = useCallback(async () => {
    if (!session) return;
    // Wishlist has no request/accept step to check here at all (see
    // app/countries/wishlist/[id].tsx) — its tab shows whenever the owner
    // has actually shared at least one city with me on this connection,
    // checked separately from the other modules' accepted-request rows.
    const [requestsResult, wishlistResult] = await Promise.all([
      supabase
        .from('connection_share_requests')
        .select('module')
        .eq('connection_id', connectionId)
        .eq('to_user_id', session.user.id)
        .eq('status', 'accepted'),
      supabase.rpc('shared_wishlist_cities', { p_connection_id: connectionId }),
    ]);

    const next = new Set<ModuleKey>();
    for (const row of requestsResult.data ?? []) {
      next.add(SHARE_MODULE_ROUTE[row.module]);
    }
    if ((wishlistResult.data ?? []).length > 0) next.add('wishlist');
    setEnabled(next);
    setIsLoading(false);
  }, [session, connectionId]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  if (isLoading || enabled.size <= 1) return null;

  return (
    <View style={styles.row}>
      {MODULE_DEFS.filter((m) => enabled.has(m.key)).map((m) => {
        const isActive = m.key === active;
        return (
          <Pressable
            key={m.key}
            onPress={() => {
              if (!isActive) router.push(`/connections/${connectionId}/${m.key}`);
            }}
            style={[
              styles.tile,
              { borderColor: accentColor },
              isActive ? { backgroundColor: accentColor } : null,
            ]}>
            <IconSymbol name={m.icon} size={16} color={isActive ? Colors.light.backgroundSolid : accentColor} />
            <ThemedText
              numberOfLines={1}
              style={[styles.tileText, isActive ? styles.tileTextActive : { color: accentColor }]}>
              {m.label}
            </ThemedText>
          </Pressable>
        );
      })}
    </View>
  );
}

const styles = StyleSheet.create({
  row: {
    flexDirection: 'row',
    gap: 8,
    paddingHorizontal: 16,
    paddingBottom: 8,
  },
  tile: {
    flex: 1,
    alignItems: 'center',
    gap: 4,
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 12,
    paddingVertical: 10,
  },
  tileText: {
    fontSize: 12,
  },
  tileTextActive: {
    color: Colors.light.backgroundSolid,
    fontWeight: '600',
  },
});
