import { useState } from 'react';
import { Pressable, ScrollView, StyleSheet } from 'react-native';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { formatMoney } from '@/lib/currency';
import { DEMO_CSV_FILE_NAME, DEMO_CSV_RAW_HEADER, DEMO_CSV_ROWS } from '@/lib/demoData';
import { formatDateDisplay } from '@/lib/format';

const ACCENT = ModuleAccents.spend;

type Step = 'upload' | 'mapping' | 'summary' | 'done';

const STEP_ORDER: Step[] = ['upload', 'mapping', 'summary', 'done'];

/**
 * Illustrates the real CSV import flow (app/transactions/import.tsx) —
 * upload, column mapping, preview, done — using a fabricated statement
 * instead of a real file picker. A brand-new account has nothing to
 * actually import yet, so this walks through the same four steps with
 * canned data instead. Purely local `step` state; nothing here parses a
 * real file or writes to Supabase.
 */
export default function DemoCsvImportScreen() {
  const [step, setStep] = useState<Step>('upload');
  const stepPosition = STEP_ORDER.indexOf(step);

  function advance() {
    const next = STEP_ORDER[Math.min(stepPosition + 1, STEP_ORDER.length - 1)];
    setStep(next);
  }

  const matchedCount = DEMO_CSV_ROWS.filter((r) => r.matchedCategory).length;

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedText type="title" style={{ color: ACCENT }}>
          Import from CSV
        </ThemedText>
        <ThemedText style={styles.muted}>
          Example bank statement, nothing here is really imported. This is the exact flow you&apos;ll use for your
          own statements later.
        </ThemedText>

        {step === 'upload' ? (
          <Surface accentColor={ACCENT}>
            <ThemedText type="defaultSemiBold">1. Upload a statement</ThemedText>
            <ThemedText style={styles.muted}>
              Export a CSV from your bank or card issuer, then pick it here. Works the same on web and mobile.
            </ThemedText>
            <ThemedView style={styles.filePickerRow}>
              <ThemedText style={styles.fileName}>{DEMO_CSV_FILE_NAME}</ThemedText>
              <ThemedText style={styles.muted}>{DEMO_CSV_ROWS.length} rows detected</ThemedText>
            </ThemedView>
            <ThemedText type="mono" style={styles.rawHeader} numberOfLines={1}>
              {DEMO_CSV_RAW_HEADER}
            </ThemedText>
          </Surface>
        ) : null}

        {step === 'mapping' ? (
          <Surface accentColor={ACCENT}>
            <ThemedText type="defaultSemiBold">2. Match the columns</ThemedText>
            <ThemedText style={styles.muted}>
              Tell Cluster which column is which. Every bank labels these differently, so this only has to be set
              once per statement format.
            </ThemedText>
            {[
              { field: 'Date', column: 'Transaction Date' },
              { field: 'Merchant', column: 'Description' },
              { field: 'Amount', column: 'Amount' },
            ].map((mapping) => (
              <ThemedView key={mapping.field} style={styles.mappingRow}>
                <ThemedText style={styles.muted}>{mapping.field}</ThemedText>
                <ThemedView style={[styles.mappingChip, { borderColor: ACCENT }]}>
                  <ThemedText style={{ color: ACCENT }}>{mapping.column}</ThemedText>
                </ThemedView>
              </ThemedView>
            ))}
          </Surface>
        ) : null}

        {step === 'summary' || step === 'done' ? (
          <Surface accentColor={ACCENT}>
            <ThemedText type="defaultSemiBold">
              {step === 'done' ? `${DEMO_CSV_ROWS.length} transactions imported` : '3. Review before importing'}
            </ThemedText>
            <ThemedText style={styles.muted}>
              {matchedCount} of {DEMO_CSV_ROWS.length} auto-categorized from merchant rules you&apos;ve set up.
              Everything else lands as Uncategorized, ready to sort later.
            </ThemedText>
            {DEMO_CSV_ROWS.map((row) => (
              <ThemedView key={row.description} style={styles.previewRow}>
                <ThemedView style={styles.flexShrink}>
                  <ThemedText numberOfLines={1}>{row.description}</ThemedText>
                  <ThemedText style={styles.muted}>{formatDateDisplay(row.date)}</ThemedText>
                </ThemedView>
                <ThemedView style={{ alignItems: 'flex-end' }}>
                  <ThemedText type="mono">{formatMoney(Math.abs(row.amount), 'USD')}</ThemedText>
                  <ThemedText style={styles.muted}>{row.matchedCategory ?? 'Uncategorized'}</ThemedText>
                </ThemedView>
              </ThemedView>
            ))}
          </Surface>
        ) : null}

        {step !== 'done' ? (
          <Pressable onPress={advance} style={[styles.button, { backgroundColor: ACCENT }]}>
            <ThemedText style={{ color: ModuleAccentOnColor.spend, fontWeight: '600' }}>
              {step === 'summary' ? 'Import' : 'Continue'}
            </ThemedText>
          </Pressable>
        ) : (
          <ThemedText style={[styles.muted, styles.sectionSpacing]}>
            That&apos;s the whole flow. Find it for real from any account or card&apos;s detail page.
          </ThemedText>
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 12,
    paddingBottom: 96,
  },
  filePickerRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginTop: 4,
  },
  fileName: {
    fontWeight: '600',
  },
  rawHeader: {
    fontSize: 12,
    opacity: 0.6,
    color: Colors.light.textMuted,
    marginTop: 6,
  },
  mappingRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingVertical: 4,
  },
  mappingChip: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 14,
    paddingHorizontal: 12,
    paddingVertical: 5,
  },
  previewRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 8,
    paddingVertical: 6,
    borderTopWidth: StyleSheet.hairlineWidth,
    borderTopColor: Colors.light.icon,
  },
  flexShrink: {
    flexShrink: 1,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 14,
    alignItems: 'center',
  },
  sectionSpacing: {
    marginTop: 8,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
});
