import { useFocusEffect } from '@react-navigation/native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useCallback, useEffect, useState } from 'react';
import * as WebBrowser from 'expo-web-browser';
import { ActivityIndicator, Pressable, StyleSheet, TextInput } from 'react-native';
import { KeyboardAwareScrollView, KeyboardStickyView } from 'react-native-keyboard-controller';

import { CountryFlag } from '@/components/country-flag';
import { SelectModal, type SelectOption } from '@/components/select-modal';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { useConnectionDisplay } from '@/hooks/use-connection-display';
import { useCurrency } from '@/contexts/currency-context';
import { formatDateTimeDisplay } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import type { DocumentRow, SharedTripNoteRow } from '@/types/database';

const ACCENT = ModuleAccents.countries;
const SIGNED_URL_EXPIRY_SECONDS = 300;

type NoteAttachment = { id: string; name: string; doc_type: string; file_ref: string };

export default function SharedTripNotesScreen() {
  const { connectionId, country } = useLocalSearchParams<{ connectionId: string; country: string }>();
  const router = useRouter();
  const { session } = useAuth();
  const { hiddenFlagCountries } = useCurrency();
  const display = useConnectionDisplay(connectionId);

  const [notes, setNotes] = useState<SharedTripNoteRow[]>([]);
  const [attachmentByNoteId, setAttachmentByNoteId] = useState<Map<string, NoteAttachment>>(new Map());
  const [draft, setDraft] = useState('');
  const [attachedDocumentId, setAttachedDocumentId] = useState<string | null>(null);
  const [myDocuments, setMyDocuments] = useState<DocumentRow[]>([]);
  const [showDocPicker, setShowDocPicker] = useState(false);
  const [editingNoteId, setEditingNoteId] = useState<string | null>(null);
  const [editDraft, setEditDraft] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  // The trip this planning page is "about" — preferring one that's actually
  // shared (joint_group_id set) over a personal, unrelated trip to the same
  // country, since that's what these notes are really discussing. Null
  // until a matching trip is found (or if there isn't one logged yet),
  // in which case the title just isn't tappable.
  const [myTripId, setMyTripId] = useState<string | null>(null);

  // Only writes via the functional setState updater below, never reads
  // attachmentByNoteId to decide what to fetch — avoids a stale-closure
  // bug where this function (captured once by the realtime effect below)
  // would otherwise keep checking a Map frozen at mount time. Slightly
  // redundant re-fetching on reload is a fine trade for correctness here.
  const fetchAttachments = useCallback(async (rows: SharedTripNoteRow[]) => {
    const withDocs = rows.filter((r) => r.document_id);
    if (withDocs.length === 0) return;
    const results = await Promise.all(
      withDocs.map((r) => supabase.rpc('shared_trip_note_document', { p_note_id: r.id }).maybeSingle())
    );
    setAttachmentByNoteId((prev) => {
      const next = new Map(prev);
      withDocs.forEach((r, index) => {
        const data = results[index].data;
        if (data) next.set(r.id, data);
      });
      return next;
    });
  }, []);

  useEffect(() => {
    let cancelled = false;
    supabase
      .from('countries_visited')
      .select('trip_id')
      .eq('country', country)
      .not('trip_id', 'is', null)
      .then(async ({ data: visits }) => {
        if (cancelled) return;
        const tripIds = Array.from(
          new Set((visits ?? []).map((v) => v.trip_id).filter((tid): tid is string => !!tid))
        );
        if (tripIds.length === 0) return;
        const { data: trips } = await supabase.from('trips').select('id, joint_group_id').in('id', tripIds);
        if (cancelled || !trips || trips.length === 0) return;
        const jointTrip = trips.find((t) => t.joint_group_id);
        setMyTripId((jointTrip ?? trips[0]).id);
      });
    return () => {
      cancelled = true;
    };
  }, [country]);

  const load = useCallback(async () => {
    setError(null);
    const { data, error: fetchError } = await supabase
      .from('shared_trip_notes')
      .select('*')
      .eq('connection_id', connectionId)
      .eq('country', country)
      .order('created_at', { ascending: true });
    if (fetchError) {
      setError(fetchError.message);
    } else {
      setNotes(data ?? []);
      void fetchAttachments(data ?? []);
    }
    setIsLoading(false);
  }, [connectionId, country, fetchAttachments]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  // Live updates — either party's edits/adds/deletes show up without
  // needing to leave and refocus this screen. Filtered to this connection
  // server-side; country is filtered client-side since Realtime's simple
  // filter syntax only covers one column cleanly.
  useEffect(() => {
    const channel = supabase
      .channel(`shared-trip-notes-${connectionId}`)
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'shared_trip_notes', filter: `connection_id=eq.${connectionId}` },
        (payload) => {
          if (payload.eventType === 'DELETE') {
            const oldRow = payload.old as { id: string };
            setNotes((prev) => prev.filter((n) => n.id !== oldRow.id));
            return;
          }
          const row = payload.new as SharedTripNoteRow;
          if (row.country !== country) return;
          if (payload.eventType === 'INSERT') {
            setNotes((prev) =>
              prev.some((n) => n.id === row.id)
                ? prev
                : [...prev, row].sort((a, b) => (a.created_at < b.created_at ? -1 : 1))
            );
            void fetchAttachments([row]);
          } else if (payload.eventType === 'UPDATE') {
            setNotes((prev) => prev.map((n) => (n.id === row.id ? row : n)));
            void fetchAttachments([row]);
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [connectionId, country, fetchAttachments]);

  async function handleSend() {
    if (!session || !draft.trim()) return;
    setIsSaving(true);
    setError(null);
    const { error: insertError } = await supabase.from('shared_trip_notes').insert({
      connection_id: connectionId,
      country,
      author_id: session.user.id,
      note: draft.trim(),
      document_id: attachedDocumentId,
    });
    setIsSaving(false);
    if (insertError) {
      setError(insertError.message);
      return;
    }
    setDraft('');
    setAttachedDocumentId(null);
    await load();
  }

  async function handleDelete(id: string) {
    setError(null);
    const { error: deleteError } = await supabase.from('shared_trip_notes').delete().eq('id', id);
    if (deleteError) {
      setError(deleteError.message);
      return;
    }
    setNotes((prev) => prev.filter((n) => n.id !== id));
  }

  function startEdit(note: SharedTripNoteRow) {
    setEditingNoteId(note.id);
    setEditDraft(note.note);
  }

  function cancelEdit() {
    setEditingNoteId(null);
    setEditDraft('');
  }

  async function saveEdit(id: string) {
    if (!editDraft.trim()) return;
    setError(null);
    const { error: updateError } = await supabase
      .from('shared_trip_notes')
      .update({ note: editDraft.trim() })
      .eq('id', id);
    if (updateError) {
      setError(updateError.message);
      return;
    }
    setNotes((prev) =>
      prev.map((n) => (n.id === id ? { ...n, note: editDraft.trim(), updated_at: new Date().toISOString() } : n))
    );
    setEditingNoteId(null);
    setEditDraft('');
  }

  async function handleOpenDocPicker() {
    if (!session) return;
    setError(null);
    const { data, error: fetchError } = await supabase
      .from('documents')
      .select('*')
      .eq('user_id', session.user.id)
      .order('name');
    if (fetchError) {
      setError(fetchError.message);
      return;
    }
    if ((data ?? []).length === 0) {
      setError('No documents to attach yet. Add one from the Documents tab first.');
      return;
    }
    setMyDocuments(data ?? []);
    setShowDocPicker(true);
  }

  async function handleOpenAttachment(noteId: string) {
    const attachment = attachmentByNoteId.get(noteId);
    if (!attachment) return;
    setError(null);
    const { data, error: signedError } = await supabase.storage
      .from('documents')
      .createSignedUrl(attachment.file_ref, SIGNED_URL_EXPIRY_SECONDS);
    if (signedError || !data?.signedUrl) {
      // Temporarily surfacing the raw error (name/status/message) rather
      // than just .message, which Supabase's storage client sometimes
      // truncates to a generic "Object not found" that masks the real
      // cause (RLS denial vs. missing object vs. something else).
      const raw = signedError as { name?: string; status?: number; statusCode?: string; message?: string } | null;
      setError(
        raw
          ? `[${raw.status ?? raw.statusCode ?? '?'}] ${raw.name ?? 'Error'}: ${raw.message ?? 'unknown'}`
          : 'Could not open attachment (no signed URL returned).'
      );
      return;
    }
    await WebBrowser.openBrowserAsync(data.signedUrl);
  }

  const docPickerOptions: SelectOption[] = myDocuments.map((doc) => ({ value: doc.id, label: doc.name }));
  const attachedDocumentName = myDocuments.find((doc) => doc.id === attachedDocumentId)?.name ?? null;

  return (
    <ThemedView variant="screen" style={styles.flex} keyboardAvoiding={false}>
      <ThemedView style={styles.titleRow}>
          <Pressable
            disabled={!myTripId}
            onPress={() => myTripId && router.push(`/countries/trips/${myTripId}`)}
            style={styles.titleWithFlag}>
            <CountryFlag countryName={country} hiddenFlagCountries={hiddenFlagCountries} size={28} />
            <ThemedText
              type="title"
              style={[{ color: ACCENT }, styles.titleText]}
              numberOfLines={1}
              adjustsFontSizeToFit>
              {country} Planning
            </ThemedText>
          </Pressable>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedText style={styles.hint}>
          Visible only to you and {display.displayName}, not shared with any other connections. Either of you can
          edit or delete any note here.
        </ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {isLoading ? (
          <ActivityIndicator color={ACCENT} style={styles.loading} />
        ) : (
          <KeyboardAwareScrollView style={styles.flex} contentContainerStyle={styles.notesList}>
            {notes.length === 0 ? (
              <ThemedText style={styles.hint}>No notes yet. Add the first one below.</ThemedText>
            ) : null}
            {notes.map((n) => {
              const isMine = n.author_id === session?.user.id;
              const isEditing = editingNoteId === n.id;
              const attachment = n.document_id ? attachmentByNoteId.get(n.id) : null;
              return (
                <Surface key={n.id} accentColor={ACCENT} style={styles.noteCard}>
                  <ThemedView style={styles.noteHeader}>
                    <ThemedView style={styles.noteMeta}>
                      <ThemedText style={styles.noteAuthor}>{isMine ? 'You' : display.displayName}</ThemedText>
                      <ThemedText style={styles.noteTimestamp}>
                        {n.updated_at !== n.created_at ? 'Edited ' : ''}
                        {formatDateTimeDisplay(n.updated_at)}
                      </ThemedText>
                    </ThemedView>
                    {!isEditing ? (
                      <ThemedView style={styles.noteActions}>
                        <Pressable onPress={() => startEdit(n)} hitSlop={12}>
                          <IconSymbol name="pencil" size={16} color={Colors.light.textMuted} />
                        </Pressable>
                        <Pressable onPress={() => handleDelete(n.id)} hitSlop={12}>
                          <IconSymbol name="trash" size={16} color={Colors.light.negative} />
                        </Pressable>
                      </ThemedView>
                    ) : null}
                  </ThemedView>
                  {isEditing ? (
                    <>
                      <TextInput
                        value={editDraft}
                        onChangeText={setEditDraft}
                        multiline
                        style={[styles.input, { borderColor: ACCENT }]}
                      />
                      <ThemedView style={styles.editActions}>
                        <Pressable onPress={cancelEdit}>
                          <ThemedText style={styles.muted}>Cancel</ThemedText>
                        </Pressable>
                        <Pressable onPress={() => saveEdit(n.id)}>
                          <ThemedText style={{ color: ACCENT, fontWeight: '600' }}>Save</ThemedText>
                        </Pressable>
                      </ThemedView>
                    </>
                  ) : (
                    <ThemedText>{n.note}</ThemedText>
                  )}
                  {n.document_id ? (
                    <Pressable onPress={() => handleOpenAttachment(n.id)} style={styles.attachmentRow} hitSlop={4}>
                      <IconSymbol name="paperclip" size={14} color={ACCENT} />
                      <ThemedText style={[styles.attachmentText, { color: ACCENT }]} numberOfLines={1}>
                        {attachment?.name ?? 'Attached document'}
                      </ThemedText>
                    </Pressable>
                  ) : null}
                </Surface>
              );
            })}
          </KeyboardAwareScrollView>
        )}

        <KeyboardStickyView>
          {attachedDocumentName ? (
            <ThemedView style={styles.attachedPreview}>
              <IconSymbol name="paperclip" size={14} color={ACCENT} />
              <ThemedText style={[styles.attachmentText, { color: ACCENT }]} numberOfLines={1}>
                {attachedDocumentName}
              </ThemedText>
              <Pressable onPress={() => setAttachedDocumentId(null)} hitSlop={8}>
                <ThemedText style={styles.muted}>Remove</ThemedText>
              </Pressable>
            </ThemedView>
          ) : null}

          <ThemedView style={styles.composerRow}>
            <Pressable onPress={handleOpenDocPicker} style={styles.attachButton} hitSlop={8}>
              <IconSymbol name="paperclip" size={20} color={ACCENT} />
            </Pressable>
            <TextInput
              value={draft}
              onChangeText={setDraft}
              placeholder="Add a note..."
              placeholderTextColor={Colors.light.textMuted}
              style={[styles.input, styles.composerInput, { borderColor: ACCENT }]}
              multiline
            />
            <Pressable
              onPress={handleSend}
              disabled={isSaving || !draft.trim()}
              style={[styles.sendButton, { backgroundColor: ACCENT, opacity: isSaving || !draft.trim() ? 0.5 : 1 }]}>
              <IconSymbol name="paperplane.fill" size={18} color={Colors.light.backgroundSolid} />
            </Pressable>
          </ThemedView>
        </KeyboardStickyView>

      <SelectModal
        visible={showDocPicker}
        onClose={() => setShowDocPicker(false)}
        options={docPickerOptions}
        selectedValue={attachedDocumentId}
        onSelect={setAttachedDocumentId}
      />
    </ThemedView>
  );
}

