// Trimmed from 58 to offset the new X-axis label strip added below (see
// HOME_CHART_X_AXIS_HEIGHT) — keeps this card's total footprint close to
// what the earlier "fit without scrolling" pass already tuned for.
const CHART_HEIGHT = 46;
const WHEEL_ZONE_PADDING_BOTTOM = 8;

type TileKey = 'cash' | 'invest' | 'cards' | 'liabilities';

/** "Good Morning"/"Afternoon"/"Evening" by local wall-clock hour — both words capitalized, matching the mockup's title-case greeting. */
function timeOfDayGreeting(hour: number): string {
  if (hour < 12) return 'Good Morning';
  if (hour < 17) return 'Good Afternoon';
  return 'Good Evening';
}

/**
 * All four tiles always share the same fixed WIDTH and, at rest, the same
 * HEIGHT and full content. Selecting one drops ALL FOUR (not just the
 * others) to a short icon-only row — per the user's own sketch, this is
 * deliberately two plain stacked rows (icon strip, then a full-width graph
 * card below it) rather than one tile staying tall and the graph rendered
 * behind/under the others. That earlier layered approach depended on the
 * selected tile's opaque background reliably painting over the graph
 * behind it, which turned out to be an unreliable assumption on Android
 * (its stacking order for absolutely-positioned + elevated siblings didn't
 * match plain JSX order, so the graph's text bled through). Two
 * non-overlapping flow rows have no stacking order to get wrong.
 */
function SummaryTile({
  icon,
  symbolText,
  label,
  iconColor,
  badgeColor,
  value,
  currency,
  hideValue,
  highlighted,
  compact,
  onToggle,
}: {
  /** Mutually exclusive with symbolText — provide exactly one. */
  icon?: IconSymbolName;
  /** A short text glyph (e.g. a currency symbol) instead of an IconSymbol — used for Cash, since the wheel's own money-bag icon is already "Wealth" and reusing it on this tile read as the same thing twice. */
  symbolText?: string;
  label: string;
  /** Icon/sparkline/change% color — the mockup's per-tile "icon" hex, not a wheel module accent. */
  iconColor: string;
  /** Icon badge background — the mockup's per-tile pale "light" hex, a dedicated color rather than a computed tint of iconColor. */
  badgeColor: string;
  value: TileValue;
  currency: string;
  /** Privacy toggle — masks the dollar figure only; the %-change stays visible since it doesn't reveal an absolute amount. */
  hideValue: boolean;
  /** This exact tile is the one currently expanded — border accent only, independent of compact (both states can be true at once). */
  highlighted: boolean;
  /** True on ALL FOUR tiles whenever any one of them is expanded — icon only, label/value/change% hidden, to make room for the graph row below. */
  compact: boolean;
  onToggle: () => void;
}) {
  const isUp = value.changePct != null && value.changePct >= 0;
  return (
    <Pressable
      onPress={onToggle}
      style={[
        styles.tile,
        compact ? styles.tileCompact : null,
        // Always present (never added/removed from the array) — border
        // width/color toggling in and out of the style entirely, rather
        // than staying present with a changing value, left a residual
        // gray border-shaped box behind after a tile was deselected. The
        // border is always there, just invisible (transparent) when not
        // highlighted.
        { borderWidth: 1.5, borderColor: highlighted ? HomePalette.emerald2 : 'transparent' },
      ]}>
      <ThemedView
        style={[styles.tileIconBadge, { backgroundColor: badgeColor }, compact ? styles.tileIconBadgeCompact : null]}>
        {icon ? (
          <IconSymbol name={icon} size={14} color={iconColor} />
        ) : (
          <ThemedText style={[styles.tileSymbol, { color: iconColor }]}>{symbolText}</ThemedText>
        )}
      </ThemedView>
      {!compact ? (
        <>
          <ThemedText style={styles.tileLabel} numberOfLines={1}>
            {label}
          </ThemedText>
          <ThemedText style={styles.tileValue} numberOfLines={1} adjustsFontSizeToFit>
            {hideValue ? '••••' : formatMoney(value.current, currency, { decimals: 0 })}
          </ThemedText>
          {value.changePct != null ? (
            <ThemedText style={[styles.tileChange, { color: isUp ? Colors.light.positive : Colors.light.negative }]}>
              {isUp ? '↗' : '↘'} {Math.abs(value.changePct).toFixed(2)}%
            </ThemedText>
          ) : null}
        </>
      ) : null}
    </Pressable>
  );
}

/**
 * The graph card shown below the tile row once one is expanded — a plain
 * flow sibling underneath tileRow, not layered behind it (see SummaryTile's
 * doc comment for why). Carries a small icon badge + label identifying
 * which tile it belongs to (matching the user's sketch), plus min/max value
 * labels next to the line so the trend reads as an actual scale.
 */
function TileTrendStrip({
  icon,
  symbolText,
  label,
  color,
  badgeColor,
  value,
  currency,
  hideValue,
  history,
  historyDates,
}: {
  icon?: IconSymbolName;
  symbolText?: string;
  label: string;
  color: string;
  badgeColor: string;
  value: TileValue;
  currency: string;
  hideValue: boolean;
  history: number[];
  /** Same length/order as history — 5 month-ends + today, see app/index.tsx's tileHistoryDates. Only the first/middle/last get an actual label below; this strip is too small to show all 6 without crowding. */
  historyDates: Date[];
}) {
  const [chartWidth, setChartWidth] = useState(0);
  const chartHeight = 50;
  const hasHistory = history.length >= 2;
  const isUp = value.changePct != null && value.changePct >= 0;

  const max = hasHistory ? Math.max(...history) : value.current;
  const min = hasHistory ? Math.min(...history) : value.current;
  const range = max - min || Math.abs(max) || 1;
  const domainPad = range * 0.15;
  const domainMax = max + domainPad;
  const domainMin = min - domainPad;
  const domainRange = domainMax - domainMin || 1;
  // Labeled/gridlined at "nice" round values (niceTicks — same algorithm
  // every other chart in this app uses), not the raw data max/min — an
  // actual balance like 31,397 is real, but it isn't a ROUND axis number,
  // and showing it as one read as broken/unrounded rather than a
  // deliberate exact figure. 4 ticks (not 2) — same TICK_COUNT the
  // candlestick/line/bar charts use, so this genuinely scales its own
  // gridlines to the data's actual range instead of just bounding the top
  // and bottom.
  const ticks = hasHistory ? niceTicks(domainMin, domainMax, 4).filter((t) => t >= domainMin && t <= domainMax) : [];
  const axisUnit = axisUnitFor(ticks);
  const topTick = ticks[ticks.length - 1];

  function toY(v: number): number {
    return chartHeight - ((v - domainMin) / domainRange) * chartHeight;
  }
  function toX(i: number): number {
    return (i / (history.length - 1)) * chartWidth;
  }

  return (
    <View style={styles.tileGraphStrip}>
      <View style={styles.tileGraphHeader}>
        <View style={styles.tileGraphHeaderLeft}>
          <ThemedView style={[styles.tileGraphBadge, { backgroundColor: badgeColor }]}>
            {icon ? (
              <IconSymbol name={icon} size={11} color={color} />
            ) : (
              <ThemedText style={[styles.tileGraphBadgeSymbol, { color }]}>{symbolText}</ThemedText>
            )}
          </ThemedView>
          <ThemedText style={styles.tileGraphLabel} numberOfLines={1}>
            {label} · last 5 months
          </ThemedText>
        </View>
        {value.changePct != null ? (
          <ThemedText
            style={[styles.tileGraphChange, { color: isUp ? Colors.light.positive : Colors.light.negative }]}
            numberOfLines={1}>
            {isUp ? '↗' : '↘'} {Math.abs(value.changePct).toFixed(2)}%
          </ThemedText>
        ) : null}
      </View>
      <View style={styles.tileGraphBody}>
        <View style={styles.tileGraphAxis}>
          {ticks.map((tick) => (
            <ThemedText
              key={tick}
              style={[styles.tileGraphAxisText, { top: Math.min(Math.max(toY(tick) - 6, 0), chartHeight - 12) }]}
              numberOfLines={1}>
              {hideValue ? '••••' : formatAxisTick(tick, currency, axisUnit, tick === topTick)}
            </ThemedText>
          ))}
        </View>
        <View style={styles.tileGraphChartArea} onLayout={(e) => setChartWidth(e.nativeEvent.layout.width)}>
          {hasHistory && chartWidth > 0 ? (
            <Svg width={chartWidth} height={chartHeight}>
              {ticks.map((tick) => (
                <Polyline
                  key={tick}
                  points={`0,${toY(tick)} ${chartWidth},${toY(tick)}`}
                  stroke={HomePalette.line}
                  strokeWidth={1}
                />
              ))}
              <Polyline
                points={history.map((v, i) => `${toX(i)},${toY(v)}`).join(' ')}
                fill="none"
                stroke={color}
                strokeWidth={2}
                strokeLinejoin="round"
                strokeLinecap="round"
              />
              <Circle cx={toX(history.length - 1)} cy={toY(history[history.length - 1])} r={3} fill={color} />
            </Svg>
          ) : null}
        </View>
      </View>
      {hasHistory ? (
        <View style={styles.tileGraphXAxisRow}>
          <ThemedText style={styles.tileGraphXAxisText} numberOfLines={1}>
            {historyDates[0].toLocaleDateString(undefined, { month: 'short' })}
          </ThemedText>
          <ThemedText style={styles.tileGraphXAxisText} numberOfLines={1}>
            {historyDates[Math.floor((historyDates.length - 1) / 2)].toLocaleDateString(undefined, { month: 'short' })}
          </ThemedText>
          <ThemedText style={styles.tileGraphXAxisText} numberOfLines={1}>
            {historyDates[historyDates.length - 1].toLocaleDateString(undefined, { month: 'short' })}
          </ThemedText>
        </View>
      ) : null}
    </View>
  );
}

const HOME_CHART_AXIS_GUTTER = 36;
const HOME_CHART_X_AXIS_HEIGHT = 14;
const HOME_CHART_TICK_COUNT = 3;

function compactMonthLabel(dateStr: string): string {
  return new Date(dateStr).toLocaleDateString(undefined, { month: 'short' });
}

/** Home's own chart card — same shape as NetWorthSparkline (line + gradient fill + end dot), plus a real Y-axis (value scale) and X-axis (which months are covered) — every graph in this app is time-based, so the period actually surveyed needs to be visible alongside the value scale, not just a bare trend line. Kept local rather than changing the shared component, which other screens also use without axes. */
function HomeNetWorthChart({ candles, color, currency }: { candles: Candle[]; color: string; currency: string }) {
  const [width, setWidth] = useState(0);
  const outerHeight = CHART_HEIGHT + HOME_CHART_X_AXIS_HEIGHT;

  if (width === 0) {
    return <View onLayout={(e) => setWidth(e.nativeEvent.layout.width)} style={{ height: outerHeight }} />;
  }
  if (candles.length < 2) {
    return <View style={{ height: outerHeight }} />;
  }

  const values = candles.map((c) => c.close);
  const max = Math.max(...values);
  const min = Math.min(...values);
  const range = max - min || Math.abs(max) || 1;
  const padding = range * 0.15;
  const domainMax = max + padding;
  const domainMin = min - padding;
  const domainRange = domainMax - domainMin || 1;

  const ticks = niceTicks(domainMin, domainMax, HOME_CHART_TICK_COUNT).filter((t) => t >= domainMin && t <= domainMax);
  const axisUnit = axisUnitFor(ticks);
  const topTick = ticks[ticks.length - 1];
  const plotWidth = Math.max(width - HOME_CHART_AXIS_GUTTER, 0);
  // Same "skip candles so labels don't overlap" idea as components/
  // candlestick-chart.tsx, sized down for this card's much smaller width.
  const labelStep = Math.max(1, Math.ceil((32 * candles.length) / plotWidth));

  function toY(value: number): number {
    return CHART_HEIGHT - ((value - domainMin) / domainRange) * CHART_HEIGHT;
  }
  function toX(index: number): number {
    return HOME_CHART_AXIS_GUTTER + (index / (values.length - 1)) * plotWidth;
  }

  const linePoints = values.map((v, i) => `${toX(i)},${toY(v)}`).join(' ');
  const fillPoints = `${HOME_CHART_AXIS_GUTTER},${CHART_HEIGHT} ${linePoints} ${HOME_CHART_AXIS_GUTTER + plotWidth},${CHART_HEIGHT}`;
  const lastIndex = values.length - 1;

  return (
    <View style={{ height: outerHeight }}>
      {ticks.map((tick) => (
        <Text
          key={tick}
          numberOfLines={1}
          style={[styles.homeChartAxisLabel, { top: Math.min(Math.max(toY(tick) - 7, 0), CHART_HEIGHT - 14) }]}>
          {formatAxisTick(tick, currency, axisUnit, tick === topTick)}
        </Text>
      ))}
      <Svg width={width} height={CHART_HEIGHT} style={styles.homeChartPlot}>
        <Defs>
          <LinearGradient id="homeChartFill" x1="0" y1="0" x2="0" y2="1">
            <Stop offset="0%" stopColor={color} stopOpacity={0.18} />
            <Stop offset="100%" stopColor={color} stopOpacity={0} />
          </LinearGradient>
        </Defs>
        {ticks.map((tick) => (
          <Polyline
            key={tick}
            points={`${HOME_CHART_AXIS_GUTTER},${toY(tick)} ${HOME_CHART_AXIS_GUTTER + plotWidth},${toY(tick)}`}
            stroke={HomePalette.line}
            strokeWidth={1}
          />
        ))}
        <Polygon points={fillPoints} fill="url(#homeChartFill)" />
        <Polyline points={linePoints} fill="none" stroke={color} strokeWidth={2.5} strokeLinejoin="round" strokeLinecap="round" />
        <Circle cx={toX(lastIndex)} cy={toY(values[lastIndex])} r={4} fill={color} />
      </Svg>
      {candles.map((candle, index) => {
        if (index % labelStep !== 0 && index !== candles.length - 1) return null;
        return (
          <Text
            key={candle.periodStart}
            numberOfLines={1}
            style={[styles.homeChartXAxisLabel, { left: toX(index) - 16, top: CHART_HEIGHT + 1 }]}>
            {compactMonthLabel(candle.periodStart)}
          </Text>
        );
      })}
    </View>
  );
}

export default function HomeScreen() {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const { session } = useAuth();
  const { displayCurrency, homeCountry, availableCurrencies, convertToCurrency, needsOnboarding, isLoading: isCurrencyLoading, fullName } =
    useCurrency();
  const { filterTransactions, filterAccounts, filterSnapshots } = useScope();
  const [allTransactions, setTransactions] = useState<TransactionRow[]>([]);
  const [allAccounts, setAccounts] = useState<AccountRow[]>([]);
  const [allSnapshots, setSnapshots] = useState<BalanceSnapshotRow[]>([]);
  // Raw rows above, scope-filtered (All / Personal / Business) below —
  // every tile, the wheel and the change figures derive from these.
  const transactions = filterTransactions(allTransactions);
  const accounts = filterAccounts(allAccounts);
  const snapshots = filterSnapshots(allSnapshots);
  const [isLoading, setIsLoading] = useState(true);
  // Both Home-only prefs, persisted to user_settings (not lifted into
  // CurrencyProvider — nothing outside this screen reads either one).
  const [showBalances, setShowBalancesState] = useState(true);
  const [wheelRotation, setWheelRotation] = useState(0);
  // Set from Account settings, not here — Home only ever reads it.
  const [wheelSpinOnLoad, setWheelSpinOnLoad] = useState(true);
  const [expandedTile, setExpandedTile] = useState<TileKey | null>(null);
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();
  const noticeCount = useNoticeCount();
  const { step: tourStep } = useTour();
  const isWheelHighlighted = tourStep?.highlightAnchor === 'home-wheel';

  // Guards against a slower, earlier-started load() overwriting a newer
  // one's state after it resolves out of order — e.g. Home refocusing
  // repeatedly in quick succession (navigating away and back several times)
  // can have more than one load() in flight at once, and network responses
  // don't necessarily resolve in the order the requests were sent. Only the
  // result from the most recently *started* call is ever applied.
  const loadTokenRef = useRef(0);

  const load = useCallback(async () => {
    const token = ++loadTokenRef.current;
    const [txResult, accountsResult, snapshotsResult, prefsResult] = await Promise.all([
      fetchAllRows<TransactionRow>((from, to) =>
        supabase.from('transactions').select('*').order('date').order('id').range(from, to)
      ),
      supabase.from('accounts').select('*'),
      fetchAllRows<BalanceSnapshotRow>((from, to) =>
        supabase.from('balance_snapshots').select('*').order('date').order('id').range(from, to)
      ),
      session
        ? supabase
            .from('user_settings')
            .select('show_balances, wheel_rotation_degrees, wheel_spin_on_load')
            .eq('user_id', session.user.id)
            .maybeSingle()
        : Promise.resolve({ data: null }),
    ]);
    if (token !== loadTokenRef.current) return;

    setTransactions(txResult.data);
    setAccounts(accountsResult.data ?? []);
    setSnapshots(snapshotsResult.data);
    if (prefsResult.data) {
      setShowBalancesState(prefsResult.data.show_balances ?? true);
      setWheelRotation(prefsResult.data.wheel_rotation_degrees ?? 0);
      setWheelSpinOnLoad(prefsResult.data.wheel_spin_on_load ?? true);
    }
    setIsLoading(false);
    // Keyed on the stable user id, not the session object — see the same
    // note in contexts/currency-context.tsx: Supabase hands back a new
    // session reference on every token refresh, which would otherwise
    // re-run this on a timer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [session?.user.id]);

  async function handleSetShowBalances(value: boolean) {
    setShowBalancesState(value);
    if (!session) return;
    const { error } = await supabase
      .from('user_settings')
      .upsert({ user_id: session.user.id, show_balances: value }, { onConflict: 'user_id' });
    if (error) {
      console.error('Failed to save show-balances preference:', error.message);
      setShowBalancesState(!value);
    }
  }

  async function handleWheelRotationChange(degrees: number) {
    setWheelRotation(degrees);
    if (!session) return;
    const { error } = await supabase
      .from('user_settings')
      .upsert({ user_id: session.user.id, wheel_rotation_degrees: degrees }, { onConflict: 'user_id' });
    if (error) {
      console.error('Failed to save wheel rotation:', error.message);
    }
  }

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  if (!isCurrencyLoading && needsOnboarding) {
    return <Redirect href="/onboarding" />;
  }

  const wealthCurrency = resolveWealthCurrency(displayCurrency, homeCountry, availableCurrencies);
  const convert = (amount: number, fromCurrency: string) => convertToCurrency(amount, fromCurrency, wealthCurrency.currency);

  const netWorth = isLoading
    ? 0
    : computeCurrentBalance({
        transactions,
        accounts,
        balanceSnapshots: snapshots,
        convert,
      });

  const rawName = fullName?.trim() || session?.user.email?.split('@')[0] || null;
  const firstName = rawName ? rawName.split(/\s+/)[0] : null;
  const now = new Date();
  const greeting = timeOfDayGreeting(now.getHours());
  const todayLabel = now.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' }).toUpperCase();
  // Shared X-axis for every tile's expanded graph below — same 5-month-end
  // + today points every computeCategoryTileHistory/computeCardOutstandingHistory
  // call already builds its own history off, so this just mirrors that date
  // math once rather than re-deriving it per tile.
  const tileHistoryDates = [...priorMonthEnds(now, 5), now];

  const cashTile = computeCategoryTile(
    accounts,
    transactions,
    snapshots,
    (a) => a.account_type === 'asset' && a.asset_category === 'cash',
    convert,
    now
  );
  const cashHistory = computeCategoryTileHistory(
    accounts,
    transactions,
    snapshots,
    (a) => a.account_type === 'asset' && a.asset_category === 'cash',
    convert,
    now
  );
  const investmentsTile = computeCategoryTile(
    accounts,
    transactions,
    snapshots,
    // real_estate folds in here rather than getting its own tile.
    (a) => a.account_type === 'asset' && (a.asset_category === 'investment' || a.asset_category === 'real_estate'),
    convert,
    now
  );
  const investmentsHistory = computeCategoryTileHistory(
    accounts,
    transactions,
    snapshots,
    (a) => a.account_type === 'asset' && (a.asset_category === 'investment' || a.asset_category === 'real_estate'),
    convert,
    now
  );
  const cardOutstandingTile = computeCardOutstandingTile(transactions, convert, now);
  const cardOutstandingHistory = computeCardOutstandingHistory(transactions, convert, now);
  const otherLiabilitiesTile = computeCategoryTile(
    accounts,
    transactions,
    snapshots,
    (a) => a.account_type === 'liability',
    convert,
    now,
    { negate: true }
  );
  const otherLiabilitiesHistory = computeCategoryTileHistory(
    accounts,
    transactions,
    snapshots,
    (a) => a.account_type === 'liability',
    convert,
    now,
    { negate: true }
  );

  const ytdPeriods = generatePeriods('month', now.getMonth() + 1, now);
  const ytdCandles = isLoading ? [] : computeWealthSeries({ transactions, accounts, balanceSnapshots: snapshots, periods: ytdPeriods, convert });
  const ytdValues = ytdCandles.map((c) => c.close);
  const ytdTrendUp = ytdValues.length > 1 ? ytdValues[ytdValues.length - 1] >= ytdValues[0] : true;

  function toggleTile(key: TileKey) {
    setExpandedTile((prev) => (prev === key ? null : key));
  }

  const expandedTileGraph =
    expandedTile === 'cash'
      ? {
          symbolText: currencySymbol(wealthCurrency.currency),
          label: 'Cash',
          value: cashTile,
          history: cashHistory,
          color: HomeTileColors.cash.icon,
          badgeColor: HomeTileColors.cash.badge,
        }
      : expandedTile === 'invest'
        ? {
            icon: 'chart.line.uptrend.xyaxis' as IconSymbolName,
            label: 'Invest',
            value: investmentsTile,
            history: investmentsHistory,
            color: HomeTileColors.invest.icon,
            badgeColor: HomeTileColors.invest.badge,
          }
        : expandedTile === 'cards'
          ? {
              icon: 'creditcard' as IconSymbolName,
              label: 'Credit cards',
              value: cardOutstandingTile,
              history: cardOutstandingHistory,
              color: HomeTileColors.cards.icon,
              badgeColor: HomeTileColors.cards.badge,
            }
          : expandedTile === 'liabilities'
            ? {
                icon: 'scalemass' as IconSymbolName,
                label: 'Other liabilities',
                value: otherLiabilitiesTile,
                history: otherLiabilitiesHistory,
                color: HomeTileColors.liabilities.icon,
                badgeColor: HomeTileColors.liabilities.badge,
              }
            : null;

  return (
    <View style={styles.container}>
      <HomeIridescentBackground />
      <ConnectionsSwipePanel
        connections={swipeConnections}
        isLoading={isConnectionsLoading}
        accentColor={ModuleAccents.wealth}
        destinationModule="travel">
        <ScrollView
          style={styles.scroll}
          contentContainerStyle={[styles.content, { paddingBottom: insets.bottom + 12 }]}
          refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
          <ThemedView style={[styles.header, isWheelHighlighted ? styles.tourDimmed : null]}>
            {/* Two rows, each pairing the left-side text with its own
                right-side element (date/"Show balances" label, greeting/
                toggle switch) so the label sits level with the date and the
                switch sits level with the salutation — not both stacked
                together off to one side. Name is its own row below, with
                enough lineHeight that the italic Fraunces descender doesn't
                get clipped by the row below it. */}
            <ThemedView style={styles.headerRow}>
              <ThemedText style={styles.dateLabel}>{todayLabel}</ThemedText>
              <ThemedText style={styles.toggleLabel}>Show balances</ThemedText>
            </ThemedView>
            <ThemedView style={styles.headerRow}>
              <ThemedText style={styles.greetingLine} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.6}>
                {greeting}
                {firstName ? ',' : ''}
              </ThemedText>
              <HomePearlToggle value={showBalances} onValueChange={handleSetShowBalances} />
            </ThemedView>
            {firstName ? (
              <ThemedText style={styles.greetingName} numberOfLines={1}>
                {firstName}
              </ThemedText>
            ) : null}
          </ThemedView>

          {/* Blank unless something's actually active — takes no space at
              all in the common case, preserving the "fits without
              scrolling" tuning everywhere else on this screen. Shares its
              count with TopBar's badge via useNoticeCount so the two can
              never disagree. */}
          {noticeCount > 0 ? (
            <Pressable onPress={() => router.push('/summary')} style={styles.noticeBanner}>
              <ThemedText style={styles.noticeBannerText}>
                {noticeCount} item{noticeCount === 1 ? '' : 's'} to review
              </ThemedText>
              <IconSymbol name="chevron.right" size={13} color={HomePalette.emerald2} />
            </Pressable>
          ) : null}

          {/* flex:1 so the wheel centers itself within whatever room is left
              above the tiles, instead of sitting glued directly under the
              header — the tiles + YTD card below keep their natural size
              and stay anchored near the bottom of the screen. The wheel's
              own size is never capped by this zone's available space (see
              home-wheel.tsx) — it's the centerpiece of Home and stays full
              size; fitting the page without scrolling is handled by
              keeping everything ELSE on this screen compact instead (small
              paddingBottom here, a tightened header above, a shorter YTD
              chart below). */}
          <ThemedView style={styles.wheelZone}>
            {/* Gated on !isLoading, same as the tiles/sparkline below, rather
                than always-mounted with defaults (rotationDegrees=0,
                spinOnLoad=true) that get corrected once the real
                user_settings row arrives. That correction is what caused
                both the "half spin on load even when the toggle is off" bug
                (the entrance animation started against the wrong assumed
                default before getting cut off) AND a separate, unrelated
                glitch where userRotation itself SNAPS from 0 to the real
                persisted angle the instant it loads — a jump with no
                connection to spinOnLoad at all, so it happened regardless of
                the toggle. Not mounting until the real values are already
                known avoids both by construction: there's no wrong default
                to ever be visibly correct out of. */}
            {!isLoading ? (
              <HomeWheel
                netWorth={netWorth}
                currency={wealthCurrency.currency}
                isLoading={isLoading}
                hideValue={!showBalances}
                rotationDegrees={wheelRotation}
                onRotationChange={handleWheelRotationChange}
                spinOnLoad={wheelSpinOnLoad}
              />
            ) : null}
          </ThemedView>

          {!isLoading ? (
            <ThemedView style={isWheelHighlighted ? styles.tourDimmed : undefined}>
              <ScopeSwitch accent={Colors.light.tint} />
              <ThemedText style={styles.sectionTitle}>Accounts</ThemedText>
              <ThemedView style={styles.tileRowWrapper}>
                <ThemedView style={styles.tileRow}>
                  <SummaryTile
                    symbolText={currencySymbol(wealthCurrency.currency)}
                    label="Cash"
                    iconColor={HomeTileColors.cash.icon}
                    badgeColor={HomeTileColors.cash.badge}
                    value={cashTile}
                    currency={wealthCurrency.currency}
                    hideValue={!showBalances}
                    highlighted={expandedTile === 'cash'}
                    compact={expandedTile !== null}
                    onToggle={() => toggleTile('cash')}
                  />
                  <SummaryTile
                    icon="chart.line.uptrend.xyaxis"
                    label="Invest"
                    iconColor={HomeTileColors.invest.icon}
                    badgeColor={HomeTileColors.invest.badge}
                    value={investmentsTile}
                    currency={wealthCurrency.currency}
                    hideValue={!showBalances}
                    highlighted={expandedTile === 'invest'}
                    compact={expandedTile !== null}
                    onToggle={() => toggleTile('invest')}
                  />
                  <SummaryTile
                    icon="creditcard"
                    label="Credit cards"
                    iconColor={HomeTileColors.cards.icon}
                    badgeColor={HomeTileColors.cards.badge}
                    value={cardOutstandingTile}
                    currency={wealthCurrency.currency}
                    hideValue={!showBalances}
                    highlighted={expandedTile === 'cards'}
                    compact={expandedTile !== null}
                    onToggle={() => toggleTile('cards')}
                  />
                  <SummaryTile
                    icon="scalemass"
                    label="Other liabilities"
                    iconColor={HomeTileColors.liabilities.icon}
                    badgeColor={HomeTileColors.liabilities.badge}
                    value={otherLiabilitiesTile}
                    currency={wealthCurrency.currency}
                    hideValue={!showBalances}
                    highlighted={expandedTile === 'liabilities'}
                    compact={expandedTile !== null}
                    onToggle={() => toggleTile('liabilities')}
                  />
                </ThemedView>
                {expandedTileGraph ? (
                  <TileTrendStrip
                    icon={expandedTileGraph.icon}
                    symbolText={expandedTileGraph.symbolText}
                    label={expandedTileGraph.label}
                    color={expandedTileGraph.color}
                    badgeColor={expandedTileGraph.badgeColor}
                    value={expandedTileGraph.value}
                    currency={wealthCurrency.currency}
                    hideValue={!showBalances}
                    history={expandedTileGraph.history}
                    historyDates={tileHistoryDates}
                  />
                ) : null}
              </ThemedView>

              <Pressable onPress={() => router.push('/wealth')}>
                <Surface accentColor={ModuleAccents.wealth} style={styles.chartCard}>
                  <ThemedView style={styles.chartHead}>
                    <ThemedText style={styles.chartTitle}>Net worth over time</ThemedText>
                    <ThemedText style={styles.chartPeriod}>YTD</ThemedText>
                  </ThemedView>
                  <HomeNetWorthChart
                    candles={ytdCandles}
                    color={ytdTrendUp ? HomePalette.emerald : Colors.light.negative}
                    currency={wealthCurrency.currency}
                  />
                </Surface>
              </Pressable>
            </ThemedView>
          ) : null}
        </ScrollView>
      </ConnectionsSwipePanel>
    </View>
  );
}

