import { useLocalSearchParams, useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, TextInput } from 'react-native';

import { SelectModal, type SelectOption } from '@/components/select-modal';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { showAlert } from '@/lib/alert';
import { supabase } from '@/lib/supabase';
import type { BudgetRow, CategoryRow } from '@/types/database';

const ACCENT = ModuleAccents.spend;

export default function EditBudgetScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();
  const { availableCurrencies, currencyNames } = useCurrency();

  const [budget, setBudget] = useState<BudgetRow | null>(null);
  const [categoryName, setCategoryName] = useState<string | null>(null);
  const [amount, setAmount] = useState('');
  const [currency, setCurrency] = useState('USD');
  const [showCurrencyPicker, setShowCurrencyPicker] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      const { data, error: loadError } = await supabase.from('budgets').select('*').eq('id', id).maybeSingle();
      if (loadError || !data) {
        setError(loadError?.message ?? 'Budget not found.');
        setIsLoading(false);
        return;
      }
      setBudget(data);
      setAmount(String(data.amount));
      setCurrency(data.currency);
      if (data.category_id) {
        const { data: category } = await supabase
          .from('categories')
          .select('name')
          .eq('id', data.category_id)
          .maybeSingle();
        setCategoryName((category as CategoryRow | null)?.name ?? null);
      }
      setIsLoading(false);
    }
    load();
  }, [id]);

  async function handleSave() {
    const parsedAmount = Number(amount);
    if (!amount.trim() || Number.isNaN(parsedAmount) || parsedAmount <= 0) {
      setError('Enter a valid amount.');
      return;
    }
    if (!currency.trim()) {
      setError('Enter a currency.');
      return;
    }

    setError(null);
    setIsSaving(true);

    const { error: saveError } = await supabase
      .from('budgets')
      .update({ amount: parsedAmount, currency: currency.trim().toUpperCase() })
      .eq('id', id);

    setIsSaving(false);

    if (saveError) {
      setError(saveError.message);
      return;
    }

    router.back();
  }

  function handleDelete() {
    showAlert('Delete budget', 'This will remove the limit. It can be re-added later.', [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Delete',
        style: 'destructive',
        onPress: async () => {
          const { error: deleteError } = await supabase.from('budgets').delete().eq('id', id);
          if (deleteError) {
            setError(deleteError.message);
            return;
          }
          router.back();
        },
      },
    ]);
  }

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={styles.flex}>
        <ActivityIndicator style={styles.loading} color={ACCENT} />
      </ThemedView>
    );
  }

  const label = budget?.category_id ? (categoryName ?? 'Category') : (budget?.country ?? 'Country');

  // Falls back to the bare code if the name hasn't been populated yet, same as components/top-bar.tsx's own currency picker.
  function currencyLabel(code: string): string {
    const currencyName = currencyNames[code];
    return currencyName ? `${currencyName} (${code})` : code;
  }
  const currencyOptions: SelectOption[] = availableCurrencies.map((code) => ({
    value: code,
    label: currencyLabel(code),
  }));

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.headerRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            {label}
          </ThemedText>
          <Pressable onPress={handleDelete} hitSlop={12}>
            <IconSymbol name="trash" size={22} color={Colors.light.negative} />
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedText type="defaultSemiBold">Monthly limit</ThemedText>
        <TextInput
          value={amount}
          onChangeText={setAmount}
          placeholder="0.00"
          keyboardType="decimal-pad"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        <ThemedText type="defaultSemiBold">Currency</ThemedText>
        <Pressable onPress={() => setShowCurrencyPicker(true)} style={[styles.input, { borderColor: ACCENT }]}>
          <ThemedText>{currency ? currencyLabel(currency) : 'Select a currency'}</ThemedText>
        </Pressable>
        <SelectModal
          visible={showCurrencyPicker}
          onClose={() => setShowCurrencyPicker(false)}
          options={currencyOptions}
          selectedValue={currency || null}
          onSelect={(value) => {
            setCurrency(value);
            setShowCurrencyPicker(false);
          }}
        />

        <Pressable onPress={handleSave} disabled={isSaving} style={[styles.button, { backgroundColor: ACCENT }]}>
          {isSaving ? (
            <ActivityIndicator color={ModuleAccentOnColor.spend} />
          ) : (
            <ThemedText style={{ color: ModuleAccentOnColor.spend, fontWeight: '600' }}>Save</ThemedText>
          )}
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  headerRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  loading: {
    marginTop: 32,
  },
  error: {
    color: Colors.light.negative,
  },
});
