import { computeCurrentBalance, type LedgerInput } from '@/lib/wealthSeries';
import type { AccountRow } from '@/types/database';

export type LiquidityBreakdown = {
  liquidNetWorth: number;
  illiquidNetWorth: number;
  netWorth: number;
};

const ILLIQUID_CATEGORIES = new Set<AccountRow['asset_category']>(['investment', 'real_estate']);

function isLiquidAccount(account: Pick<AccountRow, 'asset_category'>): boolean {
  return !ILLIQUID_CATEGORIES.has(account.asset_category);
}

/**
 * Splits current net worth into liquid vs illiquid using each account's
 * existing asset_category — 'cash' (and liabilities not secured against
 * real estate, e.g. a credit card) count as liquid; 'investment' and
 * 'real_estate' (and anything secured against real estate, e.g. a
 * mortgage) count as illiquid. Investments are grouped with real estate
 * deliberately, not split out on their own: the point of this view is "what
 * could I actually spend right now without unwinding a position first," so
 * a large unrealized brokerage gain shouldn't read the same as cash on
 * hand, even though it's more liquid than a house in the abstract.
 *
 * Reuses computeCurrentBalance — the same engine the Wealth chart is built
 * on — on two account subsets rather than a fresh balance calculation, so
 * this inherits its already-correct handling of balance-based vs
 * transaction-based accounts, the liability sign convention, and the
 * real-estate/internal-transfer exclusions that took real debugging to get
 * right the first time.
 */
export function computeLiquidityBreakdown(params: LedgerInput, today: Date = new Date()): LiquidityBreakdown {
  const { transactions, accounts, balanceSnapshots, convert } = params;
  const liquidAccountIds = new Set(accounts.filter(isLiquidAccount).map((a) => a.id));

  const liquidAccounts = accounts.filter((a) => liquidAccountIds.has(a.id));
  const illiquidAccounts = accounts.filter((a) => !liquidAccountIds.has(a.id));

  const liquidNetWorth = computeCurrentBalance({
    accounts: liquidAccounts,
    transactions: transactions.filter((tx) => !!tx.account_id && liquidAccountIds.has(tx.account_id)),
    balanceSnapshots: balanceSnapshots.filter((s) => liquidAccountIds.has(s.account_id)),
    convert,
    asOf: today,
  });
  const illiquidNetWorth = computeCurrentBalance({
    accounts: illiquidAccounts,
    transactions: transactions.filter((tx) => !!tx.account_id && !liquidAccountIds.has(tx.account_id)),
    balanceSnapshots: balanceSnapshots.filter((s) => !liquidAccountIds.has(s.account_id)),
    convert,
    asOf: today,
  });

  return { liquidNetWorth, illiquidNetWorth, netWorth: liquidNetWorth + illiquidNetWorth };
}
