import type { CountryVisitedRow, TripRow, TripSegmentRow } from '@/types/database';

export type TripSummary = {
  id: string;
  displayName: string;
  startDate: string;
  endDate: string | null;
  isOngoing: boolean;
  /** Distinct countries, ordered by each country's earliest stop — "flags in order of travel." */
  countries: string[];
  /** Stops sorted by entry_date. */
  stops: CountryVisitedRow[];
};

function stopLabel(stop: CountryVisitedRow): string {
  return stop.city?.trim() || stop.country;
}

/** "Agra, Jaipur & Jaisalmer" — Oxford-joined, deduping consecutive repeats (e.g. two stops in the same city back to back). */
function joinStopLabels(labels: string[]): string {
  const deduped: string[] = [];
  for (const label of labels) {
    if (deduped[deduped.length - 1] !== label) deduped.push(label);
  }
  if (deduped.length === 0) return '';
  if (deduped.length === 1) return deduped[0];
  if (deduped.length === 2) return `${deduped[0]} & ${deduped[1]}`;
  return `${deduped.slice(0, -1).join(', ')} & ${deduped[deduped.length - 1]}`;
}

/**
 * Groups countries_visited rows ("stops") by trip_id into display-ready
 * summaries. Everything here — date range, country list, name — is derived
 * from the stops themselves, never stored on the trip row, so it can never
 * drift out of sync with the actual itinerary. `allSegments` is optional
 * (most callers only have stops loaded, and the country list/display name
 * never depended on segments anyway) — when given, it widens startDate/
 * endDate to cover the full itinerary, not just the stays: a trip's first
 * leg often departs before its first stop even starts (the outbound
 * flight), and its last leg often arrives after its last stop ends (the
 * flight home) — the trip's own date range should read start-to-finish of
 * the whole journey, not just the places you actually stayed.
 */
export function computeTripSummaries(
  trips: TripRow[],
  allStops: CountryVisitedRow[],
  allSegments: TripSegmentRow[] = []
): TripSummary[] {
  const stopsByTrip = new Map<string, CountryVisitedRow[]>();
  for (const stop of allStops) {
    if (!stop.trip_id) continue;
    const list = stopsByTrip.get(stop.trip_id) ?? [];
    list.push(stop);
    stopsByTrip.set(stop.trip_id, list);
  }
  const segmentsByTrip = new Map<string, TripSegmentRow[]>();
  for (const segment of allSegments) {
    const list = segmentsByTrip.get(segment.trip_id) ?? [];
    list.push(segment);
    segmentsByTrip.set(segment.trip_id, list);
  }

  const summaries: TripSummary[] = [];
  for (const trip of trips) {
    const stops = stopsByTrip.get(trip.id);
    // A trip with no stops left is an artifact of an abandoned/emptied
    // creation flow — not shown, not a real trip to the user.
    if (!stops || stops.length === 0) continue;
    const segments = segmentsByTrip.get(trip.id) ?? [];

    const sorted = [...stops].sort((a, b) => (a.entry_date < b.entry_date ? -1 : a.entry_date > b.entry_date ? 1 : 0));

    const isOngoing = sorted.some((s) => !s.exit_date);
    let startDate = sorted[0].entry_date;
    let endDate = isOngoing
      ? null
      : sorted.reduce<string | null>((max, s) => (!max || (s.exit_date && s.exit_date > max) ? s.exit_date : max), null);
    for (const segment of segments) {
      if (segment.depart_date < startDate) startDate = segment.depart_date;
      if (endDate && segment.arrive_date > endDate) endDate = segment.arrive_date;
    }

    const countries: string[] = [];
    for (const stop of sorted) {
      if (!countries.includes(stop.country)) countries.push(stop.country);
    }

    const displayName = trip.name?.trim() || joinStopLabels(sorted.map(stopLabel));

    summaries.push({ id: trip.id, displayName, startDate, endDate, isOngoing, countries, stops: sorted });
  }

  return summaries;
}

/** For splitting the Trip List into Upcoming/Ongoing vs. Past sections. */
export function isTripUpcomingOrOngoing(summary: TripSummary, today: string): boolean {
  return summary.isOngoing || !summary.endDate || summary.endDate >= today;
}

/** Chronological order for a trip's travel legs on their own — see computeTripTimeline for the merged view actually shown on the Trip Detail screen. */
export function sortSegments(segments: TripSegmentRow[]): TripSegmentRow[] {
  return [...segments].sort((a, b) => {
    if (a.depart_date !== b.depart_date) return a.depart_date < b.depart_date ? -1 : 1;
    const aTime = a.depart_time ?? '';
    const bTime = b.depart_time ?? '';
    return aTime < bTime ? -1 : aTime > bTime ? 1 : 0;
  });
}

export type TimelineEntry =
  | { kind: 'stop'; date: string; stop: CountryVisitedRow }
  | { kind: 'segment'; date: string; segment: TripSegmentRow };

function normalizedStopLabel(stop: CountryVisitedRow): string {
  return (stop.city?.trim() || stop.country).trim().toLowerCase();
}

/**
 * Orders the entries landing on one exact date via a real topological
 * sort (Kahn's algorithm) instead of a plain pairwise comparator. The old
 * comparator had no rule at all for two same-date STOPS — it always
 * returned a tie, falling back to array order — which broke as soon as a
 * real segment on that date connected them (arrived at one, then departed
 * for the other): the segment correctly sorted between each stop and
 * itself, but the two stops compared directly had no way to inherit that
 * relationship, so array order could still put the later one first.
 * Confirmed against a real trip: adding a same-day stop after an
 * already-later-dated one left it sorted in the wrong place in the
 * Itinerary list despite a segment on the map correctly connecting them
 * in sequence. Building the two possible edges explicitly (stop -> the
 * segment departing it; the segment arriving at it -> stop) and
 * topologically sorting avoids that regardless of how many same-date
 * entries are involved — see lib/tripRoute.ts's orderSameDateGroup for
 * the same technique, first proven there.
 */
function manualOrderOf(entry: TimelineEntry): number | null {
  return entry.kind === 'stop' ? entry.stop.manual_order : entry.segment.manual_order;
}

function orderSameDateEntries(group: { entry: TimelineEntry; index: number }[]): TimelineEntry[] {
  const n = group.length;
  if (n <= 1) return group.map((g) => g.entry);
  // A user-reordered group (see app/countries/trips/[id].tsx's move-up/
  // move-down controls) always sets manual_order on EVERY entry in it at
  // once, specifically so this check is unambiguous — a group with only
  // some entries set (e.g. a new same-date entry added since the last
  // manual reorder) falls back to the automatic graph below entirely,
  // rather than mixing a stale manual position with an inferred one.
  if (group.every((g) => manualOrderOf(g.entry) != null)) {
    return [...group].sort((a, b) => manualOrderOf(a.entry)! - manualOrderOf(b.entry)!).map((g) => g.entry);
  }
  const successors: number[][] = Array.from({ length: n }, () => []);
  const inDegree = new Array(n).fill(0);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) continue;
      const a = group[i].entry;
      const b = group[j].entry;
      const isEdge =
        (a.kind === 'stop' && b.kind === 'segment' && b.segment.from_label.trim().toLowerCase() === normalizedStopLabel(a.stop)) ||
        (a.kind === 'segment' && b.kind === 'stop' && a.segment.to_label.trim().toLowerCase() === normalizedStopLabel(b.stop)) ||
        // Two stops starting the same day, independent of any segment: the
        // one you left same-day comes first, the one you stayed in (an
        // exit_date later than its own entry_date) comes after — you pass
        // through the short stop on the way to the one you're actually
        // staying at.
        (a.kind === 'stop' && b.kind === 'stop' && a.stop.exit_date != null && b.stop.exit_date != null && a.stop.exit_date < b.stop.exit_date);
      if (isEdge) {
        successors[i].push(j);
        inDegree[j]++;
      }
    }
  }
  const used = new Array(n).fill(false);
  const result: TimelineEntry[] = [];
  for (let step = 0; step < n; step++) {
    let pick = -1;
    for (let i = 0; i < n; i++) {
      if (used[i] || inDegree[i] > 0) continue;
      if (pick === -1 || group[i].index < group[pick].index) pick = i;
    }
    if (pick === -1) break; // Only reachable if the edge rules ever produced a real cycle — they can't, but never hang the list over it.
    used[pick] = true;
    result.push(group[pick].entry);
    for (const j of successors[pick]) inDegree[j]--;
  }
  for (let i = 0; i < n; i++) if (!used[i]) result.push(group[i].entry);
  return result;
}

/**
 * Stops and travel legs merged into one chronological sequence — an
 * itinerary is every leg of the trip, not two separate lists sorted
 * independently. Segments are pre-sorted by depart_time (sortSegments) so
 * two same-date, otherwise-unconnected segments still land in a sensible
 * order — real ordering, when a segment and a same-date stop are actually
 * connected, comes from orderSameDateEntries' graph instead.
 */
export function computeTripTimeline(stops: CountryVisitedRow[], segments: TripSegmentRow[]): TimelineEntry[] {
  const withIndex: { entry: TimelineEntry; index: number }[] = [
    ...stops.map((stop) => ({ kind: 'stop' as const, date: stop.entry_date, stop })),
    ...sortSegments(segments).map((segment) => ({ kind: 'segment' as const, date: segment.depart_date, segment })),
  ].map((entry, index) => ({ entry, index }));
  const byDate = new Map<string, { entry: TimelineEntry; index: number }[]>();
  for (const item of withIndex) {
    const list = byDate.get(item.entry.date);
    if (list) list.push(item);
    else byDate.set(item.entry.date, [item]);
  }
  return Array.from(byDate.keys())
    .sort()
    .flatMap((date) => orderSameDateEntries(byDate.get(date)!));
}
