import { createContext, useCallback, useContext, useEffect, useMemo, useState, type PropsWithChildren } from 'react';

import { useAuth } from '@/contexts/auth-context';
import {
  filterAccountLinkedByScope,
  filterAccountsByScope,
  filterCardsByScope,
  filterSnapshotsByScope,
  filterTransactionsByScope,
  type FinanceScope,
  type Ownership,
} from '@/lib/scope';
import { supabase } from '@/lib/supabase';
import type { AccountRow, BalanceSnapshotRow, CreditCardRow, TransactionRow } from '@/types/database';

type ScopeContextValue = {
  scope: FinanceScope;
  /** Optimistic — flips immediately, persists to user_settings.finance_scope, reverts on failure. */
  setScope: (scope: FinanceScope) => Promise<void>;
  /** True once at least one account or card is tagged business — the switch is hidden until then so a purely personal user never sees it. */
  hasBusinessItems: boolean;
  /** Re-reads the id→ownership maps and hasBusinessItems — call after tagging an account/card, or on entering a scoped screen. */
  refresh: () => Promise<void>;
  filterAccounts: <T extends Pick<AccountRow, 'ownership'>>(accounts: T[]) => T[];
  filterCards: <T extends Pick<CreditCardRow, 'ownership'>>(cards: T[]) => T[];
  filterTransactions: <T extends Pick<TransactionRow, 'account_id' | 'card_id'>>(transactions: T[]) => T[];
  filterSnapshots: <T extends Pick<BalanceSnapshotRow, 'account_id'>>(snapshots: T[]) => T[];
  /** For rows carrying only an account_id (no card_id) — e.g. a `select('account_id, amount')` ledger slice. */
  filterAccountLinked: <T extends { account_id: string | null }>(rows: T[]) => T[];
};

const ScopeContext = createContext<ScopeContextValue | null>(null);

/**
 * The All / Personal / Business switch. Holds one id→ownership map for
 * accounts and one for cards so every screen can filter its own already-
 * fetched rows (transactions included, via the source account/card)
 * without extra queries — see lib/scope.ts. Maps are refreshed on demand
 * (ScopeSwitch mounts, edit screens save) rather than subscribed, which
 * is plenty for how rarely accounts/cards change.
 */
export function ScopeProvider({ children }: PropsWithChildren) {
  const { session } = useAuth();
  const userId = session?.user.id;
  const [scope, setScopeState] = useState<FinanceScope>('all');
  const [accountOwnership, setAccountOwnership] = useState<Map<string, Ownership>>(new Map());
  const [cardOwnership, setCardOwnership] = useState<Map<string, Ownership>>(new Map());

  const refresh = useCallback(async () => {
    if (!userId) return;
    const [accountsResult, cardsResult] = await Promise.all([
      supabase.from('accounts').select('id, ownership'),
      supabase.from('credit_cards').select('id, ownership'),
    ]);
    if (!accountsResult.error) {
      setAccountOwnership(new Map((accountsResult.data ?? []).map((a) => [a.id, a.ownership])));
    }
    if (!cardsResult.error) {
      setCardOwnership(new Map((cardsResult.data ?? []).map((c) => [c.id, c.ownership])));
    }
  }, [userId]);

  useEffect(() => {
    if (!userId) {
      setScopeState('all');
      setAccountOwnership(new Map());
      setCardOwnership(new Map());
      return;
    }
    let cancelled = false;
    supabase
      .from('user_settings')
      .select('finance_scope')
      .eq('user_id', userId)
      .maybeSingle()
      .then(({ data }) => {
        if (!cancelled && data?.finance_scope) setScopeState(data.finance_scope);
      });
    refresh();
    return () => {
      cancelled = true;
    };
  }, [userId, refresh]);

  const hasBusinessItems = useMemo(
    () => [...accountOwnership.values(), ...cardOwnership.values()].some((o) => o === 'business'),
    [accountOwnership, cardOwnership]
  );

  // A user with no business items left (e.g. retagged the last one back to
  // personal) shouldn't be stuck looking at an empty "Business" view with
  // the switch hidden.
  const effectiveScope: FinanceScope = hasBusinessItems ? scope : 'all';

  const value = useMemo<ScopeContextValue>(() => {
    async function setScope(next: FinanceScope) {
      const previous = scope;
      setScopeState(next);
      if (!userId) return;
      const { error } = await supabase
        .from('user_settings')
        .upsert({ user_id: userId, finance_scope: next }, { onConflict: 'user_id' });
      if (error) {
        console.error('Failed to save finance scope:', error.message);
        setScopeState(previous);
      }
    }
    return {
      scope: effectiveScope,
      setScope,
      hasBusinessItems,
      refresh,
      filterAccounts: (accounts) => filterAccountsByScope(accounts, effectiveScope),
      filterCards: (cards) => filterCardsByScope(cards, effectiveScope),
      filterTransactions: (transactions) =>
        filterTransactionsByScope(transactions, effectiveScope, accountOwnership, cardOwnership),
      filterSnapshots: (snapshots) => filterSnapshotsByScope(snapshots, effectiveScope, accountOwnership),
      filterAccountLinked: (rows) => filterAccountLinkedByScope(rows, effectiveScope, accountOwnership),
    };
  }, [scope, effectiveScope, hasBusinessItems, refresh, userId, accountOwnership, cardOwnership]);

  return <ScopeContext.Provider value={value}>{children}</ScopeContext.Provider>;
}

export function useScope() {
  const context = useContext(ScopeContext);
  if (!context) throw new Error('useScope must be used within ScopeProvider');
  return context;
}
