import { useFocusEffect } from '@react-navigation/native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { LineChart, type LinePoint } from '@/components/line-chart';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { formatMoney } from '@/lib/currency';
import {
  computeForeignAssetWeeklySeries,
  FOREIGN_REPORTING_JURISDICTIONS,
  type ForeignReportingJurisdictionId,
} from '@/lib/foreignAssetReporting';
import { fetchAllRows } from '@/lib/fetchAll';
import { formatDateDisplay } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import type { AccountRow, BalanceSnapshotRow, TransactionRow } from '@/types/database';

const ACCENT = ModuleAccents.countries;

function isValidJurisdiction(value: string | undefined): value is ForeignReportingJurisdictionId {
  return !!value && value in FOREIGN_REPORTING_JURISDICTIONS;
}

export default function ForeignBalanceHistoryScreen() {
  const router = useRouter();
  const { convertToCurrency } = useCurrency();
  const { jurisdiction: jurisdictionParam } = useLocalSearchParams<{ jurisdiction?: string }>();
  // Falls back to fbar if the param is missing/malformed — shouldn't happen
  // via the app's own navigation (always passed explicitly), but this
  // screen shouldn't crash on a bad deep link.
  const jurisdiction = isValidJurisdiction(jurisdictionParam) ? jurisdictionParam : 'fbar';
  const config = FOREIGN_REPORTING_JURISDICTIONS[jurisdiction];

  const [accounts, setAccounts] = useState<AccountRow[]>([]);
  const [transactions, setTransactions] = useState<TransactionRow[]>([]);
  const [snapshots, setSnapshots] = useState<BalanceSnapshotRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const [accountsResult, transactionsResult, snapshotsResult] = await Promise.all([
      supabase.from('accounts').select('*'),
      fetchAllRows<Pick<TransactionRow, 'date' | 'amount' | 'currency' | 'account_id'>>((from, to) =>
        supabase.from('transactions').select('date, amount, currency, account_id').order('date').order('id').range(from, to)
      ),
      fetchAllRows<BalanceSnapshotRow>((from, to) =>
        supabase.from('balance_snapshots').select('*').order('date').order('id').range(from, to)
      ),
    ]);

    if (accountsResult.error) {
      setError(accountsResult.error.message);
      setIsLoading(false);
      return;
    }

    setAccounts(accountsResult.data ?? []);
    setTransactions(transactionsResult.data as TransactionRow[]);
    setSnapshots(snapshotsResult.data);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  const series = computeForeignAssetWeeklySeries(accounts, transactions, snapshots, jurisdiction, convertToCurrency);

  const points: LinePoint[] = (series ?? []).map((p) => ({
    label: formatDateDisplay(p.periodEnd),
    value: p.balance,
  }));
  const peak = points.length > 0 ? Math.max(...points.map((p) => p.value)) : 0;
  const isOverThreshold = config.threshold != null && peak > config.threshold;

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            {config.label} Balance Over Time
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}
        <ThemedText style={styles.hint}>
          Combined {config.threshold != null ? 'foreign' : 'overseas'}-currency account balance, sampled weekly from
          January 1st through today, in {config.currency}.
        </ThemedText>

        <Surface accentColor={isOverThreshold ? Colors.light.negative : ACCENT}>
          <LineChart
            points={points}
            color={isOverThreshold ? Colors.light.negative : ACCENT}
            currency={config.currency}
            threshold={config.threshold ?? undefined}
            thresholdLabel={config.threshold != null ? `${formatMoney(config.threshold, config.currency)} ${config.label} threshold` : undefined}
          />
        </Surface>

        <ThemedView style={styles.statsRow}>
          <ThemedView style={styles.statTile}>
            <ThemedText style={styles.muted}>Peak this year</ThemedText>
            <ThemedText type="mono" style={styles.statValue}>
              {formatMoney(peak, config.currency)}
            </ThemedText>
          </ThemedView>
        </ThemedView>
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  centered: { alignItems: 'center', justifyContent: 'center' },
  content: {
    padding: 16,
    gap: 12,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  statsRow: {
    flexDirection: 'row',
    gap: 8,
  },
  statTile: {
    flex: 1,
    gap: 4,
  },
  statValue: {
    fontSize: 20,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
});
