import { Figtree_400Regular, Figtree_500Medium, Figtree_600SemiBold } from '@expo-google-fonts/figtree';
import { Fraunces_300Light, Fraunces_400Regular, Fraunces_500Medium, Fraunces_500Medium_Italic, Fraunces_600SemiBold } from '@expo-google-fonts/fraunces';
import { IBMPlexMono_500Medium } from '@expo-google-fonts/ibm-plex-mono';
import { Inter_400Regular, Inter_500Medium, Inter_600SemiBold, Inter_700Bold } from '@expo-google-fonts/inter';
import { Marcellus_400Regular } from '@expo-google-fonts/marcellus';
import { DefaultTheme, ThemeProvider } from '@react-navigation/native';
import { useFonts } from 'expo-font';
import { Stack } from 'expo-router';
import * as SplashScreen from 'expo-splash-screen';
import { StatusBar } from 'expo-status-bar';
import { useEffect } from 'react';
import { ActivityIndicator, View } from 'react-native';
import { GestureHandlerRootView } from 'react-native-gesture-handler';
import { KeyboardProvider } from 'react-native-keyboard-controller';
import 'react-native-reanimated';

import { GradientBackground } from '@/components/gradient-background';
import { ThemedView } from '@/components/themed-view';
import { TopBar } from '@/components/top-bar';
import { TourOverlay } from '@/components/tour-overlay';
import { Colors } from '@/constants/theme';
import { AuthProvider, useAuth } from '@/contexts/auth-context';
import { CurrencyProvider } from '@/contexts/currency-context';
import { ScopeProvider } from '@/contexts/scope-context';
import { TourProvider } from '@/contexts/tour-context';

export const unstable_settings = {
  anchor: 'index',
};

SplashScreen.preventAutoHideAsync();

const NavigationTheme = {
  ...DefaultTheme,
  colors: {
    ...DefaultTheme.colors,
    background: Colors.light.backgroundSolid,
    card: Colors.light.surface,
    text: Colors.light.text,
    border: Colors.light.icon,
    primary: Colors.light.tint,
  },
};

function RootNavigator() {
  const { session, isLoading, mfaRequired } = useAuth();
  const isFullyAuthenticated = !!session && !mfaRequired;

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>
        <ActivityIndicator />
      </ThemedView>
    );
  }

  return (
    <View style={{ flex: 1 }}>
      {/* TopBar sits outside the Stack, so it needs its own copy of the shared
          gradient behind it — each screen's own ThemedView paints another
          copy over its content area, harmlessly overlapping this one. */}
      <GradientBackground />
      {isFullyAuthenticated ? <TopBar /> : null}
      <Stack screenOptions={{ headerShown: false }}>
        <Stack.Protected guard={isFullyAuthenticated}>
          {/* index first, matching this file's own unstable_settings.anchor
              above — with no explicit initialRouteName on the Stack itself,
              React Navigation defaults to the first-declared screen, and a
              literal name="onboarding" below doesn't match any real route
              (the file is onboarding/index.tsx) or EVERY sign-in landed
              users on onboarding/demo-liquidity instead of Home, regardless
              of whether they'd ever actually finished onboarding — the
              first VALID entry in the old list, not anything tied to
              needsOnboarding (confirmed directly: an account with a real,
              months-old onboarding_completed_at still hit this every time). */}
          <Stack.Screen name="index" />
          <Stack.Screen name="onboarding/index" />
          <Stack.Screen name="onboarding/demo-liquidity" />
          <Stack.Screen name="onboarding/demo-csv-import" />
          <Stack.Screen name="onboarding/demo-country" />
          <Stack.Screen name="onboarding/demo-accounts" />
          <Stack.Screen name="countries" />
          <Stack.Screen name="cards" />
          <Stack.Screen name="accounts" />
          <Stack.Screen name="documents" />
          <Stack.Screen name="spend" />
          <Stack.Screen name="wealth" />
          <Stack.Screen name="summary" />
          <Stack.Screen name="search" />
          <Stack.Screen name="account" />
          <Stack.Screen name="connections" />
          <Stack.Screen name="transactions/new" options={{ presentation: 'modal' }} />
          <Stack.Screen name="transactions/[id]" options={{ presentation: 'modal' }} />
          <Stack.Screen name="transactions/import" options={{ presentation: 'modal' }} />
          <Stack.Screen name="transactions/imports" options={{ presentation: 'modal' }} />
        </Stack.Protected>
        <Stack.Protected guard={!!session && mfaRequired}>
          <Stack.Screen name="mfa-challenge" />
        </Stack.Protected>
        <Stack.Protected guard={!session}>
          <Stack.Screen name="login" />
        </Stack.Protected>
        {/* Reachable regardless of session state — a fresh recovery-link tap
            establishes a session (detectSessionInUrl, see lib/supabase.ts) so
            this can't sit inside the guard={!session} group, but navigating
            here with no session at all should still show its own "link
            expired" state rather than 404 via the guard={!!session} group. */}
        <Stack.Screen name="reset-password" />
      </Stack>
      {/* Rendered LAST, after the Stack — not just given a high zIndex —
          so it reliably paints on top of whatever screen is current via
          plain render order, the one thing guaranteed to work the same on
          iOS/Android/web rather than depending on zIndex/elevation
          quirks across platforms. */}
      {isFullyAuthenticated ? <TourOverlay /> : null}
    </View>
  );
}

export default function RootLayout() {
  const [fontsLoaded] = useFonts({
    Marcellus_400Regular,
    Figtree_400Regular,
    Figtree_500Medium,
    Figtree_600SemiBold,
    IBMPlexMono_500Medium,
    // Home-screen-specific — see constants/theme.ts's HomeFonts. Loaded
    // globally here (useFonts has no per-screen scoping) but only actually
    // used by app/index.tsx and its child components; every other screen
    // keeps using Figtree/Marcellus/IBMPlexMono unchanged.
    Fraunces_300Light,
    Fraunces_400Regular,
    Fraunces_500Medium,
    Fraunces_500Medium_Italic,
    Fraunces_600SemiBold,
    Inter_400Regular,
    Inter_500Medium,
    Inter_600SemiBold,
    Inter_700Bold,
  });

  useEffect(() => {
    if (fontsLoaded) {
      SplashScreen.hideAsync();
    }
  }, [fontsLoaded]);

  if (!fontsLoaded) {
    return null;
  }

  return (
    <GestureHandlerRootView style={{ flex: 1 }}>
      {/* No statusBarTranslucent/navigationBarTranslucent props here — the
          library auto-detects edge-to-edge via its own react-native-is-edge-
          to-edge dependency and ignores (with a console warning) any manual
          value for these once that detection is active, so setting them
          explicitly was dead code as of this library version. */}
      <KeyboardProvider>
        <AuthProvider>
          <CurrencyProvider>
            <ScopeProvider>
              <ThemeProvider value={NavigationTheme}>
                <TourProvider>
                  <RootNavigator />
                  <StatusBar style="dark" />
                </TourProvider>
              </ThemeProvider>
            </ScopeProvider>
          </CurrencyProvider>
        </AuthProvider>
      </KeyboardProvider>
    </GestureHandlerRootView>
  );
}
