import { useState } from 'react';
import { Modal, Pressable, StyleSheet } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import type { TransactionCategoryFilterValue } from '@/lib/transactionFilter';
import type { CategoryRow } from '@/types/database';

/**
 * Compact trigger chip + modal, self-contained (owns its own open/closed
 * state) so call sites just hold the filter value — same grouped-chip
 * layout as components/category-picker.tsx, minus the "add category" flow,
 * plus "All categories"/"Uncategorized" options a filter needs but a
 * per-transaction picker doesn't.
 */
export function TransactionCategoryFilter({
  categories,
  value,
  onChange,
  accentColor,
}: {
  categories: CategoryRow[];
  value: TransactionCategoryFilterValue;
  onChange: (value: TransactionCategoryFilterValue) => void;
  accentColor: string;
}) {
  const insets = useSafeAreaInsets();
  const [visible, setVisible] = useState(false);

  const topLevel = categories.filter((c) => c.parent_id === null);
  const childrenByParent = new Map<string, CategoryRow[]>();
  for (const c of categories) {
    if (c.parent_id) childrenByParent.set(c.parent_id, [...(childrenByParent.get(c.parent_id) ?? []), c]);
  }

  const label =
    value === 'all'
      ? 'All categories'
      : value === 'uncategorized'
        ? 'Uncategorized'
        : (categories.find((c) => c.id === value)?.name ?? 'Category');
  const isFiltered = value !== 'all';

  function select(next: TransactionCategoryFilterValue) {
    onChange(next);
    setVisible(false);
  }

  return (
    <>
      <Pressable
        onPress={() => setVisible(true)}
        style={[
          styles.trigger,
          { borderColor: accentColor, backgroundColor: isFiltered ? accentColor : 'transparent' },
        ]}>
        <ThemedText style={isFiltered ? { color: Colors.light.backgroundSolid } : undefined} numberOfLines={1}>
          {label} ▾
        </ThemedText>
      </Pressable>

      <Modal visible={visible} transparent animationType="fade" onRequestClose={() => setVisible(false)}>
        <Pressable style={styles.backdrop} onPress={() => setVisible(false)}>
          <Pressable style={[styles.sheet, { paddingBottom: insets.bottom + 16 }]} onPress={(e) => e.stopPropagation()}>
            <ThemedText type="defaultSemiBold" style={styles.title}>
              Filter by category
            </ThemedText>

            <ThemedView style={styles.chipRow}>
              {(['all', 'uncategorized'] as const).map((special) => {
                const isSelected = value === special;
                return (
                  <Pressable
                    key={special}
                    onPress={() => select(special)}
                    style={[
                      styles.chip,
                      { borderColor: accentColor, backgroundColor: isSelected ? accentColor : 'transparent' },
                    ]}>
                    <ThemedText style={isSelected ? { color: Colors.light.backgroundSolid } : undefined}>
                      {special === 'all' ? 'All categories' : 'Uncategorized'}
                    </ThemedText>
                  </Pressable>
                );
              })}
            </ThemedView>

            {topLevel.map((parent) => {
              const children = childrenByParent.get(parent.id) ?? [];
              const options = children.length > 0 ? children : [parent];
              return (
                <ThemedView key={parent.id} style={styles.section}>
                  {children.length > 0 ? <ThemedText style={styles.sectionLabel}>{parent.name}</ThemedText> : null}
                  <ThemedView style={styles.chipRow}>
                    {options.map((option) => {
                      const isSelected = value === option.id;
                      return (
                        <Pressable
                          key={option.id}
                          onPress={() => select(option.id)}
                          style={[
                            styles.chip,
                            { borderColor: accentColor, backgroundColor: isSelected ? accentColor : 'transparent' },
                          ]}>
                          <ThemedText style={isSelected ? { color: Colors.light.backgroundSolid } : undefined}>
                            {option.name}
                          </ThemedText>
                        </Pressable>
                      );
                    })}
                  </ThemedView>
                </ThemedView>
              );
            })}

            <Pressable onPress={() => setVisible(false)} style={styles.doneButton} hitSlop={8}>
              <ThemedText type="link">Done</ThemedText>
            </Pressable>
          </Pressable>
        </Pressable>
      </Modal>
    </>
  );
}

const styles = StyleSheet.create({
  trigger: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 14,
    paddingHorizontal: 12,
    paddingVertical: 5,
    maxWidth: 200,
  },
  backdrop: {
    flex: 1,
    backgroundColor: 'rgba(0,0,0,0.35)',
    justifyContent: 'flex-end',
  },
  sheet: {
    backgroundColor: Colors.light.backgroundSolid,
    borderTopLeftRadius: 18,
    borderTopRightRadius: 18,
    padding: 16,
    gap: 10,
    maxHeight: '80%',
  },
  title: {
    fontSize: 16,
  },
  section: {
    gap: 6,
  },
  sectionLabel: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  chipRow: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
  },
  chip: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 16,
    paddingHorizontal: 12,
    paddingVertical: 6,
  },
  doneButton: {
    alignSelf: 'center',
    marginTop: 4,
  },
});
