import { Pressable, StyleSheet, Switch } from 'react-native';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { formatMoney } from '@/lib/currency';
import { DEMO_HOME_COUNTRY, DEMO_TRIP_COUNTRY, type DemoTransaction } from '@/lib/demoData';
import { formatDateDisplay } from '@/lib/format';

const DEMO_CATEGORY_CYCLE = ['Dining', 'Shopping', 'Transport', 'Subscriptions', 'Uncategorized'];

/**
 * Visual twin of components/transaction-row.tsx for the onboarding demo —
 * same layout (amount + credit/debit, tappable category badge, country/city
 * + "not related to this trip" toggle) but 100% local state. The real
 * TransactionRow writes straight to Supabase from inside its own handlers
 * (category change, travel-toggle flip) and its CategoryPicker can INSERT a
 * real category row — fine against a real transaction.id, but wrong here,
 * where the "transaction" is fabricated and tapping it should never reach
 * the database. Deliberately not just TransactionRow with the writes
 * stripped out — keeping it a separate, tiny component means the real one
 * never has to grow a "demo mode" branch to serve this one screen.
 */
export function DemoTransactionRow({
  transaction,
  accentColor,
  onChange,
}: {
  transaction: DemoTransaction;
  accentColor: string;
  onChange: (updated: DemoTransaction) => void;
}) {
  const isCredit = transaction.amount >= 0;

  function cycleCategory() {
    const index = DEMO_CATEGORY_CYCLE.indexOf(transaction.categoryName);
    const next = DEMO_CATEGORY_CYCLE[(index + 1) % DEMO_CATEGORY_CYCLE.length];
    onChange({ ...transaction, categoryName: next });
  }

  return (
    <Surface accentColor={accentColor} style={styles.card}>
      <ThemedView style={styles.rowBetween}>
        <ThemedText type="defaultSemiBold" style={styles.flexShrink} numberOfLines={1}>
          {transaction.merchant}
        </ThemedText>
        <ThemedView style={styles.amountGroup}>
          <ThemedText type="mono">{formatMoney(Math.abs(transaction.amount), transaction.currency)}</ThemedText>
          <ThemedText style={[styles.creditDebitTag, { color: isCredit ? Colors.light.positive : Colors.light.negative }]}>
            {isCredit ? 'Credit' : 'Debit'}
          </ThemedText>
        </ThemedView>
      </ThemedView>
      <ThemedText type="mono" style={styles.muted}>
        {formatDateDisplay(transaction.date)}
      </ThemedText>

      <ThemedView style={styles.rowBetween}>
        <Pressable onPress={cycleCategory} hitSlop={6}>
          <ThemedView style={[styles.categoryBadge, { borderColor: accentColor }]}>
            <ThemedText style={[styles.categoryBadgeText, { color: accentColor }]}>{transaction.categoryName}</ThemedText>
          </ThemedView>
        </Pressable>
        <ThemedText style={styles.muted} numberOfLines={1}>
          {transaction.excludedFromTrip ? `${DEMO_HOME_COUNTRY} (home)` : `${transaction.city}, ${DEMO_TRIP_COUNTRY}`}
        </ThemedText>
      </ThemedView>

      <ThemedView style={styles.travelToggleRow}>
        <ThemedText style={styles.muted}>Not related to this trip</ThemedText>
        <Switch
          value={transaction.excludedFromTrip}
          onValueChange={(value) => onChange({ ...transaction, excludedFromTrip: value })}
          trackColor={{ true: accentColor }}
        />
      </ThemedView>
    </Surface>
  );
}

const styles = StyleSheet.create({
  card: {
    gap: 6,
  },
  rowBetween: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 8,
  },
  flexShrink: {
    flexShrink: 1,
  },
  amountGroup: {
    alignItems: 'flex-end',
    gap: 2,
  },
  creditDebitTag: {
    fontSize: 11,
    fontWeight: '600',
    textTransform: 'uppercase',
  },
  categoryBadge: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 12,
    paddingHorizontal: 10,
    paddingVertical: 3,
  },
  categoryBadgeText: {
    fontSize: 12,
    fontWeight: '600',
  },
  travelToggleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingTop: 4,
    borderTopWidth: StyleSheet.hairlineWidth,
    borderTopColor: Colors.light.icon,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
});
